export const MANUELS_HTML: Record<string, string> = {
  "achats": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Manuel — Achats · ERP Seem Semrac</title>\n<link rel=\"stylesheet\" href=\"manuel.css\">\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header class=\"doc\">\n    <div class=\"brandrow\">\n      <div class=\"logo\">SS</div>\n      <div>\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\n        <div class=\"eyebrow\">Manuel utilisateur</div>\n      </div>\n      <div class=\"kind\">docs/manuel/html</div>\n    </div>\n    <h1>Service <span class=\"hi\">Achats</span></h1>\n    <p class=\"lede\">Le service Achats pilote tout ce que l'entreprise achète : consultations de prix auprès des fournisseurs (RFQ), demandes d'achat venues de l'atelier, bons de commande fournisseurs et sous-traitants, référentiel et évaluation des fournisseurs. Vous apprendrez ici à consulter des prix, transformer une demande d'achat en bon de commande et tenir votre panel fournisseurs à jour.</p>\n    <div class=\"metachips\">\n      <span class=\"chip\">👤 Pour qui : <b>Acheteur(se)</b> (écriture : Achats, Stocks — lecture : Commercial, BE, Production, Expéditions, Maintenance)</span>\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Achats</b></span>\n      <span class=\"chip\">🗂 <b>5 onglets</b></span>\n    </div>\n  </header>\n\n  <nav class=\"toc\">\n    <div class=\"toc-t\">Sommaire</div>\n    <ol>\n      <li><a href=\"#tab-rfq\">Demandes de prix (RFQ)</a></li>\n      <li><a href=\"#tab-da\">Demandes d'achat</a></li>\n      <li><a href=\"#tab-fourn\">Fournisseurs / ST</a></li>\n      <li><a href=\"#tab-scorecard\">Scorecard</a></li>\n      <li><a href=\"#tab-dashboard\">Dashboard achats</a></li>\n    </ol>\n  </nav>\n\n  <div class=\"note\"><b>Règle d'or du service :</b> les <b>prix officiels</b> d'un fournisseur viennent exclusivement des réponses aux <b>demandes de prix (RFQ)</b> validées. Les bons de commande n'écrivent <b>jamais</b> le prix au catalogue : un prix saisi sur un BC n'engage que ce BC. À l'ouverture, la page s'affiche sur l'onglet <b>Demandes d'achat</b> ; les autres onglets sont accessibles par les boutons en haut de page.</div>\n\n  <section class=\"tab\" id=\"tab-rfq\">\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Demandes de prix (RFQ)</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est ici que vous consultez les fournisseurs et sous-traitants pour obtenir des prix. Une demande peut viser plusieurs références et, pour chaque référence, plusieurs fournisseurs : à la création, l'ERP la scinde automatiquement en <b>une RFQ par fournisseur</b>. Quand vous validez une réponse, le prix retenu devient le <b>prix officiel</b> du catalogue de ce fournisseur — c'est la seule porte d'entrée des prix dans l'ERP.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>En haut, le titre avec le nombre de demandes et le bouton <b>« Demande de prix »</b> (création). Une rangée de pastilles filtre la liste par statut : <b>Toutes</b>, <span class=\"b b-warn\">À traiter</span>, <span class=\"b b-info\">Envoyée</span>, <span class=\"b b-info\">Réponse reçue</span>, <span class=\"b b-ok\">Clôturée</span>. Le tableau liste chaque RFQ avec les colonnes <b>N°</b>, <b>Fournisseur</b>, <b>Origine</b> (Analyse DT, Nomenclature ou Libre — d'où vient le besoin), <b>Demandeur</b>, <b>Créée</b> (date) et <b>Statut</b>. Une pastille <span class=\"b b-warn\">à relancer</span> apparaît sur les demandes restées trop longtemps sans réponse. À droite de chaque ligne : un bouton <b>PDF</b> (télécharge le document à envoyer au fournisseur), un bouton <b>« Relancer »</b> (si la demande est à relancer, il régénère le PDF) et le bouton vert <b>« Traiter »</b> qui ouvre la fiche de la demande.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/achats-rfq.png\" alt=\"Capture de l'onglet Demandes de prix (RFQ)\" loading=\"lazy\">\n      <figcaption><b>Demandes de prix (RFQ)</b> — les pastilles de statut au-dessus du tableau et, sur chaque ligne, les boutons PDF et « Traiter ».</figcaption>\n    </figure>\n\n    <h3>Pas à pas — créer une demande de prix</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Demande de prix »</b> (ou, depuis l'onglet <b>Fournisseurs / ST</b>, sur le petit bouton devis d'une ligne fournisseur : la demande s'ouvre pré-remplie avec ce fournisseur).</li>\n      <li>Sur la première ligne, saisissez la <b>référence</b> (facultative), la <b>désignation</b> (obligatoire), la <b>quantité</b> et l'<b>unité</b> (« pce » par défaut).</li>\n      <li>Dans la colonne <b>« Fournisseurs à consulter »</b>, tapez le nom d'un fournisseur ou sous-traitant puis appuyez sur <b>Entrée</b> : il s'ajoute sous forme d'étiquette. Répétez pour consulter plusieurs fournisseurs sur la même référence — chaque référence doit en avoir <b>au moins un</b>.</li>\n      <li>Cliquez <b>« Ajouter une référence »</b> pour d'autres lignes, complétez éventuellement les <b>Notes</b> (précisions, délai souhaité…).</li>\n      <li>Cliquez <b>« Créer la demande de prix »</b> : l'ERP crée <b>une RFQ par fournisseur</b> consulté et confirme le nombre de demandes créées.</li>\n    </ol>\n\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Référence</td><td>Texte</td><td>Non</td><td>Référence interne de l'article à chiffrer.</td></tr>\n          <tr><td>Désignation</td><td>Texte</td><td><b>Oui</b></td><td>Description de l'article ou de la prestation ; une ligne sans référence ni désignation est ignorée.</td></tr>\n          <tr><td>Qté</td><td>Nombre</td><td>Non</td><td>Quantité estimée, transmise au fournisseur à titre indicatif.</td></tr>\n          <tr><td>Unité</td><td>Texte</td><td>Non</td><td>« pce » par défaut (pièce) ; adaptez si besoin (kg, m, barre…).</td></tr>\n          <tr><td>Fournisseurs à consulter</td><td>Nom + Entrée (liste proposée)</td><td><b>Oui</b> (≥ 1 par référence)</td><td>Fournisseurs et sous-traitants existants proposés en saisie ; un nom libre est aussi accepté.</td></tr>\n          <tr><td>Notes</td><td>Texte libre</td><td>Non</td><td>Précisions communes à la demande (délai souhaité, conditions…).</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-achats-rfq.png\" alt=\"Fenêtre Nouvelle demande de prix : références à chiffrer et fournisseurs à consulter\" loading=\"lazy\">\n      <figcaption><b>Nouvelle demande de prix</b> — le bloc « Références à chiffrer » : une ligne par référence (Référence, Désignation obligatoire, Qté, Unité « pce ») et la colonne <b>Fournisseurs à consulter</b> où chaque nom validé par Entrée devient une étiquette. « Ajouter une référence » empile les lignes ; « Créer la demande de prix » scinde le tout en une RFQ par fournisseur.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — envoyer, saisir les réponses et valider les prix</h3>\n    <ol class=\"steps\">\n      <li>Ouvrez la demande avec <b>« Traiter »</b>. Si elle est <span class=\"b b-warn\">À traiter</span>, cliquez <b>« Accepter et envoyer »</b> : elle passe au statut <span class=\"b b-info\">Envoyée</span>.</li>\n      <li>Cliquez <b>« Télécharger le PDF »</b> et transmettez le document au fournisseur (par email, hors ERP).</li>\n      <li>À réception des offres, rouvrez la demande : pour chaque référence, saisissez le <b>prix unitaire</b> et le <b>délai (jours)</b> proposés. Le bouton <b>« Ajouter un fournisseur »</b> permet d'enregistrer l'offre d'un fournisseur supplémentaire sur une référence.</li>\n      <li>Cochez la colonne <b>« Retenu »</b> pour désigner l'offre gagnante de chaque référence (une seule par référence).</li>\n      <li><b>« Enregistrer les réponses »</b> sauvegarde votre saisie sans rien clôturer ; <b>« Valider &amp; mettre à jour les prix »</b> enregistre puis met à jour les <b>prix officiels</b> au catalogue des fournisseurs retenus et <b>clôture</b> la RFQ (statut <span class=\"b b-ok\">Clôturée</span>).</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-achats-rfq-reponses.png\" alt=\"Fenêtre de traitement d'une RFQ : saisie des prix, délais et choix du fournisseur retenu\" loading=\"lazy\">\n      <figcaption><b>Traiter une demande de prix</b> — l'en-tête rappelle le n° de RFQ, son origine et son statut, avec « Télécharger le PDF » et « Accepter et envoyer ». Sous chaque référence, une ligne par fournisseur consulté : <b>Prix unit.</b>, <b>Délai (j)</b> et le bouton radio <b>Retenu</b>. « Enregistrer les réponses » sauvegarde seulement ; « Valider &amp; mettre à jour les prix » écrit le prix retenu au catalogue et clôture la RFQ.</figcaption>\n    </figure>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>La validation exige <b>au moins une offre cochée « Retenu » avec un prix saisi</b> ; sinon l'ERP refuse et vous le signale.</li>\n      <li>Les prix validés alimentent le catalogue fournisseur et servent ensuite partout dans l'ERP (nomenclatures, coûts). Les bons de commande ne modifient jamais ces prix.</li>\n      <li>L'<b>origine</b> d'une RFQ indique qui a déclenché le besoin : une analyse de demande de travaux (« Analyse DT »), une nomenclature, ou une création libre depuis cet onglet.</li>\n      <li>Le bouton <b>« Supprimer »</b> dans la fiche efface définitivement la demande (une confirmation est demandée).</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> l'ERP ne transmet pas la demande au fournisseur tout seul — « Accepter et envoyer » change le statut, mais c'est à vous d'envoyer le <b>PDF</b> téléchargé. Une demande envoyée sans réponse finit marquée <span class=\"b b-warn\">à relancer</span> : utilisez le bouton « Relancer » pour régénérer le PDF.</div>\n    <div class=\"astuce\"><b>Astuce :</b> partez de l'onglet <b>Fournisseurs / ST</b> pour consulter un fournisseur précis : le bouton devis de sa ligne ouvre la demande de prix déjà pré-remplie à son nom.</div>\n  </section>\n\n  <section class=\"tab\" id=\"tab-da\">\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Demandes d'achat</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Les demandes d'achat (DA) sont les besoins exprimés par l'atelier et les autres services : matière, outillage, consommables, produits chimiques. Votre travail d'acheteur consiste à les transformer en <b>bons de commande</b> (BC) fournisseur ou sous-traitant. Une fois le BC créé, son suivi (arrivée, réception) se fait dans le service <b>Expéditions</b>.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Deux listes superposées. En haut, <b>« Demandes d'achat à traiter »</b> avec son compteur vert : colonnes <b>N° DA</b>, <b>Article</b>, <b>Fournisseur</b>, <b>Qté</b>, <b>Type</b> (Matière, Outillage, Consommable, Chimique), <b>Priorité</b> (<span class=\"b b-crit\">critique</span> / <span class=\"b b-warn\">urgent</span> / <span class=\"b b-ok\">normal</span>), <b>Date DA</b>, <b>Livraison souhaitée</b>, <b>Statut</b> et le bouton d'action <b>« Traiter → BC »</b>. Une pastille <span class=\"b b-info\">AUTO</span> à côté du numéro signale une DA générée automatiquement par l'ERP (et non saisie à la main) ; le numéro d'affaire lié s'affiche sous l'article. En bas, <b>« Demandes d'achat traitées »</b> (compteur bleu) : un BC a été généré, avec les colonnes <b>Type BC</b> (Fournisseur ou Sous-traitant), <b>Statut</b> (<span class=\"b b-ok\">Commandé ✓</span>, <span class=\"b b-info\">En cours</span>, <span class=\"b b-ok\">Reçu ✓</span>, <span class=\"b b-crit\">Annulé</span>…) et un lien <b>« Voir BC »</b> qui mène aux bons de commande du service Expéditions. Au-dessus des listes : une <b>barre de recherche</b> (par article, fournisseur, demandeur, type ou priorité), le bouton <b>« Fusionner les DA cochées »</b> et le bouton <b>« Créer un BC »</b>. Chaque ligne « à traiter » porte une <b>case à cocher</b> (pour la fusion) et, à droite, deux petits boutons : <b>crayon</b> pour modifier la demande, <b>corbeille</b> pour la retirer de la liste — la corbeille n'apparaît pas sur les demandes <span class=\"b b-info\">AUTO</span>, qui traduisent un besoin réel issu d'une commande et ne peuvent être que modifiées.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/achats-da.png\" alt=\"Capture de l'onglet Demandes d'achat\" loading=\"lazy\">\n      <figcaption><b>Demandes d'achat</b> — la liste « à traiter » en haut avec priorités et bouton « Traiter → BC », les DA déjà transformées en BC en dessous.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — transformer une DA en bon de commande</h3>\n    <ol class=\"steps\">\n      <li>Sur la ligne de la DA, cliquez <b>« Traiter → BC »</b>. La fenêtre « Traiter la DA — Bon de Commande » s'ouvre, pré-remplie avec l'article, le fournisseur pressenti et la livraison souhaitée.</li>\n      <li>Renseignez la <b>Référence du matériel</b>. C'est le point important : tant qu'elle est vide, l'ERP ne peut que deviner le fournisseur à partir du libellé. Dès que vous choisissez une référence du catalogue, la liste « Fournisseur / ST » place en tête, sous « Référencés pour … », <b>les seuls fournisseurs qui portent vraiment cette référence</b>, chacun avec sa désignation catalogue — et s'il n'y en a qu'un, il est sélectionné automatiquement. Un message sous les deux champs dit ce qui a été trouvé : un fournisseur, plusieurs (vérifiez alors la désignation, un même code peut couvrir deux produits différents), ou aucun. Les autres fournisseurs restent toujours accessibles dans le second groupe : rien ne vous bloque si le produit n'est pas encore au catalogue.</li>\n      <li>Choisissez le <b>type de commande</b> (BC Fournisseur ou BC Sous-Traitant), vérifiez le <b>fournisseur / ST</b>, les <b>articles</b>, saisissez le <b>montant HT</b> et la <b>livraison prévue</b> ; le <b>n° d'affaire</b> et les <b>notes</b> sont optionnels.</li>\n      <li>Deux issues possibles : <b>« Enregistrer (brouillon) »</b> garde la DA dans la liste « à traiter » avec la pastille <span class=\"b b-mut\">Brouillon</span> — le bouton devient « Reprendre » pour continuer plus tard. <b>« Soumettre → créer BC »</b> crée le bon de commande (le fournisseur est alors obligatoire).</li>\n      <li>Après soumission, l'ERP confirme le numéro du BC créé : la DA bascule dans « traitées » et le BC apparaît côté <b>Expéditions</b>, en attente de réception.</li>\n    </ol>\n\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Type de commande</td><td>Liste : BC Fournisseur / BC Sous-Traitant</td><td>Oui (prérempli)</td><td>Détermine si le BC part chez un fournisseur ou un sous-traitant.</td></tr>\n          <tr><td>Fournisseur / ST</td><td>Texte (raison sociale)</td><td><b>Oui</b> pour soumettre</td><td>Destinataire du bon de commande.</td></tr>\n          <tr><td>Référence du matériel</td><td>Texte + liste de choix (catalogue)</td><td>Non, mais recommandé</td><td><b>La référence du produit à commander.</b> En la choisissant, le champ « Fournisseur / ST » ne propose plus en tête que les fournisseurs qui portent réellement cette référence au catalogue, avec leur désignation. Si un seul la porte, il est sélectionné pour vous. La référence part sur le PDF envoyé au fournisseur et sert à créditer le bon article en stock à la réception.</td></tr>\n          <tr><td>Articles / Prestation</td><td>Texte</td><td>Oui (prérempli avec la DA)</td><td>Désignation de ce qui est commandé. Se complète depuis le catalogue si vous choisissez une référence et que le champ est vide.</td></tr>\n          <tr><td>Montant HT (€)</td><td>Nombre</td><td>Non</td><td>Montant hors taxes du BC. N'affecte pas le prix officiel du catalogue.</td></tr>\n          <tr><td>Livraison prévue</td><td>Date</td><td>Non</td><td>Date attendue — elle sert au suivi des arrivées et au calcul de ponctualité (OTD) côté Expéditions.</td></tr>\n          <tr><td>N° d'affaire</td><td>Texte (AFF-2026-XXX)</td><td>Non</td><td>Rattache la dépense à une affaire cliente.</td></tr>\n          <tr><td>Notes</td><td>Texte libre</td><td>Non</td><td>Conditions, remarques pour le fournisseur.</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <h3>Pas à pas — créer un bon de commande direct (sans DA)</h3>\n    <ol class=\"steps\">\n      <li>Cliquez <b>« Créer un BC »</b> en haut de l'onglet : la fenêtre « Nouveau bon de commande » s'ouvre.</li>\n      <li>Choisissez le <b>destinataire</b> (Fournisseur ou Sous-traitant), saisissez son <b>nom</b> (obligatoire) et les <b>articles / désignation</b> (obligatoire), puis quantité, montant HT, livraison prévue, n° d'affaire et notes.</li>\n      <li>Détaillez la commande dans <b>« Lignes commandées »</b> : pour chaque ligne, référence, désignation, catégorie (Matière, Accessoires, Outils, Chimique, Consommable, Autres), quantité et prix unitaire. Le <b>montant HT se calcule tout seul</b> à partir des lignes.</li>\n      <li>Pour un achat stratégique ou d'un montant élevé, cochez <b>« Soumettre ce BC à la validation de la Direction »</b> : le BC sera présenté dans l'onglet « À valider » du service Direction.</li>\n      <li>Cliquez <b>« Créer le BC »</b> : il apparaît aussitôt dans la liste des BC du service <b>Expéditions</b>, en attente de réception.</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-achats-bc.png\" alt=\"Formulaire de création d'un bon de commande\" loading=\"lazy\">\n      <figcaption><b>Créer un BC</b> — destinataire, articles, montant HT, livraison prévue et lignes détaillées ; le montant se recalcule à partir des lignes.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — modifier ou retirer une demande d'achat</h3>\n    <ol class=\"steps\">\n      <li>Sur la ligne de la demande, cliquez le <b>crayon</b>. La fenêtre reprend l'article, la quantité, le type, le fournisseur pressenti, la priorité, la livraison souhaitée et le numéro d'affaire.</li>\n      <li>Corrigez ce qu'il faut, puis <b>Enregistrer</b>. Une bannière en haut de la fenêtre rappelle si la demande est <b>libre</b> ou <b>automatique</b>.</li>\n      <li>Sur une demande <b>automatique</b> (pastille AUTO), le <b>numéro d'affaire est verrouillé</b> : il relie la dépense à sa commande et commande l'ouverture de la matière en production. Tout le reste se modifie normalement.</li>\n      <li>Pour retirer une demande <b>libre</b>, cliquez la <b>corbeille</b> et confirmez. Elle disparaît des listes et des tableaux de bord — <b>mais reste enregistrée en base</b> : rien n'est effacé, c'est un retrait d'affichage.</li>\n    </ol>\n\n    <h3>Pas à pas — réunir plusieurs demandes en une seule commande</h3>\n    <ol class=\"steps\">\n      <li><b>Cochez</b> les demandes que vous voulez réunir (au moins deux). Le compteur du bouton se met à jour.</li>\n      <li>Cliquez <b>« Fusionner les DA cochées »</b>. Une fenêtre récapitule ce qui va être réuni : article, quantité, fournisseur et affaire de chaque demande.</li>\n      <li>Lisez le <b>verdict</b> affiché en dessous. Une fusion ne donne <b>qu'une seule commande</b>, donc <b>un seul fournisseur</b> : si les demandes cochées visent des fournisseurs différents, la fusion est <b>refusée</b> et le bouton reste inactif. Si aucune ne porte de fournisseur, la fenêtre vous demande de le choisir.</li>\n      <li>Si les demandes viennent d'<b>affaires différentes</b>, le verdict vous l'annonce : la commande sera <b>commune aux deux affaires</b>, et chacune verra sa matière débloquée à la réception.</li>\n      <li>Choisissez la <b>demande porteuse</b> (celle qui restera dans la liste), puis <b>Fusionner</b>. Les autres disparaissent de la liste et une pastille <b>FUSION</b> apparaît sur la porteuse.</li>\n      <li>Erreur de sélection ? Le bouton <b>défusionner</b> (deux carrés séparés) sur la demande porteuse rend leur autonomie à toutes les demandes réunies — tant que le bon de commande n'a pas été émis.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Une DA est considérée <b>traitée</b> dès qu'un BC a été créé pour elle ; son avancement (commandé, en cours, reçu) se suit ensuite dans Expéditions via le lien « Voir BC ».</li>\n      <li>Les DA <span class=\"b b-crit\">critique</span> sont à traiter en priorité — elles remontent aussi en alerte sur le Dashboard achats.</li>\n      <li>Le prix saisi sur un BC (montant, prix unitaires des lignes) ne met <b>pas</b> à jour le prix officiel du fournisseur : pour cela, passez par une <b>demande de prix</b> (onglet 1).</li>\n      <li>Le champ <b>Fournisseur / ST</b> de la fenêtre de traitement est une <b>liste déroulante</b>, plus une saisie libre. Elle propose d'abord, sous « Référencés pour &lt;article&gt; », les seuls fournisseurs qui portent cette référence au catalogue ; les autres restent disponibles dans le groupe suivant. Si la référence n'est encore au catalogue de personne, le premier groupe est vide et le second est intitulé « Aucun fournisseur référencé pour cette référence » — vous choisissez alors librement, et c'est le signal qu'une demande de prix serait utile.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> utilisez « Enregistrer (brouillon) » quand il vous manque une information (prix, délai) : la DA reste visible dans « à traiter » avec la pastille Brouillon, et le bouton « Reprendre » restaure toute votre saisie.</div>\n  </section>\n\n  <section class=\"tab\" id=\"tab-fourn\">\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>Fournisseurs / ST</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le référentiel de votre panel : d'un côté les <b>fournisseurs</b> (matière, visserie, consommables…), de l'autre les <b>sous-traitants</b> (traitements de surface, découpe, rectification…). Chaque fiche porte les contacts, le catalogue de références avec prix, les familles de fourniture ou prestations, et sert de base aux demandes de prix et aux bons de commande.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Un sélecteur bascule entre les deux listes : <b>Fournisseurs</b> et <b>Sous-traitants</b>, chacun avec son compteur. À droite : le lien <b>« Exporter (Excel) »</b> (exporte tous les fournisseurs et sous-traitants avec leur catalogue et prestations, feuille Données + feuille TCD) et le bouton violet <b>« Nouveau fournisseur »</b> / <b>« Nouveau sous-traitant »</b> (le libellé suit la liste affichée). Une barre de filtres permet de restreindre par <b>catégorie</b>, par <b>activité</b> (Seem, Semrac, Seem &amp; Semrac) ou par recherche libre (nom, contact, email). Le tableau des fournisseurs affiche : nom et code, catégorie, activité, contact, email / téléphone, <b>Catalogue</b> (nombre de références connues), <b>Délai</b> moyen en jours, et les actions. Celui des sous-traitants remplace le délai par les <b>Prestations</b> (étiquettes, les 4 premières puis « +N ») et signale par une pastille <span class=\"b b-warn\">à qualifier</span> un sous-traitant pas encore approuvé. Sur chaque ligne : un bouton devis (<b>demander un prix</b> — ouvre une RFQ pré-remplie), le bouton <b>« Fiche »</b> (ouvre la fiche complète pour consulter ou modifier) et une corbeille (suppression). Si des références de catalogue n'ont <b>pas de prix</b>, un bandeau jaune l'annonce en haut avec le bouton <b>« Nettoyer »</b>.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/achats-fournisseurs.png\" alt=\"Capture de l'onglet Fournisseurs / ST\" loading=\"lazy\">\n      <figcaption><b>Fournisseurs / ST</b> — la bascule Fournisseurs / Sous-traitants, les filtres catégorie / activité et, sur chaque ligne, les boutons devis, Fiche et suppression.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — créer un fournisseur ou un sous-traitant</h3>\n    <ol class=\"steps\">\n      <li>Affichez la bonne liste (Fournisseurs ou Sous-traitants) puis cliquez le bouton violet <b>« Nouveau fournisseur »</b> / <b>« Nouveau sous-traitant »</b>.</li>\n      <li>Renseignez au minimum la <b>raison sociale</b> (obligatoire) ; complétez code, SIRET, contact, email, téléphone, délai moyen, adresse.</li>\n      <li>Pour un fournisseur, ajoutez ses <b>familles de fourniture</b> (Aluminium, Acier, Inox, Visserie…) ; pour un sous-traitant, ses <b>prestations</b> (Oxydation anodique sulfurique, Zingage, Rectification…) : choisissez dans la liste proposée ou tapez librement, puis Entrée ou « + » — plusieurs étiquettes possibles.</li>\n      <li>Cliquez <b>« Créer »</b> : la fiche apparaît dans la liste et devient disponible dans les demandes de prix et les bons de commande.</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-achats-fournisseur.png\" alt=\"Fenêtre Nouveau fournisseur : raison sociale, coordonnées, familles de fourniture\" loading=\"lazy\">\n      <figcaption><b>Nouveau fournisseur</b> — seule la <b>Raison sociale</b> porte l'astérisque (obligatoire) ; le <b>Code</b> suit le format FOUR-XXX. Le bloc <b>Familles de fourniture</b> se remplit en choisissant dans la liste ou en saisissant librement, puis « + » : chaque famille s'ajoute au-dessus. « Créer » verse la fiche dans la liste Fournisseurs.</figcaption>\n    </figure>\n\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Raison sociale</td><td>Texte</td><td><b>Oui</b></td><td>Nom officiel du fournisseur ou du sous-traitant.</td></tr>\n          <tr><td>Code</td><td>Texte (FOUR-XXX / ST-XXX)</td><td>Non</td><td>Code court interne, affiché sous le nom dans la liste.</td></tr>\n          <tr><td>SIRET</td><td>Texte</td><td>Non</td><td>Identifiant légal de l'entreprise.</td></tr>\n          <tr><td>Contact / Email / Téléphone</td><td>Texte</td><td>Non</td><td>Interlocuteur habituel et ses coordonnées.</td></tr>\n          <tr><td>Familles de fourniture <i>(fournisseur)</i></td><td>Étiquettes (liste + saisie libre)</td><td>Non</td><td>Ce que le fournisseur sait livrer ; plusieurs familles possibles.</td></tr>\n          <tr><td>Prestations <i>(sous-traitant)</i></td><td>Étiquettes (liste + saisie libre)</td><td>Non</td><td>Opérations sous-traitées proposées ; plusieurs possibles.</td></tr>\n          <tr><td>Certifications <i>(sous-traitant)</i></td><td>Texte, séparées par des virgules</td><td>Non</td><td>Ex. : ISO 9001, EN 9100 — utile pour les exigences aéronautiques.</td></tr>\n          <tr><td>Délai moyen (j)</td><td>Nombre</td><td>Non</td><td>Délai de livraison habituel, affiché dans la liste des fournisseurs.</td></tr>\n          <tr><td>Conditions de paiement <i>(fournisseur)</i></td><td>Texte</td><td>Non</td><td>Ex. : virement 30 jours.</td></tr>\n          <tr><td>Adresse</td><td>Texte</td><td>Non</td><td>Adresse postale.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-achats-st.png\" alt=\"Fenêtre Nouveau sous-traitant : prestations de sous-traitance et certifications\" loading=\"lazy\">\n      <figcaption><b>Nouveau sous-traitant</b> — même trame que le fournisseur, mais le <b>Code</b> suit le format ST-XXX et deux champs remplacent les familles et les conditions de paiement : <b>Prestations de sous-traitance</b> (liste ou saisie libre, plusieurs possibles) et <b>Certifications</b> séparées par des virgules (ISO 9001, EN 9100…). Sans prestation ni approbation, la fiche créée reste marquée « à qualifier » dans la liste.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — nettoyer les références sans prix</h3>\n    <ol class=\"steps\">\n      <li>Quand le bandeau jaune « N référence(s) sans prix dans le catalogue fournisseur » s'affiche, cliquez <b>« Nettoyer »</b>.</li>\n      <li>La fenêtre liste les références concernées (référence, désignation, fournisseur) et marque <b>« éligible »</b> celles sans prix depuis plus de <b>90 jours</b>.</li>\n      <li>Supprimez une référence isolée avec le <b>×</b> de sa ligne, ou cliquez <b>« Purger les éligibles (&gt; 90 j) »</b> pour tout nettoyer d'un coup (confirmation demandée).</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Le badge <b>Activité</b> (Seem, Semrac ou Seem &amp; Semrac) indique pour quel site le fournisseur travaille ; le filtre du même nom s'appuie dessus.</li>\n      <li>Le compteur <b>Catalogue</b> (« N réf. ») correspond aux références connues de ce fournisseur — alimentées principalement par les demandes de prix validées.</li>\n      <li>Les cases à cocher de la barre de sélection permettent une <b>suppression groupée</b> de plusieurs fiches à la fois.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> la suppression d'un fournisseur ou d'un sous-traitant est <b>définitive</b> (confirmation demandée). Si la fiche est référencée ailleurs dans l'ERP (BC, catalogue…), l'ERP peut refuser la suppression et vous l'indique.</div>\n    <div class=\"astuce\"><b>Astuce :</b> le bouton devis d'une ligne est le chemin le plus rapide pour consulter un fournisseur précis : il ouvre directement une nouvelle demande de prix avec ce fournisseur déjà positionné.</div>\n  </section>\n\n  <section class=\"tab\" id=\"tab-scorecard\">\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Scorecard</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La scorecard évalue objectivement vos fournisseurs et sous-traitants à partir de leur historique réel dans l'ERP : ponctualité de livraison, qualité à réception et régularité de paiement. Elle vous aide à choisir qui consulter, qui surveiller et qui écarter — une exigence classique des audits EN 9100.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Un tableau classant les fournisseurs et sous-traitants ayant une <b>activité d'achat</b> (au moins un BC) ; l'en-tête rappelle la formule du score : <b>OTD 50 % + qualité réception 35 % + ponctualité paiement 15 %</b>, ainsi que le nombre de fiches en base et celles avec activité. Colonnes : <b>Fournisseur</b> (cliquable, ouvre la fiche), <b>Type</b> (Fournisseur / Sous-traitant), <b>Score</b> (pastille de couleur : <span class=\"b b-ok\">≥ 85 vert</span>, <span class=\"b b-warn\">65–84 orange</span>, <span class=\"b b-crit\">&lt; 65 rouge</span>), <b>OTD</b> (livraisons à l'heure : vert ≥ 90 %, orange ≥ 75 %, rouge en dessous — avec le nombre de livraisons évaluées), <b>Qualité récept.</b> (réceptions sans non-conformité : vert ≥ 98 %, orange ≥ 90 %, rouge en dessous — le nombre de NC s'affiche le cas échéant), <b>Délai paiement</b> (jours), <b>Nb BC</b> et <b>Montant</b> total acheté en euros. Un tiret « — » signifie : pas encore assez de données pour noter.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/achats-scorecard.png\" alt=\"Capture de l'onglet Scorecard\" loading=\"lazy\">\n      <figcaption><b>Scorecard</b> — le score global en pastille colorée, décomposé en OTD, qualité de réception et délai de paiement.</figcaption>\n    </figure>\n\n    <h3>Pas à pas</h3>\n    <ol class=\"steps\">\n      <li>Parcourez le tableau : les pastilles rouges (score &lt; 65, OTD &lt; 75 %, qualité &lt; 90 %) désignent les fournisseurs à surveiller ou à challenger.</li>\n      <li>Cliquez sur le <b>nom</b> d'un fournisseur pour ouvrir sa fiche complète et creuser (catalogue, historique).</li>\n      <li>Avant de lancer une demande de prix importante, vérifiez ici l'OTD et la qualité des candidats pressentis.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Les notes se construisent automatiquement à partir des <b>BC</b>, des <b>livraisons</b> (dates prévues vs réelles), des <b>non-conformités</b> déclarées en Qualité et des <b>factures fournisseur</b> réglées en Comptabilité : plus l'historique est riche, plus le score est fiable.</li>\n      <li>Un fournisseur sans aucun BC n'apparaît pas dans le tableau — d'où le message « Aucune donnée fournisseur » tant qu'il n'y a ni BC, ni livraison, ni facture.</li>\n      <li>L'OTD est mesuré sur la <b>première</b> date de livraison promise : repousser une date ne « blanchit » pas un retard.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> combinez la scorecard et l'onglet Demandes de prix : consultez systématiquement au moins deux fournisseurs bien notés pour garder de la concurrence sur vos références clés.</div>\n  </section>\n\n  <section class=\"tab\" id=\"tab-dashboard\">\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Dashboard achats</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est la vue d'ensemble du service : votre charge du moment (DA en attente), les urgences à ne pas rater et la répartition des achats par type. C'est l'écran à consulter en début de journée pour organiser votre travail.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Quatre tuiles de compteurs : <b>DAs à traiter</b>, <b>Commandes en cours</b>, <b>Réceptions à valider</b> et <b>Total DAs (tous statuts)</b>. En dessous, deux blocs côte à côte : les <b>Alertes</b> — un encart rouge « N DA(s) CRITIQUE(S) en attente — traitement prioritaire immédiat » si des DA critiques attendent, un encart jaune « N demande(s) en attente de traitement », ou « Aucune alerte active » quand tout est traité — et la <b>Répartition par type</b> (Matière, Outillage, Consommable, Chimique) en barres de pourcentage. Enfin, trois <b>accès rapides</b> : <b>« Créer un BC »</b> (ouvre la création directe de bon de commande), <b>« Réception &amp; Stock »</b> (page de validation des réceptions) et <b>« Fournisseurs SS-T »</b> (liste complète des fournisseurs et sous-traitants).</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/achats-dashboard.png\" alt=\"Capture de l'onglet Dashboard achats\" loading=\"lazy\">\n      <figcaption><b>Dashboard achats</b> — les quatre compteurs, le bloc Alertes et la répartition des DA par type d'achat.</figcaption>\n    </figure>\n\n    <h3>Pas à pas</h3>\n    <ol class=\"steps\">\n      <li>Commencez par le bloc <b>Alertes</b> : s'il affiche des DA critiques, filez à l'onglet <b>Demandes d'achat</b> les traiter en premier.</li>\n      <li>Surveillez la tuile <b>Réceptions à valider</b> : des marchandises sont arrivées et attendent votre validation via l'accès rapide « Réception &amp; Stock ».</li>\n      <li>Utilisez la <b>répartition par type</b> pour repérer une dérive (ex. : explosion des achats de consommables) et en parler en réunion.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Les compteurs se recalculent à chaque affichage de la page à partir des demandes d'achat réelles — aucun chiffre saisi à la main.</li>\n      <li>« Commandes en cours » compte les DA déjà transformées en BC dont la réception n'est pas terminée ; leur détail se suit côté Expéditions.</li>\n    </ul>\n    <div class=\"note\"><b>Bon à savoir :</b> des analyses achats plus poussées (tendances, montants, filtres par période) existent dans <b>Tableaux de bord → Dashboard Achats</b>, commun à toute l'entreprise.</div>\n  </section>\n\n  <div class=\"docnav\">\n    <a href=\"index.html\">← Sommaire des manuels</a>\n    <a href=\"production.html\">Manuel suivant : Production →</a>\n  </div>\n\n  <footer class=\"doc\">\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\n  </footer>\n\n</div>\n</body>\n</html>\n",
  "be": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Manuel — Bureau d'Études · ERP Seem Semrac</title>\n<link rel=\"stylesheet\" href=\"manuel.css\">\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header class=\"doc\">\n    <div class=\"brandrow\">\n      <div class=\"logo\">SS</div>\n      <div>\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\n        <div class=\"eyebrow\">Manuel utilisateur</div>\n      </div>\n      <div class=\"kind\">docs/manuel/html</div>\n    </div>\n    <h1>Service <span class=\"hi\">Bureau d'Études</span></h1>\n    <p class=\"lede\">Le Bureau d'Études définit techniquement les pièces : il crée les nomenclatures (matière, accessoires, gamme d'opérations), analyse les Demandes de Travaux (DT) transmises par le commercial pour calculer le coût de revient, prépare les programmes CN et tient le catalogue des références achetées. Ce manuel décrit chaque onglet et les procédures pas à pas.</p>\n    <div class=\"metachips\">\n      <span class=\"chip\">👤 Pour qui : <b>Technicien(ne) BE</b> (écriture : BE, Achats)</span>\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Bureau Études</b></span>\n      <span class=\"chip\">🗂 <b>5 onglets</b></span>\n    </div>\n  </header>\n\n  <nav class=\"toc\">\n    <div class=\"toc-t\">Sommaire</div>\n    <ol>\n      <li><a href=\"#tab-noms\">Nomenclatures</a></li>\n      <li><a href=\"#tab-analyse\">Analyse DT (page /be/analyse)</a></li>\n      <li><a href=\"#tab-prep\">Préparations tech.</a></li>\n      <li><a href=\"#tab-refs\">Références</a></li>\n      <li><a href=\"#tab-dashboard\">Dashboard BE</a></li>\n    </ol>\n  </nav>\n\n  <!-- ══════════════════════ 1. NOMENCLATURES ══════════════════════ -->\n  <section class=\"tab\" id=\"tab-noms\">\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Nomenclatures</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La nomenclature est la carte d'identité de fabrication d'une pièce : sa matière, ses accessoires, sa gamme d'opérations et son prix de revient calculé automatiquement. C'est ici que le BE crée les nomenclatures demandées par les DT « Nouveau produit », complète les brouillons, et fait vivre les révisions (indices A, B, C…). Sans nomenclature validée, l'analyse BE d'une DT ne peut pas chiffrer la pièce.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>L'onglet s'ouvre sur quatre sous-onglets, avec en haut à droite un bouton <b>« Créer une demande de prix »</b> (envoi d'articles à chiffrer au service Achats) :</p>\n    <ul class=\"points\">\n      <li><b>Nomenclatures à créer</b> — bandeau jaune « Nomenclatures à faire (depuis DT validées) » : chaque DT en attente de nomenclature y apparaît avec son client, son type, sa priorité, et un bouton par pièce à nomencler (réf ×&nbsp;quantité). Le compteur du sous-onglet totalise les pièces restant à créer.</li>\n      <li><b>Brouillons à traiter</b> — les nomenclatures non validées (colonnes : N° NOM, Indice, Entité, N° Affaire, Code Réf, Description, Type, Créé le), avec les boutons <b>Terminer</b> et <b>Supprimer</b>. Un brouillon n'apparaît pas dans Standards/Mères tant qu'il n'est pas validé.</li>\n      <li><b>Standards (1 pièce)</b> — les nomenclatures validées décrivant <b>une seule pièce</b>. Colonnes : #, N° NOM, Indice (liste déroulante des révisions), Entité, N° Affaire, Code Réf Produit, Description, Statut, Prix de revient, Créé le, Action (<b>Ouvrir</b> / <b>Supprimer</b>). Filtres <b>Toutes / Seem / Semrac</b>, champ de recherche, sélection multiple pour suppression groupée, bouton <b>« + Nouvelle nomenclature standard »</b>.</li>\n      <li><b>Mères (assemblages)</b> — les nomenclatures qui assemblent des standards (colonne <b>Composants</b> = nombre de standards). Bouton <b>« + Nouvelle mère »</b>. Le prix de revient d'une mère est la somme de ses composants.</li>\n    </ul>\n    <p>Statuts d'une nomenclature : <span class=\"b b-mut\">Brouillon</span> <span class=\"b b-info\">En cours</span> <span class=\"b b-ok\">Validée ✓</span>. L'entité est signalée par un badge <span class=\"b b-ok\">Seem</span> ou <span class=\"b b-crit\">Semrac</span>.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/be-noms.png\" alt=\"Capture de l'onglet Nomenclatures\" loading=\"lazy\">\n      <figcaption><b>Onglet Nomenclatures</b> — les quatre sous-onglets (À créer / Brouillons / Standards / Mères), le bandeau des pièces à nomencler issues des DT validées et la liste des standards avec leur indice.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — créer une nomenclature depuis une DT</h3>\n    <ol class=\"steps\">\n      <li>Sous-onglet <b>Nomenclatures à créer</b> : repérez la DT concernée, puis cliquez le bouton de la pièce à nomencler (ex. <b>+ REF-PIECE ×10</b>). Le formulaire s'ouvre pré-rempli (N° affaire, réf. pièce, n° de plan) — une notification le confirme.</li>\n      <li>Complétez l'<b>Identification</b> (voir tableau des champs ci-dessous) : entité Seem/Semrac, description, masse, dimensions, surface…</li>\n      <li>Ajoutez la <b>Matière (tôle)</b> : saisissez la <b>réf. matière</b> (ou la désignation) — la liste propose le catalogue existant. Le fournisseur qui porte cette réf se sélectionne tout seul s'il est unique. Le <b>prix tôle</b> s'affiche automatiquement s'il date de moins de 6 mois ; sinon un bouton <b>« demande de prix »</b> l'envoie aux Achats (un bouton <b>« vérifier »</b> apparaît ensuite pour récupérer la réponse). Renseignez <b>Pc/tôle</b> : le prix matière par pièce = prix tôle ÷ pièces par tôle.</li>\n      <li>Ajoutez les <b>Accessoires</b> (visserie, composants…) : réf catalogue, fournisseur, prix paquet (mêmes règles de fraîcheur de prix), quantité par paquet et nombre par pièce. Prix accessoire / pièce = (prix paquet ÷ qté par paquet) × nb par pièce.</li>\n      <li>Construisez la <b>gamme</b> (« Étapes de production ») : pour chaque étape, choisissez le <b>Type</b> (Interne ou Sous-traité), puis le <b>Poste</b> d'atelier et le <b>Process</b> du poste (la machine liée et son taux horaire se renseignent seuls ; un process manuel n'a pas de temps machine). Saisissez les temps <b>en millièmes d'heure</b> (1000&nbsp;‰ = 1&nbsp;h) : réglage, MO, machine. Réordonnez les étapes par glisser-déposer — cet ordre devient la séquence de fabrication des BDT.</li>\n      <li>Pour une étape <b>sous-traitée</b> : choisissez le sous-traitant puis l'opération — le prix unitaire pièce et le forfait de son tarif s'appliquent automatiquement.</li>\n      <li>Vérifiez le panneau <b>« Prix de revient unitaire — Calcul automatique »</b> : matière, accessoire, MO fixe (réglage / lot), MO variable, sous-traitance, et le total. Le bloc <b>« Estimation commande »</b> simule le coût pour une quantité : le réglage n'est compté qu'une fois par lot et la sous-traitance applique le forfait plancher (max entre forfait et qté × prix unitaire).</li>\n      <li>Enregistrez : <b>Brouillon</b> (retrouvable dans « Brouillons à traiter »), <b>Enregistrer &amp; continuer</b> (statut En cours), ou <b>Valider la nomenclature</b>. Le N° de nomenclature est obligatoire pour enregistrer.</li>\n      <li>À la <b>validation</b> d'une nomenclature créée depuis une DT, la DT bascule automatiquement « en attente BE » : l'analyse (onglet Analyse DT) est débloquée.</li>\n    </ol>\n\n    <h3>Pas à pas — créer une nomenclature mère (assemblage)</h3>\n    <ol class=\"steps\">\n      <li>Sous-onglet <b>Mères</b>, cliquez <b>« + Nouvelle mère »</b> (ou basculez le type sur « Mère (assemblage) » dans le formulaire).</li>\n      <li>Dans le bloc <b>Composants</b>, cliquez <b>« Ajouter un standard »</b> puis choisissez chaque nomenclature standard et sa quantité. Le total des composants s'affiche en direct.</li>\n      <li>Les compartiments matière/accessoires disparaissent (une mère n'a pas de fournitures propres) : son prix de revient est la somme de ses standards.</li>\n      <li>Enregistrez puis validez, comme pour une standard.</li>\n    </ol>\n\n    <h3>Pas à pas — créer une révision (indice)</h3>\n    <ol class=\"steps\">\n      <li>Depuis la liste : la colonne <b>Indice</b> est une liste déroulante qui montre toutes les révisions du produit. Choisissez <b>« ➕ Créer indice B… »</b> (ou C, D…) : la nouvelle révision clone la dernière, <b>l'ancienne est conservée</b> et reste ouvrable via la même liste.</li>\n      <li>Depuis le formulaire d'une nomenclature enregistrée : le bandeau violet <b>« Indice actuel »</b> propose <b>« Incrémenter l'indice → B »</b>. Confirmez : la révision précédente est conservée telle quelle.</li>\n    </ol>\n\n    <h3>Le formulaire nomenclature, champ par champ (Identification)</h3>\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>N° Nomenclature = réf. pièce</td><td>Texte (ex. SEEM-DISSIP-A24)</td><td>Oui</td><td>Identifiant de la nomenclature ; c'est la référence interne de la pièce.</td></tr>\n          <tr><td>N° Affaire</td><td>Texte (ex. 2026-081)</td><td>Non</td><td>Rattache la nomenclature à une affaire ; vide = nomenclature « libre ».</td></tr>\n          <tr><td>Entité</td><td>Seem / Semrac</td><td>Oui</td><td>Filtre les fournisseurs, postes et process proposés dans le reste du formulaire.</td></tr>\n          <tr><td>Type de nomenclature</td><td>Standard (1 pièce) / Mère (assemblage)</td><td>Oui (Standard par défaut)</td><td>Une mère assemble des standards ; ses fournitures propres sont masquées.</td></tr>\n          <tr><td>Code produit</td><td>Texte</td><td>Non</td><td>Par défaut égal au N° de nomenclature.</td></tr>\n          <tr><td>Description produit</td><td>Texte</td><td>Non</td><td>Désignation complète du produit.</td></tr>\n          <tr><td>N° de plan</td><td>Texte (ex. PL-138001 ind. A)</td><td>Non</td><td>Référence du plan de la pièce.</td></tr>\n          <tr><td>Nom du fichier CAO</td><td>Texte (ex. PL-138001_A.pdf)</td><td>Non</td><td>Se remplit seul si vous joignez le plan CAO en GED.</td></tr>\n          <tr><td>Masse pour 1 pc (g)</td><td>Nombre</td><td>Non</td><td>Saisie en <b>grammes</b> (stockée en kg côté base).</td></tr>\n          <tr><td>Dimensions pour 1 pc</td><td>Texte (ex. 150 × 80 × 20 mm)</td><td>Non</td><td>Encombrement de la pièce.</td></tr>\n          <tr><td>Surface totale pour 1 pc (mm²)</td><td>Nombre</td><td>Non</td><td>Surface développée : sert au calcul de charge des balancelles OAS.</td></tr>\n          <tr><td>Créé par</td><td>Liste des analystes BE</td><td>Non</td><td>Auteur de la nomenclature.</td></tr>\n          <tr><td>Notes</td><td>Texte</td><td>Non</td><td>Remarques libres.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p>Sous l'identification, deux blocs complètent la fiche : <b>« Clients &amp; réfs de cette pièce »</b> (le répertoire réf interne ↔ réf client ↔ plan, alimenté automatiquement par les DT validées, avec ajout manuel possible) et <b>« Documents (GED) »</b> pour joindre le plan client, le plan CAO et les programmes FAO par étape machine.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-be-nomenclature.png\" alt=\"Capture du formulaire de nomenclature\" loading=\"lazy\">\n      <figcaption><b>Formulaire nomenclature</b> — à gauche identification + fournitures (matière / accessoires), à droite la gamme en millièmes d'heure et le prix de revient calculé automatiquement.</figcaption>\n    </figure>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li><b>Temps en millièmes d'heure</b> : 1000&nbsp;‰ = 1&nbsp;h. Les totaux s'affichent en heures/minutes.</li>\n      <li><b>Le réglage est un coût fixe par lot</b> : il n'est jamais multiplié par la quantité produite (la machine se règle une fois, qu'on fasse 1 ou 10&nbsp;000 pièces).</li>\n      <li><b>Prix fournisseurs pilotés par le catalogue</b> : un prix n'est appliqué que s'il date de moins de 6 mois ; au-delà (ou s'il est absent), passez par la <b>demande de prix</b> — pas de saisie manuelle du prix matière/accessoire.</li>\n      <li><b>Postes et process se gèrent dans Production → « Postes &amp; Process »</b> : la gamme ne fait que les choisir.</li>\n      <li>Une nomenclature ouverte par un collègue est <b>verrouillée</b> : une notification vous indique qui la modifie ; patientez, la liste se met à jour en direct (rafraîchissement automatique toutes les ~7&nbsp;secondes hors édition).</li>\n      <li>Les champs « N° programme machine / fichier programme » n'apparaissent dans la gamme que pour les étapes sur <b>machine CNC</b>.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> la suppression d'une nomenclature est <b>irréversible</b> (une confirmation est demandée). Pour faire évoluer une pièce, préférez toujours <b>créer un nouvel indice</b> : l'ancienne révision reste consultable.</div>\n    <div class=\"astuce\"><b>Astuce :</b> le bouton <b>« Créer une demande de prix »</b> en haut de l'onglet accepte plusieurs articles d'un coup — l'ERP crée <b>une demande par référence</b> et les envoie dans Achats → « Demandes de prix ». Le prix officiel du catalogue est mis à jour à la validation de la réponse.</div>\n  </section>\n\n  <!-- ══════════════════════ 2. ANALYSE DT ══════════════════════ -->\n  <section class=\"tab\" id=\"tab-analyse\">\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Analyse DT (page /be/analyse)</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Quand le commercial valide une DT, elle arrive ici pour l'analyse technique : faisabilité, gamme, couverture matière et calcul du coût de revient unitaire (CRU). Le résultat alimente directement l'offre de prix côté commercial. L'onglet liste les DT à analyser et celles déjà analysées ; le bouton <b>Analyser</b> ouvre la page d'analyse complète.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Deux tableaux et un bouton <b>« Demande de prix »</b> :</p>\n    <ul class=\"points\">\n      <li><b>DTs en attente d'analyse BE</b> — colonnes : N° DT / Affaire, Client, Pièce(s) · Qté, Type DT (<span class=\"b b-info\">Nouveau produit</span> / <span class=\"b b-info\">Maj produit</span> / <span class=\"b b-warn\">Maj prix</span>), Priorité (<span class=\"b b-crit\">critique</span> <span class=\"b b-warn\">urgent</span> <span class=\"b b-ok\">normal</span>), Date DT, Analyste, et deux actions : <b>Analyser</b> (ouvre la page /be/analyse pré-remplie) et <b>Visualiser</b> (œil).</li>\n      <li><b>DT analysées — offres &amp; commandes</b> — colonnes : N° DT / Affaire, Client, Pièce(s) · Qté, Montant offre, Statut offre (<span class=\"b b-info\">Offre en cours</span> <span class=\"b b-ok\">Offre acceptée</span> <span class=\"b b-info\">Commande créée</span> <span class=\"b b-mut\">Pas d'offre</span>). Tant que l'offre n'est pas acceptée : bouton <b>« Ré-éditer l'analyse »</b>. Offre acceptée ou commande créée : l'analyse est <b>figée</b> (cadenas), seul <b>Visualiser</b> reste disponible.</li>\n    </ul>\n    <p>Le bouton <b>œil « Visualiser »</b> ouvre un panneau en <b>LECTURE SEULE</b> (le badge l'indique) : la décomposition auto-calculée depuis les nomenclatures validées — par pièce : réf. interne, nomenclature, quantité, matière, MO (réglage inclus), machine, sous-traitance (forfait minimum inclus), total série et €&nbsp;/&nbsp;pièce. Aucune modification possible depuis cette vue : pour éditer, passez par « Analyser ».</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/be-analyse.png\" alt=\"Capture de l'onglet Analyse DT\" loading=\"lazy\">\n      <figcaption><b>Onglet Analyse DT</b> — en haut les DT en attente avec les boutons « Analyser » et « Visualiser » (œil, lecture seule) ; en dessous les DT déjà analysées avec leur statut d'offre.</figcaption>\n    </figure>\n\n    <h3>La page d'analyse /be/analyse en détail</h3>\n    <p>Ouverte via <b>Analyser</b>, la page charge automatiquement la DT : entête, pièces, quantités, exigences et plan sont déversés (une notification le confirme). Elle se compose, de haut en bas :</p>\n    <ul class=\"points\">\n      <li><b>Référence DT à analyser</b> — N° DT et Client sont pré-remplis et verrouillés ; vous renseignez : <b>Analyste BE</b> (obligatoire, liste des salariés habilités BE), Date analyse, Priorité (Standard / Urgent / Critique), Type demande (Commande ferme / Prototype / Essai / Réclamation).</li>\n      <li><b>Produits analysés</b> — un bloc par pièce de la DT, avec le <b>triplet lié</b> : Réf. interne pièce ↔ N° plan client ↔ Réf. pièce client. Saisir l'une des trois remplit les cases vides depuis le répertoire des références clients ; un lien <b>« Ouvrir le plan client »</b> apparaît si le plan est en GED. La <b>quantité</b> vient de la DT (verrouillée).</li>\n      <li><b>Exigences normatives</b> — cases à cocher identiques à la DT : ISO 9001, EN 9100, REACH, RoHS, EN 13485.</li>\n      <li><b>Couverture matière &amp; accessoires</b> — pour chaque fourniture de la nomenclature : besoin exprimé en <b>unités d'achat entières</b> (tôles / paquets, arrondi supérieur), prix unité (ou « à chiffrer » si aucun prix récent), coût série, stock restant, seuil, et un état : <span class=\"b b-ok\">Couvert</span> <span class=\"b b-warn\">Repasse sous seuil</span> <span class=\"b b-warn\">Insuffisant</span> <span class=\"b b-crit\">Rupture</span> <span class=\"b b-mut\">Hors stock</span>. Le pied de tableau totalise le coût matière + accessoires de la série.</li>\n      <li><b>Gamme opératoire</b> — mêmes colonnes que la nomenclature (N°, Type, Poste, Process, Régl.&nbsp;‰h, MO&nbsp;‰h, Mach&nbsp;‰h, Coût/pc). Les étapes issues de la nomenclature sont <b>verrouillées</b> (cadenas, non modifiables ni déplaçables). Le bouton <b>« Ajouter une étape »</b> insère une étape supplémentaire (fond violet) que vous positionnez <b>par glisser-déposer</b> entre les étapes verrouillées ; son coût s'ajoute au CRU.</li>\n      <li><b>Temps &amp; coûts par poste</b> — regroupement par poste d'atelier avec les <b>temps réels</b> (réglage par lot + variable × quantité) et le coût série ; les flèches ‹&nbsp;› font défiler les différentes quantités chiffrées.</li>\n      <li><b>Chiffrage — Coût de revient (CRU)</b> — tout est calculé automatiquement (matière, accessoire, MO+machine, sous-traitance) ; le seul champ saisissable est <b>Frais généraux / lot</b> (coût fixe par lot, amorti sur la quantité). Le tableau affiche une ligne par quantité : Matière ×q, Access. ×q, MO+mach ×q, S-trait ×q, Frais g. (lot), <b>CRU total</b> et <b>CRU /pc</b> ; la ligne de la quantité de la DT est surlignée.</li>\n      <li><b>Analyse de faisabilité technique</b> — Faisabilité (obligatoire : Faisable sans réserve / Faisable avec adaptation / Non faisable – alternative proposée), Commentaires, et pièces jointes complémentaires pour l'offre (rangées en GED, dossier « analyse DT »).</li>\n      <li><b>Conclusion &amp; transmission</b> — Décision BE (obligatoire : ✅ Faisable – Offre à établir / ⚠ Faisable avec réserves – Points à clarifier / ❌ Non faisable – Alternative proposée) puis le bouton <b>« Valider l'analyse BE complète »</b>.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-be-analyse.png\" alt=\"Capture de la page d'analyse /be/analyse\" loading=\"lazy\">\n      <figcaption><b>Page /be/analyse</b> — bloc produit avec triplet réf interne ↔ plan ↔ réf client, couverture matière/stock, gamme verrouillée (cadenas) + étapes ajoutées glissables, et chiffrage CRU par quantité.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — analyser une DT</h3>\n    <ol class=\"steps\">\n      <li>Onglet <b>Analyse DT</b>, ligne de la DT, cliquez <b>Analyser</b>. Vérifiez l'entête et choisissez l'<b>Analyste BE</b>.</li>\n      <li>Contrôlez chaque bloc produit : triplet de références, exigences cochées, <b>couverture matière</b> (un état « Rupture » ou « à chiffrer » se règle par une demande de prix ou un réapprovisionnement avant le lancement).</li>\n      <li>Ajustez la gamme si besoin en <b>ajoutant des étapes</b> (les étapes nomenclature restent intouchées) et saisissez les éventuels <b>frais généraux par lot</b>.</li>\n      <li>Renseignez <b>Faisabilité</b>, commentaires, et joignez les documents utiles à l'offre.</li>\n      <li>Choisissez la <b>Décision BE</b> puis cliquez <b>« Valider l'analyse BE complète »</b> : l'analyse est enregistrée, le montant calculé, et la DT <b>bascule dans les offres</b> côté commercial (notification, puis retour automatique à l'onglet).</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>L'analyse reste <b>ré-éditable</b> tant que l'offre n'est pas acceptée ; les <b>marges par produit</b> fixées dans l'offre sont conservées lors d'une ré-édition.</li>\n      <li>La <b>marge et le prix de vente ne se fixent pas ici</b> : le BE produit le coût de revient ; la marge se règle dans l'offre de prix (service Commercial).</li>\n      <li>Les BDT/BDS sont générés à la <b>validation de la commande</b>, puis visibles en Production.</li>\n    </ul>\n    <div class=\"note\"><b>DT mixte Seem + Semrac :</b> si la DT mélange des pièces des deux sites, l'analyse passe automatiquement en <b>2 volets</b> (une barre d'onglets Volet SEEM / Volet SEMRAC apparaît). Chaque volet se termine séparément — le bouton devient « Terminer le volet … » — et l'offre n'est générée que lorsque <b>les deux volets</b> sont terminés.</div>\n    <div class=\"astuce\"><b>Astuce :</b> le bouton <b>œil</b> est le moyen rapide de consulter le CRU d'une DT déjà analysée sans risquer de rien modifier — la vue est strictement en lecture seule, y compris pour les analyses figées.</div>\n  </section>\n\n  <!-- ══════════════════════ 3. PRÉPARATIONS TECH. ══════════════════════ -->\n  <section class=\"tab\" id=\"tab-prep\">\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>Préparations tech.</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Avant de lancer une commande en fabrication, les pièces usinées sur machine CNC ont besoin de leurs codes programme. Cet onglet liste les commandes en attente de préparation technique et donne accès à la page de saisie des programmes CN — qui seront imprimés sur l'Ordre de Fabrication (OF) du lot.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Le tableau <b>« Préparations techniques en attente »</b> (le compteur reprend le badge de l'onglet) : N° CMD / Affaire, Client, Pièce(s), Activité, Livraison, Statut (<span class=\"b b-info\">Attente prépa</span> ou <span class=\"b b-warn\">À programmer</span>) et le bouton <b>Préparer</b> qui ouvre la page <b>/be/preparation</b>.</p>\n    <p>Sur la page de préparation : une liste déroulante <b>« Pièce à programmer »</b> propose les nomenclatures dont au moins une étape tourne sur une <b>machine CNC</b> (le nombre de machines CNC et de pièces concernées est rappelé). Après sélection s'affichent : le bloc <b>Plan de la pièce</b> (N° de plan + indice, fichier plan / CAO) et, pour chaque étape CNC de la gamme, deux champs : <b>N° programme CN</b> (ex. O1234) et <b>Fichier programme</b> (ex. piece.nc, prog.mpf).</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/be-prep.png\" alt=\"Capture de l'onglet Préparations techniques\" loading=\"lazy\">\n      <figcaption><b>Onglet Préparations tech.</b> — les commandes en attente de prépa avec leur statut ; « Préparer » ouvre la saisie des codes programme CN.</figcaption>\n    </figure>\n\n    <h3>Pas à pas</h3>\n    <ol class=\"steps\">\n      <li>Cliquez <b>Préparer</b> sur la commande concernée (ou ouvrez directement la page de préparation).</li>\n      <li>Choisissez la <b>pièce</b> dans la liste (nomenclatures avec étape CNC uniquement).</li>\n      <li>Renseignez le <b>N° de plan (+ indice)</b> et le <b>fichier plan / CAO</b> — le fichier lui-même se joint en GED depuis la nomenclature.</li>\n      <li>Pour chaque étape CNC, saisissez le <b>N° programme CN</b> et le <b>fichier programme</b>.</li>\n      <li>Cliquez <b>« Enregistrer la prépa (plan + codes) »</b> : les codes se déversent dans la nomenclature et seront <b>imprimés sur l'OF</b> du lot (colonne « N° Programme »).</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Seules les pièces dont la gamme comporte une étape sur machine <b>marquée CNC</b> apparaissent dans la liste. Si la liste est vide, marquez vos machines comme CNC (Production → Machines) et rattachez-les aux étapes de la nomenclature.</li>\n      <li>La préparation technique fait partie des <b>portes de lancement</b> : une commande « Attente prépa » ne part pas en production tant que la prépa n'est pas faite.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> les codes programme peuvent aussi être saisis directement dans la gamme de la nomenclature (champs « N° programme machine » des étapes CNC) — la page de préparation les regroupe simplement au même endroit, commande par commande.</div>\n  </section>\n\n  <!-- ══════════════════════ 4. RÉFÉRENCES ══════════════════════ -->\n  <section class=\"tab\" id=\"tab-refs\">\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Références</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le catalogue des références achetées (matières, fournitures, outils…) avec leur dernier prix unitaire et son historique. Il alimente la sélection matière/accessoires des nomenclatures et se remplit automatiquement à la validation des bons de commande, des demandes de prix, et depuis les nomenclatures du BE.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>En tête, le nombre de références et deux boutons de création : <b>« + Fournisseur / Sous-traitant »</b> et <b>« + Entrée catalogue »</b>. Puis deux rangées de filtres — <b>Catégorie</b> (Toutes, Matière, Accessoires, Outils, Produits chimiques, Consommable, Autres) et <b>Activité</b> (Tous, Seem, Semrac) — avec un champ de recherche (réf, désignation, fournisseur).</p>\n    <p>Le tableau : <b>Réf.</b>, <b>Désignation</b>, <b>Catégorie</b>, <b>Activité</b>, <b>Fournisseur</b>, <b>Dernier PU</b>, et la colonne d'actions : <b>Éditer</b> (modifier la référence), <b>Évolution</b> (courbe du prix unitaire au fil des bons de commande, avec dernier prix, % d'évolution et tableau Date / PU / Qté / Fournisseur / BC), et — uniquement si le prix est absent ou daté de plus de 6 mois — <b>Demande de prix</b> (pré-remplit la demande avec cette référence).</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/be-refs.png\" alt=\"Capture de l'onglet Références\" loading=\"lazy\">\n      <figcaption><b>Onglet Références</b> — filtres par catégorie et activité, dernier prix unitaire, et boutons Éditer / Évolution / Demande de prix par référence.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — ajouter une entrée catalogue</h3>\n    <ol class=\"steps\">\n      <li>Cliquez <b>« + Entrée catalogue »</b>.</li>\n      <li>Renseignez : Fournisseur, <b>Référence</b> (obligatoire), Catégorie (Matière / Accessoire / Outillage / Consommable / Chimique), <b>Désignation</b> (obligatoire), Prix HT (optionnel), Activité (Les deux / Seem / Semrac).</li>\n      <li><b>Enregistrer</b>. Sans prix, l'entrée reste « en attente de prix » — complétez-la via une demande de prix.</li>\n    </ol>\n\n    <h3>Pas à pas — créer un fournisseur ou un sous-traitant</h3>\n    <ol class=\"steps\">\n      <li>Cliquez <b>« + Fournisseur / Sous-traitant »</b> et choisissez le <b>Type</b>.</li>\n      <li>Renseignez le <b>Nom</b> (obligatoire), le code, l'email, le téléphone — et pour un sous-traitant, ses <b>prestations</b> (séparées par des virgules, ex. Oxydation, Sérigraphie, Zingage).</li>\n      <li><b>Créer</b> : le fournisseur devient sélectionnable dans les nomenclatures et le catalogue. La fiche complète (tarifs ST…) se gère dans le service Achats.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Le <b>bon de commande n'écrit jamais le prix</b> : le prix officiel vient des demandes de prix validées — d'où le bouton « Demande de prix » sur les références au prix manquant ou périmé (&gt; 6 mois).</li>\n      <li>Lors de l'<b>édition</b> d'une référence, le champ prix laissé vide ne change pas le prix existant (il reste piloté par les demandes de prix).</li>\n      <li>L'historique « Évolution » se remplit à chaque <b>bon de commande validé</b> : une référence jamais commandée n'a pas encore de courbe.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> utilisez « Évolution » avant de chiffrer une nomenclature — une matière dont le prix grimpe fortement mérite une nouvelle demande de prix plutôt qu'un chiffrage sur l'ancien tarif.</div>\n  </section>\n\n  <!-- ══════════════════════ 5. DASHBOARD BE ══════════════════════ -->\n  <section class=\"tab\" id=\"tab-dashboard\">\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Dashboard BE</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Vue synthétique de la charge du Bureau d'Études : ce qui attend une analyse, une nomenclature ou une préparation, et les urgences à traiter en priorité. C'est l'écran à consulter en début de journée.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <ul class=\"points\">\n      <li><b>4 tuiles KPI</b> : DTs en attente BE, Nomenclatures en cours, Préparations, Nomenclatures validées.</li>\n      <li><b>Pipeline DTs</b> : répartition En attente BE / Dans les offres / Commandes créées / Refus.</li>\n      <li><b>Alertes</b> : DT <span class=\"b b-crit\">critiques</span> (traitement prioritaire immédiat), DT <span class=\"b b-warn\">urgentes</span>, nomenclatures en attente, préparations qui bloquent la production — ou « Aucune alerte active ».</li>\n      <li><b>Accès rapides</b> : trois raccourcis vers Nomenclatures, Analyse DT et Prépa technique.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/be-dashboard.png\" alt=\"Capture du Dashboard BE\" loading=\"lazy\">\n      <figcaption><b>Dashboard BE</b> — tuiles de charge, pipeline des DT et alertes priorisées ; les accès rapides renvoient vers les onglets de travail.</figcaption>\n    </figure>\n\n    <h3>Pas à pas</h3>\n    <ol class=\"steps\">\n      <li>Consultez d'abord le bloc <b>Alertes</b> : traitez les DT critiques puis urgentes via l'accès rapide « Analyse DT ».</li>\n      <li>Vérifiez les <b>préparations</b> en attente : chacune bloque le lancement d'une commande en production.</li>\n      <li>Utilisez le <b>Pipeline DTs</b> pour suivre le devenir de vos analyses (offres, commandes, refus).</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Les compteurs sont calculés en direct à l'ouverture de la page : rechargez la page pour actualiser après un traitement.</li>\n      <li>Pour des indicateurs filtrables par période et par site, utilisez aussi <b>Tableaux de bord → Dashboard Bureau Études</b> dans la sidebar.</li>\n    </ul>\n    <div class=\"note\"><b>Info :</b> les badges des onglets (Nomenclatures, Analyse DT, Préparations tech., Références) reprennent ces mêmes compteurs — le dashboard en donne la lecture d'ensemble.</div>\n  </section>\n\n  <div class=\"docnav\">\n    <a href=\"index.html\">← Sommaire des manuels</a>\n    <a href=\"achats.html\">Achats →</a>\n  </div>\n\n  <footer class=\"doc\">\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\n  </footer>\n\n</div>\n</body>\n</html>\n",
  "commercial": "<!doctype html>\r\n<html lang=\"fr\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>Manuel — Commercial · ERP Seem Semrac</title>\r\n<link rel=\"stylesheet\" href=\"manuel.css\">\r\n</head>\r\n<body>\r\n<div class=\"wrap\">\r\n\r\n  <header class=\"doc\">\r\n    <div class=\"brandrow\">\r\n      <div class=\"logo\">SS</div>\r\n      <div>\r\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\r\n        <div class=\"eyebrow\">Manuel utilisateur</div>\r\n      </div>\r\n      <div class=\"kind\">docs/manuel/html</div>\r\n    </div>\r\n    <h1>Service <span class=\"hi\">Commercial</span></h1>\r\n    <p class=\"lede\">Le service Commercial est la porte d'entrée de toutes les affaires : il réceptionne les demandes (site internet ou directes), crée les Demandes de Travaux, transforme les analyses du Bureau d'Études en offres chiffrées, valide les commandes et gère les avoirs. Le fil conducteur est le <b>numéro d'affaire unique</b> : DT-2026-XXXX = OFF-2026-XXXX = CMD-2026-XXXX.</p>\r\n    <div class=\"metachips\">\r\n      <span class=\"chip\">👤 Pour qui : <b>Chargé(e) d'affaires / commercial</b></span>\r\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Commercial</b></span>\r\n      <span class=\"chip\">🗂 <b>8 onglets</b></span>\r\n    </div>\r\n  </header>\r\n\r\n  <nav class=\"toc\">\r\n    <div class=\"toc-t\">Sommaire</div>\r\n    <ol>\r\n      <li><a href=\"#tab-site\">Demandes site internet</a></li>\r\n      <li><a href=\"#tab-dt\">DT / Demande travaux</a></li>\r\n      <li><a href=\"#tab-offre\">Offre (PRC1-D5)</a></li>\r\n      <li><a href=\"#tab-avoirs\">Avoirs &amp; Commandes P</a></li>\r\n      <li><a href=\"#tab-clients\">Liste clients</a></li>\r\n      <li><a href=\"#tab-cmd\">Commandes validées</a></li>\r\n      <li><a href=\"#tab-affaires\">Affaires (circuit)</a></li>\r\n      <li><a href=\"#tab-dashboard\">Dashboard Commercial</a></li>\r\n    </ol>\r\n  </nav>\r\n\r\n  <!-- ══════════ 1. DEMANDES SITE INTERNET ══════════ -->\r\n  <section class=\"tab\" id=\"tab-site\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Demandes site internet</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Cet onglet réceptionne en temps réel les demandes envoyées depuis le formulaire « Contactez-nous » du site internet de l'entreprise. C'est souvent le premier contact d'un prospect : le commercial y trie les demandes, les prend en charge, puis les transforme si besoin en Demande de Travaux (onglet suivant).</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Quatre tuiles de comptage en haut de l'écran : <b>Nouvelles</b>, <b>En cours</b>, <b>Traitées</b> et <b>Total</b>. En dessous, le tableau des demandes avec les colonnes : <b>Contact</b> (nom, email et téléphone), <b>Société</b>, <b>Type de demande</b>, <b>Message</b> (aperçu tronqué à 80 caractères), <b>Priorité</b>, <b>Reçu le</b> (date et heure), <b>Statut</b> et <b>Actions</b>. Les statuts possibles : <span class=\"b b-info\">Nouveau</span> <span class=\"b b-warn\">En cours</span> <span class=\"b b-ok\">Traité ✓</span> <span class=\"b b-mut\">Archivé</span>. Tant qu'aucune demande n'est arrivée, l'écran affiche « Aucune demande reçue pour le moment ».</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/commercial-site.png\" alt=\"Capture de l'onglet Demandes site internet\" loading=\"lazy\">\r\n      <figcaption><b>Demandes site internet</b> — tuiles de comptage par statut et tableau des demandes reçues depuis le formulaire de contact du site.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas</h3>\r\n    <ol class=\"steps\">\r\n      <li>Ouvrez <b>Commercial → Demandes site internet</b> (c'est l'onglet affiché par défaut à l'arrivée sur le service).</li>\r\n      <li>Repérez les demandes au statut <span class=\"b b-info\">Nouveau</span> — la tuile « Nouvelles » vous donne le compte d'un coup d'œil.</li>\r\n      <li>Lisez le message et les coordonnées du contact, puis cliquez sur le bouton <b>Traiter</b> de la ligne pour prendre la demande en charge.</li>\r\n      <li>Si la demande débouche sur un chiffrage, passez à l'onglet <b>DT / Demande travaux</b> pour créer la Demande de Travaux correspondante (le client sera créé au passage s'il est nouveau).</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Les demandes arrivent automatiquement : il n'y a rien à saisir ici, uniquement à trier et traiter.</li>\r\n      <li>La priorité (normal / urgent / critique) est indiquée par une pastille de couleur — traitez d'abord les demandes critiques.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> l'onglet actif est mémorisé dans l'adresse de la page (ex. <code>#dt</code>, <code>#offre</code>) — vous pouvez mettre en favori l'onglet sur lequel vous travaillez le plus.</div>\r\n  </section>\r\n\r\n  <!-- ══════════ 2. DT / DEMANDE TRAVAUX ══════════ -->\r\n  <section class=\"tab\" id=\"tab-dt\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>DT / Demande travaux</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La Demande de Travaux (DT) est l'acte de naissance d'une affaire : elle enregistre le client, les pièces demandées (référence, plan, quantités) et les exigences. Sa création attribue le <b>numéro d'affaire unique</b> qui suivra le dossier jusqu'à la facture. Une fois validée, la DT part au Bureau d'Études pour analyse et chiffrage.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>En haut : un champ <b>Rechercher…</b> et le bouton <b>Créer</b> (ouvre le formulaire de nouvelle DT). L'onglet est divisé en deux sous-onglets à bascule, chacun avec son compteur :</p>\r\n    <h3>Sous-onglet « DT enregistrées non finies »</h3>\r\n    <p>Les DT en cours de saisie ou en attente de validation. Le tableau affiche : <b>N° Affaire / DT</b>, <b>Client</b>, <b>Pièce(s)</b> (avec quantités), <b>Type</b>, <b>Analyste</b>, <b>Priorité</b>, <b>Statut</b> et <b>Actions</b>. Trois boutons par ligne : <b>Valider</b> (envoie la DT au BE), <b>Modifier</b> (crayon, ouvre la fiche d'édition) et <b>Supprimer</b> (poubelle).</p>\r\n    <h3>Sous-onglet « DT validées »</h3>\r\n    <p>Les DT déjà envoyées au BE ou plus avancées dans le circuit. Les statuts que vous y rencontrerez : <span class=\"b b-warn\">En attente analyse BE</span> <span class=\"b b-info\">Nomenclature à faire</span> <span class=\"b b-info\">Dans la liste des offres</span> <span class=\"b b-ok\">Commande créée ✓</span> <span class=\"b b-crit\">Refus</span>. Les lignes validées portent un badge vert « Validée » à la place du bouton Valider, mais restent modifiables (crayon).</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/commercial-dt.png\" alt=\"Capture de l'onglet DT / Demande travaux\" loading=\"lazy\">\r\n      <figcaption><b>DT / Demande travaux</b> — sous-onglets « non finies / validées » avec compteurs, et tableau des DT avec statut du circuit.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — créer une DT</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>Créer</b> : le formulaire « Nouvelle DT » s'ouvre. Le <b>N° DT</b> est attribué automatiquement (DT-2026-XXXX) — c'est le futur numéro d'affaire.</li>\r\n      <li>Recherchez le <b>client</b> dans le champ à autocomplétion. S'il n'existe pas, cliquez sur <b>Nouveau client</b> : un sous-formulaire s'ouvre (raison sociale obligatoire, SIRET, contact, email, téléphone, adresse, mode de facturation) ; le client créé est aussitôt sélectionné.</li>\r\n      <li>Choisissez la <b>priorité</b> (Normal / Urgent / Critique) et la <b>date besoin</b> du client.</li>\r\n      <li>Remplissez le premier bloc <b>Produit</b> (voir tableau des champs ci-dessous). Un point important : l'<b>Activité</b> (SEEM/SEMRAC) et le <b>Type de DT</b> se choisissent <b>par produit</b> — un produit peut être « Nouveau produit » et un autre « Produit à jour » dans la même DT.</li>\r\n      <li>Besoin de chiffrer plusieurs quantités pour la même pièce ? Cliquez sur <b>+ Ajouter une quantité</b> : chaque case quantité donnera sa propre ligne de prix dans l'analyse du BE.</li>\r\n      <li>Ajoutez d'autres pièces avec <b>Produit supplémentaire</b> si l'affaire en compte plusieurs, puis cliquez sur <b>Créer la DT</b>. Elle apparaît dans « DT enregistrées non finies ».</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — valider une DT (envoi au BE)</h3>\r\n    <ol class=\"steps\">\r\n      <li>Dans « DT enregistrées non finies », cliquez sur <b>Valider</b> sur la ligne concernée et confirmez.</li>\r\n      <li>L'ERP oriente automatiquement la DT selon son contenu : s'il y a au moins une pièce nouvelle ou à mettre à jour, elle part dans la file <b>Nomenclatures à créer</b> du BE ; s'il s'agit d'une mise à jour de prix ou de pièces déjà à jour, elle part <b>directement en Analyse DT</b> du BE.</li>\r\n      <li>La DT bascule dans le sous-onglet « DT validées » avec le statut <span class=\"b b-warn\">En attente analyse BE</span> ou <span class=\"b b-info\">Nomenclature à faire</span>. Quand le BE aura terminé son analyse, l'offre apparaîtra dans l'onglet <b>Offre (PRC1-D5)</b>.</li>\r\n    </ol>\r\n\r\n    <h3>Formulaire « Nouvelle DT » — champ par champ</h3>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-commercial-dt.png\" alt=\"Formulaire de création d'une DT\" loading=\"lazy\">\r\n      <figcaption><b>Formulaire Nouvelle DT</b> — en-tête (client, priorité, date) puis un bloc par produit avec ses quantités, son activité, son type et ses exigences.</figcaption>\r\n    </figure>\r\n    <div class=\"tbl\">\r\n      <table>\r\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n        <tbody>\r\n          <tr><td>Client</td><td>Recherche / autocomplétion</td><td>Oui</td><td>Client existant, ou création à la volée via « Nouveau client ».</td></tr>\r\n          <tr><td>N° DT</td><td>Automatique (lecture seule)</td><td>—</td><td>Numéro d'affaire unique DT-AAAA-XXXX, repris par l'offre et la commande.</td></tr>\r\n          <tr><td>Priorité</td><td>Liste : Normal / Urgent / Critique</td><td>Non</td><td>Pilote la pastille de priorité dans les listes.</td></tr>\r\n          <tr><td>Date besoin</td><td>Date</td><td>Non</td><td>Date souhaitée par le client.</td></tr>\r\n          <tr><td>Réf. interne pièce</td><td>Texte (suggestions)</td><td>Oui (par produit)</td><td>N° de nomenclature / référence de la pièce chez nous.</td></tr>\r\n          <tr><td>Nom du plan</td><td>Texte (suggestions)</td><td>Non</td><td>Ex. PLAN-DISSIP-A24-v3.</td></tr>\r\n          <tr><td>Réf. pièce client</td><td>Texte (suggestions)</td><td>Non</td><td>Référence de la pièce chez le client (ex. LGR-A-20485).</td></tr>\r\n          <tr><td>Quantité</td><td>Nombre entier</td><td>Oui (par produit)</td><td>Quantité principale à chiffrer.</td></tr>\r\n          <tr><td>Quantités supplémentaires</td><td>Une case par quantité (bouton +)</td><td>Non</td><td>Chaque quantité ajoutée aura son propre prix dans l'analyse du BE.</td></tr>\r\n          <tr><td>Activité</td><td>Liste : SEEM / SEMRAC</td><td>Oui (par produit)</td><td>Site qui produira la pièce.</td></tr>\r\n          <tr><td>Type de DT</td><td>Liste : Maj prix / Maj produit / Nouveau produit / Produit à jour</td><td>Oui (par produit)</td><td>Détermine le circuit au BE (nomenclature à créer ou analyse directe).</td></tr>\r\n          <tr><td>Plan — PDF ou STEP</td><td>Fichier (.pdf, .step, .stp)</td><td>Non</td><td>Plan joint au produit, repris par le BE.</td></tr>\r\n          <tr><td>Exigences normatives</td><td>Cases : ISO 9001, EN 9100, REACH, RoHS, EN 13485</td><td>Non</td><td>Exigences client tracées jusque dans l'offre (bloc traçabilité).</td></tr>\r\n          <tr><td>Oxydation anodique sulfurique</td><td>Case à cocher</td><td>Non</td><td>Traitement de surface OAS ; ouvre l'option complémentaire ci-dessous.</td></tr>\r\n          <tr><td>Oxydation noire (en complément)</td><td>Case à cocher</td><td>Non</td><td>Visible uniquement si l'oxydation anodique est cochée.</td></tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>À la création : le client est obligatoire, il faut au moins une pièce avec quantité, et chaque produit doit avoir son Activité et son Type de DT — sinon l'enregistrement est refusé avec un message d'erreur.</li>\r\n      <li><b>Auto-complétion du répertoire</b> : quand vous saisissez une réf. client ou une réf. interne déjà connue, l'ERP relie automatiquement les autres champs vides (réf. interne ↔ réf. client ↔ plan) depuis le répertoire des références clients.</li>\r\n      <li>Le bouton <b>Modifier</b> ouvre une fenêtre d'édition complète (client, priorité, délai, pièces) ; les modifications sont <b>automatiquement répercutées dans l'analyse DT du Bureau d'Études</b>.</li>\r\n    </ul>\r\n    <div class=\"note\"><b>Verrou d'édition :</b> si un collègue est déjà en train de modifier la même DT, l'ERP vous l'indique (« DT en cours d'édition par… ») et bloque l'ouverture — réessayez quand il aura terminé.</div>\r\n    <div class=\"warn\"><b>Attention :</b> la suppression d'une DT (bouton poubelle) est définitive après confirmation. Ne supprimez jamais une DT déjà partie au BE sans vous coordonner avec lui.</div>\r\n  </section>\r\n\r\n  <!-- ══════════ 3. OFFRE (PRC1-D5) ══════════ -->\r\n  <section class=\"tab\" id=\"tab-offre\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>Offre (PRC1-D5)</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est ici que le devis prend forme et se joue : les offres générées par le BE après analyse y arrivent « à traiter ». Le commercial fixe la marge, envoie l'offre au client, gère la négociation (versions successives) puis la validation — qui crée automatiquement la commande en Production.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Deux sous-onglets à bascule avec compteurs, et quatre tuiles de pipeline : <b>Offre en attente</b>, <b>Attente réponse client</b>, <b>Acceptées</b>, <b>Annulées</b>.</p>\r\n    <h3>Sous-onglet « Offres à traiter »</h3>\r\n    <p>Les offres en statut <span class=\"b b-warn\">Offre en attente</span>, <span class=\"b b-warn\">En attente réponse client</span> ou <span class=\"b b-info\">Négociation</span>. Colonnes du tableau : <b>N° OFF / Affaire</b> (avec badge <b>v2, v3…</b> si l'offre a été révisée en négociation), <b>DT liée</b>, <b>Client</b>, <b>Pièces · CRU · PV</b> (par pièce : coût de revient unitaire et prix de vente calculé avec la marge de l'offre, plus les puces « ×quantité → PV/pièce » pour les chiffrages multi-quantités), <b>Montant HT</b>, <b>Coût revient</b>, <b>Marge</b>, <b>Validité</b>, <b>Statut</b> et <b>Actions</b>. Une pastille <span class=\"b b-warn\">À relancer</span> apparaît sous le statut quand une offre envoyée attend une réponse depuis plus de 7 jours.</p>\r\n    <h3>Sous-onglet « Offres validées »</h3>\r\n    <p>Les offres <span class=\"b b-ok\">Acceptée ✓</span> par le client — prêtes à devenir des commandes (ou déjà transformées).</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/commercial-offre.png\" alt=\"Capture de l'onglet Offre\" loading=\"lazy\">\r\n      <figcaption><b>Offre (PRC1-D5)</b> — pipeline en tuiles, tableau des offres avec détail CRU/PV par pièce et boutons d'action selon le statut.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — traiter une offre de bout en bout</h3>\r\n    <ol class=\"steps\">\r\n      <li>Une offre arrive du BE en statut <span class=\"b b-warn\">Offre en attente</span>. Cliquez sur le bouton <b>Éditer</b> (crayon) : la page d'édition s'ouvre avec, pour chaque produit, le <b>résumé des coûts issu de l'analyse DT</b> (matière, accessoires, MO + machine, sous-traitance, frais généraux par lot, CRU par pièce) et le <b>coefficient de marge</b> à saisir (PV = CRU × coefficient ; le taux de marque, la marge en € et le PV se recalculent en direct). Le tableau interne « COEFFICIENT DE MARGES » est consultable depuis cette page. Les certifications exigées et les avoirs applicables du client y sont rappelés.</li>\r\n      <li>De retour sur la liste, cliquez sur <b>Envoyer</b> puis confirmez : l'offre passe en <span class=\"b b-warn\">En attente réponse client</span>.</li>\r\n      <li>Pour transmettre le devis, cliquez sur l'icône <b>PDF</b> : une fenêtre d'impression s'ouvre avec le devis au logo de la société (choisissez « Enregistrer en PDF »).</li>\r\n      <li><b>Si le client négocie</b> : cliquez sur <b>Négocier</b>, indiquez éventuellement le point à négocier — l'offre est rouverte en révision (nouvelle version v2, v3…) et la page d'édition s'ouvre pour ajuster prix et marge. Le bouton d'envoi devient <b>Renvoyer</b>.</li>\r\n      <li><b>Si le client accepte</b> : cliquez sur <b>Valider</b>. La fenêtre récapitule montant et marge et propose une <b>date de livraison confirmée</b> (facultative — la Production peut la fixer ensuite). En confirmant : l'offre passe en <span class=\"b b-ok\">Acceptée ✓</span>, la <b>commande est créée</b> (visible en Production « à programmer ») et les <b>avoirs en cours du client sont automatiquement déduits</b>.</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — créer une offre manuellement</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>Créer</b> : le formulaire « Nouvelle offre » s'ouvre.</li>\r\n      <li>Sélectionnez la <b>DT associée</b> (seules les DT au statut « Dans la liste des offres » sont proposées), la <b>date de validité</b> et le <b>montant HT</b> ; le vendeur et le délai de livraison estimé sont facultatifs.</li>\r\n      <li>Cliquez sur <b>Envoyer l'offre</b>. Le numéro d'offre reprend le numéro d'affaire de la DT.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li><b>Marge = taux de marque</b> : (PV − PR) / PV. Le coefficient multiplicateur est la référence : ×2 → 50 %, ×2,5 → 60 %, ×3,05 → 67 %.</li>\r\n      <li>Le PV affiché dans la colonne « Pièces · CRU · PV » est calculé avec la <b>marge de l'offre</b> (fixée par le commercial), pas avec une marge d'analyse.</li>\r\n      <li>La validation d'une offre est <b>idempotente</b> : si la commande existe déjà, l'ERP le signale (« déjà créée ») sans créer de doublon.</li>\r\n      <li>Une offre déjà envoyée n'a plus de bouton « Envoyer » : seuls <b>Valider</b>, <b>Négocier</b>, le PDF, l'édition et la suppression restent disponibles.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> surveillez les pastilles <span class=\"b b-warn\">À relancer</span> — plus de 7 jours sans réponse client, c'est le moment de rappeler.</div>\r\n    <div class=\"warn\"><b>Attention :</b> pour le devis PDF, votre navigateur doit autoriser les fenêtres pop-up ; sinon l'ERP vous le signale et rien ne s'ouvre.</div>\r\n  \r\n    <div class=\"warn\"><b>Mode de règlement « Proforma » — le client paie avant qu'on engage quoi que ce soit.</b>\r\n      Choisissez <b>Proforma</b> dans <i>Mode de règlement</i> (page d'édition de l'offre) lorsque vous voulez être payé d'avance.\r\n      À l'acceptation de l'offre : la commande est créée normalement, <b>une facture proforma part immédiatement en Comptabilité &rsaquo; Facturation</b>,\r\n      mais <b>aucune préparation technique ni demande d'achat n'est lancée</b> — rien n'est commandé, rien n'est engagé.\r\n      Dès que cette facture passe au statut <b>payée</b>, la préparation technique et les demandes d'achat se déclenchent automatiquement,\r\n      et la production peut suivre son cours normal. Entre-temps les bons de travaux existent mais restent hors planning,\r\n      faute de matière réceptionnée.</div>\r\n</section>\r\n\r\n  <!-- ══════════ 4. AVOIRS & COMMANDES P ══════════ -->\r\n  <section class=\"tab\" id=\"tab-avoirs\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Avoirs &amp; Commandes P</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Cet onglet regroupe deux suites du service après-vente : les <b>avoirs</b> accordés aux clients (avances, retours, gestes commerciaux) et les <b>commandes prioritaires</b> (Commandes P) issues des retours clients acceptés en refabrication côté Qualité. Les avoirs sont ensuite déduits automatiquement des factures ou de la commande suivante.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Deux sous-onglets à bascule : <b>Avoirs</b> (avec compteur) et <b>Commandes P</b> (compteur des commandes restant à lancer).</p>\r\n    <h3>Sous-onglet « Avoirs »</h3>\r\n    <p>Quatre tuiles : <b>Avoirs actifs</b>, <b>Partiels</b>, <b>Clôturés</b>, <b>Total</b>. Le tableau liste : <b>N° Avoir</b>, <b>Client</b>, <b>Motif</b>, <b>Montant</b>, <b>Solde</b> (restant à consommer, en vert s'il est positif), <b>Date</b>, <b>Saisi par</b>, <b>Statut</b> — <span class=\"b b-ok\">Actif</span> <span class=\"b b-warn\">Partiel</span> <span class=\"b b-mut\">Clôturé</span>, complété le cas échéant du badge de décision Direction — et <b>Actions</b> (modifier / supprimer).</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/commercial-avoirs.png\" alt=\"Capture du sous-onglet Avoirs\" loading=\"lazy\">\r\n      <figcaption><b>Avoirs</b> — tuiles par statut et liste des avoirs avec montant, solde restant et suivi de qui a saisi.</figcaption>\r\n    </figure>\r\n    <h3>Sous-onglet « Commandes P »</h3>\r\n    <p>Le bandeau rappelle le circuit : un retour client accepté en relance (Qualité → NC client → « Retour ») crée une commande prioritaire numérotée <b>CMDP-AAAA-XX</b> sur l'affaire d'origine. Le tableau affiche : <b>N° Commande P</b>, <b>Client</b>, <b>Réf. / Désignation</b>, <b>Qté</b>, <b>Coût revient unit.</b> (ou la mention « à chiffrer »), <b>Montant estimé</b>, <b>NC origine</b>, <b>Statut</b> — <span class=\"b b-warn\">À faire</span> ou <span class=\"b b-ok\">Lancée</span> —, <b>Date</b> et l'action <b>Lancer la production</b>.</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/commercial-avoirs-cmdp.png\" alt=\"Capture du sous-onglet Commandes P\" loading=\"lazy\">\r\n      <figcaption><b>Commandes P</b> — commandes prioritaires issues des retours clients, avec leur NC d'origine et le bouton de lancement en production.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — émettre un avoir</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>Créer</b> : le formulaire « Nouvel avoir » s'ouvre.</li>\r\n      <li>Sélectionnez le <b>client</b> et le <b>type d'avoir</b> : <b>Avance</b> (matière / outil / consignation — saisie par le Commercial) ou <b>Réclamation</b> (réservée au service Qualité).</li>\r\n      <li>Choisissez la <b>restitution</b> : « Déduire d'une facture en cours » ou « Déduire de la commande suivante » (l'avoir sera alors proposé automatiquement à la prochaine offre du client).</li>\r\n      <li>Facultatif : <b>chargez une facture client</b> (cela renseigne automatiquement l'affaire et sélectionne le client) et/ou <b>rattachez l'avoir à une affaire</b>. Un aperçu du numéro s'affiche : <b>AV-AAAA-&lt;affaire&gt;</b> si rattaché, <b>AVL-AAAA-…</b> (libre, incrémental) sinon.</li>\r\n      <li>Saisissez le <b>montant</b>, la <b>date</b> et le <b>motif</b>. Si nécessaire, cochez « <b>Soumettre cet avoir à la validation de la Direction</b> » — il apparaîtra alors dans la file « À valider » du service Direction.</li>\r\n      <li>Cliquez sur <b>Émettre l'avoir</b>. Il apparaît dans la liste en <span class=\"b b-ok\">Actif</span> ; son solde diminuera au fil des déductions jusqu'à <span class=\"b b-mut\">Clôturé</span>.</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — lancer une commande prioritaire</h3>\r\n    <ol class=\"steps\">\r\n      <li>Ouvrez le sous-onglet <b>Commandes P</b> et repérez les lignes <span class=\"b b-warn\">À faire</span>.</li>\r\n      <li>Cliquez sur <b>Lancer la production</b> puis confirmez : l'ERP crée la commande prioritaire, un lot <b>LOTP</b> et les bons de travail <b>BDTP/BDSP</b>, qui apparaissent <b>encadrés en rouge</b> dans le planning de Production.</li>\r\n      <li>La ligne passe en <span class=\"b b-ok\">Lancée</span> avec le numéro de la commande créée. Le suivi se poursuit côté Production.</li>\r\n    </ol>\r\n\r\n    <h3>Formulaire « Nouvel avoir » — champ par champ</h3>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-commercial-avoir.png\" alt=\"Formulaire de création d'un avoir\" loading=\"lazy\">\r\n      <figcaption><b>Formulaire Nouvel avoir</b> — type, mode de restitution, rattachement à une facture ou une affaire, et case de validation Direction.</figcaption>\r\n    </figure>\r\n    <div class=\"tbl\">\r\n      <table>\r\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n        <tbody>\r\n          <tr><td>Client</td><td>Liste des clients</td><td>Oui</td><td>Bénéficiaire de l'avoir (rempli automatiquement si une facture est chargée).</td></tr>\r\n          <tr><td>Type d'avoir</td><td>Liste : Avance / Réclamation</td><td>Oui</td><td>Avance = Commercial ; Réclamation = circuit Qualité.</td></tr>\r\n          <tr><td>Restitution de l'avoir</td><td>Liste : facture en cours / commande suivante</td><td>Oui</td><td>« Commande suivante » = proposé automatiquement à la prochaine offre.</td></tr>\r\n          <tr><td>Origine</td><td>Liste : Commercial-avance / Achat de matière / Non-conformité</td><td>Non</td><td>« Achat de matière » ouvre le bloc de liaison des factures.</td></tr>\r\n          <tr><td>Facture d'affaire interne (cible)</td><td>Liste des factures</td><td>Non</td><td>Visible si origine = matière : facture sur laquelle l'avoir sera déduit.</td></tr>\r\n          <tr><td>Charger une facture client</td><td>Liste des factures</td><td>Non</td><td>Renseigne automatiquement l'affaire et le client.</td></tr>\r\n          <tr><td>Rattacher à une affaire</td><td>N° d'affaire (suggestions)</td><td>Non</td><td>Vide = avoir libre AVL-AAAA-… ; rempli = AV-AAAA-&lt;affaire&gt;.</td></tr>\r\n          <tr><td>Montant (€)</td><td>Nombre</td><td>Oui</td><td>Montant de l'avoir (doit être supérieur à 0).</td></tr>\r\n          <tr><td>Date de l'avoir</td><td>Date</td><td>Oui</td><td>Date d'émission.</td></tr>\r\n          <tr><td>Motif / Description</td><td>Texte libre</td><td>Oui</td><td>Justification de l'avoir.</td></tr>\r\n          <tr><td>Validation Direction</td><td>Case à cocher</td><td>Non</td><td>Soumet l'avoir à la file de validation de la Direction.</td></tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li><b>Avoir = prix de vente</b> des pièces retournées (AV-AAAA-XX) ; <b>Commande P = coût de revient</b> (CMDP-AAAA-XX) : deux logiques différentes pour le même retour client.</li>\r\n      <li>Le bouton <b>Modifier</b> d'un avoir rouvre le même formulaire pré-rempli (titre « Modifier l'avoir ») ; l'enregistrement met à jour l'avoir existant.</li>\r\n      <li>Les avoirs « à déduire de la commande suivante » sont proposés automatiquement dans la page d'édition d'offre du même client.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> le lancement d'une commande prioritaire crée immédiatement lot et bons de travail prioritaires dans le planning — assurez-vous que le coût de revient est chiffré et que la décision de refabrication est actée côté Qualité.</div>\r\n  </section>\r\n\r\n  <!-- ══════════ 5. LISTE CLIENTS ══════════ -->\r\n  <section class=\"tab\" id=\"tab-clients\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Liste clients</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Le référentiel clients de l'entreprise : identité, contacts multiples, adresses, mode de règlement, et le chiffre d'affaires facturé par client. C'est ici que l'on crée et met à jour les fiches ; les informations sont propagées automatiquement aux DT, offres et commandes.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>En haut : le compteur de clients, l'outil de <b>sélection multiple</b> (suppression groupée), une <b>recherche ciblée</b> par champ (Raison sociale, Contact, Email, Téléphone, Mode facturation, SIRET), le bouton <b>Exporter (Excel)</b> — tous les clients et les produits qu'ils ont commandés, avec feuille Données et feuille TCD — et le bouton <b>Nouveau client</b>.</p>\r\n    <p>Une barre de filtres <b>Activité</b> (Tous / SEEM / SEMRAC / SEEM &amp; SEMRAC, chacun avec son compte) et des boutons de <b>tri</b> : A → Z, CA de l'année en cours, CA total (le CA est le chiffre d'affaires <b>facturé HT</b>). Le tableau affiche : <b>Raison sociale</b> (avec l'identifiant), <b>Contact</b> (et sa fonction), <b>Email</b>, <b>Téléphone</b>, <b>Mode facturation</b>, <b>SIRET</b>, <b>CA année</b>, <b>CA total</b>, <b>Crédits</b> (pastille orange si le client a un avoir en cours) et <b>Actions</b> (crayon Modifier / poubelle Supprimer). Un clic n'importe où sur la ligne ouvre la <b>fiche client</b>.</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/commercial-clients.png\" alt=\"Capture de l'onglet Liste clients\" loading=\"lazy\">\r\n      <figcaption><b>Liste clients</b> — filtres par activité, tris par CA, colonnes de CA facturé et accès à la fiche client d'un clic sur la ligne.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — créer ou modifier un client</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>Nouveau client</b> (ou sur le crayon d'une ligne existante) : la fenêtre client s'ouvre.</li>\r\n      <li>Saisissez la <b>raison sociale</b> (seul champ obligatoire). Astuce : saisissez d'abord le <b>N° TVA intracommunautaire</b> — le <b>SIRET</b> se remplit automatiquement (retrait du préfixe pays et des espaces).</li>\r\n      <li>Choisissez le <b>mode de règlement</b> (Proforma, Virement 30/45/60 j, 30/45/60 j net ou fin de mois, Traite 30 j) : il sera appliqué par défaut aux factures de ce client.</li>\r\n      <li>Ajoutez les <b>contacts</b> (nom, fonction, email, téléphone) avec « Ajouter un contact » ; cochez la puce ◉ du contact <b>principal</b>.</li>\r\n      <li>Renseignez l'<b>adresse postale</b> (rue, code postal, ville). Si la facturation part ailleurs, cochez « <b>Adresse de facturation différente</b> » et complétez le bloc dédié.</li>\r\n      <li>Cliquez sur <b>Créer le client</b> (ou <b>Enregistrer</b> en modification).</li>\r\n    </ol>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-commercial-client.png\" alt=\"Formulaire de création / modification d'une fiche client\" loading=\"lazy\">\r\n      <figcaption><b>Fenêtre client</b> — seule la <b>raison sociale</b> est obligatoire ; le N° TVA intracommunautaire remplit le SIRET automatiquement, le mode de règlement devient le défaut des factures, et les blocs <b>contacts</b> (avec la puce du contact principal) &amp; <b>adresse</b> (option « adresse de facturation différente ») se déplient à la demande. À l'enregistrement, la fiche est immédiatement disponible dans les DT, offres et commandes.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — consulter la fiche client</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur la ligne du client : la fiche s'ouvre avec l'identité complète (contact principal, email, adresse, SIRET, TVA, mode de règlement, mode de livraison).</li>\r\n      <li>Le bloc <b>Pilotage 360</b> montre : CA facturé, encours impayé, marge cumulée, offres gagnées / perdues et crédit, puis les tableaux Commandes et Factures.</li>\r\n      <li>Le tableau <b>Produits achetés par ce client</b> croise réf. interne ↔ réf. client ↔ désignation ↔ plan (ouvrable d'un clic s'il est en GED) ↔ affaires rattachées : chaque numéro d'affaire est cliquable vers sa fiche.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le CA affiché est le chiffre d'affaires <b>facturé</b> (HT) : un client sans facture affiche « — » même s'il a des commandes en cours.</li>\r\n      <li>La modification d'un client est protégée par le <b>verrou d'édition</b> : si un collègue édite déjà la fiche, vous êtes prévenu et devez attendre.</li>\r\n      <li>Les filtres Activité et la recherche se cumulent : vous pouvez chercher « virement » dans le mode de facturation en n'affichant que les clients SEEM.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> la suppression d'un client (individuelle ou groupée) est définitive après confirmation. Vérifiez qu'aucune affaire en cours ne lui est rattachée.</div>\r\n  </section>\r\n\r\n  <!-- ══════════ 6. COMMANDES VALIDÉES ══════════ -->\r\n  <section class=\"tab\" id=\"tab-cmd\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">6</span><h2>Commandes validées</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La vue de contrôle du carnet de commandes : toutes les commandes clients validées des <b>365 derniers jours</b>, avec leur montant, leur date de livraison et leur état d'avancement. C'est un onglet de consultation — la commande naît de la validation d'une offre (onglet Offre), pas d'une saisie directe ici.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Le compteur de commandes sur un an, une <b>recherche ciblée</b> (Client, Pièce(s), Statut, N° affaire) et le tableau : <b>N° CMD / Affaire</b>, <b>Client</b>, <b>Pièce(s)</b>, <b>Montant</b>, <b>Date CMD</b>, <b>Livraison</b> et <b>Statut</b>. Les statuts de commande : <span class=\"b b-warn\">À programmer</span> <span class=\"b b-info\">Attente prépa</span> <span class=\"b b-info\">Attente matière</span> <span class=\"b b-ok\">En production</span> <span class=\"b b-info\">À expédier</span> <span class=\"b b-ok\">Expédié ✓</span> <span class=\"b b-crit\">Annulé</span>.</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/commercial-cmd.png\" alt=\"Capture de l'onglet Commandes validées\" loading=\"lazy\">\r\n      <figcaption><b>Commandes validées</b> — carnet de commandes sur 365 jours avec statut d'avancement de chaque commande.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas</h3>\r\n    <ol class=\"steps\">\r\n      <li>Utilisez la recherche ciblée pour retrouver une commande : choisissez le champ (ex. « N° affaire ») puis tapez votre critère — la liste se filtre en direct.</li>\r\n      <li>Lisez le statut pour connaître l'étape en cours ; pour le détail production (lots, BDT, coûts), ouvrez l'affaire correspondante dans l'onglet <b>Affaires (circuit)</b>.</li>\r\n      <li>Si un client demande où en est sa commande, la colonne <b>Livraison</b> donne la date confirmée (ou « — » si la Production ne l'a pas encore fixée).</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>La liste est limitée aux 365 derniers jours pour rester lisible ; les commandes plus anciennes restent consultables via la fiche affaire.</li>\r\n      <li>Le numéro de commande reprend le numéro d'affaire : CMD-2026-XXXX = OFF-2026-XXXX = DT-2026-XXXX.</li>\r\n    </ul>\r\n    <div class=\"note\"><b>Bon à savoir :</b> l'avancement fin (BDT soldés, coûts réels, marge) se consulte dans la fiche affaire ou côté Production — cet onglet donne la photo commerciale du carnet.</div>\r\n  </section>\r\n\r\n  <!-- ══════════ 7. AFFAIRES (CIRCUIT) ══════════ -->\r\n  <section class=\"tab\" id=\"tab-affaires\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">7</span><h2>Affaires (circuit)</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La vue « dossier » du Commercial : chaque numéro d'affaire regroupe tout son circuit — DT → offre → commande → production → livraison → facturation. En un tableau, vous voyez où en est chaque affaire ; en un clic, vous ouvrez sa fiche 360 complète.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Le tableau des affaires, triées de la plus récente à la plus ancienne : <b>N° Affaire</b>, <b>Client</b>, <b>Circuit</b> (trois pastilles DT / Offre / Commande, colorées si l'étape existe, grisées sinon), <b>Montant</b> (celui de la commande, sinon de l'offre), <b>Statut</b> (le plus avancé du circuit) et le bouton <b>Ouvrir</b>.</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/commercial-affaires.png\" alt=\"Capture de l'onglet Affaires\" loading=\"lazy\">\r\n      <figcaption><b>Affaires (circuit)</b> — une ligne par numéro d'affaire avec les pastilles d'avancement DT / Offre / Commande.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — exploiter la fiche affaire 360</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur une ligne (ou sur <b>Ouvrir</b>) : la fiche « Affaire N° … » s'ouvre.</li>\r\n      <li>En tête, le bloc <b>Pilotage 360</b> : montant offre, montant commande, CA facturé, coût de revient, marge (en € et en %) et avancement (BDT soldés / total). Juste dessous, le <b>chemin de l'affaire</b> en 6 étapes : DT, Offre, Commande, Production, Livraison, Facturation — chaque étape s'allume quand elle est franchie.</li>\r\n      <li>Descendez pour le détail, tableau par tableau : demandes de travaux, offres, commandes, lots de production, bons de travail avec opérateurs et temps, matières consommées, bons de livraison, factures, PV de contrôle, non-conformités et avoirs liés. Les liens « Analyse », « Éditer », « Suivi » renvoient directement vers le BE, l'édition d'offre ou le suivi de production.</li>\r\n      <li>Le bouton « Retour aux affaires » vous ramène à la liste.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>L'affaire agrège tout ce qui porte le même numéro d'affaire : c'est le fil conducteur de l'ERP — d'où l'importance de ne jamais créer d'offre ou de commande « hors DT ».</li>\r\n      <li>Si une affaire n'a ni DT, ni offre, ni commande, la fiche l'indique clairement (« Aucune donnée trouvée »).</li>\r\n      <li>La marge affichée est calculée sur le CA facturé quand il existe, sinon sur le budget : elle s'affine au fil de la vie de l'affaire.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> la fiche affaire est le meilleur écran à ouvrir pendant un appel client — tout le dossier y est, de la demande initiale à la facture.</div>\r\n  </section>\r\n\r\n  <!-- ══════════ 8. DASHBOARD COMMERCIAL ══════════ -->\r\n  <section class=\"tab\" id=\"tab-dashboard\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">8</span><h2>Dashboard Commercial</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Le tableau de bord de pilotage du service : chiffre d'affaires commandé, charge du pipeline (DT chez le BE, offres sans réponse, commandes à programmer) et poids des avoirs actifs. Il se calcule en direct sur les données réelles du service.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Quatre indicateurs en tuiles : <b>CA commandé</b> du mois en cours (avec le cumul annuel en sous-titre), <b>DT en attente BE</b> (à analyser), <b>Offres en cours</b> (sans réponse client) et <b>Avoirs actifs</b> (montant total et nombre). En dessous : le graphique en barres <b>CA commandé mensuel</b> de l'année (un mois par ligne jusqu'au mois courant, avec le total cumulé), le bloc <b>Top Clients</b>, puis le <b>Pipeline Commercial</b> en trois colonnes — DT en attente BE, Offres en attente de réponse, Commandes à programmer — chaque affaire y figurant sous forme de carte (numéro + client).</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/commercial-dashboard.png\" alt=\"Capture du Dashboard Commercial\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Commercial</b> — KPI du mois, CA mensuel de l'année et pipeline des affaires en cours en trois colonnes.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas</h3>\r\n    <ol class=\"steps\">\r\n      <li>Commencez la journée par ce tableau de bord : les trois colonnes du pipeline vous disent immédiatement où agir (relancer le BE, relancer un client, pousser une commande vers la programmation).</li>\r\n      <li>Comparez le CA du mois au cumul annuel pour situer votre progression ; le graphique mensuel montre la saisonnalité.</li>\r\n      <li>Surveillez la tuile <b>Avoirs actifs</b> : un montant qui grimpe signale des retours ou avances à solder.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le CA de ce tableau de bord est le CA <b>commandé</b> (montants des commandes validées de l'année), à distinguer du CA <b>facturé</b> affiché dans la Liste clients.</li>\r\n      <li>Un tableau de bord Commercial plus complet et filtrable existe aussi dans le service <b>Tableaux de bord</b> de la sidebar.</li>\r\n    </ul>\r\n    <div class=\"note\"><b>Bon à savoir :</b> les compteurs affichés sur les onglets du service (badges) reprennent les mêmes chiffres : nombre de demandes site, de DT, d'offres à traiter, d'avoirs, de clients, de commandes et d'affaires.</div>\r\n  </section>\r\n\r\n  <div class=\"docnav\">\r\n    <a href=\"index.html\">← Sommaire des manuels</a>\r\n    <a href=\"be.html\">Bureau d'Études →</a>\r\n  </div>\r\n\r\n  <footer class=\"doc\">\r\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\r\n  </footer>\r\n\r\n</div>\r\n</body>\r\n</html>\r\n",
  "compta": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Manuel — Comptabilité · ERP Seem Semrac</title>\n<link rel=\"stylesheet\" href=\"manuel.css\">\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header class=\"doc\">\n    <div class=\"brandrow\">\n      <div class=\"logo\">SS</div>\n      <div>\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\n        <div class=\"eyebrow\">Manuel utilisateur</div>\n      </div>\n      <div class=\"kind\">docs/manuel/html</div>\n    </div>\n    <h1>Service <span class=\"hi\">Comptabilité</span></h1>\n    <p class=\"lede\">La Comptabilité suit tout l'argent de l'entreprise : les factures clients à encaisser, les factures fournisseurs et sous-traitants à régler, les écritures du Grand Livre (alimentées automatiquement par l'activité), la TVA à déclarer et la trésorerie. Vous apprendrez ici à suivre et encaisser vos factures, saisir et payer les factures fournisseurs, préparer la déclaration de TVA et exporter le FEC pour l'expert-comptable.</p>\n    <div class=\"metachips\">\n      <span class=\"chip\">👤 Pour qui : <b>Comptable</b> (écriture — l'export FEC est aussi ouvert à la Direction)</span>\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Comptabilité</b></span>\n      <span class=\"chip\">🗂 <b>5 onglets</b></span>\n    </div>\n  </header>\n\n  <nav class=\"toc\">\n    <div class=\"toc-t\">Sommaire</div>\n    <ol>\n      <li><a href=\"#tab-0\">Facturation</a></li>\n      <li><a href=\"#tab-1\">Grand Livre</a></li>\n      <li><a href=\"#tab-2\">TVA &amp; Déclarations</a></li>\n      <li><a href=\"#tab-3\">Balance &amp; Trésorerie</a></li>\n      <li><a href=\"#tab-4\">Dashboard</a></li>\n    </ol>\n  </nav>\n\n  <div class=\"note\"><b>Le principe du service :</b> la comptabilité s'alimente en grande partie <b>toute seule</b>. Chaque facture client émise génère automatiquement une écriture au journal des <b>ventes (VTE)</b>, chaque facture fournisseur enregistrée une écriture au journal des <b>achats (ACH)</b> : le Grand Livre, la TVA et la Balance reflètent donc l'activité sans ressaisie. À l'ouverture, la page s'affiche sur l'onglet <b>Facturation</b> ; les pastilles des onglets Facturation et Grand Livre indiquent respectivement le nombre de factures (clients + fournisseurs) et le nombre d'écritures.</div>\n\n  <section class=\"tab\" id=\"tab-0\">\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Facturation</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le poste de travail quotidien du comptable : d'un côté les <b>factures clients</b> (suivre les règlements, relancer les retards, encaisser), de l'autre les <b>factures fournisseurs et sous-traitants</b> à valider puis à payer. Tout ce qui est saisi ou soldé ici alimente directement le Grand Livre, la marge brute du Dashboard et la prévision de trésorerie.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Deux grands volets à bascule en haut de l'onglet : <b>« Factures clients »</b> et <b>« Factures fournisseurs / sous-traitants »</b> — ce dernier porte une pastille rouge avec le nombre de factures restant à traiter (à valider, validées ou à payer). Chaque volet a ensuite ses propres sous-onglets, détaillés ci-dessous.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/compta.png\" alt=\"Capture de l'onglet Facturation\" loading=\"lazy\">\n      <figcaption><b>Facturation</b> — les deux volets à bascule (clients / fournisseurs-ST) et, dessous, les sous-onglets du volet actif.</figcaption>\n    </figure>\n\n    <h3>Factures clients — sous-onglet « Liste »</h3>\n    <p>Deux tableaux superposés : <b>« Factures en attente de règlement »</b> (compteur orange et total TTC en jeu) puis <b>« Factures réglées »</b> (compteur vert et total TTC encaissé). Colonnes : <b>N° Facture</b>, <b>Client</b>, <b>Affaire</b>, <b>Date</b>, <b>Échéance</b>, <b>HT</b>, <b>TTC</b>, <b>Statut</b> et <b>Actions</b>. Les statuts possibles : <span class=\"b b-mut\">Brouillon</span>, <span class=\"b b-info\">Envoyée</span>, <span class=\"b b-warn\">Partiel.</span> (partiellement payée), <span class=\"b b-ok\">Payée</span>, <span class=\"b b-crit\">En retard</span> (accompagné du nombre de jours de dépassement <b>J+X</b> en rouge) et <b>Litige</b> (badge violet). Une petite étiquette <b>« partielle »</b> à côté du numéro signale une facture émise sur une livraison partielle. Selon le statut, trois boutons d'action : <b>« Envoyer »</b> (brouillons uniquement), <b>« Payée »</b> (toute facture envoyée non soldée) et <b>« PDF »</b> (toujours disponible).</p>\n\n    <h3>Pas à pas — suivre et encaisser une facture client</h3>\n    <ol class=\"steps\">\n      <li>Repérez la facture dans le tableau <b>« Factures en attente de règlement »</b> ; l'échéance et l'éventuel <b>J+X</b> vous disent si elle est en retard.</li>\n      <li>Pour produire le document à transmettre, cliquez <b>« PDF »</b> : une fenêtre d'impression s'ouvre avec la facture complète au logo Seem Semrac (client, affaire, lignes, totaux HT / TVA / TTC, mention « PAYÉE » ou « EN ATTENTE DE RÈGLEMENT »). Imprimez ou enregistrez en PDF depuis le navigateur.</li>\n      <li>Si la facture est encore <span class=\"b b-mut\">Brouillon</span>, cliquez <b>« Envoyer »</b> : l'ERP confirme l'envoi et la facture passe au statut <span class=\"b b-info\">Envoyée</span>.</li>\n      <li>Quand le règlement du client arrive en banque, cliquez <b>« Payée »</b> : la facture passe au statut <span class=\"b b-ok\">Payée</span>, la page se recharge en douceur et la facture bascule dans le tableau « Factures réglées ». L'encaissement remonte aussitôt dans le Dashboard et l'historique des règlements.</li>\n    </ol>\n\n    <h3>Factures clients — sous-onglet « Créer facture »</h3>\n    <p>Un formulaire pour émettre une facture client manuelle. Le montant HT saisi calcule automatiquement la <b>TVA à 20 %</b> et le <b>TTC</b> (champs grisés, non modifiables). Le bouton <b>« Créer la facture »</b> confirme la création (« Facture créée. Prête à envoyer. ») ; <b>« Annuler »</b> ramène à la liste.</p>\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Client</td><td>Liste déroulante</td><td><b>Oui</b></td><td>Choisi parmi les clients déjà facturés dans l'ERP.</td></tr>\n          <tr><td>N° Affaire</td><td>Texte (ex. CMD-2026-xxx)</td><td><b>Oui</b></td><td>Rattache la facture à l'affaire ; elle apparaîtra dans la fiche 360 de l'affaire côté Commercial.</td></tr>\n          <tr><td>Date facture</td><td>Date</td><td><b>Oui</b></td><td>Date d'émission.</td></tr>\n          <tr><td>Date d'échéance</td><td>Date</td><td><b>Oui</b></td><td>Date limite de règlement ; sert au calcul des retards (J+X) et des relances.</td></tr>\n          <tr><td>Désignation / Prestations</td><td>Texte libre</td><td><b>Oui</b></td><td>Détail des prestations ou références facturées.</td></tr>\n          <tr><td>Montant HT (€)</td><td>Nombre</td><td><b>Oui</b></td><td>Sa saisie remplit automatiquement TVA et TTC.</td></tr>\n          <tr><td>TVA 20 % (€)</td><td>Calculé</td><td>—</td><td>Champ automatique, non modifiable.</td></tr>\n          <tr><td>Montant TTC (€)</td><td>Calculé</td><td>—</td><td>Champ automatique, non modifiable.</td></tr>\n          <tr><td>Mode de paiement</td><td>Liste : Virement / Chèque / Prélèvement / LCR</td><td>Non</td><td>Mode de règlement attendu.</td></tr>\n          <tr><td>Notes internes</td><td>Texte libre</td><td>Non</td><td>Observations, conditions particulières — visibles en interne.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"note\"><b>Bon à savoir :</b> la plupart des factures clients ne se créent pas ici — elles sont générées automatiquement par l'ERP au moment de la <b>livraison</b> (bon de livraison client, service Expéditions), y compris pour les livraisons partielles. Ce formulaire sert aux facturations manuelles ou exceptionnelles.</div>\n\n    <h3>Factures clients — sous-onglet « Relances »</h3>\n    <p>Le sous-onglet porte une pastille rouge avec le nombre de factures à relancer (toutes les factures <span class=\"b b-info\">Envoyée</span>, <span class=\"b b-warn\">Partiel.</span> ou <span class=\"b b-crit\">En retard</span>). Un bandeau ambre récapitule ce nombre et le <b>montant total en jeu</b>. Le tableau affiche N° Facture, Client, Échéance (avec J+X si dépassée), Montant TTC, Statut, <b>Nb relances</b> déjà effectuées, et un bouton vert <b>« Envoyer relance »</b> par ligne.</p>\n    <ol class=\"steps\">\n      <li>Ouvrez le sous-onglet <b>Relances</b> et triez mentalement par urgence : les J+X les plus élevés d'abord.</li>\n      <li>Cliquez <b>« Envoyer relance »</b> sur la ligne concernée : l'ERP confirme (« Relance envoyée à [client]. Notification email déclenchée. »).</li>\n      <li>La colonne <b>Nb relances</b> vous permet de suivre l'historique : au-delà de 2 relances sans effet, envisagez le passage en <b>Litige</b> avec la Direction.</li>\n    </ol>\n\n    <h3>Factures fournisseurs / sous-traitants — saisir une facture (« À régler »)</h3>\n    <p>Le second volet s'ouvre sur une barre d'action : un rappel (« Saisissez les factures fournisseurs et sous-traitants à régler — elles alimentent la marge brute du dashboard ») et le bouton vert <b>« Nouvelle facture fournisseur / ST »</b> qui ouvre la fenêtre de saisie. Dessous, quatre sous-onglets : <b>Fournisseurs</b>, <b>Sous-traitants</b>, <b>Historique règlements</b> et <b>Énergie / EDF</b>.</p>\n    <ol class=\"steps\">\n      <li>Cliquez <b>« Nouvelle facture fournisseur / ST »</b> et remplissez la fenêtre (champs détaillés ci-dessous). Le TTC se calcule automatiquement à partir du HT et du taux de TVA.</li>\n      <li>Si le montant le justifie, cochez <b>« Soumettre cette facture à la validation de la Direction »</b> : une demande de validation est créée dans le service Direction et un badge de décision (accordée / refusée) s'affichera ensuite sur la ligne de la facture.</li>\n      <li>Cliquez <b>« Enregistrer »</b> : la facture apparaît dans la liste avec le statut <span class=\"b b-warn\">À valider</span>.</li>\n      <li>Contrôlez la facture (rapprochement avec le bon de commande et le bon de livraison côté Expéditions), puis cliquez <b>« Valider »</b> : elle passe au statut prêt au règlement.</li>\n      <li>Au moment du règlement, cliquez <b>« Payer »</b> : la facture passe <span class=\"b b-ok\">Payée</span> à la date du jour (mode Virement) et le Dashboard est mis à jour.</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-compta-fournisseur.png\" alt=\"Fenêtre Nouvelle facture fournisseur / sous-traitant\" loading=\"lazy\">\n      <figcaption><b>Nouvelle facture fournisseur / ST</b> — le TTC se calcule seul ; la case jaune du bas soumet la facture à la validation de la Direction.</figcaption>\n    </figure>\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Type</td><td>Liste : Fournisseur / Sous-traitant</td><td><b>Oui</b></td><td>Détermine le sous-onglet dans lequel la facture sera classée.</td></tr>\n          <tr><td>N° Facture</td><td>Texte (ex. FOURN-2026-XXXX)</td><td>Non</td><td>Numéro porté sur la facture du fournisseur ; attribué automatiquement si laissé vide.</td></tr>\n          <tr><td>Fournisseur / Sous-traitant</td><td>Texte (raison sociale)</td><td><b>Oui</b></td><td>Nom du tiers — refusé s'il est vide.</td></tr>\n          <tr><td>Date facture</td><td>Date</td><td>Non</td><td>Pré-remplie à la date du jour à l'ouverture de la fenêtre.</td></tr>\n          <tr><td>Échéance</td><td>Date</td><td>Non</td><td>Date limite de paiement ; alimente les échéances du Dashboard et la prévision de trésorerie.</td></tr>\n          <tr><td>Montant HT</td><td>Nombre</td><td><b>Oui</b> (&gt; 0)</td><td>Montant hors taxes — refusé s'il est nul.</td></tr>\n          <tr><td>TVA %</td><td>Nombre</td><td>Non</td><td>20 % par défaut ; modifiable.</td></tr>\n          <tr><td>Montant TTC</td><td>Calculé</td><td>—</td><td>Recalculé automatiquement à chaque saisie du HT ou du taux.</td></tr>\n          <tr><td>Compte de charge</td><td>Liste : 601100 – Matières premières / 604100 – Sous-traitance / 606100 – Consommables / 606300 – Énergie / 615000 – Entretien-maintenance / Autres</td><td>Non</td><td>Classe la dépense ; sert au tableau « Charges à payer par catégorie » du Dashboard et à l'échéancier EDF.</td></tr>\n          <tr><td>Notes</td><td>Texte</td><td>Non</td><td>Affichées sous forme d'icône d'alerte au survol de la ligne.</td></tr>\n          <tr><td>Validation Direction</td><td>Case à cocher</td><td>Non</td><td>Envoie la facture dans la file « À valider » du service Direction.</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <h3>Sous-onglets « Fournisseurs » et « Sous-traitants »</h3>\n    <p>Chaque sous-onglet liste ses factures avec les colonnes <b>N° Facture</b>, <b>Fournisseur</b> (ou Sous-traitant), <b>Date</b>, <b>Échéance</b>, <b>HT</b>, <b>TTC</b>, <b>Compte charge</b>, <b>Statut</b> et <b>Actions</b>. Statuts : <span class=\"b b-warn\">À valider</span>, <span class=\"b b-info\">Validée</span>, <span class=\"b b-crit\">À payer</span>, <span class=\"b b-ok\">Payée</span> et <b>Litige</b> (badge violet) ; un second badge indique le cas échéant la décision de la Direction. Sur le sous-onglet Fournisseurs, des pastilles filtrent la liste : <b>Tous</b>, <b>À valider (n)</b>, <b>À payer (n)</b>, <b>Litiges</b>. En bas de chaque liste, un bandeau rouge affiche le <b>total à régler</b> (factures à payer et validées).</p>\n\n    <h3>Sous-onglet « Historique règlements »</h3>\n    <p>Toutes les factures <b>payées</b>, clients comme fournisseurs, dans un seul tableau trié du règlement le plus récent au plus ancien : <b>Type</b> (étiquette CLIENT bleue ou FOURN. orange), <b>N° Facture</b>, <b>Tiers</b>, <b>Date paiement</b>, <b>Mode</b> de règlement et <b>Montant TTC</b> (en vert pour les encaissements clients, en rouge pour les décaissements fournisseurs). C'est votre journal de caisse consultable en un coup d'œil.</p>\n\n    <h3>Sous-onglet « Énergie / EDF »</h3>\n    <p>L'échéancier des factures <b>EDF</b> : mensualités estimées et régularisation annuelle. Chaque échéance est une facture fournisseur au compte <b>606300 – Énergie</b> ; l'ERP regroupe ici automatiquement les factures de ce compte (ou dont le fournisseur évoque EDF / électricité / énergie), triées par échéance. Trois tuiles résument <b>Total EDF</b>, <b>Payé</b> et <b>Reste à payer (report)</b> — ce report est repris automatiquement dans la prévision de trésorerie. Le bouton orange <b>« Nouvelle échéance EDF »</b> ouvre la fenêtre de saisie habituelle, pré-remplie (fournisseur EDF, compte 606300 – Énergie, numéro EDF-année) : il ne reste qu'à saisir le montant et l'échéance. La validation et le paiement se font ensuite avec les mêmes boutons <b>« Valider »</b> / <b>« Payer »</b> que les autres factures.</p>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Chaque facture émise ou enregistrée génère <b>automatiquement son écriture comptable</b> (journal VTE côté ventes, ACH côté achats) : ne créez jamais d'écriture à la main en double.</li>\n      <li>Le total du bandeau rouge « Total à régler » ne compte que les factures <b>à payer</b> et <b>validées</b> — les factures encore « à valider » n'y figurent pas mais restent dans la pastille rouge du volet.</li>\n      <li>Les factures fournisseurs marquées payées le sont <b>à la date du jour</b>, en mode Virement : soldez-les le jour effectif du règlement.</li>\n      <li>Une facture soumise à la Direction reste réglable normalement : le badge de décision est un <b>avis</b> visible sur la ligne, pas un blocage technique. Attendez la décision avant de payer les montants concernés.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> le bouton <b>« PDF »</b> ouvre la facture dans une fenêtre surgissante — si votre navigateur bloque les pop-ups, l'ERP vous le signale : autorisez les pop-ups pour ce site, sinon aucune fenêtre d'impression ne s'ouvrira.</div>\n    <div class=\"astuce\"><b>Astuce :</b> traitez les factures fournisseurs en deux temps avec les pastilles de filtre : d'abord <b>« À valider »</b> (contrôle facture / commande / réception), puis <b>« À payer »</b> le jour des règlements. Vous viderez la pastille rouge du volet méthodiquement.</div>\n  </section>\n\n  <section class=\"tab\" id=\"tab-1\">\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Grand Livre</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Le Grand Livre est le registre de <b>toutes les écritures comptables</b> de l'entreprise, classées par journal. Il s'alimente automatiquement : facturation client → journal des ventes, facture fournisseur → journal des achats. C'est ici que vous contrôlez les écritures, recherchez une pièce et exportez le <b>FEC</b> pour Sage ou l'expert-comptable.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>En haut, des pastilles de filtre par journal : <b>Tous journaux</b>, puis <b>VTE</b> (ventes, badge bleu), <b>ACH</b> (achats, orange), <b>BQ</b> (banque, vert), <b>OD</b> (opérations diverses, gris) et <b>SAL</b> (salaires, violet). À droite : un champ <b>« Rechercher compte / libellé… »</b> qui filtre le tableau au fil de la frappe, un champ <b>année d'exercice</b> et le bouton vert <b>« Export FEC (Sage) »</b>. Le tableau liste chaque écriture : <b>Date</b>, <b>Journal</b> (badge), <b>Pièce</b> (référence du document d'origine), <b>Compte</b>, <b>Libellé</b>, <b>Débit</b> (en bleu), <b>Crédit</b> (en rouge), <b>Lettrage</b> et <b>Validé</b> (coche verte = écriture validée, horloge orange = en attente). La ligne <b>TOTAUX</b> du bas affiche le total débit, le total crédit et le solde (D ou C).</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/compta-grand-livre.png\" alt=\"Capture de l'onglet Grand Livre\" loading=\"lazy\">\n      <figcaption><b>Grand Livre</b> — les pastilles de journaux, la recherche, le bouton « Export FEC (Sage) » et les totaux débit / crédit en pied de tableau.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — contrôler les écritures et exporter le FEC</h3>\n    <ol class=\"steps\">\n      <li>Filtrez par journal (par exemple <b>VTE</b> pour ne voir que les ventes) ou tapez un numéro de compte ou un mot du libellé dans la recherche : le tableau se réduit instantanément.</li>\n      <li>Vérifiez l'équilibre : sur la ligne <b>TOTAUX</b>, débit et crédit doivent être égaux (solde nul) — un écart signale une anomalie à investiguer.</li>\n      <li>Pour l'export : saisissez l'<b>année d'exercice</b> dans le petit champ (année en cours par défaut), puis cliquez <b>« Export FEC (Sage) »</b>. Le Fichier des Écritures Comptables se télécharge, prêt à être importé dans Sage ou transmis à l'expert-comptable.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Le FEC (Fichier des Écritures Comptables) est le format légal exigé par l'administration fiscale : c'est le livrable à transmettre à l'expert-comptable en fin d'exercice.</li>\n      <li>L'export FEC est réservé aux rôles <b>Comptable</b> et <b>Direction</b>.</li>\n      <li>La colonne <b>Pièce</b> fait le lien avec le document d'origine (numéro de facture) : c'est votre piste d'audit entre une écriture et l'onglet Facturation.</li>\n      <li>Le <b>lettrage</b> rapproche une facture de son règlement (même code sur les deux écritures) ; une écriture non lettrée correspond à une facture non soldée.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> la recherche accepte aussi bien un début de compte (« 411 » pour tous les clients) qu'un mot du libellé (le nom d'un client, par exemple) — combinez-la avec un filtre de journal pour cibler très vite une écriture.</div>\n  </section>\n\n  <section class=\"tab\" id=\"tab-2\">\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>TVA &amp; Déclarations</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Cet onglet calcule automatiquement votre TVA à partir des écritures du Grand Livre : TVA <b>collectée</b> sur les ventes, TVA <b>déductible</b> sur les achats, et TVA <b>nette à reverser</b>. Il vous rappelle l'échéance de la déclaration <b>CA3</b> et fournit le détail justificatif compte par compte du mois à déclarer.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Quatre tuiles pour le mois en cours : <b>TVA Collectée</b> (comptes 4457xx, au crédit), <b>TVA Déductible</b> (comptes 4456xx, au débit), <b>TVA nette à reverser</b> (collectée − déductible) et <b>Date déclaration CA3</b> (dépôt avant le 19 du mois suivant). Dessous, un tableau des deux périodes : le mois courant avec le statut <span class=\"b b-warn\">En cours</span> et le mois précédent avec le statut <span class=\"b b-crit\">À déclarer</span>, chacun avec ses montants collectée / déductible / nette et sa date limite CA3. Enfin, le bloc <b>« Détail déclaration »</b> du mois précédent présente côte à côte les écritures de TVA collectée et de TVA déductible (compte, libellé, montant, totaux), un bandeau violet avec la <b>TVA nette à reverser</b> et le bouton <b>« Préparer déclaration CA3 »</b>.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/compta-tva.png\" alt=\"Capture de l'onglet TVA et Déclarations\" loading=\"lazy\">\n      <figcaption><b>TVA &amp; Déclarations</b> — les tuiles du mois en cours, le tableau des périodes et le détail justificatif du mois à déclarer.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — préparer la déclaration mensuelle</h3>\n    <ol class=\"steps\">\n      <li>En début de mois, ouvrez l'onglet : la ligne du <b>mois précédent</b> porte le statut <span class=\"b b-crit\">À déclarer</span> avec sa date limite (le 19 du mois en cours).</li>\n      <li>Contrôlez le bloc <b>« Détail déclaration »</b> : chaque montant de TVA doit correspondre à une facture identifiable par son libellé. Un doute ? Retrouvez l'écriture dans le <b>Grand Livre</b> (recherche « 4457 » ou « 4456 »).</li>\n      <li>Relevez la <b>TVA nette à reverser</b> du bandeau violet, puis cliquez <b>« Préparer déclaration CA3 »</b> : l'ERP confirme la préparation de la déclaration.</li>\n      <li>Reportez les montants sur le portail des impôts (télédéclaration CA3) avant la date limite — l'ERP prépare les chiffres, la télétransmission reste à faire sur le site officiel.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Les montants sont calculés en direct depuis les écritures : une facture saisie en retard dans le mois modifie la TVA affichée — saisissez les factures fournisseurs sans attendre.</li>\n      <li>Si la TVA déductible dépasse la collectée, la TVA nette est négative : c'est un <b>crédit de TVA</b> à reporter ou à demander en remboursement.</li>\n      <li>La date limite affichée est le <b>19 du mois suivant</b> la période : anticipez de quelques jours pour garder le temps de contrôler.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> l'ERP ne télédéclare pas à votre place. « Préparer déclaration CA3 » rassemble les chiffres — la déclaration officielle se fait sur le portail des impôts, avec ces montants.</div>\n  </section>\n\n  <section class=\"tab\" id=\"tab-3\">\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Balance &amp; Trésorerie</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La <b>balance des comptes</b> donne la photographie comptable de l'entreprise : total débit, total crédit et solde de chaque grand compte. La partie <b>trésorerie</b> répond à la question quotidienne du dirigeant : combien avons-nous en banque, et à combien serons-nous dans 30 jours compte tenu des factures à encaisser et à payer ?</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>En haut, la <b>Balance des comptes</b> : un tableau avec <b>N° Compte</b>, <b>Intitulé</b>, <b>Total Débit</b>, <b>Total Crédit</b>, <b>Solde Débiteur</b> (bleu) et <b>Solde Créditeur</b> (rouge). Les grands comptes du plan comptable y figurent — 411 Clients, 401 Fournisseurs, 512 Banque, 531 Caisse, 421 et 431 (personnel et cotisations), 601 Achats matières premières, 604 Sous-traitance, 606 Énergie / fournitures, 607 Marchandises, 622 Honoraires, 641 Salaires, 681 Dotations, 701 / 706 / 707 (ventes et prestations), TVA collectée et déductible. Chaque ligne agrège tous les sous-comptes de sa racine, et les comptes sans mouvement sont masqués. En bas, deux cartes côte à côte : <b>« Trésorerie estimée »</b> — Solde bancaire (compte 512, caisse comprise), <b>Prévision J+30</b> (vert si positive, rouge sinon), Encaissements prévus et Décaissements prévus — et <b>« Tendance trésorerie »</b>, un graphique en barres du solde bancaire mois par mois depuis janvier, le mois le plus récent en vert.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/compta-balance.png\" alt=\"Capture de l'onglet Balance et Trésorerie\" loading=\"lazy\">\n      <figcaption><b>Balance &amp; Trésorerie</b> — la balance par compte en haut, la trésorerie estimée et la tendance mensuelle en bas.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — lire la prévision de trésorerie</h3>\n    <ol class=\"steps\">\n      <li>Partez du <b>Solde bancaire</b> : c'est le solde réel du compte banque (et de la caisse) reconstitué depuis les écritures.</li>\n      <li>Les <b>Encaissements prévus</b> additionnent les factures clients non payées dont l'échéance tombe dans les 30 jours ; les <b>Décaissements prévus</b>, les factures fournisseurs et sous-traitants non payées à échéance dans les 30 jours — y compris le report EDF.</li>\n      <li>La <b>Prévision J+30</b> = solde bancaire + encaissements − décaissements. Si elle vire au rouge, agissez en amont : relancez les clients (onglet Facturation → Relances) ou étalez des règlements fournisseurs.</li>\n      <li>La <b>Tendance trésorerie</b> montre si le solde s'améliore ou se dégrade sur l'année : une pente descendante régulière mérite une alerte à la Direction.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>La fiabilité de la prévision dépend des <b>dates d'échéance</b> : une facture saisie sans échéance n'entre pas dans le calcul des 30 jours.</li>\n      <li>La balance doit être équilibrée : la ligne TOTAUX affiche le même montant en débit et en crédit. Un déséquilibre signale une écriture anormale — contrôlez au Grand Livre.</li>\n      <li>Les soldes « Clients » (411) et « Fournisseurs » (401) de la balance recoupent les encours de l'onglet Facturation : c'est un bon contrôle croisé mensuel.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> consultez cet onglet chaque lundi matin — cinq minutes suffisent pour vérifier le solde, la prévision J+30 et repérer une échéance fournisseur importante à venir.</div>\n  </section>\n\n  <section class=\"tab\" id=\"tab-4\">\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Dashboard</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Le tableau de bord financier de l'exercice : chiffre d'affaires facturé, encaissements et décaissements, marge brute, activité mensuelle en base 100, alertes sur les retards et litiges, meilleurs clients et prochaines échéances. C'est la synthèse à présenter à la Direction — elle se met à jour automatiquement à chaque facture émise ou soldée.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Un bandeau <b>« Exercice AAAA »</b> précise l'année de référence (la plus récente présente dans les factures) : tous les indicateurs sont cumulés du 1<sup>er</sup> janvier au mois courant. Puis, de haut en bas :</p>\n    <ul class=\"points\">\n      <li><b>5 tuiles principales</b> : CA facturé (HT, cumul annuel), Encaissé (règlements clients reçus TTC), Décaissé (fournisseurs + ST réglés TTC), En attente règlement (factures clients envoyées, partielles ou en retard) et Reste à payer F/ST (factures à valider + à payer).</li>\n      <li><b>Marge brute globale</b> : le chiffre clé <b>encaissé − payé</b> (le réalisé, en vert ou rouge), deux barres comparant « Rentré » et « Sorti », puis la <b>marge HT comptable</b> (CA HT − charges HT), le <b>taux de marge</b> et le <b>DSO</b> (délai moyen de paiement clients, en jours).</li>\n      <li><b>Base 100 annuelle</b> : l'indice mensuel du CA HT, base 100 = premier mois facturé de l'année. Barres vertes quand le mois progresse, rouges quand il recule, avec l'indice courant en grand et les cumuls CA HT / charges HT dessous.</li>\n      <li><b>4 tuiles secondaires</b> : Charges engagées HT, Trésorerie nette (encaissé − décaissé), nombre de factures clients émises et nombre de factures fournisseurs / ST reçues.</li>\n      <li><b>Alertes</b> : un bandeau rouge <b>« Factures en retard (n) »</b> détaille chaque facture concernée (numéro, client, montant, J+X, nombre de relances) ; un bandeau ambre <b>« Litiges en cours »</b> liste les litiges avec leurs notes.</li>\n      <li><b>Top 5 Clients par CA</b> (client, CA HT, nombre de factures) et <b>Charges à payer par catégorie</b> (par compte de charge, avec total) côte à côte.</li>\n      <li><b>Prochaines échéances – 30 jours</b> : les échéances proches, clients (étiquette bleue) et fournisseurs (étiquette orange) confondus, triées par date, avec <b>J+X</b> en rouge si l'échéance est déjà dépassée.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/compta-dashboard.png\" alt=\"Capture de l'onglet Dashboard Comptabilité\" loading=\"lazy\">\n      <figcaption><b>Dashboard</b> — les tuiles de l'exercice, la marge brute « rentré / sorti » et la base 100 mensuelle du CA.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — la revue mensuelle en 4 points</h3>\n    <ol class=\"steps\">\n      <li>Vérifiez la <b>marge brute réalisée</b> (encaissé − payé) : c'est l'argent réellement gagné, indépendamment de ce qui reste à encaisser.</li>\n      <li>Comparez-la à la <b>marge HT comptable</b> : un gros écart signifie que des factures clients traînent — contrôlez le <b>DSO</b> et le bandeau des retards.</li>\n      <li>Balayez les <b>alertes</b> : chaque facture en retard doit avoir une relance récente (le compteur de relances est affiché) ; chaque litige, un plan d'action.</li>\n      <li>Terminez par <b>Prochaines échéances</b> pour anticiper la semaine : les lignes fournisseurs vous donnent les sorties d'argent à préparer, les lignes clients les encaissements à surveiller.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Le Dashboard ne se remplit pas à la main : il reflète les factures et statuts de l'onglet <b>Facturation</b>. Un chiffre étonnant se corrige donc là-bas, jamais ici.</li>\n      <li>La <b>base 100</b> mesure l'évolution relative de l'activité, pas sa valeur absolue : un indice 120 signifie « 20 % de mieux que le premier mois facturé de l'année ».</li>\n      <li>Le <b>DSO</b> se surveille dans la durée : s'il s'allonge de mois en mois, vos clients paient de plus en plus tard — intensifiez les relances.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> avant une réunion de Direction, ouvrez cet onglet et l'onglet Balance &amp; Trésorerie côte à côte : le premier raconte l'exercice, le second dit ce qu'il y a en banque et à 30 jours. Les deux ensemble font le point financier complet.</div>\n  </section>\n\n  <div class=\"docnav\">\n    <a href=\"index.html\">← Sommaire des manuels</a>\n    <a href=\"securite.html\">Manuel suivant : Sécurité →</a>\n  </div>\n\n  <footer class=\"doc\">\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\n  </footer>\n\n</div>\n</body>\n</html>\n",
  "dashboard": "<!doctype html>\r\n<html lang=\"fr\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>Manuel — Tableaux de bord · ERP Seem Semrac</title>\r\n<link rel=\"stylesheet\" href=\"manuel.css\">\r\n</head>\r\n<body>\r\n<div class=\"wrap\">\r\n\r\n  <header class=\"doc\">\r\n    <div class=\"brandrow\">\r\n      <div class=\"logo\">SS</div>\r\n      <div>\r\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\r\n        <div class=\"eyebrow\">Manuel utilisateur</div>\r\n      </div>\r\n      <div class=\"kind\">docs/manuel/html</div>\r\n    </div>\r\n    <h1>Service <span class=\"hi\">Tableaux de bord</span></h1>\r\n    <p class=\"lede\">Les Tableaux de bord ne saisissent rien : ils <b>lisent</b> ce que les autres services ont enregistré (devis, commandes, BDT, PV, NC, BL, factures, pointages, relevés) et le transforment en indicateurs chiffrés. Un hub d'entrée donne le chiffre phare de chaque service ; derrière, quinze dashboards détaillés partagent la même barre de filtres (période, site, client/machine/fournisseur, comparaison N-1, export PDF). Ce manuel décrit d'abord cette barre commune, puis chacun des quinze dashboards.</p>\r\n    <div class=\"metachips\">\r\n      <span class=\"chip\">👤 Pour qui : <b>Direction, responsables de service, encadrement</b> — chaque dashboard suit le droit de <b>lecture</b> du service correspondant</span>\r\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Tableaux de bord</b></span>\r\n      <span class=\"chip\">🗂 <b>16 onglets</b> (1 hub + 15 dashboards)</span>\r\n    </div>\r\n  </header>\r\n\r\n  <nav class=\"toc\">\r\n    <div class=\"toc-t\">Sommaire</div>\r\n    <ol>\r\n      <li><a href=\"#tab-hub\">Vue d'ensemble (hub) &amp; barre de filtres</a></li>\r\n      <li><a href=\"#tab-direction\">Dashboard Direction</a></li>\r\n      <li><a href=\"#tab-commercial\">Dashboard Commercial</a></li>\r\n      <li><a href=\"#tab-finance\">Dashboard Finance</a></li>\r\n      <li><a href=\"#tab-be\">Dashboard Bureau Études</a></li>\r\n      <li><a href=\"#tab-achats\">Dashboard Achats</a></li>\r\n      <li><a href=\"#tab-fournisseurs\">Dashboard Fournisseurs</a></li>\r\n      <li><a href=\"#tab-production\">Dashboard Production</a></li>\r\n      <li><a href=\"#tab-programmation\">Dashboard Programmation</a></li>\r\n      <li><a href=\"#tab-qualite\">Dashboard Qualité</a></li>\r\n      <li><a href=\"#tab-oas\">Dashboard OAS</a></li>\r\n      <li><a href=\"#tab-maintenance\">Dashboard Maintenance</a></li>\r\n      <li><a href=\"#tab-stock\">Dashboard Stock</a></li>\r\n      <li><a href=\"#tab-expedition\">Dashboard Expéditions</a></li>\r\n      <li><a href=\"#tab-rh\">Dashboard RH</a></li>\r\n      <li><a href=\"#tab-environnement\">Dashboard Environnement</a></li>\r\n    </ol>\r\n  </nav>\r\n\r\n  <!-- ══════════════ 1. HUB + BARRE DE FILTRES ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-hub\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Vue d'ensemble (hub)</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Le hub est la porte d'entrée des tableaux de bord : une carte par dashboard, avec son <b>chiffre phare du moment</b>. En un écran, vous voyez si le carnet se remplit, si la qualité dérape, si l'atelier est saturé ou si la trésorerie tient — puis vous cliquez la carte qui vous intéresse pour ouvrir le dashboard détaillé. C'est aussi la section où est décrite la <b>barre de filtres</b>, identique sur les quinze dashboards : la comprendre une fois suffit pour toutes les autres pages.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Une grille de <b>quinze cartes cliquables</b>. Chaque carte porte une icône colorée, une valeur en gros caractères, le libellé de ce que compte cette valeur, et le nom du dashboard suivi d'une flèche. Les valeurs affichées sont celles de l'instant (aucun filtre sur le hub) :</p>\r\n    <ul class=\"points\">\r\n      <li><b>Direction</b> — CA cumulé · <b>Commercial</b> — CA facturé (mois) · <b>Finance</b> — Trésorerie nette</li>\r\n      <li><b>Bureau Études</b> — DT à analyser · <b>Achats</b> — DA à traiter · <b>Fournisseurs</b> — OTD global</li>\r\n      <li><b>Production</b> — OTD · <b>Programmation</b> — Charge atelier · <b>Qualité</b> — NC ouvertes</li>\r\n      <li><b>OAS</b> — Sessions OAS · <b>Maintenance</b> — Disponibilité · <b>Stock</b> — Valorisation</li>\r\n      <li><b>Expéditions</b> (BL &amp; OTD) et <b>Environnement</b> (ISO 14001 · GES · RSE) n'affichent qu'une flèche : ces deux dashboards n'ont pas un chiffre unique qui les résume.</li>\r\n      <li><b>RH</b> — Effectif actif.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-hub.png\" alt=\"Capture du hub des tableaux de bord\" loading=\"lazy\">\r\n      <figcaption><b>Vue d'ensemble</b> — une carte par dashboard ; le gros chiffre est le KPI phare du service, la flèche ouvre le tableau de bord détaillé.</figcaption>\r\n    </figure>\r\n\r\n    <h3>La barre de filtres, commune aux quinze dashboards</h3>\r\n    <p>Dès que vous ouvrez un dashboard, une barre blanche <b>reste collée en haut de l'écran</b> pendant que vous faites défiler la page. Elle contient, de gauche à droite : les six boutons de période, les dates personnalisées (si période « Perso »), le choix du site, éventuellement un champ contextuel (client, machine ou fournisseur), le bouton de comparaison <b>vs N-1</b>, puis, à droite, <b>Réinit.</b> et <b>Exporter</b>.</p>\r\n\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Bouton</th><th>Période couverte</th><th>Quand l'utiliser</th></tr></thead>\r\n      <tbody>\r\n        <tr><td><b>Ce mois</b> (par défaut)</td><td>Du 1<sup>er</sup> du mois en cours à aujourd'hui.</td><td>Point de situation quotidien / hebdomadaire.</td></tr>\r\n        <tr><td><b>Mois -1</b></td><td>Le mois précédent, complet (du 1<sup>er</sup> au dernier jour).</td><td>Bilan du mois écoulé, une fois toutes les saisies faites.</td></tr>\r\n        <tr><td><b>YTD</b></td><td>Du 1<sup>er</sup> janvier de l'année en cours à aujourd'hui.</td><td>Cumul annuel « où en est-on depuis janvier ».</td></tr>\r\n        <tr><td><b>12 mois</b></td><td>Les douze derniers mois glissants, jusqu'à aujourd'hui.</td><td>Voir une saisonnalité sans coupure au 1<sup>er</sup> janvier.</td></tr>\r\n        <tr><td><b>Année</b></td><td>Année civile entière (1<sup>er</sup> janvier → 31 décembre).</td><td>Comparaison d'années pleines, revue annuelle.</td></tr>\r\n        <tr><td><b>Perso</b></td><td>Deux champs de date apparaissent : début → fin, à votre main.</td><td>Une campagne, un chantier, un audit sur une fenêtre précise.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Contrôle</th><th>Choix</th><th>Ce que ça change</th><th>Où on le trouve</th></tr></thead>\r\n      <tbody>\r\n        <tr><td><b>Site</b></td><td>Tous sites (défaut) · Seem · Semrac</td><td>Ne garde que les lignes rattachées au site choisi.</td><td>Les quinze dashboards.</td></tr>\r\n        <tr><td><b>Client…</b></td><td>Champ avec liste de suggestions, alimentée par les clients réellement présents dans les données de la page.</td><td>Restreint tous les indicateurs à ce client.</td><td>Direction, Commercial, Finance, Bureau Études, Production, Programmation, Qualité, Expéditions.</td></tr>\r\n        <tr><td><b>Fournisseur…</b></td><td>Champ avec liste de suggestions (fournisseurs des BC, des factures et des DA).</td><td>Restreint les achats et les retards à ce fournisseur.</td><td>Achats.</td></tr>\r\n        <tr><td><b>Machine…</b></td><td>Champ avec liste de suggestions (parc machines).</td><td>Restreint disponibilité, MTBF/MTTR, OM et OPEX à cette machine.</td><td>Maintenance.</td></tr>\r\n        <tr><td><b>vs N-1</b></td><td>Bouton bascule (violet quand il est actif)</td><td>Ajoute sur les graphes une <b>courbe grise en pointillé</b> : la même mesure, un an plus tôt.</td><td>Les quinze dashboards (sur les graphes qui ont une série mensuelle).</td></tr>\r\n        <tr><td><b>Réinit.</b></td><td>Lien rouge, n'apparaît que si un filtre est actif</td><td>Remet tout à zéro : « Ce mois », tous sites, aucun client/machine/fournisseur, comparaison désactivée.</td><td>Les quinze dashboards.</td></tr>\r\n        <tr><td><b>Exporter</b></td><td>Bouton sombre avec l'icône PDF</td><td>Ouvre un <b>nouvel onglet en version imprimable</b> : sidebar et barre de filtres masquées, mise en page A4 paysage, et la fenêtre d'impression s'ouvre seule une fois les graphes dessinés.</td><td>Les quinze dashboards.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n\r\n    <h3>Lire une tuile KPI</h3>\r\n    <p>Toutes les tuiles suivent le même dessin : une icône, la <b>valeur</b>, le <b>libellé</b>, puis une ligne grise de contexte (le cumul, le nombre d'éléments comptés…). Selon l'indicateur s'y ajoutent :</p>\r\n    <ul class=\"points\">\r\n      <li>Un <b>badge de tendance</b> en haut à droite : <span class=\"b b-ok\">▲ +x %</span> par rapport à la période précédente, <span class=\"b b-crit\">▼ -x %</span> si la valeur recule.</li>\r\n      <li>Une <b>mini-courbe</b> (sparkline) sous la valeur : l'évolution mois par mois de la même mesure.</li>\r\n      <li>Une <b>ligne d'objectif</b> avec une pastille de couleur : <span class=\"b b-ok\">atteint</span> (vert), <span class=\"b b-warn\">à surveiller</span> (orange, entre le seuil d'alerte et la cible), <span class=\"b b-crit\">sous l'objectif</span> (rouge). Les cibles se règlent dans <b>Réglages › Objectifs / Cibles KPI</b> ; si rien n'y est saisi, l'ERP applique ses valeurs par défaut (OTD 95 %, OTK 92 %, marge 25 %, DSO 45 j, taux de NC ≤ 2 %, Cpk 1,33, disponibilité machines 90 %, absentéisme ≤ 4 %, rotation de stock 6…).</li>\r\n      <li>Certaines tuiles sont <b>cliquables</b> : elles ouvrent la liste correspondante <b>en conservant vos filtres</b>. C'est le « drill-down ».</li>\r\n    </ul>\r\n    <ul class=\"points\">\r\n      <li>Commercial → <b>Taux conversion</b> ouvre la liste des offres · <b>Carnet de commandes</b> ouvre la liste des DT.</li>\r\n      <li>Bureau Études → <b>DT à analyser</b> ouvre la liste des DT.</li>\r\n      <li>Achats → <b>DA à traiter</b> ouvre la liste des demandes d'achat.</li>\r\n      <li>Programmation → <b>BDT actifs</b> et Production → <b>Avancement BDT</b> ouvrent la liste des bons de travail.</li>\r\n      <li>Qualité → <b>NC ouvertes</b> ouvre la liste des non-conformités.</li>\r\n      <li>RH → <b>Habilitations</b> ouvre la page Compétences.</li>\r\n    </ul>\r\n\r\n    <h3>Pas à pas — analyser une période puis la partager</h3>\r\n    <ol class=\"steps\">\r\n      <li>Depuis la sidebar, ouvrez <b>Tableaux de bord</b>, puis cliquez la carte du service qui vous concerne.</li>\r\n      <li>Choisissez la période : par exemple <b>Mois -1</b> pour le bilan du mois écoulé, ou <b>Perso</b> puis les deux dates si vous visez une fenêtre précise.</li>\r\n      <li>Si besoin, restreignez avec <b>Site</b> (Seem ou Semrac) et le champ contextuel (client, fournisseur ou machine selon la page).</li>\r\n      <li>Activez <b>vs N-1</b> : les graphes affichent en pointillé gris la même période l'an dernier — c'est ce qui transforme un chiffre en tendance.</li>\r\n      <li>Cliquez une tuile KPI pour descendre dans le détail : vous arrivez sur la liste correspondante, déjà filtrée comme le dashboard.</li>\r\n      <li>Pour diffuser l'analyse, cliquez <b>Exporter</b> : un onglet s'ouvre en version imprimable et propose l'impression ou l'enregistrement en PDF.</li>\r\n      <li>Pour revenir à l'état d'origine, cliquez <b>Réinit.</b></li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li><b>Vos filtres sont dans l'adresse de la page</b> : vous pouvez mettre une vue filtrée en favori ou en copier le lien pour un collègue — il verra exactement la même chose (s'il a les droits de lecture du service).</li>\r\n      <li>Le hub, lui, <b>n'a pas de barre de filtres</b> : il montre toujours la situation du moment.</li>\r\n      <li>L'accès est calqué sur les droits de lecture : un profil qui ne lit pas la comptabilité n'ouvre pas le Dashboard Finance, un profil sans lecture RH n'ouvre pas le Dashboard RH.</li>\r\n      <li>Aucun chiffre n'est inventé : quand une table est vide, l'ERP affiche <b>0</b>, un tiret <b>—</b> ou un message du type « Aucune donnée sur la période ». Ce n'est pas une panne, c'est une saisie qui manque dans le service source.</li>\r\n    </ul>\r\n    <div class=\"note\"><b>Le filtre Site est tolérant.</b> Il n'écarte une ligne que si celle-ci porte réellement un site. Les données qui n'ont pas de rattachement Seem/Semrac (bons de livraison, relevés OAS, ordres de maintenance…) restent affichées même quand vous choisissez un site : c'est volontaire, pour ne pas faire disparaître des informations en donnant l'illusion d'un périmètre propre.</div>\r\n    <div class=\"warn\"><b>Attention :</b> un dashboard ne corrige rien. S'il affiche un indicateur faux, la cause est <b>toujours</b> dans la saisie amont (une date de livraison non renseignée, un BDT jamais soldé, une facture au mauvais statut). Corrigez à la source : le dashboard suivra à la prochaine ouverture.</div>\r\n    <div class=\"astuce\"><b>Astuce :</b> les mesures « instantanées » (stock, retards, backlog, quarantaines) ne dépendent pas de la période choisie — elles décrivent l'état d'aujourd'hui. Seules les séries mensuelles et les cumuls suivent la période.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 2. DIRECTION ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-direction\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Dashboard Direction</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est la vision consolidée de l'entreprise : commerce, finance, production, qualité, RH et maintenance sur un même écran, complétés par le <b>carnet à venir</b> (le CA déjà vendu mais pas encore livré) et par le suivi <b>objectifs vs réel</b>. On l'ouvre pour la revue de direction, la préparation d'un comité, ou simplement pour savoir ce qui brûle aujourd'hui.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li>Six tuiles en haut : <b>CA facturé (mois)</b> avec le cumul et la tendance, <b>Marge brute</b>, <b>OTD global</b> avec le lead time, <b>NC actives</b> (dont 8D et taux de NC), <b>DSO</b> avec l'encours clients, <b>Dispo machines</b> avec l'absentéisme.</li>\r\n      <li><b>CA vs Charges (k€)</b> — deux courbes mensuelles, plus la courbe N-1 en pointillé si la comparaison est active.</li>\r\n      <li><b>Jalons critiques</b> — la liste des vrais points durs du moment, chacun avec une flèche qui mène droit au bon écran : NC critiques ou bloquantes, impayés en retard, ruptures de stock, congés en attente de validation, audits à préparer.</li>\r\n      <li>Section <b>Chiffre d'affaires prévisionnel</b> : Carnet total à venir, CA programmé sur 6 mois, <b>À livrer en retard</b>, Au-delà de 6 mois ; puis le CA programmé par mois de livraison (barres Seem / Semrac empilées) et son détail mensuel en euros.</li>\r\n      <li>Section <b>Objectifs vs Réel</b> : quatre jauges « bullet » (OTD livraison, marge brute, disponibilité machines, absentéisme) où le trait noir marque la cible ; à côté, la répartition du CA par client.</li>\r\n      <li>Quatre cartes de synthèse en bas : <b>Qualité</b>, <b>RH</b>, <b>Stock &amp; Achats</b>, et <b>Accès rapide</b> (Finance, Stock, Fournisseurs, Validations, Objectifs KPI).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-direction.png\" alt=\"Capture du Dashboard Direction\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Direction</b> — les six tuiles donnent le pouls ; à droite, les « Jalons critiques » listent ce qui doit être traité aujourd'hui.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — préparer la revue de direction</h3>\r\n    <ol class=\"steps\">\r\n      <li>Sélectionnez <b>YTD</b> (ou <b>Année</b> pour une revue annuelle) et activez <b>vs N-1</b>.</li>\r\n      <li>Commentez les six tuiles : la pastille de couleur sous chacune dit immédiatement si l'objectif est atteint, à surveiller, ou manqué.</li>\r\n      <li>Descendez sur <b>Objectifs vs Réel</b> : les quatre bullets montrent l'écart à la cible. Si une cible ne correspond plus à la réalité de l'entreprise, ouvrez <b>Objectifs KPI</b> depuis la carte Accès rapide et corrigez-la.</li>\r\n      <li>Passez au carnet à venir : « À livrer en retard » et « CA programmé (6 mois) » indiquent si la charge vendue est tenable.</li>\r\n      <li>Traitez les <b>Jalons critiques</b> un par un en cliquant la flèche de chaque ligne (NC, impayés, ruptures, congés, audits).</li>\r\n      <li>Cliquez <b>Exporter</b> pour joindre l'état au compte rendu.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le graphe du <b>CA programmé</b> ne peut se remplir que si les commandes portent une <b>date de livraison</b> : sans elle, le message « renseignez la date de livraison des commandes » s'affiche à la place.</li>\r\n      <li>Les jalons ne sont pas une liste de tâches à cocher : ce sont des sondes automatiques. Un jalon disparaît quand la donnée qui l'a déclenché est traitée dans son service.</li>\r\n      <li>Les cartes Maintenance et RH de cette page donnent l'état global du parc et de l'effectif, indépendamment du client sélectionné.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> « Marge réelle prod. » (carte Stock &amp; Achats) ne s'affiche que pour les commandes dont la marge a été recalculée au soldage — c'est le meilleur juge de paix entre le chiffrage du BE et la réalité de l'atelier.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 3. COMMERCIAL ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-commercial\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>Dashboard Commercial</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Il suit le cycle de vente de bout en bout : ce qui est facturé, ce qui est proposé et attend une réponse, ce qui est signé mais pas encore livré, et sur quels clients repose le chiffre. C'est l'écran du point commercial hebdomadaire.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li><b>CA facturé</b> sur la période, avec le cumul, le badge de tendance et la mini-courbe mensuelle.</li>\r\n      <li><b>Taux conversion</b> — offres gagnées / offres envoyées, avec l'objectif (30 % par défaut) ; la tuile ouvre la liste des offres.</li>\r\n      <li><b>Pipeline en attente</b> — la valeur des offres encore sans réponse, et leur nombre.</li>\r\n      <li><b>Carnet de commandes</b> — le montant des commandes non soldées, et le panier moyen ; la tuile ouvre la liste des DT.</li>\r\n      <li><b>Commandes Seem vs Semrac (k€)</b> — barres mensuelles par site (+ total N-1 en pointillé si la comparaison est active).</li>\r\n      <li><b>Concentration clients</b> — anneau des principaux clients, titre rappelant la part du premier, et un Pareto avec le pourcentage cumulé.</li>\r\n      <li><b>DT en cours</b> — les six premières, avec un liseré de couleur selon la priorité (rouge = critique, orange = urgent, vert = normal) et un lien « Voir toutes les DT ».</li>\r\n      <li><b>Offres en attente réponse</b> — numéro d'affaire, client, montant et date d'offre, avec un lien vers la liste complète.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-commercial.png\" alt=\"Capture du Dashboard Commercial\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Commercial</b> — CA, conversion, pipeline et carnet en haut ; en dessous, la répartition Seem/Semrac et la concentration clients.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — relancer le pipeline</h3>\r\n    <ol class=\"steps\">\r\n      <li>Laissez la période sur <b>Ce mois</b> et regardez la tuile <b>Pipeline en attente</b> : c'est l'argent qui dort.</li>\r\n      <li>Dans la carte <b>Offres en attente réponse</b>, repérez les offres dont la date est la plus ancienne : ce sont les relances prioritaires.</li>\r\n      <li>Cliquez <b>« Voir toutes les offres »</b> pour ouvrir la liste et traiter chaque offre dans le service Commercial.</li>\r\n      <li>Après relance, revenez au dashboard : le taux de conversion se met à jour dès qu'une offre passe en acceptée.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Une offre en brouillon n'est <b>pas</b> comptée comme envoyée : elle ne pèse ni sur le taux de conversion ni sur le pipeline.</li>\r\n      <li>Le carnet de commandes additionne les commandes <b>ouvertes</b> ; une commande soldée en sort automatiquement.</li>\r\n      <li>Le CA vient des <b>factures client</b>, pas des commandes : un mois sans facturation affiche zéro même si l'atelier a produit.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> une concentration élevée (le premier client au-delà de 40 % du carnet) est un risque commercial ; le Pareto sous l'anneau vous dit combien de clients font 80 % du chiffre.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 4. FINANCE ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-finance\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Dashboard Finance</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le tableau de bord de la trésorerie et de la rentabilité : ce qui est facturé, ce qui est dépensé, ce qui est réellement encaissé, et ce que les clients doivent encore. On l'ouvre avant un point banque, avant une campagne de relance, ou pour vérifier que la marge tient.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li><b>CA HT</b> de la période (avec la marge en euros et la mini-courbe), <b>Taux de marge</b> (CA − charges, objectif 25 %), <b>Trésorerie nette</b> (encaissé − décaissé, en vert si positive, en rouge sinon), <b>DSO</b> en jours avec l'encours clients.</li>\r\n      <li><b>CA vs Charges (HT)</b> — deux courbes mensuelles (+ CA N-1 en pointillé).</li>\r\n      <li><b>Top clients (CA HT)</b> — barres classées.</li>\r\n      <li><b>Encaissements vs Décaissements (TTC)</b> — barres vertes et rouges par mois, à partir des dates de paiement.</li>\r\n      <li><b>Balance âgée</b> — deux blocs symétriques (créances clients puis dettes fournisseurs) découpés en 0–30 j, 30–60 j, 60–90 j et +90 j, suivis des <b>Impayés en retard</b> et du <b>DPO fournisseurs</b>.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-finance.png\" alt=\"Capture du Dashboard Finance\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Finance</b> — la balance âgée en bas à droite : plus les barres glissent vers « +90 j », plus le recouvrement est en retard.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — préparer une campagne de relance</h3>\r\n    <ol class=\"steps\">\r\n      <li>Choisissez <b>YTD</b> pour raisonner sur l'ensemble de l'année.</li>\r\n      <li>Lisez le <b>DSO</b> : au-delà de la cible (45 jours par défaut), la pastille passe à l'orange puis au rouge.</li>\r\n      <li>Dans la <b>Balance âgée</b>, repérez le poids des tranches 60–90 j et +90 j, et le montant des <b>impayés en retard</b>.</li>\r\n      <li>Filtrez sur un <b>client</b> pour isoler son encours avant de l'appeler.</li>\r\n      <li>Traitez les règlements dans le service Comptabilité : le passage d'une facture au statut « payée » alimente immédiatement la trésorerie et les encaissements.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>La <b>trésorerie</b> affichée n'est pas un solde bancaire : c'est la différence entre les factures client encaissées et les factures fournisseur payées sur la période.</li>\r\n      <li>Le <b>DSO</b> se lit « nombre de jours de chiffre d'affaires immobilisés dans les créances » ; le <b>DPO</b> est son équivalent côté fournisseurs (une valeur plus haute y est plutôt favorable à la trésorerie).</li>\r\n      <li>Les brouillons et les factures annulées sont exclus des encours et de la balance âgée.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> sans <b>date d'échéance</b> sur les factures, la balance âgée reste vide. Sans <b>date de paiement</b>, le graphe encaissements/décaissements reste vide alors même que la facture est marquée payée.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 5. BUREAU ÉTUDES ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-be\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Dashboard Bureau Études</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Il mesure le travail du bureau d'études : le flux de demandes de travaux à analyser, la qualité du chiffrage (coût de revient unitaire, structure de coût, marge) et la complétude des nomenclatures. C'est l'écran qui dit si le BE est en retard sur les analyses et si les prix tiennent la route.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li><b>DT à analyser</b> (avec le nombre total de DT ouvertes) — la tuile ouvre la liste des DT ; <b>DT analysées</b> en pourcentage ; <b>CRU moyen</b> en euros par pièce avec le nombre de nomenclatures chiffrées ; <b>Marge brute moyenne</b> avec le détail Seem / Semrac (objectif 25 %).</li>\r\n      <li><b>Structure de coût moyenne du CRU</b> — une barre empilée horizontale décomposant matière, main d'œuvre, machine et sous-traitance, avec les montants rappelés en dessous.</li>\r\n      <li><b>Corrélation CRU ↔ marge</b> — un nuage de points (axe X : coût de revient par pièce, axe Y : marge en %) : il montre si l'on marge moins sur les pièces chères.</li>\r\n      <li><b>Pièces les plus coûteuses</b> — classement des CRU par pièce.</li>\r\n      <li><b>Complétude des nomenclatures</b> — un pourcentage et une barre : une nomenclature est dite complète quand elle a une <b>gamme</b>, une <b>matière</b> et le statut <b>validée</b>.</li>\r\n      <li><b>DT entrantes par mois</b> (+ N-1 en pointillé) et la <b>file d'attente des DT à traiter</b>, avec la priorité en liseré, le site et le délai.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-be.png\" alt=\"Capture du Dashboard Bureau Études\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Bureau Études</b> — la structure de coût et la complétude des nomenclatures disent où le chiffrage est solide et où il est encore approximatif.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — assainir le chiffrage</h3>\r\n    <ol class=\"steps\">\r\n      <li>Regardez la <b>Complétude des nomenclatures</b> : chaque point manquant (gamme, matière ou validation) fausse le CRU.</li>\r\n      <li>Ouvrez <b>Pièces les plus coûteuses</b> et vérifiez que les CRU les plus élevés correspondent bien à des pièces réellement complexes.</li>\r\n      <li>Dans le nuage <b>CRU ↔ marge</b>, repérez les points en bas à droite : pièces chères à faible marge — ce sont les prix à renégocier ou les gammes à revoir.</li>\r\n      <li>Traitez la <b>file d'attente</b> en commençant par les priorités critiques (liseré rouge) : la tuile « DT à analyser » ouvre la liste complète.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Une DT est comptée comme « analysée » dès qu'un <b>analyste</b> lui est affecté ; celles sans analyste rejoignent la file d'attente.</li>\r\n      <li>La marge affichée provient des <b>marges saisies pièce par pièce</b> lors de l'analyse : sans coefficient renseigné, la tuile affiche un tiret.</li>\r\n      <li>Le filtre <b>Site</b> agit ici sur l'entité de la nomenclature (Seem / Semrac).</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> la structure de coût est la réponse la plus rapide à « pourquoi cette pièce coûte-t-elle si cher ? » — si la sous-traitance domine, la piste d'économie n'est pas dans l'atelier.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 6. ACHATS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-achats\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">6</span><h2>Dashboard Achats</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Il pilote les approvisionnements : les demandes d'achat en attente, les bons de commande en cours, les retards de livraison fournisseur et la dépense engagée. C'est l'écran du quotidien de l'acheteur.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li><b>DA à traiter</b> avec le nombre de demandes critiques — la tuile ouvre la liste des DA ; <b>BC en cours</b> sur le total ; <b>Retards fournisseur</b> (vert s'il n'y en a aucun, rouge sinon) ; <b>Achats</b> de la période avec le cumul et la mini-courbe.</li>\r\n      <li><b>Dépenses achats mensuelles</b> — courbe des factures fournisseur HT (+ N-1 en pointillé).</li>\r\n      <li><b>Pareto dépense fournisseur</b> — barres avec le pourcentage cumulé. Le titre précise <b>« (BC engagés) »</b> quand aucune facture n'existe encore sur la période : le calcul bascule alors sur les montants des bons de commande.</li>\r\n      <li><b>Ancienneté des BC en retard</b> — l'argent en retard réparti en 0–30 j, 30–60 j, 60–90 j et +90 j, avec le total.</li>\r\n      <li><b>Répartition des DA par nature</b> — anneau par catégorie de demande.</li>\r\n      <li><b>DA en attente de traitement</b> — six lignes avec le demandeur, l'article, le statut et la priorité.</li>\r\n      <li><b>Performance fournisseurs (OTD)</b> — une jauge de l'OTD global des réceptions plus les six premiers fournisseurs avec leur OTD (vert à partir de 85 %) et leur statut.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-achats.png\" alt=\"Capture du Dashboard Achats\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Achats</b> — « Retards fournisseur » et « Ancienneté des BC en retard » chiffrent en euros ce que les retards immobilisent.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — traiter la journée d'achats</h3>\r\n    <ol class=\"steps\">\r\n      <li>Ouvrez la page : la tuile <b>DA à traiter</b> donne la charge du jour, dont les critiques.</li>\r\n      <li>Cliquez la tuile (ou « Voir toutes les DA ») pour ouvrir la liste et transformer les demandes en bons de commande.</li>\r\n      <li>Revenez sur <b>Retards fournisseur</b> et sur l'ancienneté des BC : relancez d'abord les tranches les plus anciennes et les montants les plus lourds.</li>\r\n      <li>Filtrez sur un <b>fournisseur</b> pour préparer un point avec lui : dépense, retards et OTD s'ajustent à son périmètre.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Un BC est « en retard » dès que sa date de livraison est dépassée et qu'il n'est ni reçu ni clôturé.</li>\r\n      <li>Les indicateurs de retard et de backlog sont des <b>instantanés</b> : ils ne dépendent pas de la période choisie, seule la dépense la suit.</li>\r\n      <li>Le prix ne se saisit jamais sur un BC : il vient des demandes de prix (RFQ). Le dashboard ne fait que consolider ce qui a été engagé.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> pour un point fournisseur complet (scorecard, NC, concentration), passez au <b>Dashboard Fournisseurs</b> : les deux pages se complètent.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 7. FOURNISSEURS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-fournisseurs\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">7</span><h2>Dashboard Fournisseurs</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est l'évaluation du panel : qui livre à l'heure, qui livre complet, qui coûte cher, qui génère des non-conformités. Il sert à préparer les revues fournisseurs, à décider d'une requalification et à surveiller la dépendance à un fournisseur unique.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li><b>Fournisseurs / ST</b> — nombre total référencé et nombre d'actifs ; <b>OTD global</b> avec le <b>fill rate</b> (quantité reçue / quantité commandée) ; <b>Dépense</b> de la période avec le nombre de NC fournisseur ; <b>Concentration</b> — part du premier fournisseur dans la dépense, affichée en rouge au-delà de 40 %.</li>\r\n      <li><b>Scorecard fournisseurs</b> — le tableau central : Fournisseur, Type (<span class=\"b b-info\">Fourn.</span> ou <span class=\"b b-info\">ST</span>), OTD (vert ≥ 85 %, rouge en dessous), nombre de BC, Dépense, NC, Statut (<span class=\"b b-ok\">actif</span> ou <span class=\"b b-warn\">inactif</span>).</li>\r\n      <li><b>Dépense par fournisseur</b> — anneau de répartition.</li>\r\n      <li><b>Nuage OTD × dépense</b> — chaque bulle est un fournisseur : X = OTD, Y = dépense, taille = nombre de BC. Le quart en bas à gauche (peu ponctuel, peu de dépense) et surtout le quart en haut à gauche (gros budget, mauvaise ponctualité) sont les zones à traiter.</li>\r\n      <li><b>NC par fournisseur</b> — barres classées.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-fournisseurs.png\" alt=\"Capture du Dashboard Fournisseurs\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Fournisseurs</b> — la scorecard croise ponctualité, volume, dépense et non-conformités : c'est le support de la revue de panel.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — préparer une revue fournisseur</h3>\r\n    <ol class=\"steps\">\r\n      <li>Choisissez <b>12 mois</b> pour lisser les à-coups d'un mois isolé.</li>\r\n      <li>Triez visuellement la <b>scorecard</b> : elle est déjà classée par dépense décroissante, donc les enjeux sont en haut.</li>\r\n      <li>Croisez avec le <b>nuage OTD × dépense</b> : une grosse bulle à gauche du graphe = beaucoup d'argent chez un fournisseur peu ponctuel.</li>\r\n      <li>Regardez la colonne <b>NC</b> et le graphe « NC par fournisseur » pour objectiver la qualité de la réception.</li>\r\n      <li>Exportez la page en PDF : elle constitue la pièce jointe de la revue.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>L'OTD est calculé sur la <b>première</b> date de livraison promise : décaler la date d'un BC déjà en retard ne rattrape pas la note du fournisseur.</li>\r\n      <li>Un fournisseur sans BC daté et réceptionné affiche « — » : la note ne s'invente pas.</li>\r\n      <li>Le fill rate se calcule sur les quantités commandées et reçues des BC ; il reste à 0 tant que ces quantités ne sont pas saisies.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> une concentration au-delà de 40 % signale une dépendance. C'est une alerte de gestion des risques (rupture, hausse de prix), même si le fournisseur donne entière satisfaction.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 8. PRODUCTION ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-production\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">8</span><h2>Dashboard Production</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Il mesure la performance de l'atelier : tenue des délais (OTD), tenue des délais <i>et</i> de la conformité (OTK), rythme (takt time), durée de traversée (lead time), reprises, et charge prévisionnelle. C'est l'écran du responsable de production et du point quotidien.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li>Cinq tuiles : <b>Avancement BDT</b> (bons soldés / total, la tuile ouvre la liste des BDT), <b>OTD</b> (objectif 95 %), <b>OTK</b> — « à l'heure &amp; conforme » (objectif 92 %), <b>Lead time moyen</b> en jours (commande → livraison), <b>Taux de reprise</b> avec l'en-cours (WIP), objectif 3 %.</li>\r\n      <li>Trois <b>jauges</b> (OTD, OTK, Avancement) avec le repère de cible, et la <b>charge par opération</b> des BDT actifs en heures.</li>\r\n      <li><b>Takt time &amp; incidents</b> — takt Seem et takt Semrac en minutes, NC ouvertes et reprises.</li>\r\n      <li><b>BDT récents</b> — tableau BDT / Opération / Durée / Statut (les bons soldés portent un badge vert).</li>\r\n      <li><b>Charge atelier prévisionnelle (8 semaines)</b> — barres des heures planifiées, en <span class=\"b b-crit\">rouge</span> lorsqu'elles dépassent la ligne noire de capacité ; à côté, une synthèse : capacité par semaine, opérateurs actifs, semaines en surcharge, heures en retard à replanifier, heures au-delà de 8 semaines.</li>\r\n      <li><b>Distribution du lead time</b> (&lt; 7 j / 7–14 j / 14–30 j / 30 j et +) et <b>Productivité — temps alloué vs réel</b> avec l'écart en pourcentage (vert si l'on est sous le temps alloué, rouge si on le dépasse).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-production.png\" alt=\"Capture du Dashboard Production\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Production</b> — les jauges OTD/OTK portent le repère noir de la cible ; plus bas, la charge prévisionnelle signale les semaines en surcharge.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — comprendre un OTK qui décroche</h3>\r\n    <ol class=\"steps\">\r\n      <li>Comparez <b>OTD</b> et <b>OTK</b> : si l'OTD est bon mais l'OTK mauvais, le problème n'est pas le délai mais la conformité.</li>\r\n      <li>Regardez la carte <b>Takt time &amp; incidents</b> : le nombre de NC ouvertes et de reprises explique l'écart.</li>\r\n      <li>Ouvrez le <b>Dashboard Qualité</b> pour identifier les familles de défauts (Pareto par type et par gravité).</li>\r\n      <li>Vérifiez enfin <b>temps alloué vs réel</b> : un écart fortement positif signale des gammes sous-estimées, qui poussent aux reprises et aux retards.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>L'<b>OTD</b> compare la date de livraison réellement constatée (BL) à la date promise ; si l'une des deux manque, la commande n'entre pas dans le calcul.</li>\r\n      <li>L'<b>OTK</b> part de l'OTD et le dégrade en fonction des NC <b>critiques ou bloquantes</b> encore ouvertes : il ne peut donc jamais dépasser l'OTD.</li>\r\n      <li>La capacité de l'atelier est estimée à <b>7 heures par opérateur présent</b> ; un opérateur en absence du jour n'est pas compté.</li>\r\n      <li>Les heures « en retard (à replanifier) » correspondent à des BDT dont la date prévue est déjà passée : elles ne disparaîtront pas seules.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> le takt time n'apparaît que si des lots ont été terminés dans le mois de référence ; sans quantité livrée, il affiche « — ».</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 9. PROGRAMMATION ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-programmation\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">9</span><h2>Dashboard Programmation</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le tableau de bord de l'ordonnanceur : ce qui reste à programmer, ce qui n'est pas affecté à un opérateur, ce qui n'a pas de date, et si la charge des huit prochaines semaines tient dans la capacité. Il complète le planning unique du service Production.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li><b>BDT actifs</b> avec le nombre restant à affecter (la tuile ouvre la liste des BDT) ; <b>Charge atelier</b> en pourcentage, avec le détail « opérateurs disponibles / total » et « heures planifiées / capacité » — la tuile passe au rouge à partir de 90 % ; <b>Cmd à programmer</b> (commandes ouvertes sans lot ni BDT créé) ; <b>ST en cours</b> (bons de sous-traitance actifs).</li>\r\n      <li><b>Charge prévisionnelle 8 semaines</b> — barres des heures planifiées face à la ligne de capacité, et une <b>synthèse planning</b> (capacité hebdomadaire, opérateurs actifs, semaines en surcharge, heures en retard, heures au-delà de 8 semaines).</li>\r\n      <li><b>Charge par opérateur — aujourd'hui</b> — une barre par opérateur (verte, orange dès 70 %, rouge dès 90 %), un badge <span class=\"b b-crit\">Absent</span> pour les absents du jour, et le lien <b>« Ouvrir Gantt → »</b> vers le planning.</li>\r\n      <li><b>Charge par opération (h)</b>, <b>Sous-traitance active</b>, <b>Commandes en attente prog.</b> avec le bouton <b>« Ordonnancer → »</b>.</li>\r\n      <li><b>File d'ordonnancement — BDT à traiter</b> — deux compteurs (à affecter / non planifiés) puis la liste des BDT avec leur durée et le badge « à affecter ».</li>\r\n      <li><b>Charge ouverte par site (h)</b> — anneau Seem / Semrac.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-programmation.png\" alt=\"Capture du Dashboard Programmation\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Programmation</b> — la charge des huit semaines à venir et la file d'ordonnancement : ce qui n'est ni affecté ni daté est listé noir sur blanc.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — vider la file d'ordonnancement</h3>\r\n    <ol class=\"steps\">\r\n      <li>Lisez la tuile <b>Charge atelier</b> : au-delà de 90 %, toute nouvelle affectation créera du retard.</li>\r\n      <li>Ouvrez la carte <b>File d'ordonnancement</b> : le compteur orange donne les BDT sans opérateur, le rouge ceux sans date.</li>\r\n      <li>Cliquez <b>« Ordonnancer → »</b> pour ouvrir l'écran de programmation et donner à chaque BDT un poste et une date.</li>\r\n      <li>Affectez les opérateurs depuis <b>« Ouvrir Gantt → »</b> en évitant ceux qui sont déjà au rouge et ceux marqués Absent.</li>\r\n      <li>Traitez enfin les <b>Commandes en attente prog.</b> : chacune doit donner lieu à un lot puis à ses BDT.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>La charge affichée ici est <b>recalculée sur le périmètre filtré</b> : si vous choisissez le site Seem, la capacité ne compte que les opérateurs de Seem — le chiffre peut donc différer de celui du Dashboard Production.</li>\r\n      <li>Une semaine dont la barre dépasse la ligne noire est <b>en surcharge</b> : il faut décaler, sous-traiter ou renforcer.</li>\r\n      <li>Les BDT sans date prévue n'apparaissent dans <b>aucune</b> semaine du graphe : la file d'ordonnancement est le seul endroit où on les voit.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> « Cmd à programmer » à zéro et file d'ordonnancement vide, c'est le signe que le carnet est entièrement traduit en travail planifié — l'objectif de fin de journée pour l'ordonnancement.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 10. QUALITÉ ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-qualite\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">10</span><h2>Dashboard Qualité</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Il donne l'état de la conformité : non-conformités ouvertes et leur ancienneté, taux de NC, capabilité des cotes (Cp/Cpk, PPM), libération des PV, quarantaines et 8D, plus le rappel des ECME à étalonner et des audits à planifier. C'est le support de la revue qualité et de la préparation d'audit.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li>Cinq tuiles : <b>NC ouvertes</b> avec le nombre de critiques (la tuile ouvre la liste des NC), <b>Taux de NC</b> (NC rapportées aux lots, cible ≤ 2 %), <b>Cpk moyen</b> avec le nombre de contrôles et le PPM (cible 1,33), <b>Libération PV</b> en pourcentage (cible 95 %), <b>Quarantaines</b> avec la durée moyenne et le nombre de 8D en cours.</li>\r\n      <li><b>Non-conformités par mois</b> — courbe (+ N-1 en pointillé).</li>\r\n      <li>Une jauge <b>Conformité cotes</b> avec le rappel Cp · Cpk · PPM (ou un message si aucun contrôle de cote n'a été saisi).</li>\r\n      <li><b>NC actives à traiter</b> — six NC avec type, gravité, statut et date ; le fond et le liseré passent au rouge pour les gravités critiques et bloquantes.</li>\r\n      <li><b>Contrôles &amp; audits</b> — deux compteurs : <b>ECME à étalonner</b> (sur le total d'instruments) et <b>Audits à planifier</b>.</li>\r\n      <li>Section <b>Analyse des non-conformités</b> : <b>Pareto NC par type</b>, <b>NC par gravité</b> (anneau) et <b>Ancienneté des NC ouvertes</b> (0–30 j, 30–60 j, 60–90 j, 90 j et +).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-qualite.png\" alt=\"Capture du Dashboard Qualité\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Qualité</b> — l'ancienneté des NC ouvertes (en bas à droite) révèle les dossiers oubliés, souvent invisibles dans le compteur global.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — la revue qualité hebdomadaire</h3>\r\n    <ol class=\"steps\">\r\n      <li>Période <b>Ce mois</b>, comparaison <b>vs N-1</b> activée : la courbe des NC dit si la situation s'améliore ou se dégrade d'une année sur l'autre.</li>\r\n      <li>Traitez d'abord les NC critiques et bloquantes de la carte « NC actives » : elles bloquent aussi les expéditions des lots concernés.</li>\r\n      <li>Regardez l'<b>ancienneté des NC ouvertes</b> : toute barre à droite (60 j et plus) est un dossier qui traîne.</li>\r\n      <li>Utilisez le <b>Pareto par type</b> pour choisir la famille de défauts à attaquer en action de fond.</li>\r\n      <li>Vérifiez les compteurs <b>ECME à étalonner</b> et <b>Audits à planifier</b> avant toute échéance de certification.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le <b>taux de NC</b> rapporte le nombre de NC au nombre de lots : sans lots enregistrés, il reste à 0 même s'il existe des NC.</li>\r\n      <li>Le <b>Cpk</b> est agrégé à partir des contrôles de cotes saisis ; il faut au minimum deux mesures exploitables pour qu'il s'affiche.</li>\r\n      <li>La <b>libération PV</b> compte les PV qui ne sont ni bloqués ni refusés : elle chute dès qu'un contrôle final reste en attente de décision.</li>\r\n      <li>Le filtre <b>Site</b> s'applique ici à l'entité de la NC (Seem / Semrac).</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> ce dashboard est la vue « chiffres » ; l'onglet <b>Dashboard Qualité</b> du service Qualité propose en plus le Pareto multi-axes et la « Conformité vive » des audits. Les deux se complètent.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 11. OAS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-oas\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">11</span><h2>Dashboard OAS</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Il surveille l'atelier d'oxydation anodique : le volume de sessions traitées, la conformité des bains (concentration, température, pH) et l'autosurveillance des rejets d'eau. C'est à la fois un outil de production et une pièce de preuve pour l'environnement.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li><b>Sessions OAS</b> sur la période et au total ; <b>Conformité bains</b> en pourcentage avec le nombre de relevés et, le cas échéant, le nombre de relevés non conformes — la mini-courbe suit le pH du bain principal ; <b>Conformité sessions</b> avec le nombre de sessions terminées ; <b>Durée moyenne</b> de traitement en minutes.</li>\r\n      <li><b>État des bains — derniers paramètres</b> — une carte par bain avec sa concentration (g/L), sa température et son pH, sur fond vert avec la pastille <span class=\"b b-ok\">OK</span> ou sur fond orange avec <span class=\"b b-warn\">⚠</span>.</li>\r\n      <li><b>Sessions par mois</b> — barres (+ N-1 en pointillé).</li>\r\n      <li><b>Relevés d'eau (autosurveillance rejets)</b> — tableau Date, Volume, pH, Chlore, Turbidité et une colonne Conforme (<span class=\"b b-ok\">✓</span> ou <span class=\"b b-crit\">✗ NC</span>).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-oas.png\" alt=\"Capture du Dashboard OAS\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard OAS</b> — l'état des bains affiche le <i>dernier</i> relevé de chaque bain : c'est la photo de l'instant, pas une moyenne.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — contrôle de début de journée</h3>\r\n    <ol class=\"steps\">\r\n      <li>Ouvrez le dashboard et lisez <b>État des bains</b> : un bain sur fond orange signale un dernier relevé non conforme.</li>\r\n      <li>Retournez dans le service OAS pour refaire le relevé et corriger le bain avant de lancer les balancelles.</li>\r\n      <li>Contrôlez la tuile <b>Conformité sessions</b> : elle compare les sessions terminées conformes au total des sessions terminées.</li>\r\n      <li>Vérifiez le tableau des <b>relevés d'eau</b> : toute ligne « ✗ NC » doit être justifiée dans le suivi environnemental.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>La conformité des <b>bains</b> et celle des <b>sessions</b> sont deux choses différentes : la première vient des relevés de bain, la seconde du résultat des balancelles terminées.</li>\r\n      <li>Les bains affichent l'état <b>instantané</b> (dernier relevé connu par bain) : ils ne bougent pas quand vous changez la période.</li>\r\n      <li>Un relevé de bain non conforme déclenche une non-conformité côté Qualité : le suivi ne s'arrête pas à ce dashboard.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> exportez cette page en PDF avant une visite d'inspection : elle rassemble sur une feuille l'état des bains et l'autosurveillance des rejets.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 12. MAINTENANCE ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-maintenance\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">12</span><h2>Dashboard Maintenance</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Il donne la santé du parc machines : disponibilité, pannes en cours, MTBF/MTTR, part du préventif face au correctif, coût de maintenance et OPEX par machine. C'est le seul dashboard qui contient aussi une <b>action</b> : générer les ordres de maintenance préventifs échus.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li><b>Machines en panne</b> avec le nombre d'OM ouverts ; <b>Disponibilité parc</b> avec l'OEE et le nombre de machines (objectif 90 %) ; <b>MTTR moyen</b> en heures avec le MTBF ; <b>Ratio préventif</b> avec le décompte préventif / correctif et, si l'OPEX est renseigné, le coût horaire réel.</li>\r\n      <li>Une <b>jauge de disponibilité</b>, un anneau <b>Préventif vs Correctif</b>, et la liste <b>Statut machines</b> (<span class=\"b b-ok\">opérationnel</span>, <span class=\"b b-info\">maintenance</span>, <span class=\"b b-crit\">autre état</span>).</li>\r\n      <li><b>Prochaines maintenances</b> — les échéances préventives et les OM datés, triés par date, précédés du bouton <b>« Générer les OM préventifs dus »</b>.</li>\r\n      <li><b>Backlog OM par âge</b> — 0–7 j, 8–30 j, 31–90 j, plus de 90 j, suivi des OM ouverts les plus anciens.</li>\r\n      <li><b>Coût de maintenance mensuel</b> (+ N-1 en pointillé), <b>OPEX par machine</b> avec le total, les heures productives et le coût horaire réel, et le tableau <b>MTBF / MTTR par machine</b> (Machine, MTBF, MTTR, Dispo, Pannes) classé du plus long temps de réparation au plus court.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-maintenance.png\" alt=\"Capture du Dashboard Maintenance\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Maintenance</b> — le bouton jaune « Générer les OM préventifs dus » et, plus bas, le backlog des OM par âge.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — générer les préventifs échus</h3>\r\n    <ol class=\"steps\">\r\n      <li>Ouvrez la carte <b>Prochaines maintenances</b> et vérifiez les échéances listées.</li>\r\n      <li>Cliquez <b>« Générer les OM préventifs dus »</b>.</li>\r\n      <li>Un message confirme le nombre d'ordres créés (« <i>n</i> OM préventif(s) généré(s). »), puis la page se recharge.</li>\r\n      <li>Les ordres créés sont désormais dans le service <b>Maintenance</b> : affectez-les et planifiez-les comme des OM ordinaires.</li>\r\n      <li>Contrôlez ensuite le <b>Ratio préventif</b> : il doit remonter à mesure que le préventif est réellement exécuté.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le filtre <b>Machine</b> restreint tout l'écran (disponibilité, OM, MTBF/MTTR, OPEX) à un seul équipement : idéal pour instruire une machine à problèmes.</li>\r\n      <li>La disponibilité provient des relevés MTBF quand ils existent ; à défaut, elle est estimée par la part de machines à l'état « opérationnel ».</li>\r\n      <li>L'<b>OPEX par machine</b> reste vide tant que les consommations et achats rattachés aux machines ne sont pas saisis — le coût horaire réel n'apparaît alors pas non plus.</li>\r\n      <li>Le <b>backlog</b> se calcule depuis la date de signalement : un OM ouvert sans date de signalement n'y figure pas.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> « Générer les OM préventifs dus » <b>crée réellement</b> des ordres de maintenance dans l'ERP. Ne cliquez pas « pour voir » : lancez-le quand vous êtes prêt à les traiter.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 13. STOCK ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-stock\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">13</span><h2>Dashboard Stock</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Il répond à trois questions : combien vaut le stock, qu'est-ce qui manque, et qu'est-ce qui dort. Il fournit aussi le classement ABC (où concentrer les efforts de gestion) et des suggestions de réapprovisionnement prêtes à commander.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li><b>Valorisation stock</b> avec le nombre de références ; <b>Ruptures</b> (articles à zéro) et le nombre d'articles sous le mini ; <b>Rotation stock</b> avec la couverture moyenne en mois (objectif 6) ; <b>Dead stock (&gt; 6 mois)</b> avec la valeur immobilisée.</li>\r\n      <li><b>Flux entrées / sorties</b> — barres mensuelles vertes et rouges (+ sorties N-1 en pointillé).</li>\r\n      <li><b>Valeur par activité</b> — anneau.</li>\r\n      <li><b>Classement ABC (Pareto valeur)</b> — barres de valeur, courbe du pourcentage cumulé et trois pavés récapitulatifs : <span class=\"b b-crit\">A</span> (jusqu'à 80 % de la valeur), <span class=\"b b-warn\">B</span> (80 à 95 %), <span class=\"b b-ok\">C</span> (le reste), chacun avec son nombre de références et son montant.</li>\r\n      <li><b>Suggestions de réappro</b> — tableau Référence, Stock, Point de commande, À commander, avec un badge <span class=\"b b-info\">AUTO</span> pour les articles en réapprovisionnement automatique, et un lien « Gérer le stock ».</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-stock.png\" alt=\"Capture du Dashboard Stock\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Stock</b> — le classement ABC et les suggestions de réappro : la liste de courses est déjà triée par urgence.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — lancer un réapprovisionnement</h3>\r\n    <ol class=\"steps\">\r\n      <li>Contrôlez les tuiles <b>Ruptures</b> et « sous le mini » : ce sont les urgences.</li>\r\n      <li>Descendez sur <b>Suggestions de réappro</b> : les lignes sont classées des plus critiques (stock le plus loin sous le point de commande) aux moins urgentes.</li>\r\n      <li>Notez la colonne <b>À commander</b> : c'est la quantité calculée (quantité de commande paramétrée, ou l'écart au stock maxi).</li>\r\n      <li>Cliquez <b>« Gérer le stock → »</b> pour créer les demandes d'achat correspondantes dans le service Stock, qui alimenteront ensuite les Achats.</li>\r\n      <li>Surveillez enfin le <b>Dead stock</b> : ce sont des références sans entrée depuis plus de six mois — candidates au déstockage plutôt qu'au réachat.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le stock est un <b>niveau instantané</b> : le filtre Site s'applique, mais la période choisie n'agit que sur le graphe des flux mensuels.</li>\r\n      <li>La <b>rotation</b> et la <b>couverture</b> reposent sur la consommation mensuelle renseignée sur l'article : sans elle, ces indicateurs affichent « — ».</li>\r\n      <li>La <b>valorisation</b> utilise le prix d'achat HT de la fiche article ; un prix manquant sous-évalue le stock.</li>\r\n      <li>Les articles désactivés sont exclus de tous les calculs.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> concentrez les inventaires tournants et les négociations d'achat sur la <b>classe A</b> : peu de références, l'essentiel de la valeur.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 14. EXPÉDITIONS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-expedition\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">14</span><h2>Dashboard Expéditions</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Il prépare et contrôle les départs : quelles commandes sont prêtes à partir, lesquelles sont bloquées par la qualité, combien de bons de livraison ont été émis, et si les délais promis aux clients sont tenus.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li><b>Cmd à expédier</b> — commandes dont la production est soldée et la qualité au vert ; la ligne de contexte indique « Production soldée + qualité OK », ou passe en rouge avec le nombre de commandes <b>bloquées qualité</b>.</li>\r\n      <li><b>OTD livraisons</b> en pourcentage avec le nombre de commandes évaluées (objectif 95 %).</li>\r\n      <li><b>BL clients (total)</b> et le nombre émis sur la période.</li>\r\n      <li><b>Retards en cours</b> — commandes ouvertes marquées en retard.</li>\r\n      <li><b>Commandes en attente d'expédition</b> — client, montant, date de livraison prévue et statut, avec le lien « Voir tous les BL ».</li>\r\n      <li><b>BL clients par mois</b> (+ N-1 en pointillé), <b>Volume expédié (qté) par mois</b> et <b>Répartition par transporteur</b> (anneau).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-expedition.png\" alt=\"Capture du Dashboard Expéditions\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Expéditions</b> — la première tuile distingue ce qui est réellement expédiable de ce que la qualité retient.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — organiser les départs du jour</h3>\r\n    <ol class=\"steps\">\r\n      <li>Lisez la tuile <b>Cmd à expédier</b> : si elle est rouge, des commandes prêtes sont retenues par une non-conformité.</li>\r\n      <li>Parcourez <b>Commandes en attente d'expédition</b> et triez mentalement par date de livraison promise.</li>\r\n      <li>Cliquez <b>« Voir tous les BL → »</b> pour créer les bons de livraison dans le service Expéditions.</li>\r\n      <li>Pour les commandes bloquées, passez par le <b>Dashboard Qualité</b> ou la liste des NC : la levée de la NC débloque l'expédition.</li>\r\n      <li>En fin de mois, contrôlez l'<b>OTD livraisons</b> et le volume expédié pour la revue avec le commerce.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Une commande n'est proposée à l'expédition que si <b>tous</b> ses bons de travail sont soldés.</li>\r\n      <li>Une NC <b>critique ou bloquante</b> encore ouverte sur un lot de la commande la fait basculer en « bloquée qualité » : c'est la porte qualité, elle est volontaire.</li>\r\n      <li>Le compteur « BL clients » ne prend que les livraisons <b>clients</b> : les bons de réception et les bons de sous-traitance en sont exclus.</li>\r\n      <li>L'OTD affiché est le même que celui du Dashboard Production : une seule définition pour toute l'entreprise.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> la répartition par transporteur reste vide tant que le champ transport n'est pas renseigné sur les BL — c'est une saisie à ne pas négliger si vous voulez négocier avec vos transporteurs.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 15. RH ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-rh\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">15</span><h2>Dashboard RH</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Il suit l'effectif, les absences, les heures travaillées et surtout les <b>habilitations</b> — le point le plus sensible en aéronautique, où une certification périmée peut interdire une opération. On l'ouvre pour le suivi mensuel et pour anticiper les renouvellements.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li><b>Effectif actif</b> avec le nombre d'opérateurs ; <b>Absences</b> sur la période avec le taux d'absentéisme (cible ≤ 4 %) ; <b>Habilitations ⚠</b> avec le nombre qui expire sous 30 jours (la tuile ouvre la page Compétences) ; <b>Heures</b> de la période dont les heures supplémentaires.</li>\r\n      <li><b>Effectif par entité</b> et <b>Répartition par type de contrat</b> — deux anneaux.</li>\r\n      <li><b>Tendance absentéisme</b> — courbe du nombre d'absences par mois (+ N-1 en pointillé).</li>\r\n      <li><b>Ancienneté des habilitations</b> — quatre pavés : <span class=\"b b-crit\">Déjà expiré</span>, <span class=\"b b-warn\">&lt; 30 j</span>, <span class=\"b b-warn\">30–60 j</span>, <span class=\"b b-ok\">60–90 j</span>.</li>\r\n      <li><b>Présence opérateurs — aujourd'hui</b> — badge <span class=\"b b-ok\">Présent</span> ou <span class=\"b b-crit\">Absent</span> par opérateur.</li>\r\n      <li><b>Habilitations / Certifications</b> — salarié, intitulé et statut, avec le lien « Gérer les compétences ».</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-rh.png\" alt=\"Capture du Dashboard RH\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard RH</b> — les quatre pavés d'ancienneté des habilitations donnent le calendrier des renouvellements à lancer.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — anticiper les renouvellements d'habilitation</h3>\r\n    <ol class=\"steps\">\r\n      <li>Regardez le pavé <b>Déjà expiré</b> : ces habilitations ne couvrent plus rien, les opérations associées doivent être réaffectées immédiatement.</li>\r\n      <li>Traitez ensuite <b>&lt; 30 j</b>, puis 30–60 j : ce sont les formations à programmer maintenant.</li>\r\n      <li>Cliquez la tuile <b>Habilitations</b> ou le lien <b>« Gérer les compétences → »</b> pour ouvrir la page des compétences et mettre à jour les dates.</li>\r\n      <li>Contrôlez enfin la <b>Présence opérateurs</b> du jour avant de valider le planning d'atelier.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le <b>taux d'absentéisme</b> rapporte les jours d'absence de la période à l'effectif multiplié par les jours ouvrés : il n'a de sens que si les absences sont saisies au fil de l'eau.</li>\r\n      <li>Les <b>heures</b> et les <b>heures supplémentaires</b> proviennent des pointages ; sans pointage, les tuiles restent à zéro.</li>\r\n      <li>Le filtre <b>Site</b> agit sur l'entité du salarié ; absences, pointages et certifications, qui n'ont pas de site propre, ne sont pas écartés.</li>\r\n      <li>Ce dashboard est réservé aux profils qui ont la <b>lecture RH</b>.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> les heures relevées ici sont la base des exports de paie : un écart entre « Heures » et ce que vous attendez signale d'abord un pointage manquant, pas une erreur de calcul.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 16. ENVIRONNEMENT ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-environnement\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">16</span><h2>Dashboard Environnement</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le tableau de bord du système de management environnemental (ISO 14001) : déchets et filières, rejets, conformité réglementaire et veille, aspects environnementaux significatifs, consommations d'eau et d'énergie, bilan carbone et indicateurs RSE. Il sert au pilotage courant et à la préparation des audits ou des contrôles ICPE.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li>Six tuiles : <b>Déchets tracés</b> (dont dangereux) ; <b>Conformité réglementaire</b> en pourcentage des obligations applicables (objectif 98 %) ; <b>Rejets hors VLE</b> — les mesures qui dépassent les valeurs limites ; <b>Aspects significatifs</b> sur le total des aspects recensés ; <b>BSD conformes</b> (bordereaux de suivi des déchets dangereux, objectif 100 %) ; <b>Incidents env. (an)</b> avec les revues ATEX dues, objectif ≤ 3 par an.</li>\r\n      <li>Deux jauges (<b>Taux de conformité</b> et <b>Déchets valorisés</b>), l'anneau <b>DD / DND</b>, et trois bullets d'objectifs quantitatifs : déchets dangereux (t/an), déchets non dangereux (t/an), consommation d'eau (m³/an).</li>\r\n      <li><b>Déchets produits par mois</b> (barres empilées dangereux / non dangereux, en kg) et <b>Déchets par filière</b>.</li>\r\n      <li><b>Indicateur de la veille réglementaire</b> — barres groupées par domaine (ICPE, ISO 14001, RSE, ISO 26000, ATEX, Autre) et par état : <span class=\"b b-ok\">Conforme</span>, <span class=\"b b-crit\">Non conforme</span>, <span class=\"b b-warn\">Partiel</span>, <span class=\"b b-mut\">À vérifier</span>.</li>\r\n      <li><b>Consommation eau / énergie</b> (deux courbes), <b>Risque chimique — environnement (SEIRICH)</b> (produits classés au niveau 2 et au-delà, avec quantité et pastille de niveau) et <b>Aspects environnementaux par milieu</b>.</li>\r\n      <li><b>Bilan GES par scope</b> (scope 1 direct, scope 2 électricité, scope 3 indirect) avec le total en tCO₂e, et les <b>Postes d'émission</b>.</li>\r\n      <li><b>Veille réglementaire en alerte</b> — le nombre d'obligations à traiter puis leur détail (obligation, domaine, échéance, état) ; <b>Incidents / rejets hors VLE par mois</b> ; et, si des indicateurs RSE sont saisis, un bloc <b>social · environnement · gouvernance</b> avec valeur et cible.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/dash-environnement.png\" alt=\"Capture du Dashboard Environnement\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Environnement</b> — conformité, déchets et veille réglementaire sur un même écran : la base du dossier ISO 14001.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — préparer un audit environnemental</h3>\r\n    <ol class=\"steps\">\r\n      <li>Choisissez <b>Année</b> pour couvrir l'exercice complet.</li>\r\n      <li>Vérifiez la tuile <b>Conformité réglementaire</b> puis ouvrez <b>Veille réglementaire en alerte</b> : chaque ligne est une obligation à régulariser ou à documenter avant l'audit.</li>\r\n      <li>Contrôlez <b>BSD conformes</b> : un bordereau manquant sur un déchet dangereux est un écart immédiat.</li>\r\n      <li>Comparez les bullets d'objectifs (déchets dangereux, non dangereux, eau) à leurs cibles — les cibles sont modifiables dans les objectifs KPI.</li>\r\n      <li>Regardez le <b>bilan GES</b> et les postes d'émission pour le volet carbone, puis exportez la page en PDF pour le dossier.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le <b>bilan GES</b> est calculé par <b>méthode monétaire</b> à partir des factures fournisseur : c'est un ordre de grandeur de pilotage, pas un bilan carbone réglementaire certifié.</li>\r\n      <li>Le <b>risque chimique</b> présenté ici est la lecture environnementale de l'évaluation SEIRICH : seuls les produits de niveau 2 et au-delà sont listés. L'évaluation elle-même se fait dans le service Sécurité.</li>\r\n      <li>Chaque bloc reste vide et affiche son propre message tant que la donnée correspondante n'est pas saisie (déchets, mesures, aspects, obligations, indicateurs RSE) : la page ne s'effondre pas, elle indique simplement ce qui manque.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> l'indicateur de veille croise domaine et état : une colonne entière en « À vérifier » signale une famille d'obligations jamais instruite — c'est en général le premier constat d'un auditeur.</div>\r\n  </section>\r\n\r\n  <div class=\"docnav\">\r\n    <a href=\"index.html\">← Sommaire des manuels</a>\r\n    <a href=\"index.html\">Sommaire des manuels →</a>\r\n  </div>\r\n\r\n  <footer class=\"doc\">\r\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\r\n  </footer>\r\n\r\n</div>\r\n</body>\r\n</html>\r\n",
  "direction": "<!doctype html>\r\n<html lang=\"fr\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>Manuel — Direction · ERP Seem Semrac</title>\r\n<link rel=\"stylesheet\" href=\"manuel.css\">\r\n</head>\r\n<body>\r\n<div class=\"wrap\">\r\n\r\n  <header class=\"doc\">\r\n    <div class=\"brandrow\">\r\n      <div class=\"logo\">SS</div>\r\n      <div>\r\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\r\n        <div class=\"eyebrow\">Manuel utilisateur</div>\r\n      </div>\r\n      <div class=\"kind\">docs/manuel/html</div>\r\n    </div>\r\n    <h1>Service <span class=\"hi\">Direction</span></h1>\r\n    <p class=\"lede\">Le service Direction est le <b>cockpit de pilotage</b> de l'entreprise : il rassemble en un seul endroit tout ce qui attend un arbitrage (validations envoyées par les autres services), tout ce qui dérape (retards, impayés, non-conformités critiques, ruptures de stock, échéances de sécurité), la vue affaire par affaire, les indicateurs financiers et opérationnels, le budget de l'année et la qualité des données saisies dans l'ERP. Ce manuel décrit les 7 onglets, écran par écran.</p>\r\n    <div class=\"metachips\">\r\n      <span class=\"chip\">👤 Pour qui : <b>Direction</b> (seul rôle à accéder à ce service ; les décisions sont refusées à tout autre compte)</span>\r\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Direction</b></span>\r\n      <span class=\"chip\">🗂 <b>7 onglets</b></span>\r\n    </div>\r\n  </header>\r\n\r\n  <nav class=\"toc\">\r\n    <div class=\"toc-t\">Sommaire</div>\r\n    <ol>\r\n      <li><a href=\"#tab-avalider\">À valider</a></li>\r\n      <li><a href=\"#tab-traites\">Traités</a></li>\r\n      <li><a href=\"#tab-jalons\">Jalons critiques</a></li>\r\n      <li><a href=\"#tab-affaire\">Par affaire</a></li>\r\n      <li><a href=\"#tab-pilotage\">Pilotage</a></li>\r\n      <li><a href=\"#tab-budget\">Budget</a></li>\r\n      <li><a href=\"#tab-sante\">Santé des données</a></li>\r\n    </ol>\r\n  </nav>\r\n\r\n  <!-- ══════════════ 1. À VALIDER ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-avalider\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>À valider</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est la <b>boîte de réception de la Direction</b> : tout ce que les autres services ont soumis à arbitrage arrive ici, dans une file unique. Un bon de commande d'achat stratégique, un avoir client, une facture fournisseur, une fiche salarié, une non-conformité grave, une sortie de quarantaine, un formulaire Sécurité : partout dans l'ERP, une case <b>« Soumettre à la validation de la Direction »</b> pousse la demande dans cette file. S'y ajoutent les alertes détectées automatiquement par l'ERP, ainsi que deux circuits historiques : les <b>paiements de factures</b> et les <b>congés des fonctions support</b>. C'est l'onglet qui s'ouvre par défaut quand vous entrez dans le service.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Un bandeau doré <b>« Direction Générale · Cockpit de pilotage »</b> coiffe la page, suivi de la barre des 7 onglets — chacun portant son <b>compteur</b> (nombre de demandes en attente, de jalons ouverts, de contrôles de données à corriger…). Sous le titre <b>« File à valider »</b> et son compteur, vous disposez du bouton <b>« Scanner les alertes »</b> et d'un menu <b>Trier</b> (Plus récent · Montant ↓). Une rangée de pastilles filtre par domaine : <b>Tous</b>, puis les domaines réellement présents dans la file (Compta, RH, Qualité, Sécurité, Achats, Commercial).</p>\r\n    <ul class=\"points\">\r\n      <li>Colonnes du tableau : <b>Domaine</b>, <b>Type</b>, <b>Objet</b>, <b>Émetteur</b>, <b>Montant</b>, <b>Priorité</b>, <b>Date</b>, puis les boutons d'action.</li>\r\n      <li>Priorité : <span class=\"b b-crit\">URGENT</span> / <span class=\"b b-crit\">CRITIQUE</span> en rouge, sinon <span class=\"b b-ok\">normal</span> en vert. Une non-conformité de gravité Critique ou Bloquante arrive automatiquement en « urgent ».</li>\r\n      <li>Trois boutons par ligne : l'<b>œil</b> bleu (consulter l'objet soumis), la <b>coche verte</b> (valider) et la <b>croix rouge</b> (refuser). L'œil n'apparaît que si la demande est reliée à un objet consultable.</li>\r\n      <li>Si aucune demande n'attend : « Aucune demande en attente de validation. »</li>\r\n      <li>Sous le tableau, deux blocs de cartes apparaissent seulement s'ils sont alimentés : <b>Paiements de factures</b> (n° de facture, client, n° d'affaire, montant TTC et échéance) et <b>Congés fonctions support</b> (salarié, type de congé, période).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/direction.png\" alt=\"Capture de l'onglet À valider du service Direction\" loading=\"lazy\">\r\n      <figcaption><b>À valider</b> — la file centrale, les pastilles de domaine au-dessus et, à droite de chaque ligne, les trois boutons œil / valider / refuser.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — instruire puis valider une demande</h3>\r\n    <ol class=\"steps\">\r\n      <li>Filtrez la file si besoin : cliquez sur une pastille de domaine (par exemple <b>Achats</b>) pour ne garder que ces demandes, ou passez le tri sur <b>« Montant ↓ »</b> pour traiter d'abord les engagements les plus lourds.</li>\r\n      <li>Cliquez sur l'<b>œil</b> de la ligne : une fenêtre de consultation affiche la fiche réelle de l'objet soumis (commande, facture, non-conformité, salarié, bon de commande, demande d'achat, offre, lot, bon de travail…) champ par champ, sans quitter le cockpit.</li>\r\n      <li>Si vous voulez le contexte complet, cliquez sur <b>« Ouvrir dans le service »</b> en bas de cette fenêtre : l'ERP vous emmène sur le service concerné (une commande ouvre directement sa <b>fiche affaire</b> dans Commercial). Revenez ensuite au cockpit.</li>\r\n      <li>Cliquez sur la <b>coche verte</b> : la décision est enregistrée avec votre nom et la date, une notification « Validé. » s'affiche et la page se rafraîchit. La ligne quitte la file et bascule dans l'onglet <b>Traités</b>.</li>\r\n      <li>Côté service émetteur, l'objet porte désormais le badge <b>Direction ✓</b> — le demandeur voit votre décision sans avoir à vous appeler.</li>\r\n    </ol>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-direction-source.png\" alt=\"Fenêtre de consultation de la pièce source ouverte depuis l'œil de la file à valider\" loading=\"lazy\">\r\n      <figcaption><b>Consulter la pièce source</b> — l'œil ouvre la fiche réelle de l'objet soumis (ici une non-conformité critique), avec sous le titre la table d'origine et le numéro de pièce, puis chaque champ tel qu'il est en base : date, type, gravité, statut, détecteur, horodatages de création et de mise à jour. Le bouton violet <b>« Ouvrir dans le service »</b> en bas à droite bascule vers le service concerné ; la croix en haut à droite referme la fenêtre et vous laisse dans la file.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — refuser : annulation totale ou renvoi en révision</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur la <b>croix rouge</b> : la fenêtre <b>« Refuser cette validation »</b> s'ouvre.</li>\r\n      <li>Saisissez le <b>motif du refus</b> — il est <b>obligatoire</b> : sans texte, l'ERP affiche « Indiquez un motif de refus. » et ne va pas plus loin.</li>\r\n      <li>Choisissez l'effet du refus avec la case <b>« Annulation totale de l'élément »</b> : cochée, l'élément est définitivement écarté ; <b>décochée</b> (comportement par défaut), c'est un <b>renvoi en révision</b> — l'émetteur corrige et resoumet.</li>\r\n      <li>Cliquez sur <b>« Confirmer le refus »</b>. La notification précise l'effet retenu (« Refusé — annulation totale. » ou « Refusé — renvoi en révision. ») et la demande rejoint l'onglet Traités avec le badge correspondant.</li>\r\n      <li>Cas particulier des <b>sorties de quarantaine</b> (soumises par la Qualité) : votre décision agit directement sur le lot. Validation → le lot est <b>libéré</b> ; refus en <b>annulation</b> → le lot est <b>rejeté</b> ; refus en <b>révision</b> → le lot revient « en cours » et la Qualité peut statuer à nouveau.</li>\r\n    </ol>\r\n\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td>Motif du refus</td><td>Texte libre</td><td><b>Oui</b></td><td>Raison du refus. Repris tel quel dans la colonne Commentaire de l'onglet Traités et dans l'infobulle du badge côté service émetteur.</td></tr>\r\n        <tr><td>Annulation totale de l'élément</td><td>Case à cocher</td><td>Non (décochée par défaut)</td><td>Cochée = l'élément est annulé. Décochée = renvoi en révision, l'émetteur corrige et resoumet.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-direction-refus.png\" alt=\"Fenêtre de refus d'une validation Direction : motif obligatoire et case d'annulation totale\" loading=\"lazy\">\r\n      <figcaption><b>Refuser cette validation</b> — le champ <b>Motif du refus</b> porte l'astérisque des champs obligatoires : tant qu'il est vide, « Confirmer le refus » ne part pas. L'encart rose en dessous porte la case <b>« Annulation totale de l'élément »</b>, décochée par défaut, avec son rappel « Décoché = renvoi en révision » — c'est elle, et elle seule, qui décide si l'élément est écarté définitivement ou renvoyé à l'émetteur pour correction.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — alimenter la file avec le scan d'alertes</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Scanner les alertes »</b> : l'ERP relit les données vives et détecte les <b>commandes en retard</b>, les <b>marges faibles</b> (moins de 15 % sur une commande soldée), les <b>factures clients impayées</b> après échéance, les <b>non-conformités critiques ou bloquantes ouvertes</b> et les <b>ruptures de stock</b> (article géré tombé à zéro).</li>\r\n      <li>Une notification résume le résultat : nombre d'alertes ajoutées, nombre déjà présentes, nombre détectées. Les nouvelles lignes apparaissent dans la file avec l'émetteur <b>« Moteur alertes »</b>.</li>\r\n      <li>Traitez-les comme n'importe quelle demande : consultez l'objet avec l'œil, puis validez (vous prenez acte) ou refusez avec un motif.</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — paiements de factures et congés support</h3>\r\n    <ol class=\"steps\">\r\n      <li>Dans le bloc <b>« Paiements de factures »</b>, vérifiez le client, le montant TTC et la date d'échéance affichés sur la carte, puis cliquez sur <b>« Valider »</b> (le paiement est autorisé) ou sur la croix (refus).</li>\r\n      <li>Dans le bloc <b>« Congés fonctions support »</b>, contrôlez le salarié, le type de congé et la période, puis <b>« Valider »</b> : l'ERP crée les jours d'absence correspondants dans le RH et la notification indique combien de jours ont été posés. La croix refuse la demande.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>La <b>décision est réservée à la Direction</b> : un compte d'un autre service ne peut ni valider ni refuser (l'ERP répond « Décision réservée à la Direction. »).</li>\r\n      <li>Le scan d'alertes ne crée <b>jamais de doublon</b> : une alerte déjà présente — même déjà traitée, validée ou refusée — n'est pas recréée au scan suivant.</li>\r\n      <li>Le scan est volontairement plus sélectif que l'onglet Jalons critiques sur les stocks : il ne remonte que les <b>ruptures franches</b> (article tombé à zéro), le réapprovisionnement de routine restant l'affaire des Achats.</li>\r\n      <li>Chaque demande garde son <b>émetteur</b> : le nom de la personne qui a coché la case dans son service, ou « Moteur alertes » pour les détections automatiques.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> un refus en <b>annulation totale</b> n'est pas un simple avis — sur une sortie de quarantaine, il fait passer le lot en « rejeté ». Quand vous voulez seulement faire corriger un dossier, laissez la case décochée : le renvoi en révision permet à l'émetteur de resoumettre.</div>\r\n    <div class=\"astuce\"><b>Astuce :</b> lancez « Scanner les alertes » en début de semaine, puis triez par <b>Montant ↓</b> : vous voyez immédiatement les engagements financiers et les retards les plus coûteux, avant de descendre dans le détail.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 2. TRAITÉS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-traites\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Traités</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est la <b>mémoire des décisions</b> : toutes les demandes déjà validées ou refusées, avec leur motif, leur auteur et leur date. On y revient pour répondre à un « qu'avait-on décidé sur ce dossier ? », pour préparer une revue de direction, ou pour justifier une décision lors d'un audit. Cet onglet ne se vide jamais : il est indépendant de la file à traiter.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Le titre <b>« Historique des validations traitées »</b> avec le nombre total de décisions. Deux rangées de filtres cumulables : d'abord par <b>catégorie</b> (Toutes catégories, puis les domaines présents), ensuite par <b>décision</b> (Toutes décisions · Validées · Refusées). Le tableau détaille : Catégorie, Type, Objet, Émetteur, Montant, Décision, Décidé le, Par, Commentaire, et l'œil de consultation.</p>\r\n    <ul class=\"points\">\r\n      <li>Décisions affichées : <span class=\"b b-ok\">VALIDÉ</span> · <span class=\"b b-crit\">REFUSÉ · ANNULATION</span> · <span class=\"b b-warn\">REFUSÉ · RÉVISION</span> — le refus n'a donc pas un seul visage, on distingue toujours l'annulation du renvoi pour correction.</li>\r\n      <li>La colonne <b>Commentaire</b> reprend le motif saisi lors du refus ; elle affiche « — » quand aucun commentaire n'a été laissé.</li>\r\n      <li>Si aucune décision n'a encore été prise : « Aucune décision enregistrée pour l'instant. »</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/direction-traites.png\" alt=\"Capture de l'onglet Traités du service Direction\" loading=\"lazy\">\r\n      <figcaption><b>Traités</b> — les deux rangées de filtres (catégorie puis décision) se combinent ; les colonnes Décidé le / Par / Commentaire constituent la trace d'audit.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — retrouver une décision</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur la pastille de la <b>catégorie</b> concernée (Achats, Qualité, Compta…), puis, si besoin, sur <b>« Refusées »</b> ou <b>« Validées »</b> : les deux filtres s'appliquent ensemble.</li>\r\n      <li>Repérez la ligne à sa colonne <b>Objet</b> (elle porte le libellé rédigé par l'émetteur : fournisseur, client, numéro de pièce…).</li>\r\n      <li>Cliquez sur l'<b>œil</b> pour rouvrir la fiche de l'objet tel qu'il est aujourd'hui, et éventuellement l'ouvrir dans son service d'origine.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Cet onglet ne contient que les demandes <b>validées ou refusées</b>. Les jalons critiques marqués « Traité » ont leur propre historique, en bas de l'onglet <b>Jalons critiques</b>.</li>\r\n      <li>Une décision ne se rejoue pas depuis cet écran : il est en <b>consultation</b>. Si un dossier doit repasser en décision, il doit être resoumis par son service.</li>\r\n      <li>L'œil peut répondre « Objet introuvable » : c'est normal quand l'élément d'origine a été supprimé depuis la décision — la trace de la décision, elle, reste.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> le filtre <b>« Refusées »</b> est le meilleur point de départ d'une revue de direction : il montre en un écran ce que l'entreprise a arbitré à la baisse, avec le motif écrit.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 3. JALONS CRITIQUES ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-jalons\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>Jalons critiques</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Cet onglet ne contient <b>aucune saisie</b> : il lit directement les données vives de l'ERP et affiche ce qui déraille aujourd'hui, réparti en cinq familles — retards de livraison, stocks sous seuil, factures clients impayées, non-conformités critiques et échéances de sécurité dépassées. C'est la revue quotidienne du dirigeant : ce qui est rouge ici coûte de l'argent, du client ou de la conformité. Chaque ligne peut être marquée <b>« Traité »</b> pour tracer sa prise en charge.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Cinq sections repliées en cartes, chacune avec son <b>compteur</b> à droite du titre. Une section vide affiche « Rien à signaler ✓ ».</p>\r\n    <ul class=\"points\">\r\n      <li><b>Commandes en retard (vs date promise client)</b> — Affaire, Client, Livraison promise (en rouge avec le nombre de jours de retard), Montant. Une commande livrée, close, terminée, soldée ou annulée n'y figure plus.</li>\r\n      <li><b>Stocks critiques (à réapprovisionner)</b> — Référence, Désignation, Stock / seuil, Emplacement. Un article apparaît dès que son stock est retombé <b>au niveau ou en dessous</b> de son point de commande (ou de son stock mini).</li>\r\n      <li><b>Factures clients impayées en retard</b> — Facture, Client, Échéance (avec les jours de dépassement), Montant TTC. Les brouillons et les factures payées sont exclus.</li>\r\n      <li><b>Non-conformités critiques / bloquantes ouvertes</b> — NC, Date, Gravité (<span class=\"b b-crit\">Critique</span> ou <span class=\"b b-crit\">Bloquante</span>), Lot ou type. Une NC clôturée, fermée, résolue ou traitée disparaît de la liste.</li>\r\n      <li><b>Échéances Sécurité dépassées</b> — Type, Objet, Échéance. Le type précise l'origine : <span class=\"b b-info\">VGP</span> (vérification périodique dépassée), <span class=\"b b-info\">EPI</span> (péremption atteinte ou à moins de 30 jours), <span class=\"b b-info\">Conformité</span> (obligation non conforme ou échue), <span class=\"b b-info\">Habilitation</span> (certification expirée ou à renouveler), <span class=\"b b-info\">ATEX</span> (revue de zone dépassée) et <span class=\"b b-info\">Rejet hors VLE</span> (mesure environnementale non conforme).</li>\r\n      <li>En bas de page, <b>« Historique des jalons critiques traités »</b> : Catégorie, Objet, Traité le, Par, Note — avec l'œil pour rouvrir l'objet concerné.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/direction-jalons.png\" alt=\"Capture de l'onglet Jalons critiques\" loading=\"lazy\">\r\n      <figcaption><b>Jalons critiques</b> — les cinq familles avec leur compteur ; à droite de chaque ligne, le bouton noir « Traiter » ou la pastille verte « Traité ».</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — tracer la prise en charge d'un jalon</h3>\r\n    <ol class=\"steps\">\r\n      <li>Repérez la ligne concernée (par exemple une commande à +12 jours de retard) et cliquez sur le bouton noir <b>« Traiter »</b>.</li>\r\n      <li>La fenêtre <b>« Tracer le traitement du jalon »</b> rappelle l'objet visé. Saisissez une <b>note</b> décrivant l'action menée — relance client, réappro lancé, dérogation demandée… Le champ est facultatif, mais c'est lui qui donne sa valeur à l'historique.</li>\r\n      <li>Cliquez sur <b>« Marquer traité »</b> : la ligne troque son bouton contre une pastille verte <span class=\"b b-ok\">Traité</span> dont l'infobulle indique la date, l'auteur et la note.</li>\r\n      <li>La ligne s'ajoute aussitôt à l'<b>historique des jalons traités</b>, en bas de l'onglet — même après que le problème a disparu des données.</li>\r\n      <li>Si une <b>alerte du scan</b> existait déjà pour ce même objet dans l'onglet « À valider », elle est <b>absorbée</b> : elle sort de la file d'attente et devient cette trace « traité ». Vous ne traitez donc jamais deux fois le même sujet.</li>\r\n    </ol>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-direction-jalon-traite.png\" alt=\"Fenêtre Tracer le traitement du jalon, ouverte depuis le bouton Traiter\" loading=\"lazy\">\r\n      <figcaption><b>Tracer le traitement du jalon</b> — sous le titre, la fenêtre rappelle l'objet exactement visé (ici « Commande 0001 en retard — PROMISTEL ») : vérifiez-le avant de valider, c'est la ligne dont vous cliquez le bouton « Traiter ». Le champ <b>Note / action menée</b> est marqué <b>optionnel</b>, mais c'est lui qui donne son intérêt à l'historique. <b>« Marquer traité »</b> remplace aussitôt le bouton noir de la ligne par la pastille verte <b>Traité</b> ; « Annuler » ferme sans rien tracer.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>« Traiter » <b>ne corrige rien</b> : c'est une trace de pilotage. Le retard, l'impayé ou la NC restent visibles tant que la donnée source n'a pas changé dans son service (livraison enregistrée, encaissement saisi, NC clôturée).</li>\r\n      <li>L'action est <b>idempotente</b> : re-traiter le même jalon met à jour la note et l'horodatage au lieu de créer un doublon.</li>\r\n      <li>Les listes sont volontairement <b>plafonnées à l'écran</b> (les 20 premières lignes par famille, 25 pour la Sécurité) : elles servent à décider, pas à faire l'inventaire. Le détail exhaustif se consulte dans le service concerné.</li>\r\n      <li>Le marquage « Traité » est, comme la décision de validation, <b>réservé à la Direction</b>.</li>\r\n    </ul>\r\n    <div class=\"note\"><b>Bon à savoir :</b> les échéances de Sécurité proviennent de six sources différentes du service Sécurité / Environnement (VGP, EPI, conformité réglementaire, habilitations, zones ATEX, mesures de rejet). Une ligne rouge ici veut souvent dire qu'une saisie manque dans ces modules, pas qu'un contrôle n'a pas été fait.</div>\r\n    <div class=\"astuce\"><b>Astuce :</b> traitez la revue dans l'ordre des cartes — argent (retards, impayés), matière (stocks), conformité (NC, Sécurité) — puis relisez l'historique en fin de mois : il raconte, note après note, ce que la Direction a réellement piloté.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 4. PAR AFFAIRE ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-affaire\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Par affaire</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La vue transversale <b>affaire par affaire et client par client</b> : pour chaque commande, l'avancement réel de la production, le montant engagé, la marge et la date de livraison promise. C'est l'écran de la revue de portefeuille : quelles affaires avancent, lesquelles sont en retard, lesquelles gagnent ou perdent de l'argent.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Quatre tuiles en tête : <b>Affaires actives</b> (commandes non soldées), <b>Carnet de commandes</b> (montant restant à produire et livrer), <b>Marge moyenne</b> et <b>En retard</b> (nombre d'affaires dépassant la date promise — la tuile passe au vert quand il n'y en a aucune). Sous le titre <b>« Pilotage par affaire &amp; client »</b>, le tableau liste : Affaire, Client, Avancement, Montant, Marge, Livraison et un lien <b>détail</b>.</p>\r\n    <ul class=\"points\">\r\n      <li><b>Avancement</b> : une barre de progression accompagnée du décompte « bons de travail soldés / total ». Grise tant que rien n'est soldé, orange en cours de route, verte à 100 %.</li>\r\n      <li><b>Marge</b> en pourcentage du montant, avec un code couleur immédiat : vert à partir de 15 %, orange entre 0 et 15 %, rouge en dessous de zéro. « — » signifie que la marge réelle n'est pas encore connue.</li>\r\n      <li><b>Livraison</b> : la date promise, affichée en rouge et suivie d'un « ⚠ » si elle est dépassée alors que l'affaire n'est pas soldée.</li>\r\n      <li>Les affaires <b>en retard remontent automatiquement en tête</b> de tableau.</li>\r\n      <li>S'il n'y a aucune commande : « Aucune commande en base. »</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/direction-affaires.png\" alt=\"Capture de l'onglet Par affaire\" loading=\"lazy\">\r\n      <figcaption><b>Par affaire</b> — la barre d'avancement traduit le nombre de bons de travail soldés ; les colonnes Marge et Livraison colorent immédiatement les affaires à surveiller.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — passer une affaire en revue</h3>\r\n    <ol class=\"steps\">\r\n      <li>Lisez d'abord les quatre tuiles : elles donnent la photo du portefeuille (nombre d'affaires vivantes, carnet restant, marge moyenne, retards).</li>\r\n      <li>Parcourez les premières lignes du tableau — ce sont les affaires en retard, remontées d'office.</li>\r\n      <li>Pour une affaire précise, comparez <b>Avancement</b> et <b>Livraison</b> : une barre à 30 % avec une date déjà passée est un sujet de réunion, pas de mail.</li>\r\n      <li>Cliquez sur <b>détail</b> en bout de ligne : l'ERP ouvre la <b>fiche de la commande côté Production</b>, où se trouvent les lots, les bons de travail et l'avancement pièce par pièce.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>L'avancement est un décompte de <b>bons de travail soldés</b> : il reflète le travail déclaré à l'atelier, pas une estimation.</li>\r\n      <li>La marge affichée est la <b>marge réelle</b> calculée par l'ERP au fil de la production ; elle reste vide tant que les coûts n'ont pas été consommés.</li>\r\n      <li>Le tableau affiche au maximum les <b>100 premières affaires</b> : pour une recherche fine, passez par le service Commercial.</li>\r\n      <li>Une affaire close, livrée ou annulée n'entre plus dans les tuiles « Affaires actives » et « Carnet de commandes », mais reste dans le tableau.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> une ligne à 100 % d'avancement mais toujours ouverte signale généralement une affaire produite qui attend sa libération qualité ou son bon de livraison — le sujet se règle en un appel aux Expéditions.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 5. PILOTAGE ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-pilotage\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Pilotage</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Le tableau des <b>indicateurs de direction</b>, calculés en direct sur les données de l'ERP : cinq chiffres financiers et sept chiffres opérationnels, sur le mois et l'année en cours. C'est l'écran que l'on regarde chaque lundi matin, et celui que l'on projette en revue de direction.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Deux blocs de tuiles, précédés du rappel « Mois &amp; année en cours, données live ».</p>\r\n    <ul class=\"points\">\r\n      <li><b>Financier</b> : <b>CA facturé (mois)</b> · <b>CA facturé (année)</b> (cumul de l'année civile) · <b>Carnet de commandes</b> (le backlog encore ouvert) · <b>Encours clients</b> (le montant facturé restant à encaisser) · <b>Impayés en retard</b> (montant et nombre de factures échues non réglées).</li>\r\n      <li><b>Opérationnel</b> : <b>OTD livraison client</b> — le taux de livraison à l'heure, avec l'objectif <b>≥ 95 %</b> rappelé sous la tuile : elle est verte au-dessus de 95 %, orange en dessous · <b>NC critiques ouvertes</b> · <b>Stocks critiques</b> · <b>Échéances Sécurité</b> · <b>Accidents YTD</b> (accidents du travail de l'année, objectif = 0, la tuile est verte à zéro et rouge dès le premier) · <b>Effectif actif</b> · <b>En attente de validation</b> (le volume de votre file de l'onglet 1).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/direction-pilotage.png\" alt=\"Capture de l'onglet Pilotage\" loading=\"lazy\">\r\n      <figcaption><b>Pilotage</b> — bloc financier en haut, bloc opérationnel en dessous ; la couleur de chaque tuile porte déjà le verdict par rapport à l'objectif.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — lire les indicateurs</h3>\r\n    <ol class=\"steps\">\r\n      <li>Comparez <b>CA facturé (mois)</b> et <b>Carnet de commandes</b> : le premier dit ce qui est encaissable, le second ce qui reste à produire — c'est le couple qui annonce les mois suivants.</li>\r\n      <li>Regardez ensuite <b>Encours clients</b> et <b>Impayés en retard</b> : l'écart entre les deux mesure la qualité du recouvrement. Le détail nominatif est dans l'onglet <b>Jalons critiques</b>.</li>\r\n      <li>Sur l'<b>OTD</b>, une valeur sous 95 % renvoie directement aux <b>commandes en retard</b> de l'onglet Jalons critiques : ce sont exactement les mêmes commandes.</li>\r\n      <li>Les tuiles <b>NC critiques</b>, <b>Stocks critiques</b> et <b>Échéances Sécurité</b> reprennent les compteurs des familles de jalons : si un chiffre bouge, ouvrez l'onglet 3 pour voir de quelles lignes il s'agit.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>L'<b>OTD</b> se calcule sur les commandes dont la date promise est passée : c'est la part de celles qui ne sont pas en retard. Tant qu'aucune échéance n'est arrivée, l'indicateur affiche « — ».</li>\r\n      <li>Les chiffres de CA et d'encours de cet onglet sont exprimés en <b>TTC</b>, alors que l'onglet <b>Budget</b> raisonne en <b>HT</b> : ne comparez pas directement les deux écrans.</li>\r\n      <li>Les factures en <b>brouillon</b> sont exclues de tous les cumuls : un CA qui semble faible peut simplement signifier que des factures n'ont pas été finalisées en Compta.</li>\r\n      <li>Tous les indicateurs sont <b>recalculés à chaque ouverture</b> de la page : aucun chiffre n'est figé ni saisi à la main.</li>\r\n    </ul>\r\n    <div class=\"note\"><b>Bon à savoir :</b> ces tuiles donnent la photo du jour. Pour les courbes, les comparaisons N-1 et les filtres par période ou par site, passez par le service <b>Tableaux de bord</b>.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 6. BUDGET ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-budget\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">6</span><h2>Budget</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La vue économique de l'année : ce que l'entreprise a <b>facturé</b>, ce qu'elle a <b>acheté</b> et ce qui reste entre les deux. Les chiffres proviennent des factures réellement enregistrées en Comptabilité — clients d'un côté, fournisseurs de l'autre — et non d'un budget prévisionnel saisi à la main. Une seconde carte montre comment le carnet de commandes se répartit entre les activités.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Le titre <b>« Budget &amp; Marge »</b> suivi de l'année en cours et de la mention « données compta réelles ». Trois tuiles, puis une carte de répartition.</p>\r\n    <ul class=\"points\">\r\n      <li><b>CA facturé HT (année)</b> — cumul des factures clients de l'année civile, hors brouillons.</li>\r\n      <li><b>Achats fournisseurs HT</b> — cumul des factures fournisseurs de la même année.</li>\r\n      <li><b>Marge sur achats</b> — la différence entre les deux, assortie de son <b>pourcentage du CA</b>.</li>\r\n      <li><b>Carnet de commandes par activité</b> — une barre par activité (Seem, Semrac…), avec le montant et le poids en pourcentage, triée du plus gros au plus petit. Si aucune commande n'existe : « Aucune commande enregistrée. »</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/direction-budget.png\" alt=\"Capture de l'onglet Budget\" loading=\"lazy\">\r\n      <figcaption><b>Budget</b> — les trois tuiles CA / achats / marge, puis la répartition du carnet de commandes activité par activité.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — lire la marge de l'année</h3>\r\n    <ol class=\"steps\">\r\n      <li>Lisez d'abord <b>CA facturé HT</b> et <b>Achats fournisseurs HT</b> : ce sont deux cumuls bruts de l'année civile en cours.</li>\r\n      <li>Contrôlez le pourcentage affiché sous <b>Marge sur achats</b> : c'est la marge <b>sur achats</b>, pas la marge nette — elle ne déduit ni la main-d'œuvre, ni les charges de structure.</li>\r\n      <li>Descendez sur la carte <b>Carnet de commandes par activité</b> : elle indique quelle activité porte le travail à venir, donc où se joueront les prochains mois.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Ces montants ne valent que ce que vaut la saisie en <b>Comptabilité</b> : une facture fournisseur non enregistrée gonfle artificiellement la marge.</li>\r\n      <li>Le cumul est calé sur l'<b>année civile</b> en cours et se remet donc à zéro au 1<sup>er</sup> janvier.</li>\r\n      <li>La répartition par activité porte sur le <b>carnet de commandes</b> (les commandes enregistrées), pas sur le chiffre d'affaires facturé : les deux chiffres n'ont pas la même base.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> la « marge sur achats » n'est pas un résultat d'exploitation. Elle mesure l'écart entre facturation client et achats fournisseurs ; pour la rentabilité affaire par affaire, utilisez la colonne <b>Marge</b> de l'onglet « Par affaire ».</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 7. SANTÉ DES DONNÉES ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-sante\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">7</span><h2>Santé des données</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Un ERP ne vaut que par la qualité de ce qu'on y saisit. Cet onglet <b>audite l'ERP lui-même</b> selon quatre piliers — <b>D</b>isponibilité, <b>I</b>ntégrité, <b>C</b>onfidentialité, <b>T</b>raçabilité — et attribue un score sur 100. Il ne juge pas le terrain : il repère les données qui ne <i>circulent</i> pas entre les modules (un EPI sans fournisseur, un accident sans salarié, une habilitation orpheline) et vous dit précisément où corriger la saisie. C'est l'outil de préparation d'un audit et le thermomètre du déploiement de l'ERP.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>En haut, le <b>Score DICT global</b> sur 100 dans un cartouche coloré, avec le nombre de contrôles à corriger, et un encadré rappelant que tout est <b>recalculé à chaque ouverture</b>. Dessous, quatre jauges — une par pilier — puis le détail, contrôle par contrôle.</p>\r\n    <ul class=\"points\">\r\n      <li>Les quatre piliers : <b>Intégrité</b> (liens &amp; référentiels), <b>Disponibilité</b> (données présentes), <b>Confidentialité</b> (accès cadrés), <b>Traçabilité</b> (horodatage &amp; auteur). Chaque jauge indique son score et le nombre de points à corriger, ou « tout est lié ».</li>\r\n      <li>Code couleur des scores : <span class=\"b b-ok\">vert</span> à partir de 90, <span class=\"b b-warn\">orange</span> de 70 à 89, <span class=\"b b-crit\">rouge</span> en dessous de 70.</li>\r\n      <li>Chaque contrôle affiche à gauche un compteur — une <b>coche</b> quand tout est bon, sinon « nombre en défaut / total » — puis son libellé, la <b>consigne de correction</b> (le service et l'écran où agir) et, à droite, le taux de complétude en pourcentage.</li>\r\n      <li>Un bouton <b>détails</b> apparaît quand l'ERP peut nommer les cas fautifs : il déplie la liste des références concernées (fournisseurs hors référentiel, personnes absentes de la base salariés, lots périmés…), avec la mention « + n autre(s)… » au-delà de huit.</li>\r\n      <li>Les lignes marquées d'un <b>ℹ</b> sont des <b>informations de posture</b> (sécurité de la plateforme, horodatage automatique) : elles ne comptent pas dans le score.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/direction-donnees.png\" alt=\"Capture de l'onglet Santé des données\" loading=\"lazy\">\r\n      <figcaption><b>Santé des données</b> — le score DICT global, les quatre jauges par pilier, puis chaque contrôle avec sa consigne de correction et son taux de complétude.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Ce que chaque pilier contrôle</h3>\r\n    <ul class=\"points\">\r\n      <li><b>Intégrité</b> — les rattachements manquants : dotations EPI, catalogue EPI, produits périssables et produits chimiques sans fournisseur ; fournisseurs cités en texte libre mais absents du référentiel Achats ; accidents, dotations et certifications non reliés à une fiche salarié ; personnes citées qui n'existent pas dans la base salariés.</li>\r\n      <li><b>Disponibilité</b> — les données indispensables au pilotage : produits chimiques sans fiche de données de sécurité, lots périssables périmés encore en stock, dotations EPI sans prix (donc invisibles dans les dépenses HSE), obligations de conformité non conformes ou échues.</li>\r\n      <li><b>Confidentialité</b> — la gouvernance des accès : salariés actifs sans rôle ni autorisations, salariés actifs sans identifiant de connexion (matricule et code PIN, indispensables pour tracer qui fait quoi).</li>\r\n      <li><b>Traçabilité</b> — la preuve du « qui a fait quoi, quand » : accidents clôturés sans date de clôture, non-conformités sans horodatage de mise à jour, décisions de validation sans nom de décideur.</li>\r\n    </ul>\r\n\r\n    <h3>Pas à pas — faire remonter le score</h3>\r\n    <ol class=\"steps\">\r\n      <li>Ouvrez la jauge la plus basse : c'est là que l'effort rapporte le plus.</li>\r\n      <li>Dans la section correspondante, repérez les contrôles au compteur rouge et lisez la <b>consigne</b> : elle nomme l'écran exact où corriger (« Sécurité › EPI catalogue », « Qualité › Produits périssables », « Achats »…).</li>\r\n      <li>Cliquez sur <b>détails</b> quand le bouton est proposé : vous obtenez la liste nominative des cas à traiter — de quoi confier une consigne précise au service concerné.</li>\r\n      <li>Faites corriger la saisie dans le service, puis <b>revenez sur l'onglet</b> : le score est recalculé à l'ouverture, sans aucune manipulation.</li>\r\n      <li>Recommencez jusqu'à ce que les quatre jauges soient au vert : l'ERP est alors réellement branché de bout en bout.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le score d'un pilier est la <b>moyenne des taux de complétude</b> de ses contrôles ; le score global est la moyenne des quatre piliers. Un seul contrôle très incomplet peut donc tirer une jauge vers le bas.</li>\r\n      <li>Un défaut ici n'est <b>pas un problème terrain</b> : c'est une donnée manquante ou mal reliée dans l'ERP. La correction se fait toujours <b>à la source</b>, dans le service émetteur, jamais depuis cet écran (l'onglet est en consultation).</li>\r\n      <li>Le contrôle « fournisseurs cités hors référentiel » et « personnes citées absentes de la base salariés » raisonnent sur les <b>noms distincts</b> réellement cités : deux orthographes d'un même fournisseur comptent pour deux écarts — corrigez le nom ou créez la fiche.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> avant un audit client ou de certification, imprimez cet écran : un score DICT élevé, contrôle par contrôle, démontre en quelques minutes que le système d'information est maîtrisé et tracé.</div>\r\n  </section>\r\n\r\n  <div class=\"docnav\">\r\n    <a href=\"index.html\">← Sommaire des manuels</a>\r\n    <a href=\"dashboard.html\">Manuel suivant : Tableaux de bord →</a>\r\n  </div>\r\n\r\n  <footer class=\"doc\">\r\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\r\n  </footer>\r\n\r\n</div>\r\n</body>\r\n</html>\r\n",
  "environnement": "<!doctype html>\r\n<html lang=\"fr\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>Manuel — Environnement · ERP Seem Semrac</title>\r\n<link rel=\"stylesheet\" href=\"manuel.css\">\r\n</head>\r\n<body>\r\n<div class=\"wrap\">\r\n\r\n  <header class=\"doc\">\r\n    <div class=\"brandrow\">\r\n      <div class=\"logo\">SS</div>\r\n      <div>\r\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\r\n        <div class=\"eyebrow\">Manuel utilisateur</div>\r\n      </div>\r\n      <div class=\"kind\">docs/manuel/html</div>\r\n    </div>\r\n    <h1>Service <span class=\"hi\">Environnement</span></h1>\r\n    <p class=\"lede\">Le service Environnement rassemble tout ce que l'usine doit prouver à la DREAL, au client et à l'auditeur ISO&nbsp;14001 : le registre des déchets et ses bordereaux, l'autosurveillance des rejets, le zonage ATEX, l'analyse des aspects &amp; impacts, le classement ICPE&nbsp;/&nbsp;Seveso, le bilan carbone et la veille réglementaire. Ce manuel décrit les 8 onglets, écran par écran.</p>\r\n    <div class=\"metachips\">\r\n      <span class=\"chip\">👤 Pour qui : <b>Responsable QSE / Environnement</b> (écriture : Qualité, OAS, Direction · lecture : BE, Production, Maintenance, RH)</span>\r\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Environnement</b></span>\r\n      <span class=\"chip\">🗂 <b>10 onglets</b></span>\r\n    </div>\r\n  </header>\r\n\r\n  <nav class=\"toc\">\r\n    <div class=\"toc-t\">Sommaire</div>\r\n    <ol>\r\n      <li><a href=\"#tab-dechets\">Déchets</a></li>\r\n      <li><a href=\"#tab-rejets\">Rejets &amp; mesures</a></li>\r\n      <li><a href=\"#tab-atex\">ATEX</a></li>\r\n      <li><a href=\"#tab-aspects\">Aspects &amp; parties intéressées (ISO 14001)</a></li>\r\n      <li><a href=\"#tab-icpe\">ICPE / Seveso</a></li>\r\n      <li><a href=\"#tab-ges\">Bilan GES</a></li>\r\n      <li><a href=\"#tab-veille\">Veille réglementaire (obligations)</a></li>\r\n      <li><a href=\"#tab-autodiag\">Autodiagnostics (ISO 14001, ISO 26000 &amp; RSE)</a></li>\r\n      <li><a href=\"#tab-audit\">Audit Conformité (ISO 14001)</a></li>\r\n      <li><a href=\"#tab-dashboard\">Tableau de bord</a></li>\r\n    </ol>\r\n  </nav>\r\n\r\n  <div class=\"note\"><b>Le geste commun à tous les onglets.</b> Les onglets de saisie fonctionnent tous de la même façon : un bandeau vert de rappel réglementaire, un compteur d'éléments, un champ <b>Rechercher…</b> qui filtre le tableau à la frappe, un bouton vert de création à droite, puis un tableau dont chaque ligne se termine par deux icônes — le <b>crayon</b> (modifier) et la <b>corbeille</b> (supprimer, avec confirmation). Toutes les fenêtres de saisie se terminent par la même case jaune <b>« Soumettre à la validation de la Direction »</b> : cochée, la fiche part dans <b>Direction › À valider</b> et un badge de décision s'affichera ensuite sur la ligne.</div>\r\n\r\n  <!-- ══════════════ 1. DÉCHETS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-dechets\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Déchets</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le <b>registre des déchets</b>, à conserver 5 ans et présentable à tout contrôle. Chaque sortie de déchet y est tracée : quoi, combien, par quelle filière, avec quel transporteur, vers quel exutoire. Pour les <b>déchets dangereux</b> (bains usés, boues d'hydroxydes, rinçages du traitement de surface, huiles et émulsions d'usinage), c'est aussi ici que vit le <b>bordereau BSDD / Trackdéchets</b>. Le registre alimente la déclaration annuelle GEREP.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Sous le bandeau de rappel réglementaire, la barre <b>« Registre des déchets »</b> avec le nombre d'éléments, le champ de recherche, un bouton clair <b>« Déchets des produits périmés »</b> et le bouton vert <b>« Nouveau déchet »</b>. Le tableau liste : Date, Code déchet, Désignation, DD, Qté, Filière, BSD, Actions.</p>\r\n    <ul class=\"points\">\r\n      <li>Un <b>astérisque rouge</b> derrière le code déchet signale un code européen dangereux ; la colonne <b>DD</b> affiche alors <span class=\"b b-ok\">oui</span>, sinon <span class=\"b b-mut\">non</span>.</li>\r\n      <li>La colonne <b>BSD</b> montre où en est le bordereau : Brouillon · Émis · Pris en charge (transporteur) · Reçu (exutoire) · Traité · Refusé. Deux valeurs anciennes subsistent pour l'historique : « Enlevé » et « En attente ».</li>\r\n      <li>La quantité est affichée avec son unité ; la <b>filière</b> reprend un code R (valorisation) ou D (élimination).</li>\r\n      <li>En bas du tableau, le volet dépliant <b>« Nomenclature déchets EU (2014/955/UE) &amp; codes de filière R/D »</b> rappelle les codes utilisables : vert = non dangereux, rouge = dangereux, et la liste R1 à R13 / D5 à D15.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/environnement.png\" alt=\"Capture de l'onglet Déchets du service Environnement\" loading=\"lazy\">\r\n      <figcaption><b>Déchets</b> — c'est l'onglet qui s'ouvre par défaut ; repérez la colonne DD et la colonne BSD, ce sont les deux que l'inspecteur regarde en premier.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — enregistrer un enlèvement de déchet dangereux</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouveau déchet »</b> : la fenêtre de saisie s'ouvre, la date du jour déjà remplie.</li>\r\n      <li>Saisissez le <b>code déchet EU</b> : le champ propose la liste (commencez à taper « 11 01 » pour les acides et boues de traitement de surface, « 12 01 » pour les limailles et huiles d'usinage). <b>Si le code porte un astérisque, la case « Dangereux » est cochée toute seule à l'enregistrement</b> — vous n'avez rien à faire.</li>\r\n      <li>Renseignez la <b>désignation</b> (seul champ obligatoire), la <b>quantité</b> et son <b>unité</b>, puis la <b>zone productrice</b> (atelier, ligne OAS, magasin…).</li>\r\n      <li>Choisissez la <b>filière</b> dans la liste R/D — par exemple « R4 — Recyclage des métaux » pour les copeaux, « D9 — Traitement physico-chimique » pour un bain usé.</li>\r\n      <li>Complétez le <b>transporteur</b> et l'<b>exutoire</b> (l'installation qui traite le déchet).</li>\r\n      <li>Reportez le <b>N° BSDD</b> et l'<b>ID Trackdéchets</b>, puis positionnez le <b>cycle du bordereau</b> sur « Émis ».</li>\r\n      <li>Choisissez le <b>site</b> (Seem ou Semrac), cochez éventuellement la validation Direction, puis <b>« Enregistrer »</b>.</li>\r\n      <li>Plus tard, rouvrez la ligne au crayon pour faire avancer le cycle : « Pris en charge » à l'enlèvement, « Reçu » à l'accusé de réception, <b>« Traité »</b> quand l'exutoire retourne le bordereau final. Le bordereau n'est soldé que dans cet état.</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — verser les produits périmés au registre</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Déchets des produits périmés »</b> : une demande de confirmation s'affiche (« Déclarer en déchets tous les produits périssables périmés ? »).</li>\r\n      <li>Confirmez : l'ERP parcourt les <b>produits périssables</b> suivis dans <b>Qualité › Produits Périssables</b> et retient ceux dont la date d'expiration est dépassée.</li>\r\n      <li>Un message indique combien de déchets ont été créés sur combien de produits périmés trouvés. Chaque ligne créée porte la désignation « Produit périmé — … », la quantité et la zone de stockage d'origine, et le statut <span class=\"b b-warn\">en attente</span>.</li>\r\n      <li>Complétez ensuite chaque ligne au crayon : code déchet, filière, transporteur, exutoire, n° de bordereau.</li>\r\n    </ol>\r\n    <div class=\"astuce\"><b>Astuce :</b> l'opération est <b>rejouable sans risque</b> — un produit périmé déjà déclaré n'est pas recréé en double. Lancez-la en fin de mois, c'est le moyen le plus simple de ne pas oublier une résine ou une colle périmée au magasin.</div>\r\n\r\n    <h3>Le formulaire, champ par champ</h3>\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td>Date</td><td>Date</td><td>Non (jour du jour par défaut)</td><td>Date de production ou d'enlèvement du déchet.</td></tr>\r\n        <tr><td>Code déchet EU</td><td>Liste assistée</td><td>Non</td><td>Nomenclature 2014/955/UE. L'astérisque désigne un déchet dangereux.</td></tr>\r\n        <tr><td>Désignation</td><td>Texte</td><td><b>Oui</b></td><td>Libellé en clair (« Bain de dégraissage usé », « Copeaux aluminium »).</td></tr>\r\n        <tr><td>Dangereux</td><td>Case à cocher</td><td>Non</td><td>Cochée automatiquement si le code porte un astérisque ; à cocher à la main sinon.</td></tr>\r\n        <tr><td>Quantité · Unité</td><td>Nombre · Texte</td><td>Non</td><td>Poids ou volume enlevé, dans l'unité du bordereau (kg, t, L).</td></tr>\r\n        <tr><td>Zone productrice</td><td>Texte</td><td>Non</td><td>Où le déchet a été produit — utile pour les actions de réduction à la source.</td></tr>\r\n        <tr><td>Filière (code R/D)</td><td>Liste assistée</td><td>Non</td><td>R = valorisation, D = élimination. Le taux de valorisation du tableau de bord se calcule sur les filières R.</td></tr>\r\n        <tr><td>Transporteur · Exutoire</td><td>Texte</td><td>Non</td><td>Les deux maillons obligatoires de la chaîne de traçabilité.</td></tr>\r\n        <tr><td>N° BSDD · ID Trackdéchets</td><td>Texte</td><td>Non</td><td>Références du bordereau papier et de la plateforme nationale.</td></tr>\r\n        <tr><td>Cycle du bordereau (BSD)</td><td>Liste</td><td>Non</td><td>Brouillon → Émis → Pris en charge → Reçu → Traité (ou Refusé).</td></tr>\r\n        <tr><td>Site</td><td>Seem / Semrac</td><td>Non</td><td>Entité productrice.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-environnement-dechets.png\" alt=\"Fenêtre de saisie d'un déchet au registre des déchets\" loading=\"lazy\">\r\n      <figcaption><b>Fenêtre « Nouveau déchet »</b> — le <b>code déchet EU</b> commande tout : s'il porte un astérisque, la case <b>Dangereux</b> se coche d'elle-même à l'enregistrement. Contrôlez ensuite le trio <b>Filière R/D · Transporteur · Exutoire</b>, qui constitue la chaîne de traçabilité, et le <b>cycle du bordereau (BSD)</b> avant d'enregistrer.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le registre doit être <b>tenu à jour en continu</b> et conservé <b>5 ans</b> : saisissez à l'enlèvement, pas en fin d'année.</li>\r\n      <li>L'atelier de traitement de surface relève de la <b>rubrique ICPE 2565</b> ; ses bains, boues d'hydroxydes et eaux de rinçage sont des <b>déchets dangereux</b> et exigent tous un bordereau.</li>\r\n      <li>Ne saisissez jamais « dangereux = non » sur un code à astérisque : l'ERP le recorrigera à l'enregistrement, mais la cohérence de votre déclaration GEREP en dépend.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> la corbeille supprime définitivement la ligne du registre. Un déchet enlevé ne se supprime pas — il se corrige. N'utilisez la corbeille que pour effacer une saisie erronée du jour même.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 2. REJETS & MESURES ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-rejets\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Rejets &amp; mesures</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le carnet d'<b>autosurveillance</b> du site : rejets aqueux (pH, DCO, métaux issus des bains de rinçage), émissions dans l'air, bruit en limite de propriété, et consommations d'eau et d'énergie. Chaque mesure est confrontée à la <b>valeur limite d'émission (VLE)</b> fixée par l'arrêté préfectoral. C'est la preuve que l'on demandera lors d'une inspection DREAL.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>La barre <b>« Mesures (eau / air / bruit / énergie) »</b> avec sa recherche et le bouton vert <b>« Nouvelle mesure »</b>. Le tableau affiche : Date, Type, Point, Paramètre, Valeur, VLE, Conforme, Actions.</p>\r\n    <ul class=\"points\">\r\n      <li>La colonne <b>Conforme</b> est <b>calculée toute seule</b> dès qu'une VLE est renseignée : <span class=\"b b-ok\">oui</span> si la valeur est inférieure ou égale à la VLE, <span class=\"b b-mut\">non</span> sinon, avec la mention discrète « auto ». Si aucune VLE n'est saisie, c'est la case cochée à la main dans le formulaire qui s'affiche.</li>\r\n      <li>Sous le tableau, une ligne <b>« Relevés d'eau OAS récents »</b> reprend les 8 derniers relevés de consommation saisis dans le module <b>OAS</b> — vous n'avez pas à les ressaisir ici.</li>\r\n      <li>Le volet dépliant <b>« VLE de référence »</b> donne les repères de l'arrêté type du 02/02/1998 : pH entre 5,5 et 8,5 · température ≤ 30 °C · MES ≤ 35 mg/L · DCO ≤ 125 mg/L · DBO5 ≤ 30 mg/L · hydrocarbures totaux ≤ 10 mg/L · aluminium ≤ 5 mg/L · chrome total ≤ 0,5 mg/L · chrome VI ≤ 0,1 mg/L · nickel ≤ 0,5 mg/L · fluorures ≤ 15 mg/L · zinc ≤ 2 mg/L.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/environnement-rejets.png\" alt=\"Capture de l'onglet Rejets et mesures\" loading=\"lazy\">\r\n      <figcaption><b>Rejets &amp; mesures</b> — la colonne Conforme se remplit seule ; la ligne « Relevés d'eau OAS » sous le tableau montre le pont automatique avec l'atelier d'anodisation.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — enregistrer une analyse de rejet aqueux</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouvelle mesure »</b>.</li>\r\n      <li>Choisissez le <b>type</b> : Rejet eau (les autres choix sont Consommation eau, Émission air, Bruit, Énergie).</li>\r\n      <li>Indiquez la <b>date</b> du prélèvement et le <b>point de mesure</b> (regard de sortie, cheminée, limite de propriété…).</li>\r\n      <li>Saisissez le <b>paramètre</b> — le champ propose la liste des paramètres de référence (DCO, Chrome VI, Nickel, pH…) — puis la <b>valeur</b> mesurée et son <b>unité</b>.</li>\r\n      <li>Reportez la <b>valeur limite (VLE)</b> de votre arrêté préfectoral. Dès qu'elle est présente, la conformité s'affiche automatiquement dans le tableau.</li>\r\n      <li>Renseignez l'<b>organisme</b> qui a réalisé l'analyse, ajoutez vos <b>observations</b>, choisissez le <b>site</b>, puis <b>« Enregistrer »</b>.</li>\r\n      <li>Vérifiez la ligne : si la conformité affiche <span class=\"b b-mut\">non</span>, la mesure est comptée dans la tuile <b>« Rejets hors VLE »</b> du tableau de bord — traitez-la immédiatement.</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — suivre une consommation mensuelle</h3>\r\n    <ol class=\"steps\">\r\n      <li>Créez une mesure de type <b>Consommation eau</b> ou <b>Énergie</b>, à la date de relevé du compteur.</li>\r\n      <li>Laissez la <b>VLE vide</b> : une consommation n'a pas de valeur limite. Cochez « Conforme » si vous voulez la marquer comme normale.</li>\r\n      <li>Les consommations d'eau du mois en cours alimentent la tuile <b>« Conso. eau (mois) »</b> du tableau de bord et l'indicateur RSE annuel de consommation d'eau.</li>\r\n    </ol>\r\n\r\n    <h3>Le formulaire, champ par champ</h3>\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td>Type</td><td>Consommation eau · Rejet eau · Émission air · Bruit · Énergie</td><td>Non</td><td>Détermine la famille de suivi ; « Consommation eau » alimente les indicateurs de consommation.</td></tr>\r\n        <tr><td>Date</td><td>Date</td><td>Non (jour du jour par défaut)</td><td>Date du prélèvement ou du relevé.</td></tr>\r\n        <tr><td>Point de mesure</td><td>Texte</td><td>Non</td><td>Emplacement exact — indispensable pour comparer deux campagnes.</td></tr>\r\n        <tr><td>Paramètre</td><td>Liste assistée</td><td>Non</td><td>Grandeur mesurée (DCO, MES, Chrome VI, pH, bruit…).</td></tr>\r\n        <tr><td>Valeur · Unité</td><td>Nombre · Texte</td><td>Non</td><td>Résultat de l'analyse et son unité.</td></tr>\r\n        <tr><td>Valeur limite (VLE)</td><td>Nombre</td><td>Non</td><td>Seuil de l'arrêté préfectoral. Sa présence déclenche le calcul automatique de conformité.</td></tr>\r\n        <tr><td>Conforme (si pas de VLE)</td><td>Case à cocher</td><td>Non</td><td>Appréciation manuelle, utilisée uniquement quand aucune VLE n'est saisie.</td></tr>\r\n        <tr><td>Organisme</td><td>Texte</td><td>Non</td><td>Laboratoire ou bureau de contrôle — la traçabilité de la preuve.</td></tr>\r\n        <tr><td>Observations</td><td>Texte libre</td><td>Non</td><td>Conditions de prélèvement, incident constaté, suite donnée.</td></tr>\r\n        <tr><td>Site</td><td>Seem / Semrac</td><td>Non</td><td>Entité concernée.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-environnement-mesures.png\" alt=\"Fenêtre de saisie d'une mesure environnementale (eau, air, bruit, énergie)\" loading=\"lazy\">\r\n      <figcaption><b>Fenêtre « Nouvelle mesure »</b> — le <b>Type</b> en tête (Consommation eau · Rejet eau · Émission air · Bruit · Énergie) décide de la famille de suivi et des tuiles alimentées. Le couple <b>Valeur / Unité</b> se lit toujours avec la <b>VLE</b> juste en dessous : dès qu'une VLE est saisie, la conformité de la ligne se calcule seule et la case « Conforme » ne sert plus.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Les VLE du volet dépliant sont des <b>repères de saisie</b>, pas votre réglementation : la seule valeur opposable est celle de <b>l'arrêté préfectoral de votre site</b>. Saisissez celle-ci dans le champ VLE.</li>\r\n      <li>Le contrôle automatique compare <b>valeur ≤ VLE</b>. Pour un paramètre à plage comme le <b>pH</b> (5,5 à 8,5), seule la borne haute est vérifiée : un pH trop bas ne sera pas signalé automatiquement — jugez-le vous-même et cochez la conformité en conséquence.</li>\r\n      <li>Une mesure non conforme ne crée pas de non-conformité qualité automatiquement : ouvrez la NC correspondante dans <b>Qualité › Non-Conformités</b> et l'action associée dans l'onglet <b>Aspects &amp; impacts</b>.</li>\r\n    </ul>\r\n    <div class=\"note\"><b>Bon à savoir :</b> les relevés d'eau saisis par l'atelier <b>OAS</b> (onglet « Relevé consommation eau ») remontent ici en lecture. Ils illustrent la consommation réelle de la ligne d'anodisation sans double saisie.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 3. ATEX ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-atex\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>ATEX</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Une <b>atmosphère explosive</b> peut se former partout où l'on manipule des solvants, des vapeurs inflammables ou des poussières métalliques. La réglementation impose de <b>classer les zones</b>, d'y installer du matériel adapté et de formaliser le tout dans un <b>DRPCE</b> (Document Relatif à la Protection Contre les Explosions). Cet onglet tient l'inventaire des zones et génère le DRPCE de chacune en PDF.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>La barre <b>« Zones ATEX »</b> avec sa recherche et le bouton vert <b>« Nouvelle zone »</b>, puis le rappel réglementaire. Le tableau affiche : Zone, Type, Localisation, Origine, Matériel requis, Revue, Site, DRPCE, Actions.</p>\r\n    <ul class=\"points\">\r\n      <li>La colonne <b>Type</b> porte un badge <span class=\"b b-warn\">Zone 0</span> à <span class=\"b b-warn\">Zone 22</span> : 0 / 1 / 2 pour les gaz et vapeurs (permanent, occasionnel, rare ou bref), 20 / 21 / 22 pour les poussières.</li>\r\n      <li>La colonne <b>Revue</b> est un feu tricolore : date en <span class=\"b b-crit\">rouge</span> si la revue est dépassée, en <span class=\"b b-warn\">orange</span> si elle tombe dans les 30 jours, en texte simple au-delà.</li>\r\n      <li>La colonne <b>DRPCE</b> propose sur chaque ligne un bouton violet <b>PDF</b> : il ouvre dans un nouvel onglet le document relatif à la protection contre les explosions de cette zone, prêt à imprimer.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/environnement-atex.png\" alt=\"Capture de l'onglet ATEX\" loading=\"lazy\">\r\n      <figcaption><b>ATEX</b> — les badges de classement à gauche, le feu tricolore de la revue au centre, et le bouton PDF du DRPCE à droite de chaque ligne.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — déclarer une zone ATEX et sortir son DRPCE</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouvelle zone »</b>.</li>\r\n      <li>Donnez un <b>nom de zone</b> (champ obligatoire) parlant pour l'atelier : « Cabine de dégraissage solvant », « Local de charge batteries ».</li>\r\n      <li>Choisissez le <b>classement</b> dans la liste des six zones, puis l'<b>origine du risque</b> : Gaz / vapeur ou Poussière.</li>\r\n      <li>Décrivez la <b>localisation et l'étendue</b> de la zone (le rayon réellement classé, pas seulement le local).</li>\r\n      <li>Listez les <b>substances inflammables</b> avec, si vous les connaissez, leurs limites d'explosivité (LIE / LSE), puis les <b>sources d'inflammation identifiées</b> (points chauds, électricité statique, outillage…).</li>\r\n      <li>Indiquez le <b>matériel conforme requis</b> — catégorie et marquage attendus pour tout équipement installé dans la zone.</li>\r\n      <li>Renseignez les deux blocs de mesures : les <b>mesures techniques de prévention</b> (éviter que l'atmosphère explosive se forme : ventilation, confinement, inertage) et les <b>mesures de protection et organisationnelles</b> (limiter les effets, formation du personnel, permis de feu, consignes, coordination avec les entreprises extérieures).</li>\r\n      <li>Saisissez l'<b>évaluateur</b> et la <b>date d'évaluation / revue</b>, choisissez le <b>site</b>, puis <b>« Enregistrer »</b>.</li>\r\n      <li>Sur la ligne créée, cliquez sur le bouton <b>PDF</b> de la colonne DRPCE : le document se génère à partir de ce que vous venez de saisir. Faites-le signer et classez-le avec le dossier ICPE.</li>\r\n    </ol>\r\n\r\n    <h3>Le formulaire, champ par champ</h3>\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td>Nom de la zone</td><td>Texte</td><td><b>Oui</b></td><td>Identifiant terrain de la zone.</td></tr>\r\n        <tr><td>Classement (zone ATEX)</td><td>0 · 1 · 2 · 20 · 21 · 22</td><td>Non</td><td>Fréquence de présence de l'atmosphère explosive ; conditionne la catégorie de matériel admise.</td></tr>\r\n        <tr><td>Localisation / étendue</td><td>Texte</td><td>Non</td><td>Emplacement et dimensions du volume classé.</td></tr>\r\n        <tr><td>Origine du risque</td><td>Gaz / vapeur · Poussière</td><td>Non</td><td>Détermine la série de zones (0-1-2 ou 20-21-22).</td></tr>\r\n        <tr><td>Substances inflammables</td><td>Texte</td><td>Non</td><td>Produits en cause, avec LIE/LSE si connues.</td></tr>\r\n        <tr><td>Sources d'inflammation identifiées</td><td>Texte</td><td>Non</td><td>Inventaire des sources possibles — exigence du DRPCE.</td></tr>\r\n        <tr><td>Matériel conforme requis</td><td>Texte</td><td>Non</td><td>Catégorie et marquage imposés aux équipements de la zone.</td></tr>\r\n        <tr><td>Mesures techniques de PRÉVENTION</td><td>Texte libre</td><td>Non</td><td>Ce qui empêche l'atmosphère explosive de se former.</td></tr>\r\n        <tr><td>Mesures de PROTECTION + organisationnelles</td><td>Texte libre</td><td>Non</td><td>Ce qui limite les effets d'une explosion + formation, permis feu, consignes, coordination.</td></tr>\r\n        <tr><td>Évaluateur (DRPCE)</td><td>Texte</td><td>Non</td><td>Auteur de l'évaluation — figure sur le document.</td></tr>\r\n        <tr><td>Date d'évaluation / revue</td><td>Date</td><td>Non</td><td>Pilote le feu tricolore de la colonne Revue.</td></tr>\r\n        <tr><td>Site</td><td>Seem / Semrac</td><td>Non</td><td>Entité concernée.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-environnement-atex.png\" alt=\"Fenêtre de création d'une zone ATEX avec les critères du DRPCE\" loading=\"lazy\">\r\n      <figcaption><b>Fenêtre « Nouvelle zone »</b> — seul le <b>nom de la zone</b> est obligatoire, mais c'est l'ensemble de la fiche qui remplit le DRPCE : classement, origine du risque, substances inflammables, sources d'inflammation, matériel requis, puis les deux blocs distincts <b>mesures de prévention</b> et <b>mesures de protection &amp; organisationnelles</b>. La <b>date d'évaluation / revue</b> saisie en bas commande le feu tricolore de la colonne Revue.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le <b>DRPCE est obligatoire</b> dès qu'une zone existe. Le PDF de l'ERP ne vaut que ce que vous avez saisi : une zone sans mesures de prévention ni sources d'inflammation produit un document vide de sens.</li>\r\n      <li>Le tableau de bord compte les <b>revues dues</b> (date dépassée). Passez cette tuile à zéro avant tout audit ou visite d'inspection.</li>\r\n      <li>Les zones ATEX se reportent aussi sur le plan de l'usine, dans le service <b>Plan / Bâtiment</b>, avec les repères de type <em>atex</em> — pratique pour la formation et l'accueil des entreprises extérieures.</li>\r\n    </ul>\r\n  </section>\r\n\r\n  <!-- ══════════════ 4. ASPECTS & IMPACTS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-aspects\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Aspects &amp; parties intéressées (ISO 14001)</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est <b>l'analyse environnementale</b> exigée par l'ISO 14001 §6.1.2, le cœur du système de management environnemental. Pour chaque activité de l'entreprise on identifie ce qu'elle produit sur l'environnement (l'<em>aspect</em> : un rejet, un déchet, une consommation, du bruit), l'<em>impact</em> qui en résulte, et on le cote. Les aspects les plus critiques deviennent des <b>aspects environnementaux significatifs (AES)</b> : ce sont eux qui alimentent le programme environnemental et le plan d'audit.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Le bandeau explique la méthode de cotation. La barre <b>« Aspects &amp; impacts environnementaux »</b> affiche, en plus de la recherche, un compteur orange <b>« N AES significatif(s) »</b> et le bouton vert <b>« Nouvel aspect »</b>. Le tableau affiche : Activité / processus, Aspect environnemental, Milieu, Condition, Criticité, Significatif, Statut, Actions.</p>\r\n    <ul class=\"points\">\r\n      <li><b>Milieu</b> : badge bleu — eau, air, sol, déchet, énergie, bruit ou ressource.</li>\r\n      <li><b>Condition</b> : normale · anormale (démarrage / arrêt) · urgence (accident). Un aspect doit être coté dans chacune des conditions qui le concernent.</li>\r\n      <li><b>Criticité</b> : pastille colorée — <span class=\"b b-ok\">vert</span> jusqu'à 4, <span class=\"b b-warn\">jaune</span> jusqu'à 8, <span class=\"b b-warn\">orange</span> jusqu'à 11, <span class=\"b b-crit\">rouge</span> au-delà.</li>\r\n      <li><b>Significatif</b> : badge orange <span class=\"b b-warn\">AES</span> quand l'aspect est retenu comme significatif, sinon <span class=\"b b-mut\">non</span>.</li>\r\n      <li><b>Statut</b> du traitement : <span class=\"b b-crit\">à traiter</span> · <span class=\"b b-warn\">en cours</span> · <span class=\"b b-ok\">maîtrisé</span>.</li>\r\n      <li>Le volet dépliant <b>« Perspective cycle de vie »</b> rappelle les 8 étapes, de l'acquisition des matières premières à l'élimination finale, en précisant pour chacune si l'entreprise a une <em>maîtrise</em> ou seulement une <em>influence</em>.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/environnement-aspects.png\" alt=\"Capture de l'onglet Aspects et impacts\" loading=\"lazy\">\r\n      <figcaption><b>Aspects &amp; impacts</b> — le compteur d'AES en haut à droite est l'indicateur de pilotage du SME ; la colonne Criticité classe visuellement les priorités.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Comment se calcule la criticité</h3>\r\n    <p>L'ERP applique une <b>cotation multi-axes</b> d'inspiration INRS. Chaque axe se cote sur l'échelle <b>1 / 3 / 5 / 7</b>.</p>\r\n    <ul class=\"points\">\r\n      <li>Si vous renseignez les quatre axes <b>Probabilité (P)</b>, <b>Fréquence (F)</b>, <b>Gravité (G)</b> et <b>Sensibilité du milieu (S)</b>, la note vaut <b>P × F × G × S × (maîtrise moyenne ÷ 5)</b>, la maîtrise moyenne étant la moyenne des axes technique, humain et organisationnel réellement saisis. L'aspect est déclaré <b>significatif au-delà de 1000</b>.</li>\r\n      <li>Si vous ne saisissez que <b>Gravité</b> et <b>Fréquence</b>, l'ERP retombe sur la cotation simple <b>G × F</b>, avec un seuil de significativité à <b>9</b>.</li>\r\n      <li>Dans les deux cas, le calcul n'est fait que si vous <b>laissez la case « AES significatif » décochée</b> : cocher la case impose votre décision et l'ERP ne la contredit pas.</li>\r\n    </ul>\r\n    <div class=\"note\"><b>À lire dans le tableau :</b> la colonne <b>Criticité</b> de la liste affiche le produit <b>Gravité × Fréquence</b>, c'est-à-dire un repère de lecture rapide. La note multi-axes complète, elle, sert au calcul du caractère significatif. Ne vous étonnez donc pas qu'une ligne cotée « 15 » soit marquée AES : c'est la note complète qui a tranché.</div>\r\n\r\n    <h3>Pas à pas — coter un aspect environnemental</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouvel aspect »</b>.</li>\r\n      <li>Choisissez l'<b>activité / processus</b> (champ obligatoire, liste assistée : Traitement de surface, Usinage, Tôlerie / chaudronnerie, Dégraissage, Peinture / vernis, Stockage produits chimiques, Maintenance, Logistique / transport, Bâtiment / utilités).</li>\r\n      <li>Choisissez l'<b>aspect environnemental</b> (obligatoire, liste assistée : Rejet aqueux, Émission atmosphérique, Déchet dangereux, Déchet non dangereux, Consommation d'eau, Consommation d'énergie, Bruit, Odeur, Consommation de matières, Risque de déversement / pollution du sol) et décrivez l'<b>impact</b> attendu sur l'environnement.</li>\r\n      <li>Sélectionnez le <b>milieu</b>, l'<b>étape du cycle de vie</b> et la <b>condition</b> (normale, anormale ou urgence).</li>\r\n      <li>Cotez les axes sur l'échelle 1 / 3 / 5 / 7 : <b>Gravité</b>, <b>Fréquence</b>, puis — pour la cotation complète — <b>Probabilité</b> (en mode dégradé) et <b>Sensibilité du milieu</b>.</li>\r\n      <li>Cotez les trois axes de <b>maîtrise</b> : technique, humaine, organisationnelle. Plus la maîtrise est faible, plus la note monte.</li>\r\n      <li><b>Laissez « AES significatif » décoché</b> pour que l'ERP tranche, ou cochez-le si vous voulez imposer le caractère significatif.</li>\r\n      <li>Complétez l'<b>exigence légale associée</b>, les <b>moyens de maîtrise existants</b>, puis l'<b>action / objectif</b> du programme environnemental avec son <b>responsable</b> et son <b>échéance</b>.</li>\r\n      <li>Positionnez le <b>statut</b> (À traiter / En cours / Maîtrisé), choisissez le site et <b>« Enregistrer »</b>.</li>\r\n      <li>Vérifiez la ligne : si le badge <b>AES</b> apparaît, l'aspect entre dans le compteur du haut, dans la tuile « Aspects significatifs » du tableau de bord, et devient une entrée du plan d'audit environnemental.</li>\r\n    </ol>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-environnement-aspects.png\" alt=\"Fenêtre de cotation d'un aspect et de son impact environnemental\" loading=\"lazy\">\r\n      <figcaption><b>Fenêtre « Nouvel aspect »</b> — <b>activité / processus</b> et <b>aspect environnemental</b> sont les deux champs obligatoires ; milieu, étape du cycle de vie et condition (normale / anormale / urgence) situent la cotation. Tous les axes se cotent sur la même échelle <b>1 / 3 / 5 / 7</b> — gravité, fréquence, probabilité, sensibilité du milieu, puis les trois maîtrises. Laissez la case <b>« AES significatif »</b> décochée pour que l'ERP calcule lui-même la criticité à l'enregistrement.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Un même aspect doit être coté <b>séparément en condition normale, anormale et d'urgence</b> : un bain de rinçage n'a pas la même gravité en marche courante et en cas de rupture de cuve.</li>\r\n      <li>Les AES sont l'<b>entrée</b> du programme d'audit interne ISO 14001 (thème J) piloté dans <b>Qualité › Audit Conformité</b> — et repris dans le sous-onglet « Programme » de l'onglet <b>Audit Conformité</b>.</li>\r\n      <li>Renseignez l'<b>exigence légale associée</b> : c'est ce qui fait le lien entre votre analyse et les obligations suivies dans l'onglet <b>Veille réglementaire</b>.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> commencez par les activités à fort enjeu — Traitement de surface, Stockage produits chimiques, Dégraissage. Une analyse de dix lignes bien cotées vaut mieux qu'un tableau de cent lignes à criticité vide.</div>\r\n\r\n    <h3>Les parties intéressées</h3>\r\n    <p>Sous le tableau des aspects, le même onglet porte l'analyse du <b>contexte de l'organisme</b> (ISO 14001 §4.2) : qui a des attentes vis-à-vis de nous en matière d'environnement, et à quel point ces attentes sont maîtrisées. Les deux vont ensemble — les parties intéressées expriment des exigences, les aspects &amp; impacts disent ce que notre activité provoque. Barre <b>« Parties intéressées »</b> et bouton <b>« Nouvelle partie »</b>. Colonnes : Partie intéressée, Type, Attentes / exigences, Influence, Maîtrise, I×M, Statut.</p>\r\n    <ul class=\"points\">\r\n      <li>La cotation va de <b>1 à 4</b>. <b>Influence</b> : 1 = pas influente → 4 = très influente. <b>Maîtrise</b> : 1 = très forte → 4 = pas maîtrisée. Le <b>score I×M</b> est calculé automatiquement à l'enregistrement.</li>\r\n      <li>Plus le score est élevé, plus la partie est <b>à surveiller en priorité</b> : la pastille passe du vert au rouge en montant.</li>\r\n      <li>Statuts : à suivre · maîtrisé · critique.</li>\r\n    </ul>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouvelle partie »</b> et choisissez-la dans la liste assistée (DREAL, Riverains, Clients, Personnel, Direction, Assureur, Banque, Mairie / collectivité, Fournisseurs, Sous-traitants, Syndicats, Inspection du travail) — ou saisissez-en une autre.</li>\r\n      <li>Indiquez le <b>type</b> (externe ou interne) et détaillez ses <b>attentes / exigences</b>.</li>\r\n      <li>Cotez l'<b>influence</b> et la <b>maîtrise</b> de 1 à 4 : le score se calcule seul.</li>\r\n      <li>Formulez l'<b>exigence retenue</b> — c'est elle qui devient une obligation à créer dans l'onglet <b>Veille réglementaire</b> — et le <b>mode de réponse</b> que l'entreprise apporte.</li>\r\n      <li>Positionnez le <b>statut</b>, choisissez le site, enregistrez.</li>\r\n    </ol>\r\n    <div class=\"note\"><b>Pourquoi ici :</b> les parties intéressées vivaient auparavant sous l'onglet « Conformité &amp; Audit ». Elles ne sont pourtant pas un audit : c'est de l'<b>analyse de contexte</b>, au même titre que les aspects &amp; impacts — d'où leur place dans cet onglet.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 5. ICPE / SEVESO ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-icpe\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>ICPE / Seveso</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Répondre en une page à la question : <em>« sommes-nous Seveso ? »</em>. L'ERP calcule un classement <b>indicatif</b> à partir de l'inventaire des produits chimiques du site et rappelle les rubriques ICPE typiques d'un atelier d'usinage et de traitement de surface. C'est un onglet de <b>lecture</b> : rien ne s'y saisit, tout vient d'ailleurs.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>En haut, le titre <b>« Classement ICPE / Seveso »</b> suivi d'une étiquette jaune <span class=\"b b-warn\">INDICATIF</span>, puis le rappel de la méthode. Trois blocs suivent.</p>\r\n    <ul class=\"points\">\r\n      <li>Un <b>grand bandeau de verdict</b> : <span class=\"b b-ok\">Non Seveso</span> (vert), <span class=\"b b-warn\">Seveso — SEUIL BAS</span> (orange) ou <span class=\"b b-crit\">Seveso — SEUIL HAUT</span> (rouge). Il affiche le ratio maximal atteint au seuil bas et au seuil haut, et le nombre de produits chimiques pris en compte.</li>\r\n      <li>La carte <b>« Cumul par classe de danger »</b> : trois jauges — Santé (rubriques 41xx), Physique / incendie-explosion (43 à 47xx) et Environnement / milieu aquatique (45xx). Chaque jauge donne la somme <b>Σ q/SB</b> ; elle est verte en dessous de 0,5, orange à partir de 0,5 et rouge dès 1, seuil de bascule.</li>\r\n      <li>La carte <b>« Produits rattachés à une rubrique Seveso »</b> : les 12 produits les plus contributeurs, avec leur rubrique, leur quantité convertie en tonnes et leur ratio q/SB. Si le site n'est concerné par aucune rubrique, le message « Aucun produit ne relève d'une rubrique Seveso » s'affiche.</li>\r\n      <li>La carte <b>« Rubriques ICPE de repère »</b> liste les rubriques typiques : <b>2560</b> travail mécanique des métaux · <b>2564</b> nettoyage-dégraissage par solvants · <b>2565</b> revêtement / traitement de surface des métaux · <b>2661</b> transformation de polymères · <b>1185</b> fluides frigorigènes / gaz fluorés · <b>4734</b> produits pétroliers.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/environnement-icpe.png\" alt=\"Capture de l'onglet ICPE / Seveso\" loading=\"lazy\">\r\n      <figcaption><b>ICPE / Seveso</b> — le bandeau de verdict en haut, puis les trois jauges de cumul : c'est la jauge la plus haute qui décide du classement.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — obtenir et interpréter le classement</h3>\r\n    <ol class=\"steps\">\r\n      <li>Assurez-vous que l'inventaire chimique est à jour dans <b>Sécurité › Chimie</b> : chaque produit doit porter ses <b>mentions de danger (H)</b> et une <b>quantité avec son unité</b>. Un produit sans quantité est ignoré du calcul.</li>\r\n      <li>Revenez sur cet onglet : l'ERP rattache automatiquement chaque produit à une rubrique Seveso 4xxx à partir de ses mentions H, convertit la quantité en tonnes, puis divise par le seuil de la rubrique.</li>\r\n      <li>Lisez les trois jauges : les ratios se <b>cumulent par classe de danger</b>. Une classe dont la somme atteint <b>1 au seuil bas</b> fait basculer le site en <b>Seveso seuil bas</b> ; <b>1 au seuil haut</b> le fait passer en <b>seuil haut</b>.</li>\r\n      <li>Regardez la carte des produits pour identifier les <b>contributeurs</b> : ce sont eux qu'il faut réduire, substituer ou déstocker si vous approchez d'un seuil.</li>\r\n      <li>Comparez enfin la liste des rubriques ICPE de repère avec votre <b>arrêté préfectoral</b> pour vérifier qu'aucune activité nouvelle n'est passée sous les radars.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le résultat est <b>indicatif</b> et sert à alerter, pas à déclarer. Le <b>régime réel</b> (déclaration, enregistrement, autorisation) et les rubriques applicables sont fixés par <b>l'arrêté préfectoral du site</b>.</li>\r\n      <li>La conversion des quantités suppose une <b>densité voisine de 1</b> : les kilogrammes et les litres sont divisés par 1000 pour obtenir des tonnes. Un produit très dense ou très léger fausse légèrement le ratio.</li>\r\n      <li>Cet onglet ne remplace pas la mise à jour de l'inventaire chimique : <b>tout ce qui n'est pas saisi dans Sécurité › Chimie n'existe pas</b> dans le calcul.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> un verdict « Non Seveso » affiché avec un inventaire chimique incomplet ne prouve rien. Avant d'utiliser cet écran comme argument, vérifiez le nombre de produits pris en compte affiché dans le bandeau.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 6. BILAN GES ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-ges\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">6</span><h2>Bilan GES</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Donner une <b>première estimation de l'empreinte carbone</b> de l'entreprise sans campagne de mesure. L'ERP reprend les <b>factures fournisseurs</b> de l'exercice, les ventile par compte comptable et les convertit en tonnes de CO₂ équivalent grâce à des facteurs d'émission monétaires. C'est un onglet de <b>lecture</b> : il se remplit tout seul au rythme de la comptabilité.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Le titre <b>« Bilan GES / Carbone (BEGES) »</b> avec l'étiquette <span class=\"b b-warn\">INDICATIF — MONÉTAIRE</span>, le rappel de méthode, puis quatre tuiles et deux cartes.</p>\r\n    <ul class=\"points\">\r\n      <li>Les quatre tuiles : <b>Total CO₂e</b> de l'exercice, <b>Scope 1 — direct</b> (combustion, carburants), <b>Scope 2 — électricité</b> (énergie achetée) et <b>Scope 3 — indirect</b> (achats, transport, déchets), toutes en tonnes.</li>\r\n      <li>La carte <b>« Répartition par poste (tCO₂e) »</b> : une barre par famille d'achats, la plus émettrice en tête, colorée selon son scope. Tant qu'aucune facture fournisseur n'existe sur l'exercice, elle affiche le message « le bilan se remplit à mesure de la saisie des achats (Comptabilité) ».</li>\r\n      <li>La carte <b>« Facteurs d'émission monétaires »</b> donne les kg CO₂e par euro HT retenus par famille de compte : électricité, combustibles, énergie autre, carburants, achats matières premières, fournitures / consommables, sous-traitance (études et générale), transports sur achats et ventes, déplacements et missions. Chaque ligne indique son scope.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/environnement-ges.png\" alt=\"Capture de l'onglet Bilan GES\" loading=\"lazy\">\r\n      <figcaption><b>Bilan GES</b> — les quatre tuiles donnent la répartition par scope ; la carte des facteurs, à droite, explique exactement d'où vient chaque tonne affichée.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — fiabiliser le bilan</h3>\r\n    <ol class=\"steps\">\r\n      <li>Ouvrez l'onglet et lisez le <b>total</b> et sa répartition par scope : c'est votre point de départ.</li>\r\n      <li>Regardez la <b>répartition par poste</b> : les deux ou trois premières barres concentrent l'essentiel de l'empreinte. Ce sont vos leviers.</li>\r\n      <li>Si un poste vous paraît absent ou sous-évalué, la cause est presque toujours comptable : la facture fournisseur n'a pas été saisie, ou son <b>compte de charge</b> n'est pas renseigné. Corrigez-la dans <b>Comptabilité</b> — le bilan se recalcule à l'affichage suivant.</li>\r\n      <li>Une facture sans compte de charge reconnu est rattachée par défaut au poste « Autres achats », en scope 3 : une part importante dans ce poste signale un défaut d'imputation comptable.</li>\r\n      <li>Pour un bilan opposable, complétez cette estimation par des <b>données physiques</b> (kWh d'électricité, litres de carburant, tonnes.kilomètres de transport) : la méthode monétaire ne suffit pas à un BEGES réglementaire.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le bilan porte sur l'<b>exercice en cours</b> uniquement : les factures des autres années ne sont pas comptées.</li>\r\n      <li>Les facteurs d'émission sont <b>indicatifs</b> (Base Carbone ADEME). Ils suffisent à hiérarchiser les postes, pas à publier un chiffre officiel.</li>\r\n      <li>Une baisse du total peut refléter une baisse d'activité et non un progrès environnemental : rapportez toujours le résultat au chiffre d'affaires ou aux heures produites.</li>\r\n    </ul>\r\n    <div class=\"note\"><b>Bon à savoir :</b> comme le bilan se nourrit des achats, il progresse mécaniquement en cours d'année. Comparez des exercices complets entre eux, jamais un exercice en cours avec l'année précédente clôturée.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 7. VEILLE RÉGLEMENTAIRE ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-veille\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">7</span><h2>Veille réglementaire</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le registre des <b>obligations réglementaires environnementales</b> : ICPE / DREAL (arrêté préfectoral 2565), Code de l'environnement, REACH, ISO 14001, ISO 26000, ATEX. Pour chacune, on dit si elle nous est applicable, où on en est, qui en répond et quand il faut la revérifier.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Un tableau unique, un champ de recherche et le bouton vert <b>« Nouvelle obligation »</b>. Colonnes : Domaine, Obligation, Référence, Parution, Échéance, Responsable, Statut.</p>\r\n    <ul class=\"points\">\r\n      <li>Statuts : <span class=\"b b-info\">à vérifier</span> · <span class=\"b b-ok\">conforme</span> · <span class=\"b b-warn\">partiel</span> · <span class=\"b b-crit\">non conforme</span> · <span class=\"b b-mut\">na</span> (non applicable).</li>\r\n      <li>La colonne <b>Échéance</b> passe en <span class=\"b b-crit\">rouge</span> si la date est dépassée et en <span class=\"b b-warn\">orange</span> dans les 30 jours.</li>\r\n      <li>La colonne <b>Parution</b> combine le type de texte (loi, décret, arrêté, directive UE, règlement UE, norme, arrêté préfectoral) et sa date.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/environnement-veille.png\" alt=\"Capture de l'onglet Veille réglementaire\" loading=\"lazy\">\r\n      <figcaption><b>Veille réglementaire</b> — le registre des obligations environnementales, avec statut de conformité, responsable et échéance de revérification.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — inscrire une obligation</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouvelle obligation »</b> et choisissez le <b>domaine</b> : ICPE / Environnement, ISO 14001, RSE, ISO 26000 ou ATEX.</li>\r\n      <li>Écrivez l'<b>obligation</b> en clair (champ obligatoire) — ce que l'entreprise doit faire, pas le titre du texte.</li>\r\n      <li>Renseignez la <b>référence réglementaire</b> (l'article), le <b>type de texte</b>, la <b>source de veille</b> (organisme ou adresse consultée) et la <b>date de parution</b>.</li>\r\n      <li>Cochez <b>« Applicable »</b> si l'obligation nous concerne, puis positionnez le <b>statut</b> de conformité.</li>\r\n      <li>Datez le <b>dernier contrôle</b> et l'<b>échéance</b> du prochain, désignez un <b>responsable</b> et collez le lien de la <b>preuve</b> (rapport, attestation, PV). Enregistrez.</li>\r\n    </ol>\r\n    <div class=\"warn\"><b>Attention :</b> le registre des obligations est <b>partagé avec le service Sécurité</b>. Cet écran n'affiche que les domaines environnementaux ; les obligations santé-sécurité au travail, chimique et ISO 45001 sont dans <b>Sécurité › Veille réglementaire</b>. Choisissez donc le domaine avec soin : une obligation classée dans le mauvais domaine disparaît de la vue de son responsable.</div>\r\n    <div class=\"note\">Les alertes de conformité (statut non conforme <b>ou</b> échéance dépassée) sont comptées dans la tuile « Conformité — alertes » du tableau de bord.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 8. AUTODIAGNOSTICS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-autodiag\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">8</span><h2>Autodiagnostics</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Mesurer, chapitre par chapitre, <b>où nous en sommes</b> par rapport aux deux référentiels que nous nous appliquons : l'<b>ISO 14001</b> (management environnemental) et l'<b>ISO 26000</b> (responsabilité sociétale). L'onglet réunit les deux grilles de maturité et, en dessous, les <b>indicateurs RSE</b>. Ce sont des auto-évaluations : elles préparent l'audit, elles ne le remplacent pas.</p>\r\n\r\n    <h3>Autodiagnostic de maturité ISO 14001</h3>\r\n    <p>L'évaluation, <b>chapitre par chapitre</b>, de la maturité du système de management environnemental face à l'ISO 14001:2015. Colonnes : Chap., Exigence, Niveau actuel, Cible, Action, Échéance.</p>\r\n    <ul class=\"points\">\r\n      <li>Les quatre niveaux sont : <span class=\"b b-crit\">1 — Non conforme / inexistant</span> · <span class=\"b b-warn\">2 — Partiellement maîtrisé</span> · <span class=\"b b-warn\">3 — Conforme mais améliorable</span> · <span class=\"b b-ok\">4 — Conforme aux exigences</span>. La légende est rappelée sous le tableau.</li>\r\n      <li>Dès qu'au moins une ligne existe, la barre affiche le <b>taux de maturité</b> (« Maturité X/4 ») en vert au-delà de 75 %, orange entre 50 et 75 %, rouge en dessous ; trois tuiles apparaissent : <b>Maturité moyenne</b>, <b>Cible moyenne</b> et <b>Chapitres à traiter</b> (ceux dont le niveau actuel est inférieur ou égal à 2).</li>\r\n      <li>Les sept chapitres couverts sont : <b>4</b> Contexte de l'organisme · <b>5</b> Leadership · <b>6</b> Planification · <b>7</b> Support · <b>8</b> Réalisation des activités · <b>9</b> Évaluation des performances · <b>10</b> Amélioration.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/environnement-autodiag.png\" alt=\"Capture de l'onglet Autodiagnostics\" loading=\"lazy\">\r\n      <figcaption><b>Autodiagnostics</b> — la grille de maturité ISO 14001 en haut, l'autodiagnostic ISO 26000 et les indicateurs RSE en dessous.</figcaption>\r\n    </figure>\r\n    <ol class=\"steps\">\r\n      <li>À la toute première utilisation, cliquez sur <b>« Initialiser la grille (7 chapitres) »</b> puis confirmez : les sept lignes se créent d'un coup. Si la grille existe déjà, l'ERP vous le dit et ne fait rien.</li>\r\n      <li>Ouvrez une ligne au crayon : choisissez le <b>niveau actuel</b> et le <b>niveau cible</b>, écrivez le <b>constat</b> qui justifie la note.</li>\r\n      <li>Décrivez l'<b>action de mise à niveau</b>, désignez un <b>responsable</b> et fixez une <b>échéance</b>. Enregistrez.</li>\r\n      <li>Suivez la progression avec la tuile <b>Maturité moyenne</b> : c'est l'indicateur que vous présenterez en revue de direction.</li>\r\n    </ol>\r\n    <div class=\"astuce\"><b>Astuce :</b> cotez d'abord les sept chapitres en une seule séance, même grossièrement. Le taux de maturité initial est plus utile que sept lignes parfaites obtenues six mois plus tard.</div>\r\n\r\n    <h3>ISO 26000 &amp; indicateurs RSE</h3>\r\n    <p>Sous la grille ISO 14001, le même onglet porte l'<b>autodiagnostic ISO 26000</b> puis les <b>indicateurs RSE</b>, séparés par un trait.</p>\r\n    <ul class=\"points\">\r\n      <li><b>Autodiagnostic ISO 26000</b> — les <b>7 questions centrales</b> de la responsabilité sociétale : QC1 Gouvernance de l'organisation · QC2 Droits de l'Homme · QC3 Relations et conditions de travail · QC4 L'environnement · QC5 Loyauté des pratiques · QC6 Questions relatives aux consommateurs · QC7 Communautés et développement local. Elles se cotent sur la même échelle de maturité 1 à 4, avec constat, action de progrès, responsable et échéance ; le taux de maturité s'affiche dans la barre. Un bouton <b>« Initialiser (7 questions centrales) »</b> crée la grille en une fois.</li>\r\n      <li><b>Indicateurs RSE consolidés (AUTO)</b> — un bloc vert de tuiles <b>calculées en direct</b>, sans aucune ressaisie, depuis RH, Sécurité, Comptabilité et Environnement : effectif actif, taux de fréquence (TF), taux de gravité (TG), jours sans accident, absentéisme du mois, habilitations valides, CA HT et achats HT de l'année, part de femmes (égalité F/H), taux d'OETH (obligation légale de 6 %), turnover sur 12 mois, consommation d'eau annuelle et part de déchets valorisés (filière R).</li>\r\n      <li><b>Indicateurs RSE saisis</b> — le tableau du bas, pour tout ce que l'ERP ne sait pas calculer. Colonnes : Période, Catégorie, Indicateur, Valeur, Cible, Site. Bouton <b>« Nouvel indicateur »</b>.</li>\r\n    </ul>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouvel indicateur »</b>.</li>\r\n      <li>Saisissez la <b>période</b> (par exemple l'année), choisissez la <b>catégorie</b> — Social, Environnement ou Gouvernance — et un <b>code</b> si vous en utilisez un.</li>\r\n      <li>Écrivez le <b>libellé</b> de l'indicateur (champ obligatoire), sa <b>valeur</b>, son <b>unité</b> et la <b>cible</b> visée.</li>\r\n      <li>Choisissez le site et enregistrez : l'indicateur rejoint le tableau et remonte dans le dashboard environnemental, regroupé par catégorie.</li>\r\n    </ol>\r\n    <div class=\"note\"><b>Ne dupliquez pas :</b> tout ce qui figure déjà dans le bloc vert <b>AUTO</b> n'a pas à être ressaisi dans le tableau du bas. Réservez la saisie manuelle aux indicateurs que l'ERP ne connaît pas — part d'achats responsables, actions de mécénat, part d'énergie renouvelable, etc.</div>\r\n    <div class=\"note\">Les deux boutons d'initialisation (ISO 14001 et ISO 26000) sont <b>sans danger</b> : relancés sur une grille déjà créée, ils ne dupliquent rien et vous préviennent.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 9. AUDIT CONFORMITÉ ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-audit\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">9</span><h2>Audit Conformité</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le cycle d'<b>audit interne</b> appliqué à l'environnement : on ordonnance les audits ISO 14001 de l'année, on les réalise, on consigne les écarts et on solde les plans d'action. Cet onglet est <b>identique à celui de la Qualité et de la Sécurité</b> — mêmes quatre sous-onglets, même planning, seul le filtre normatif change (ici l'ISO 14001).</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Une barre de <b>quatre</b> sous-onglets, chacun avec son compteur (sauf <b>Référentiels</b>, qui n'est pas une liste) : <b>Programme</b> · <b>Constats &amp; plans d'action</b> · <b>Grilles</b> · <b>Référentiels</b>. Le bouton actif est bleu, les autres gris ; le contenu change sous la barre sans recharger la page, et <b>Programme</b> s'affiche à l'ouverture.</p>\r\n    <ul class=\"points\">\r\n      <li><b>Programme</b> — le planning d'audit interne, <b>commun avec le service Qualité</b> mais <b>filtré sur l'ISO 14001</b> : n'apparaissent ici que les lignes rattachées à ce référentiel ou au <b>thème J</b> (maîtrise environnementale, déchets, rejets, ATEX). Écran détaillé au paragraphe suivant.</li>\r\n      <li><b>Constats &amp; plans d'action</b> — les écarts relevés pendant les audits (<span class=\"b b-crit\">NC</span> ou <span class=\"b b-warn\">Axe</span>) avec leur preuve et l'action décidée ; le bouton <b>« Convertir en NC »</b> les bascule dans le cycle 8D du service Qualité.</li>\r\n      <li><b>Grilles</b> — les questionnaires d'audit <b>qui posent au moins une question d'environnement</b> (thème J). Chaque grille retenue est affichée entière, avec un repère <span class=\"b b-info\">N question(s) ISO 14001</span>. Pour chaque question : libellé, preuve attendue, clause, thème et <b>mode</b> (<span class=\"b b-ok\">AUTO</span> pré-rempli par les sondes de l'ERP, <span class=\"b b-info\">ASSISTÉ</span>, <span class=\"b b-mut\">MANUEL</span>). <em>Aucune grille n'y figure tant qu'aucune question de thème J n'a été créée — voir l'encadré ci-dessous.</em></li>\r\n      <li><b>Référentiels</b> — la documentation normative <b>de ce service uniquement</b> : le thème d'audit processus <b>J</b> (environnement) et la grille de conformité clause par clause de l'<b>ISO 14001</b>. Les autres normes du SMI (ISO 9001, EN 9100, ISO 45001, ISO 27001) sont dans <b>Qualité › Audit Conformité › Référentiels</b>, qui reste le hub du système.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/environnement-audit.png\" alt=\"Capture de l'onglet Audit Conformité (ISO 14001)\" loading=\"lazy\">\r\n      <figcaption><b>Audit Conformité</b> — les quatre sous-onglets standard, ouverts sur le programme d'audit filtré ISO 14001. Exactement la même barre qu'en Qualité et en Sécurité.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Le programme d'audit, écran par écran</h3>\r\n    <p>Le sous-onglet <b>Programme</b> est <b>identique à celui du service Qualité</b> : c'est le même <b>ordonnancement annuel des audits internes (EN 9100 §9.2)</b>, simplement <b>filtré sur le référentiel du service</b>. N'apparaissent ici que les lignes rattachées au référentiel <b>ISO 14001</b> ou au <b>thème J</b> ; les compteurs affichés ne couvrent donc que ce périmètre.</p>\r\n    <ol class=\"steps\">\r\n      <li><b>Choisissez l'exercice.</b> Les pastilles d'années, en haut à gauche, basculent le programme d'une année sur l'autre ; l'exercice le plus récent est sélectionné à l'ouverture.</li>\r\n      <li><b>Lisez les quatre indicateurs</b> de l'exercice affiché : <b>Lignes au programme</b>, <b>Taux de réalisation</b>, <b>En retard</b> (date cible passée sans audit réalisé) et <b>Plans d'action soldés</b>.</li>\r\n      <li><b>Servez-vous du planning annuel</b> — les douze mois de l'exercice, une case par jour, colorée selon l'état : <b>bleu</b> = audit programmé, <b>jaune</b> = pas fait (échéance dépassée), <b>rouge</b> = non conforme (NC ouverte), <b>vert</b> = soldé conforme ; une case pâle signifie qu'aucun audit n'est prévu ce jour-là. Cliquez une case occupée pour consulter l'audit ou le <b>déprogrammer</b> ; cliquez une case vide pour y <b>affecter</b> un audit non encore programmé (ou en déplacer un).</li>\r\n      <li><b>Ajoutez une ligne</b> avec <b>« + Nouvelle ligne »</b> : le formulaire demande le <b>type</b> (processus, poste, flash, procédé spécial, exigence client), la <b>famille</b> de processus, l'<b>entité auditée</b> (obligatoire), les <b>thèmes</b>, les <b>référentiels couverts</b> (cases à cocher), la <b>date cible</b>, le <b>temps estimé</b>, l'<b>auditeur</b>, l'<b>audité principal</b> et la <b>grille associée</b>. Sous le planning, les lignes se rangent dans les tableaux <b>« Audits de processus »</b> et <b>« Audits de poste &amp; flash »</b>. Le cycle d'une ligne reste : <b>planifié → réalisé → constat (NC / 8D) → plan d'action → clôture</b>.</li>\r\n      <li><b>Reconduisez le programme</b> en fin d'exercice avec <b>« Reconduire pour <em>année+1</em> »</b> : tout le programme est recopié sur l'année suivante, les dates décalées d'un an et les statuts remis à « planifié ».</li>\r\n    </ol>\r\n    <div class=\"note\"><b>Bon à savoir :</b> le planning est <b>commun avec la Qualité</b> — un seul calendrier pour tout le SMI. Une ligne créée ici apparaît aussi dans <b>Qualité › Audit Conformité</b>, et l'inverse est vrai à condition que la ligne porte le référentiel <b>ISO 14001</b> ou le <b>thème J</b> : sans quoi elle ne remontera pas dans cet écran. Cochez donc toujours le référentiel.</div>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>L'ordre de lecture du système reste le même, mais il traverse désormais <b>plusieurs onglets</b> : <b>Aspects &amp; parties</b> (contexte) → <b>Veille réglementaire</b> (obligations) → <b>Autodiagnostics</b> (maturité) → <b>Audit Conformité</b> (vérification et plans d'action). Chacun alimente le suivant.</li>\r\n      <li>Les obligations, les parties intéressées et les autodiagnostics <b>ne sont plus dans cet onglet</b> : ils ont chacun leur place au premier niveau. L'audit vérifie, il ne recense pas.</li>\r\n      <li>Cet onglet a <b>exactement la même structure</b> en Qualité, en Sécurité et en Environnement : ce que vous apprenez ici vaut dans les trois services. Seul le <b>contenu</b> change — chaque service ne voit que les critères et les grilles de <b>sa</b> norme.</li>\n      <li><b>À faire :</b> aucune grille d'audit ne porte encore de question de <b>thème J</b> (environnement), donc le sous-onglet Grilles est vide ici. Créez-en une avec <b>« Nouvelle grille »</b> — elle apparaîtra dès sa première question de thème J.</li>\r\n    </ul>\r\n  </section>\r\n\r\n  <!-- ══════════════ 10. TABLEAU DE BORD ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-dashboard\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">10</span><h2>Tableau de bord</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Voir en un écran l'état environnemental du site et savoir où intervenir aujourd'hui. C'est la page à ouvrir le matin, et celle à projeter en revue de direction ou en réunion QSE. Tout y est calculé à partir des autres onglets : rien ne s'y saisit.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Un large bandeau vert <b>« Tableau de bord environnemental complet »</b> avec un bouton <b>« Ouvrir → »</b>, puis huit tuiles de synthèse et deux colonnes de cartes.</p>\r\n    <ul class=\"points\">\r\n      <li>Les huit tuiles : <b>Déchets tracés</b> (avec le nombre de dangereux) · <b>Déchets du mois</b> (quantité cumulée) · <b>Conso. eau (mois)</b> · <b>Rejets hors VLE</b> · <b>Chimie — risque env. élevé</b> (avec le nombre de risques moyens) · <b>Aspects significatifs (AES)</b> · <b>Conformité — alertes</b> · <b>ATEX — revues dues</b>. Les tuiles d'alerte passent au rouge ou à l'orange dès qu'elles ne sont pas à zéro.</li>\r\n      <li>La carte <b>« Risque chimique pour l'environnement »</b> (SEIRICH, indicatif) liste jusqu'à dix produits classés sur l'axe environnemental — danger pour le milieu aquatique croisé avec la quantité stockée — avec leur niveau. La saisie des produits se fait dans <b>Sécurité › Chimie</b>.</li>\r\n      <li>La colonne de droite propose trois raccourcis : <b>« Audit environnemental (thème J) »</b> vers le service Qualité, <b>« Cartographie (Plan / Bâtiment) »</b> pour localiser zones ATEX, stockages de déchets dangereux et points de rejet sur le plan de l'usine, et un rappel <b>« Traitement de surface »</b>.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/environnement-dashboard.png\" alt=\"Capture de l'onglet Tableau de bord du service Environnement\" loading=\"lazy\">\r\n      <figcaption><b>Tableau de bord</b> — les huit tuiles du haut sont la revue quotidienne ; toute tuile colorée renvoie à un onglet où il y a quelque chose à faire.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — la revue quotidienne</h3>\r\n    <ol class=\"steps\">\r\n      <li>Balayez les huit tuiles. <b>Toute tuile non verte désigne un onglet à ouvrir.</b></li>\r\n      <li><b>Rejets hors VLE</b> au rouge → onglet <b>Rejets &amp; mesures</b> : identifiez la mesure non conforme, ouvrez une NC dans Qualité et une action dans Aspects &amp; impacts.</li>\r\n      <li><b>ATEX — revues dues</b> au rouge → onglet <b>ATEX</b> : les zones dont la date de revue est passée sont en rouge dans la colonne Revue. Réévaluez-les et régénérez leur DRPCE.</li>\r\n      <li><b>Conformité — alertes</b> au rouge → onglet <b>Veille réglementaire</b> : traitez les obligations non conformes et celles dont l'échéance est dépassée.</li>\r\n      <li><b>Chimie — risque env. élevé</b> au rouge → lisez la carte SEIRICH juste en dessous, puis allez réduire, substituer ou mieux confiner les produits concernés depuis <b>Sécurité › Chimie</b>.</li>\r\n      <li>Pour la vue graphique complète — jauges, tendances déchets / eau / énergie, indicateur de veille réglementaire et objectifs — cliquez sur <b>« Ouvrir → »</b> dans le bandeau vert : le dashboard environnemental s'ouvre, avec ses filtres et son export.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Les tuiles <b>« Déchets du mois »</b> et <b>« Conso. eau (mois) »</b> portent sur le <b>mois calendaire en cours</b> : elles repartent de zéro le 1<sup>er</sup> de chaque mois, ce n'est pas une anomalie.</li>\r\n      <li>Un tableau de bord tout vert avec des onglets vides ne veut rien dire : ces indicateurs ne valent que par la <b>régularité de la saisie</b> dans les six premiers onglets.</li>\r\n      <li>L'oxydation chromique (chrome VI) est <b>sous-traitée</b> ; en interne, la chromatation trivalente <b>Surtec 650</b>. Les déchets de bains, boues d'hydroxydes et eaux de rinçage sont des <b>déchets dangereux</b> à tracer par bordereau — c'est le rappel affiché en bas à droite de l'écran.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> avant une visite DREAL ou un audit de certification, visez trois zéros — Rejets hors VLE, Conformité alertes et ATEX revues dues. Ce sont les trois premiers chiffres qu'un inspecteur saura interpréter sans explication.</div>\r\n  </section>\r\n\r\n  <div class=\"docnav\">\r\n    <a href=\"index.html\">← Sommaire des manuels</a>\r\n    <a href=\"maintenance.html\">Manuel suivant : Maintenance →</a>\r\n  </div>\r\n\r\n  <footer class=\"doc\">\r\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\r\n  </footer>\r\n\r\n</div>\r\n</body>\r\n</html>\r\n",
  "expeditions": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Manuel — Expéditions · ERP Seem Semrac</title>\n<link rel=\"stylesheet\" href=\"manuel.css\">\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header class=\"doc\">\n    <div class=\"brandrow\">\n      <div class=\"logo\">SS</div>\n      <div>\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\n        <div class=\"eyebrow\">Manuel utilisateur</div>\n      </div>\n      <div class=\"kind\">docs/manuel/html</div>\n    </div>\n    <h1>Service <span class=\"hi\">Expéditions</span></h1>\n    <p class=\"lede\">Les Expéditions sont la porte d'entrée et de sortie des marchandises. Le service est organisé selon le <b>sens du flux</b> : ce qui <b>part</b> (onglet Envois, ouvert par défaut), ce qui <b>arrive</b> (onglet Réceptions), puis une vue <b>Calendrier</b> qui réunit les deux et détaille la journée. S'y ajoutent le référentiel <b>Fournisseurs</b> — avec l'historique des commandes envoyées et des livraisons reçues — et un <b>Dashboard</b>. Vous y apprendrez aussi comment l'ERP mesure la ponctualité (OTD), la vôtre envers les clients et celle de vos fournisseurs.</p>\n    <div class=\"metachips\">\n      <span class=\"chip\">👤 Pour qui : <b>Agent d'expédition</b> (écriture : Expéditions, Stock · lecture : Commercial, Achats, Production)</span>\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Expéditions</b></span>\n      <span class=\"chip\">🗂 <b>5 onglets</b></span>\n    </div>\n  </header>\n\n  <nav class=\"toc\">\n    <div class=\"toc-t\">Sommaire</div>\n    <ol>\n      <li><a href=\"#tab-envois\">Envois (ce qui part)</a></li>\n      <li><a href=\"#tab-receptions\">Réceptions (ce qui arrive)</a></li>\n      <li><a href=\"#tab-calendrier\">Calendrier &amp; journée</a></li>\n      <li><a href=\"#tab-fournisseurs\">Fournisseurs (référentiel, BC &amp; BL)</a></li>\n      <li><a href=\"#tab-dashboard\">Dashboard</a></li>\n    </ol>\n  </nav>\n\n  <div class=\"note\"><b>Le principe du service.</b> Les cinq onglets ne sont pas cinq bases de données différentes : ce sont <b>cinq projections des mêmes tables</b> (bons de commande, bons de sous-traitance, bons de livraison, commandes, non-conformités). Une réception enregistrée apparaît immédiatement dans le calendrier et dans l'historique du fournisseur — vous n'avez jamais à saisir deux fois.</div>\n\n  <!-- ═══════════════ ONGLET 1 : ENVOIS ═══════════════ -->\n  <section class=\"tab\" id=\"tab-envois\">\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Envois — ce qui part</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est l'onglet d'accueil du service : tout ce qui <b>quitte</b> l'atelier — les commandes clients prêtes à expédier, les bons de livraison à envoyer, et les pièces à confier à un sous-traitant. Le badge compte ce qui reste à faire partir.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <ul class=\"points\">\n      <li><b>Commandes prêtes à expédier</b> — les commandes dont la production est terminée et le lot <b>libéré</b> par la Qualité. C'est de là que part la création d'un BL.</li>\n      <li><b>BL à envoyer</b> — les bons de livraison créés mais pas encore partis.</li>\n      <li><b>À envoyer en sous-traitance</b> — les bons de sous-traitance (BST) en attente d'expédition chez le prestataire.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/expeditions-envois.png\" alt=\"Capture de l'onglet Envois\" loading=\"lazy\">\n      <figcaption><b>Envois</b> — commandes prêtes, BL à expédier et pièces à envoyer en sous-traitance, avec la porte qualité appliquée en amont.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — créer un bon de livraison client</h3>\n    <ol class=\"steps\">\n      <li>Dans <b>« Commandes prêtes à expédier »</b>, cliquez la commande concernée.</li>\n      <li>Sélectionnez les <b>lots</b> à expédier et la <b>quantité</b> : une livraison partielle est possible, le reliquat reste sur la commande.</li>\n      <li>Renseignez le <b>transporteur</b> et, si vous l'avez, le <b>prix de transport</b>.</li>\n      <li>Validez : le BL est créé, le stock est décrémenté et une <b>facture client</b> ainsi que l'<b>écriture de vente</b> sont préparées.</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-expeditions-bl.png\" alt=\"Fenêtre de création d'un bon de livraison\" loading=\"lazy\">\n      <figcaption><b>Nouveau bon de livraison</b> — choix des lots libérés, quantités (partiel possible), transporteur et prix de transport.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — envoyer en sous-traitance</h3>\n    <ol class=\"steps\">\n      <li>Dans <b>« À envoyer en sous-traitance »</b>, repérez le BST et cliquez son bouton d'envoi.</li>\n      <li>L'horodatage de départ est enregistré ; la pièce est désormais attendue en retour, et apparaît à ce titre dans l'onglet <b>Réceptions</b>.</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-expeditions-bst.png\" alt=\"Fenêtre d'envoi en sous-traitance\" loading=\"lazy\">\n      <figcaption><b>Envoi en sous-traitance</b> — le départ horodaté bascule automatiquement la pièce en « retour attendu » côté Réceptions.</figcaption>\n    </figure>\n\n    <div class=\"warn\"><b>La porte qualité.</b> Un bon de livraison est <b>refusé</b> si le lot porte une non-conformité ouverte ou s'il est en quarantaine. Ce n'est pas un bug : c'est la garantie qu'aucune pièce douteuse ne part chez un client. Faites lever le blocage par la Qualité (libération du lot, dérogation, ou traitement de la NC).</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 2 : RÉCEPTIONS ═══════════════ -->\n  <section class=\"tab\" id=\"tab-receptions\">\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Réceptions — ce qui arrive</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est votre écran du matin : tout ce que l'entreprise <b>attend</b>, quelle qu'en soit l'origine — commandes fournisseurs, retours de sous-traitance, retours clients — et tout ce qui a <b>déjà été réceptionné</b>. Le badge de l'onglet compte ce qui reste à recevoir.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Des blocs empilés, du plus urgent au plus froid :</p>\n    <ul class=\"points\">\n      <li><b>À réceptionner — fournisseurs &amp; sous-traitants</b> : un bon de commande par ligne, avec son numéro, le fournisseur, les articles, le montant et la <b>date d'arrivée prévue</b>. Une date dépassée passe en <span class=\"b b-crit\">en retard</span>.</li>\n      <li><b>Retours de sous-traitance attendus</b> : les pièces parties chez un prestataire et qui doivent revenir.</li>\n      <li><b>Retours clients attendus</b> : annoncés en amont depuis une <b>non-conformité client</b> (service Qualité), avec le n° de commande, la quantité et la date prévue.</li>\n      <li><b>En attente de validation fournisseur</b> : les BC envoyés dont le fournisseur n'a pas encore accusé réception.</li>\n      <li><b>Arrivées enregistrées</b> : l'historique de ce qui est entré, avec le bon de livraison correspondant.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/expeditions-receptions.png\" alt=\"Capture de l'onglet Réceptions\" loading=\"lazy\">\n      <figcaption><b>Réceptions</b> — tout ce qui arrive, regroupé par nature : commandes fournisseurs et sous-traitants, retours de sous-traitance, retours clients, puis les arrivées déjà enregistrées.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — enregistrer une réception fournisseur</h3>\n    <ol class=\"steps\">\n      <li>Repérez la ligne du bon de commande dans <b>« À réceptionner »</b> et cliquez son bouton d'action.</li>\n      <li>Vérifiez la <b>quantité reçue</b> : elle peut être inférieure à la quantité commandée (réception partielle), le BC reste alors ouvert pour le solde.</li>\n      <li>Renseignez le <b>transporteur</b> et la référence de transport si le colis en porte une — c'est ce qui alimentera la colonne Transporteur de l'historique fournisseur.</li>\n      <li>Enregistrez : un <b>bon de livraison de réception</b> est créé et rattaché au BC, la date d'arrivée réelle est posée, et la ligne bascule dans « Arrivées enregistrées ».</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-expeditions-reception.png\" alt=\"Fenêtre d'enregistrement d'une réception\" loading=\"lazy\">\n      <figcaption><b>Enregistrer une réception</b> — quantité reçue, transporteur et référence de transport ; la réception partielle laisse le bon de commande ouvert pour le solde.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — réceptionner un retour client</h3>\n    <ol class=\"steps\">\n      <li>Le retour doit d'abord avoir été <b>annoncé en Qualité</b> : à la déclaration de la non-conformité client, cochez « Retour de marchandise prévu » et renseignez le n° de commande, la quantité et la date prévue.</li>\n      <li>Il apparaît alors ici, dans <b>« Retours clients attendus »</b>. Cliquez <b>« Enregistrer l'arrivée »</b>.</li>\n      <li>Le n° de commande est <b>prérempli depuis la non-conformité</b> ; complétez la quantité réellement revenue et validez.</li>\n      <li>Un bon de livraison d'entrée est créé et rattaché à la commande, et la non-conformité passe en « retour reçu ».</li>\n    </ol>\n    <div class=\"warn\"><b>Attention :</b> un retour client ne se crée pas ici de toutes pièces. Il naît toujours d'une <b>non-conformité</b> côté Qualité — c'est ce qui garantit qu'un retour est tracé, analysé et, le cas échéant, transformé en avoir.</div>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>La <b>date d'arrivée prévue</b> peut être modifiée, mais l'ERP <b>gèle la première date promise</b> : c'est elle, et non la date repoussée, qui sert à calculer l'OTD du fournisseur. Un fournisseur ne peut donc pas « racheter » sa ponctualité en décalant ses dates.</li>\n      <li>Un bon de commande <b>annulé</b> n'apparaît nulle part dans le service — ni en réception, ni au calendrier, ni dans l'historique fournisseur.</li>\n    </ul>\n  </section>\n\n  <!-- ═══════════════ ONGLET 3 : CALENDRIER ═══════════════ -->\n  <section class=\"tab\" id=\"tab-calendrier\">\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>Calendrier &amp; journée</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Voir <b>arrivées et départs sur une même frise</b>, pour anticiper les journées chargées et repérer les retards d'un coup d'œil. En dessous, le bloc <b>« Aujourd'hui »</b> liste précisément ce qui doit entrer et sortir dans la journée, retards compris.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <ul class=\"points\">\n      <li>Une <b>frise unique</b>, une ligne par sens de flux, chaque mouvement positionné à sa date. Une légende de couleurs distingue les natures : commande fournisseur, envoi ou retour de sous-traitance, livraison client, retour client.</li>\n      <li>Un repère sur le <b>jour courant</b>, et les mouvements dépassés signalés <span class=\"b b-crit\">en retard</span>.</li>\n      <li>Sous la frise, deux blocs : <b>à réceptionner aujourd'hui</b> et <b>à envoyer aujourd'hui</b>, chaque ligne portant directement son bouton d'action.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/expeditions-calendrier.png\" alt=\"Capture de l'onglet Calendrier\" loading=\"lazy\">\n      <figcaption><b>Calendrier</b> — arrivées et départs sur une frise commune, puis le détail de la journée avec les actions à portée de clic.</figcaption>\n    </figure>\n\n    <div class=\"astuce\"><b>Astuce :</b> commencez la journée par cet onglet plutôt que par les deux premiers. Le bloc « Aujourd'hui » vous donne la liste de travail complète — entrées et sorties — sans avoir à basculer d'un onglet à l'autre.</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 4 : FOURNISSEURS ═══════════════ -->\n  <section class=\"tab\" id=\"tab-fournisseurs\">\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Fournisseurs — référentiel, commandes &amp; livraisons</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Consulter la liste des fournisseurs, en <b>ajouter</b> et en <b>supprimer</b>, et surtout retrouver pour chacun <b>tout l'historique des échanges</b> : les bons de commande qui lui ont été envoyés et les bons de livraison reçus de ses transporteurs. Chaque ligne ouvre l'affaire correspondante.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>L'écran est en deux colonnes.</p>\n    <ul class=\"points\">\n      <li><b>À gauche, la liste</b> : un champ <b>« Rechercher un fournisseur… »</b> qui filtre à la frappe, puis une ligne par fournisseur avec son nom, son code, sa catégorie et deux compteurs — <span class=\"b b-info\">N BC</span> (bons de commande envoyés) et <span class=\"b b-ok\">N BL</span> (bons de livraison reçus).</li>\n      <li><b>À droite, le détail</b> du fournisseur sélectionné : son identité (code, catégorie, contact, téléphone, e-mail), puis deux tableaux.</li>\n      <li><b>Bons de commande envoyés</b> — N° BC · Date · Montant · Réception (<span class=\"b b-ok\">reçu</span> ou <span class=\"b b-warn\">en attente</span>) · Affaire.</li>\n      <li><b>Bons de livraison reçus</b> — N° BL · Date · <b>Transporteur</b> · BC lié · Affaire.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/expeditions-fournisseurs.png\" alt=\"Capture de l'onglet Fournisseurs\" loading=\"lazy\">\n      <figcaption><b>Fournisseurs</b> — la liste filtrable à gauche avec les compteurs BC / BL, le détail du fournisseur à droite : commandes envoyées et livraisons reçues, chaque ligne ouvrant son affaire.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — consulter l'historique d'un fournisseur</h3>\n    <ol class=\"steps\">\n      <li>Tapez les premières lettres du nom dans le champ de recherche, ou faites défiler la liste.</li>\n      <li>Cliquez le fournisseur : le détail s'affiche à droite, sans recharger la page.</li>\n      <li>Lisez ses <b>bons de commande envoyés</b> — vous voyez immédiatement lesquels sont encore en attente de réception.</li>\n      <li>Lisez ses <b>bons de livraison reçus</b> : la colonne <b>Transporteur</b> indique par qui la marchandise est arrivée, et la colonne <b>BC lié</b> rattache la livraison à sa commande.</li>\n      <li><b>Cliquez n'importe quelle ligne</b> des deux tableaux : l'ERP ouvre la <b>fiche de l'affaire</b> correspondante, où vous retrouvez la commande complète, de la demande de travaux à la facturation.</li>\n    </ol>\n\n    <h3>Pas à pas — ajouter un fournisseur</h3>\n    <ol class=\"steps\">\n      <li>Cliquez <b>« Nouveau fournisseur »</b> en haut à droite.</li>\n      <li>Renseignez au minimum le <b>nom</b> (seul champ obligatoire) ; complétez si vous les avez le code, la catégorie, le contact, le téléphone, l'e-mail et l'adresse.</li>\n      <li><b>Enregistrez</b> : le fournisseur rejoint le référentiel et devient sélectionnable partout ailleurs dans l'ERP — demandes de prix, bons de commande, catalogue.</li>\n    </ol>\n\n    <h3>Pas à pas — supprimer un fournisseur</h3>\n    <ol class=\"steps\">\n      <li>Sélectionnez le fournisseur, puis cliquez <b>« Supprimer »</b> dans le bandeau de droite.</li>\n      <li>Confirmez. <b>Les bons de commande déjà émis ne sont pas supprimés</b> : l'historique comptable et documentaire reste intact.</li>\n    </ol>\n\n    <div class=\"note\"><b>Bon à savoir :</b> le bouton <b>« Fiche complète »</b> ouvre la fiche fournisseur 360 du service Achats — scorecard OTD, catalogue de produits, prix négociés, qualification. Cet onglet-ci est volontairement centré sur le <b>flux logistique</b> ; la relation commerciale se pilote côté Achats.</div>\n    <div class=\"astuce\"><b>Astuce :</b> un fournisseur qui affiche beaucoup de BC et peu de BL a des commandes en souffrance. Les compteurs de la liste sont un bon détecteur de relances à passer.</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 5 : DASHBOARD ═══════════════ -->\n  <section class=\"tab\" id=\"tab-dashboard\">\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Dashboard</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Les indicateurs du service : volumes expédiés, ponctualité (OTD) client et fournisseur, en-cours et retards. C'est la vue que l'on présente en revue de service.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/expeditions-dashboard.png\" alt=\"Capture du Dashboard Expéditions\" loading=\"lazy\">\n      <figcaption><b>Dashboard Expéditions</b> — volumes, OTD et en-cours ; la barre de filtres commune permet de changer la période, le site ou le client, et de comparer à l'année précédente.</figcaption>\n    </figure>\n    <ul class=\"points\">\n      <li>L'<b>OTD fournisseur</b> se calcule sur la <b>première date promise</b>, jamais sur une date repoussée.</li>\n      <li>Le <b>PV de contrôle</b> à réception alimente la qualité fournisseur : un colis reçu non conforme dégrade la scorecard du fournisseur, consultable côté Achats.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-expeditions-pv.png\" alt=\"Fenêtre de PV de contrôle à réception\" loading=\"lazy\">\n      <figcaption><b>PV de contrôle à réception</b> — conformité du lot reçu ; un écart déclenche une non-conformité et, si nécessaire, une mise en quarantaine.</figcaption>\n    </figure>\n  </section>\n\n  <div class=\"docnav\">\n    <a href=\"index.html\">← Sommaire des manuels</a>\n    <a href=\"stock.html\">Manuel suivant : Stocks →</a>\n  </div>\n\n  <footer class=\"doc\">\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\n  </footer>\n\n</div>\n</body>\n</html>\n",
  "index": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Manuels utilisateur · ERP Seem Semrac</title>\n<link rel=\"stylesheet\" href=\"manuel.css\">\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header class=\"doc\">\n    <div class=\"brandrow\">\n      <div class=\"logo\">SS</div>\n      <div>\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\n        <div class=\"eyebrow\">Manuels utilisateur</div>\n      </div>\n      <div class=\"kind\">docs/manuel/html</div>\n    </div>\n    <h1>Le <span class=\"hi\">mode d'emploi</span> de l'ERP, service par service</h1>\n    <p class=\"lede\">Un manuel par service, chaque onglet expliqué pas à pas avec des captures d'écran réelles de l'application. Commencez par la prise en main ci-dessous, puis ouvrez le manuel de votre service.</p>\n    <p class=\"lede\" style=\"font-size:.9rem;\"><b>Valable dans toute l application :</b> le bouton à <b>trois petites barres horizontales</b>, en haut de la barre latérale, replie le menu pour libérer toute la largeur de l écran ; un bouton identique apparaît en haut à gauche pour le réafficher. Le choix est mémorisé d une page à l autre.</p>\n    <div class=\"metachips\">\n      <span class=\"chip\">📚 <b>16 manuels</b> de service</span>\n      <span class=\"chip\">🖼 Captures réelles de l'application</span>\n      <span class=\"chip\">🖨 Imprimable (Ctrl+P) par manuel</span>\n    </div>\n  </header>\n\n  <section class=\"tab\" id=\"prise-en-main\">\n    <div class=\"tab-head\"><span class=\"tab-num\">🔑</span><h2>Prise en main — se connecter et naviguer</h2></div>\n    <p class=\"tab-but\"><b>Avant tout :</b> l'ERP est une application web. Elle s'ouvre dans un navigateur (Chrome, Edge, Firefox), au bureau comme à l'atelier — aucun logiciel à installer.</p>\n\n    <h3>Se connecter</h3>\n    <ol class=\"steps\">\n      <li>Ouvrez l'adresse de l'ERP dans le navigateur (celle fournie par la direction).</li>\n      <li>Saisissez votre <b>matricule</b> et votre <b>code PIN</b> personnel, puis validez.</li>\n      <li>En cas de PIN oublié : voir avec l'administrateur (Direction), qui peut le réinitialiser.</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/login.png\" alt=\"Écran de connexion (matricule + PIN)\" loading=\"lazy\">\n      <figcaption><b>Connexion</b> — matricule + code PIN personnel.</figcaption>\n    </figure>\n\n    <h3>L'accueil et la navigation</h3>\n    <p>Après connexion, l'<b>accueil</b> présente la grille des services. La <b>barre latérale</b> (sidebar), présente sur toutes les pages, permet de changer de service à tout moment. Chaque service s'organise en <b>onglets</b> (barre horizontale sous l'en-tête du service).</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/accueil.png\" alt=\"Page d'accueil : grille des services\" loading=\"lazy\">\n      <figcaption><b>Accueil</b> — un service = une carte ; la sidebar à gauche est toujours disponible.</figcaption>\n    </figure>\n\n    <h3>Ouvrir les manuels depuis l'ERP</h3>\n    <p>Ces manuels sont consultables <b>directement dans l'application</b> : le bouton <b>« Manuels d'utilisation »</b> se trouve en bas de la barre latérale, entre votre compte et le système de pointage. Vous n'y voyez que les manuels des services auxquels vous avez accès — la Direction les consulte tous.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/manuels-hub.png\" alt=\"Page des manuels d'utilisation dans l'ERP\" loading=\"lazy\">\n      <figcaption><b>Manuels d'utilisation</b> — une carte par manuel accessible ; le bandeau rappelle l'étendue de vos accès. Chaque manuel s'ouvre dans l'ERP et s'imprime d'un clic.</figcaption>\n    </figure>\n\n    <h3>Ce que vous voyez dépend de votre rôle</h3>\n    <ul class=\"points\">\n      <li>Chaque compte a un <b>rôle</b> (opérateur, qualité, achats, direction…) qui détermine les services visibles et les actions autorisées (lecture ou écriture).</li>\n      <li>Si un service ou un bouton n'apparaît pas, c'est en général une question de droits — pas une panne. Voir la Direction pour ajuster les autorisations.</li>\n      <li>Les données sont <b>partagées en temps réel</b> : ce que vous enregistrez est immédiatement visible par les autres services. En cas d'édition simultanée d'une même fiche, un <b>verrou</b> prévient le second utilisateur.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> chaque manuel est imprimable tel quel (Ctrl+P) — la mise en page s'adapte automatiquement à l'impression.</div>\n  </section>\n\n  <section class=\"tab\" id=\"manuels\">\n    <div class=\"tab-head\"><span class=\"tab-num\">📚</span><h2>Les manuels, service par service</h2></div>\n    <p class=\"tab-but\">Dans l'ordre du flux de l'entreprise : de la demande client jusqu'à la facturation, puis les fonctions support et le pilotage.</p>\n\n    <h3>Flux principal — de la demande client à la livraison</h3>\n    <div class=\"grid-idx\">\n      <a class=\"card-idx\" href=\"commercial.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#3b82f6\"></span>Commercial</span><span class=\"d\">Demandes site, DT, offres, avoirs, clients, commandes, affaires</span><span class=\"n\">8 onglets</span></a>\n      <a class=\"card-idx\" href=\"be.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#8b5cf6\"></span>Bureau d'Études</span><span class=\"d\">Nomenclatures, analyse DT, préparations techniques, références</span><span class=\"n\">5 onglets</span></a>\n      <a class=\"card-idx\" href=\"achats.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#0ea5e9\"></span>Achats</span><span class=\"d\">Demandes de prix (RFQ), demandes d'achat, fournisseurs, scorecard</span><span class=\"n\">5 onglets</span></a>\n      <a class=\"card-idx\" href=\"production.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#22c55e\"></span>Production</span><span class=\"d\">Plannings Gantt BDT/BST, présence, commandes &amp; lots, process ateliers</span><span class=\"n\">7 onglets</span></a>\n      <a class=\"card-idx\" href=\"oas.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#14b8a6\"></span>OAS</span><span class=\"d\">Lots &amp; balancelles, relevés eau et bains, traitement de surface</span><span class=\"n\">4 onglets</span></a>\n      <a class=\"card-idx\" href=\"qualite.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#ef4444\"></span>Qualité</span><span class=\"d\">PV, NC, 8D, dérogations, libération, quarantaine, ECME, capabilité, audits</span><span class=\"n\">13 onglets</span></a>\n      <a class=\"card-idx\" href=\"expeditions.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#f59e0b\"></span>Expéditions</span><span class=\"d\">Réceptions, envois, calendrier, fournisseurs (BC &amp; BL), OTD</span><span class=\"n\">5 onglets</span></a>\n      <a class=\"card-idx\" href=\"stock.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#84cc16\"></span>Stocks</span><span class=\"d\">Stock temps réel, gestion, mouvements, alertes &amp; réappro</span><span class=\"n\">5 onglets</span></a>\n      <a class=\"card-idx\" href=\"compta.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#6366f1\"></span>Comptabilité</span><span class=\"d\">Facturation, règlements, grand livre, TVA, balance &amp; trésorerie</span><span class=\"n\">5 onglets</span></a>\n    </div>\n\n    <h3>Support &amp; conformité</h3>\n    <div class=\"grid-idx\">\n      <a class=\"card-idx\" href=\"securite.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#dc2626\"></span>Sécurité</span><span class=\"d\">DUER, événements, EPI, chimie/FDS, contrôles, audit ISO 45001</span><span class=\"n\">9 onglets</span></a>\n      <a class=\"card-idx\" href=\"environnement.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#16a34a\"></span>Environnement</span><span class=\"d\">Déchets, rejets, ATEX, aspects &amp; impacts, ICPE, GES, ISO 14001/26000</span><span class=\"n\">10 onglets</span></a>\n      <a class=\"card-idx\" href=\"maintenance.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#f97316\"></span>Maintenance</span><span class=\"d\">Interventions/OM, préventif, MTBF, fiche 360, coûts postes, PDR</span><span class=\"n\">7 onglets</span></a>\n      <a class=\"card-idx\" href=\"rh.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#ec4899\"></span>RH</span><span class=\"d\">Employés, habilitations, compétences, organigramme, temps, pointage</span><span class=\"n\">7 pages</span></a>\n      <a class=\"card-idx\" href=\"plans.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#64748b\"></span>Plan / Bâtiment</span><span class=\"d\">Maquette du bâtiment, repères et zones</span><span class=\"n\">1 onglet</span></a>\n    </div>\n\n    <h3>Pilotage</h3>\n    <div class=\"grid-idx\">\n      <a class=\"card-idx\" href=\"direction.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#5C5391\"></span>Direction</span><span class=\"d\">Validations, jalons critiques, pilotage par affaire, budget, santé des données</span><span class=\"n\">7 onglets</span></a>\n      <a class=\"card-idx\" href=\"dashboard.html\"><span class=\"t\"><span class=\"dot\" style=\"background:#22409B\"></span>Tableaux de bord</span><span class=\"d\">Hub des 15 dashboards filtrables (période, site, comparaison N-1, export)</span><span class=\"n\">15 dashboards</span></a>\n    </div>\n  </section>\n\n  <footer class=\"doc\">\n    ERP Seem Semrac — manuels utilisateur générés depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre un manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\n  </footer>\n\n</div>\n</body>\n</html>\n",
  "maintenance": "<!doctype html>\r\n<html lang=\"fr\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>Manuel — Maintenance · ERP Seem Semrac</title>\r\n<link rel=\"stylesheet\" href=\"manuel.css\">\r\n</head>\r\n<body>\r\n<div class=\"wrap\">\r\n\r\n  <header class=\"doc\">\r\n    <div class=\"brandrow\">\r\n      <div class=\"logo\">SS</div>\r\n      <div>\r\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\r\n        <div class=\"eyebrow\">Manuel utilisateur</div>\r\n      </div>\r\n      <div class=\"kind\">docs/manuel/html</div>\r\n    </div>\r\n    <h1>Service <span class=\"hi\">Maintenance</span></h1>\r\n    <p class=\"lede\">Le service Maintenance est la GMAO de l'atelier : il recueille les pannes déclarées en Production, les transforme en <b>ordres de maintenance (OM)</b>, surveille l'usure des pièces à partir des heures réellement tournées par chaque machine, mesure la fiabilité (MTTR, MTBF, disponibilité, TRS) et chiffre ce que coûte chaque machine et chaque poste de travail. Ce manuel décrit les 7 onglets, écran par écran.</p>\r\n    <div class=\"metachips\">\r\n      <span class=\"chip\">👤 Pour qui : <b>Technicien(ne) maintenance</b> (écriture — avec la Direction · lecture : BE, Achats, Production, OAS, Qualité)</span>\r\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Maintenance</b></span>\r\n      <span class=\"chip\">🗂 <b>7 onglets</b></span>\r\n    </div>\r\n  </header>\r\n\r\n  <nav class=\"toc\">\r\n    <div class=\"toc-t\">Sommaire</div>\r\n    <ol>\r\n      <li><a href=\"#tab-interventions\">Interventions / OM</a></li>\r\n      <li><a href=\"#tab-preventif\">Plan Préventif</a></li>\r\n      <li><a href=\"#tab-mtbf\">MTBF &amp; Historique</a></li>\r\n      <li><a href=\"#tab-fiche\">Fiche 360</a></li>\r\n      <li><a href=\"#tab-postes\">Coûts postes</a></li>\r\n      <li><a href=\"#tab-pieces\">Pièces &amp; PDR</a></li>\r\n      <li><a href=\"#tab-dashboard\">Dashboard</a></li>\r\n    </ol>\r\n  </nav>\r\n\r\n  <!-- ══════════════ 1. INTERVENTIONS / OM ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-interventions\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Interventions / OM</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est l'écran de travail quotidien du technicien. Il réunit sur une seule page les <b>machines déclarées en panne</b> par l'atelier, les <b>ordres de maintenance en cours</b> et l'<b>historique des interventions clôturées</b>. Un OM est la trace complète d'une intervention : qui, quoi, combien de temps, combien ça a coûté, quelle cause racine. C'est aussi lui qui alimente tous les indicateurs de fiabilité du service (MTTR, MTBF, disponibilité) et le coût maintenance des machines et des postes.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Le bandeau jaune du service rappelle le titre <b>« Service Maintenance »</b> et sa signature <i>GMAO · OM · Préventif · MTBF · PDR · Historique · EN&nbsp;9100:2018</i>. À droite du bandeau, le bouton <b>« Demande d'achat »</b> permet de commander une pièce sans quitter la GMAO. Juste en dessous, la barre des sept onglets ; certains portent un compteur (nombre d'OM ouverts sur « Interventions / OM », nombre de pièces sur « Pièces &amp; PDR », nombre de postes actifs sur « Coûts postes »).</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/maintenance.png\" alt=\"Bandeau du service Maintenance et barre des onglets\" loading=\"lazy\">\r\n      <figcaption><b>Service Maintenance</b> — le bandeau jaune, la barre des sept onglets avec leurs compteurs, et le bouton « Demande d'achat » en haut à droite.</figcaption>\r\n    </figure>\r\n\r\n    <p>L'onglet lui-même empile <b>trois blocs</b>, du plus urgent au plus froid :</p>\r\n    <ul class=\"points\">\r\n      <li><b>Machines en panne — à traiter</b> (cadre rouge, avec le nombre de machines concernées). La mention « déclarées en panne dans Production › Process atelier » rappelle d'où vient l'information. Colonnes : <b>Machine</b> (nom + code), <b>Atelier</b> (Seem ou Semrac), <b>Motif</b>, <b>Depuis</b> (« aujourd'hui » ou nombre de jours), <b>Action</b>. La colonne Action affiche soit le bouton jaune <b>« Créer un OM »</b>, soit — si un OM est déjà ouvert sur cette machine — la mention <b>« OM-…-… en cours »</b>. Quand rien n'est en panne, le bloc affiche « Aucune machine en panne — tout tourne. »</li>\r\n      <li><b>Ordres de maintenance en cours</b>. Colonnes : <b>N°&nbsp;OM</b>, <b>Machine</b>, <b>Titre</b>, <b>Priorité</b>, <b>Statut</b>, <b>Signalé</b> (date), <b>Actions</b> (boutons <b>« Ouvrir »</b> et <b>« Clôturer »</b>).</li>\r\n      <li><b>Interventions clôturées (MTTR)</b> — les 30 dernières. Colonnes : <b>N°&nbsp;OM</b>, <b>Machine</b>, <b>Titre</b>, <b>MTTR</b> (durée réelle de l'intervention, en heures), <b>Clôturé</b> (date).</li>\r\n    </ul>\r\n    <ul class=\"points\">\r\n      <li>Priorité : <span class=\"b b-ok\">normal</span> · <span class=\"b b-warn\">urgent</span> · <span class=\"b b-crit\">critique</span>.</li>\r\n      <li>Statut d'un OM : <span class=\"b b-crit\">Ouvert</span> (signalé, pas encore pris en main) · <span class=\"b b-info\">En cours</span> (intervention démarrée) · <span class=\"b b-warn\">En attente</span> (bloqué, typiquement faute de pièce) · <span class=\"b b-ok\">Terminé</span> · <span class=\"b b-mut\">Annulé</span>.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-maintenance-om.png\" alt=\"Les trois blocs de l'onglet Interventions / OM\" loading=\"lazy\">\r\n      <figcaption><b>Interventions / OM</b> — les trois blocs empilés : machines en panne (en rouge), OM en cours, interventions clôturées. Ici une journée sans panne : « tout tourne ».</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — ouvrir un OM sur une machine en panne</h3>\r\n    <ol class=\"steps\">\r\n      <li>La panne se déclare d'abord <b>en Production</b> (onglet « Process Ateliers ») : la machine passe en arrêt avec un motif. Elle apparaît alors seule dans le bloc rouge, en haut de cet onglet.</li>\r\n      <li>Cliquez sur <b>« Créer un OM »</b> sur la ligne de la machine.</li>\r\n      <li>L'ERP crée l'ordre : numéro automatique <b>OM-AAAA-NNN</b>, type <i>correctif</i>, priorité <b>urgente</b>, statut <b>Ouvert</b>, titre « Panne — <i>nom de la machine</i> » et description reprise du motif de panne. Une notification confirme le numéro créé.</li>\r\n      <li>L'OM apparaît immédiatement dans le bloc « Ordres de maintenance en cours », et la ligne de la machine en panne affiche désormais « OM-… en cours » à la place du bouton.</li>\r\n    </ol>\r\n    <div class=\"note\"><b>Bon à savoir :</b> l'horodatage exact de la panne est conservé comme début de l'intervention. Le <b>MTTR</b> se calcule donc sur le temps réellement subi par l'atelier (panne → remise en service), pas sur le temps passé la clé à la main.</div>\r\n\r\n    <h3>Pas à pas — créer un OM vous-même (sans passer par une panne)</h3>\r\n    <p>Toute intervention ne naît pas d'un arrêt machine : un bruit suspect, une fuite, un réglage à reprendre, un graissage à planifier. Le bouton <b>« Nouvel OM »</b>, en haut à droite du bloc « Ordres de maintenance en cours », ouvre un formulaire de saisie complet.</p>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouvel OM »</b>.</li>\r\n      <li>Choisissez la <b>machine</b> concernée (obligatoire) : la liste indique le code et le site, et signale « — EN PANNE » les machines actuellement à l'arrêt.</li>\r\n      <li>Choisissez le <b>type d'intervention</b> : <b>Correctif</b> (panne, dépannage — l'intervention est réputée commencée tout de suite) ou <b>Préventif</b> (planifié : le chronomètre ne démarre qu'au moment de l'intervention réelle).</li>\r\n      <li>Saisissez un <b>titre</b> court et parlant (obligatoire), par exemple « Remplacement courroie broche », puis la <b>description</b> : ce que vous avez constaté, dans quel contexte.</li>\r\n      <li>Réglez la <b>priorité</b> (Normale / Urgente / Critique — cette dernière signalant un arrêt de production) et indiquez le <b>responsable</b> qui pilote l'intervention (la liste des salariés est proposée à la saisie).</li>\r\n      <li>Pour une intervention planifiée, renseignez la <b>date d'intervention prévue</b> et la <b>durée estimée</b> en heures. Ces deux champs sont facultatifs.</li>\r\n      <li>Validez par <b>« Créer l'OM »</b> : le numéro <b>OM-AAAA-NNN</b> est attribué automatiquement, l'ordre part au statut <b>Ouvert</b> et apparaît aussitôt dans la liste des interventions en cours.</li>\r\n    </ol>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-maintenance-nouvel-om.png\" alt=\"Formulaire de création d'un ordre de maintenance\" loading=\"lazy\">\r\n      <figcaption><b>Nouvel ordre de maintenance</b> — machine et titre sont les deux seuls champs obligatoires ; le type choisi (correctif ou préventif) détermine le point de départ du calcul du temps d'arrêt.</figcaption>\r\n    </figure>\r\n    <div class=\"astuce\"><b>Astuce :</b> réservez la priorité <b>Critique</b> aux cas qui bloquent réellement la production — c'est elle qui fait remonter l'intervention en tête des urgences et dans les indicateurs de la Direction.</div>\r\n\r\n    <h3>Pas à pas — renseigner et suivre une intervention</h3>\r\n    <ol class=\"steps\">\r\n      <li>Sur la ligne de l'OM, cliquez sur <b>« Ouvrir »</b> : la fenêtre de l'ordre de maintenance s'ouvre, son titre rappelant le numéro d'OM et la machine.</li>\r\n      <li>Complétez le diagnostic, la priorité, le <b>responsable</b> et l'<b>intervenant</b> (les deux champs proposent la liste des salariés), les pièces utilisées, le coût réel, la cause racine et vos observations (voir le tableau ci-dessous).</li>\r\n      <li>Passez le statut à <b>En cours</b> dès que vous intervenez, ou à <b>En attente</b> si vous êtes bloqué par une pièce à commander.</li>\r\n      <li>Cliquez sur <b>« Enregistrer »</b> : l'ERP confirme « OM enregistré (sans clôture) » — la machine reste en arrêt et l'OM reste ouvert.</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — clôturer une intervention</h3>\r\n    <ol class=\"steps\">\r\n      <li>Renseignez d'abord le <b>coût réel</b>, les <b>pièces utilisées</b>, l'<b>intervenant</b>, la <b>cause racine</b> et les <b>observations</b> : à la clôture, ces informations sont enregistrées avec l'OM.</li>\r\n      <li>Cliquez sur <b>« Clôturer l'intervention »</b> (dans la fenêtre de l'OM) ou sur <b>« Clôturer »</b> (directement sur la ligne). Une confirmation apparaît : « Clôturer cette intervention ? La machine sera remise en service et le MTTR calculé. »</li>\r\n      <li>Validez. L'OM passe en <span class=\"b b-ok\">Terminé</span>, sa durée est calculée et affichée dans la notification (« Intervention clôturée — MTTR X,X h »).</li>\r\n      <li>La <b>machine repasse automatiquement en état opérationnel</b> : le motif et la date de panne sont effacés. Elle redevient disponible au planning de Production et repasse au vert sur la maquette du bâtiment.</li>\r\n      <li>L'intervention descend dans le bloc « Interventions clôturées (MTTR) » et son coût vient alimenter la Fiche 360 de la machine et les Coûts postes.</li>\r\n    </ol>\r\n\r\n    <h3>La fiche d'intervention (bouton « Ouvrir »), champ par champ</h3>\r\n    <p>Il s'agit ici de la fiche d'une intervention <b>déjà créée</b> — celle que vous complétez au fil du dépannage. À ne pas confondre avec le formulaire de <b>création</b> décrit plus haut.</p>\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td>Titre</td><td>Texte</td><td>Recommandé</td><td>Intitulé court de l'intervention (prérempli « Panne — <i>machine</i> » sur un OM créé depuis une panne).</td></tr>\r\n        <tr><td>Description / diagnostic</td><td>Texte libre</td><td>Non</td><td>Ce qui a été constaté ; prérempli avec le motif de panne saisi en Production.</td></tr>\r\n        <tr><td>Priorité</td><td>Normale / Urgente / Critique</td><td>Oui (Urgente par défaut sur une panne)</td><td>Une priorité <i>critique</i> alimente la tuile « OM critiques » du Dashboard.</td></tr>\r\n        <tr><td>Statut</td><td>Ouvert / En cours / En attente</td><td>Oui</td><td>« En attente » sert aux interventions suspendues faute de pièce de rechange. La clôture ne se fait pas ici mais par le bouton dédié.</td></tr>\r\n        <tr><td>Responsable</td><td>Texte (liste des salariés)</td><td>Non</td><td>Qui pilote l'intervention.</td></tr>\r\n        <tr><td>Intervenant</td><td>Texte (liste des salariés)</td><td>Non</td><td>Qui a réellement effectué le travail.</td></tr>\r\n        <tr><td>Coût réel (€)</td><td>Nombre</td><td>Non (mais fortement conseillé)</td><td>Coût de l'intervention : c'est la seule source du coût maintenance dans la Fiche 360, les Coûts postes et le Dashboard.</td></tr>\r\n        <tr><td>Pièces utilisées</td><td>Texte</td><td>Non</td><td>Pièces consommées ; à répercuter ensuite sur le stock PDR de la machine.</td></tr>\r\n        <tr><td>Cause racine</td><td>Texte</td><td>Non</td><td>Pourquoi la panne est arrivée — la matière première des actions de fond et des 8D côté Qualité.</td></tr>\r\n        <tr><td>Observations</td><td>Texte libre</td><td>Non</td><td>Commentaire de fin d'intervention, consignes, points à surveiller.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Une machine ne se déclare pas en panne depuis la Maintenance : la déclaration se fait <b>en Production, onglet « Process Ateliers »</b>. La Maintenance prend le relais dès que la machine apparaît dans le bloc rouge.</li>\r\n      <li>Une seule ligne « Créer un OM » par machine : dès qu'un OM non clos existe sur la machine, le bouton disparaît au profit de son numéro. Cela évite les doublons d'ordres sur la même panne.</li>\r\n      <li>Le <b>coût réel</b> est la donnée la plus stratégique de l'écran : sans lui, le TCO de la machine et le coût du poste restent faux, et le prix de revient calculé en Production est sous-estimé.</li>\r\n      <li>Le <b>numéro d'OM</b> est attribué par l'ERP (OM-AAAA-NNN) : ne le saisissez jamais à la main.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> la clôture d'un OM <b>remet la machine en service</b> sans autre contrôle. Ne clôturez qu'une fois la machine réellement apte à produire : le planning de Production la considérera immédiatement comme disponible.</div>\r\n    <div class=\"astuce\"><b>Astuce :</b> s'il manque une pièce, passez l'OM en <b>« En attente »</b> et utilisez le bouton <b>« Demande d'achat »</b> du bandeau : la demande part directement au service Achats, qui la transformera en bon de commande fournisseur.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 2. PLAN PRÉVENTIF ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-preventif\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Plan Préventif</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Anticiper la casse plutôt que la subir. Cet onglet suit, machine par machine, les <b>heures de fonctionnement réellement tournées</b> — déduites des bons de travail (BDT) de la Production — et les compare à la <b>durée de vie conseillée</b> de chaque pièce remplaçable. Vous voyez d'un coup d'œil quelle pièce a consommé son capital d'heures, et laquelle est à changer maintenant.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Le titre <b>« Plan préventif — usure &amp; remplacement des pièces »</b> et son rappel : les heures viennent des BDT, la durée de vie et la date du dernier remplacement se définissent dans l'onglet <b>« Pièces &amp; PDR »</b>. L'écran est en deux volets.</p>\r\n    <ul class=\"points\">\r\n      <li><b>À gauche</b>, la liste des machines avec leur compteur et un champ <b>« Rechercher… »</b>. Chaque vignette porte le nom de la machine, son code et son atelier ; un liseré coloré rappelle le site (bleu pour Seem, rose pour Semrac).</li>\r\n      <li><b>À droite</b>, tant qu'aucune machine n'est choisie : « Choisissez une machine pour voir ses heures de fonctionnement et l'usure de ses pièces. »</li>\r\n      <li>Une fois la machine sélectionnée, trois tuiles : <b>Heures tournées (année)</b>, <b>Heures totales (BDT)</b> et <b>Pièces à remplacer</b> (le nombre de pièces dont la durée de vie est dépassée).</li>\r\n      <li>En dessous, le tableau <b>« Pièces remplaçables — usure &amp; échéance »</b> : <b>Pièce</b>, <b>Référence</b>, <b>Durée de vie</b>, <b>Dernier rempl.</b>, <b>Utilisé depuis</b> (heures machine cumulées depuis le dernier remplacement), <b>Restant avant rempl.</b>, <b>Usure</b> (barre de progression en %) et un bouton d'action.</li>\r\n      <li>Codes couleur de la barre d'usure : <span class=\"b b-ok\">vert</span> jusqu'à 80&nbsp;% · <span class=\"b b-warn\">orange</span> à partir de 80&nbsp;% · <span class=\"b b-crit\">rouge</span> à 100&nbsp;%, la colonne « Restant » affichant alors <b>À REMPLACER</b>. Une pièce sans durée de vie renseignée affiche « durée de vie ? » et un bouton <b>« définir »</b>.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/maintenance-preventif.png\" alt=\"Capture de l'onglet Plan Préventif\" loading=\"lazy\">\r\n      <figcaption><b>Plan Préventif</b> — la liste des machines à gauche (liseré bleu = Seem, rose = Semrac) ; le détail d'usure s'affiche à droite dès qu'une machine est choisie.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — vérifier l'usure d'une machine</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur la machine dans la liste de gauche (ou tapez son nom dans « Rechercher… » pour filtrer la liste).</li>\r\n      <li>Lisez les trois tuiles : les heures de l'année en cours, les heures totales depuis toujours, et le nombre de pièces déjà à remplacer.</li>\r\n      <li>Parcourez le tableau : les barres orange annoncent les remplacements du mois à venir, les rouges sont à traiter tout de suite.</li>\r\n      <li>Si une pièce affiche « durée de vie ? », cliquez sur <b>« définir »</b> et saisissez le nombre d'heures de fonctionnement avant remplacement conseillé (donnée du constructeur ou retour d'expérience). Le suivi d'usure démarre aussitôt.</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — enregistrer un remplacement de pièce</h3>\r\n    <ol class=\"steps\">\r\n      <li>Après avoir changé la pièce, cliquez sur le bouton vert en fin de ligne (« Marquer la pièce remplacée »).</li>\r\n      <li>Confirmez : « Marquer cette pièce remplacée aujourd'hui ? Le compteur d'usure repart à zéro. »</li>\r\n      <li>La date du jour devient le nouveau <b>dernier remplacement</b> ; la colonne « Utilisé depuis » revient à zéro et la barre d'usure redevient verte.</li>\r\n      <li>Pensez à décrémenter le stock de la pièce dans l'onglet <b>« Pièces &amp; PDR »</b>, et à rattacher l'intervention à un OM si elle a immobilisé la machine.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Les heures affichées sont le <b>temps machine alloué des BDT</b> (issu de la gamme définie à l'analyse DT), pas un compteur physique lu sur la machine. Une gamme mal renseignée en Bureau d'Études fausse donc le préventif.</li>\r\n      <li>Seules les pièces déclarées <b>remplaçables</b> apparaissent ici ; les consommables non suivis restent dans « Pièces &amp; PDR ».</li>\r\n      <li>Si aucune date de dernier remplacement n'est renseignée, l'usure est comptée depuis <b>l'origine</b> des heures machine — d'où l'intérêt de saisir cette date dès la création de la pièce.</li>\r\n    </ul>\r\n    <div class=\"note\"><b>Automatisme :</b> à chaque ouverture du service Maintenance, l'ERP passe en revue le préventif et <b>crée tout seul les OM échus</b>, sans doublon : d'une part les plans <b>calendaires</b> dont la date prévue est atteinte (le plan est ensuite avancé à la prochaine échéance), d'autre part les pièces <b>en fin de vie</b> (heures machine cumulées ≥ durée de vie), avec un OM « Remplacement pièce — … ». Vous les retrouvez dans l'onglet « Interventions / OM », en type préventif.</div>\r\n    <div class=\"astuce\"><b>Astuce :</b> renseignez la durée de vie <b>et</b> la date du dernier remplacement de chaque pièce critique dès sa création : c'est le seul travail de saisie du préventif — ensuite, l'ERP ouvre les OM tout seul au bon moment.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 3. MTBF & HISTORIQUE ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-mtbf\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>MTBF &amp; Historique</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Mesurer la fiabilité du parc machines. Deux indicateurs, calculés automatiquement à partir des OM : le <b>MTTR</b> (temps moyen de réparation — combien de temps une machine reste immobilisée) et le <b>MTBF</b> (temps moyen entre deux pannes — à quelle fréquence elle tombe). C'est l'écran qui permet de désigner les machines à fiabiliser en priorité, et de justifier un investissement ou un contrat de maintenance.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>En haut, le titre <b>« Fiabilité — MTTR &amp; MTBF »</b>, trois pastilles de filtre <b>Tout l'atelier</b> · <b>SEEM</b> · <b>SEMRAC</b>, et le rappel « MTTR = temps moyen de réparation · MTBF = temps moyen entre pannes ». Quatre tuiles suivent : <b>MTTR moyen</b> (en heures), <b>MTBF moyen</b> (en jours), <b>Disponibilité</b> (en %) et <b>Total pannes</b>. En dessous, le tableau <b>« Indicateurs par machine »</b> : <b>Machine</b> (nom souligné, cliquable), <b>Atelier</b>, <b>Pannes</b>, <b>MTTR (h)</b>, <b>MTBF (h)</b>, <b>État</b>.</p>\r\n    <ul class=\"points\">\r\n      <li>État de la machine : <span class=\"b b-ok\">OK</span> (opérationnelle) · <span class=\"b b-warn\">Maintenance</span> · <span class=\"b b-crit\">En panne</span>.</li>\r\n      <li>Le MTBF s'affiche en <b>heures</b> tant qu'il reste court, et bascule en <b>jours</b> au-delà de 48&nbsp;h — plus lisible pour un parc fiable.</li>\r\n      <li>Un tiret « — » signifie que l'indicateur n'est pas calculable : le MTTR demande au moins une intervention <b>clôturée</b>, le MTBF au moins <b>deux</b> pannes signalées.</li>\r\n      <li>La <b>disponibilité</b> est le rapport MTBF / (MTBF + MTTR) : la part du temps où la machine est apte à produire.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/maintenance-mtbf.png\" alt=\"Capture de l'onglet MTBF &amp; Historique\" loading=\"lazy\">\r\n      <figcaption><b>MTBF &amp; Historique</b> — les quatre tuiles résument le parc filtré ; dans le tableau, chaque nom de machine souligné ouvre sa Fiche 360.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — analyser la fiabilité d'un atelier</h3>\r\n    <ol class=\"steps\">\r\n      <li>Choisissez le périmètre avec les pastilles : <b>Tout l'atelier</b>, <b>SEEM</b> ou <b>SEMRAC</b>. Les quatre tuiles et le tableau se recalculent instantanément.</li>\r\n      <li>Triez votre lecture par la colonne <b>Pannes</b> : les machines qui tombent le plus souvent sont vos candidates au préventif renforcé.</li>\r\n      <li>Comparez ensuite <b>MTTR</b> et <b>MTBF</b> : un MTTR élevé signale un problème de pièces de rechange ou de compétence disponible ; un MTBF faible signale une machine réellement fragile ou mal entretenue.</li>\r\n      <li>Cliquez sur le <b>nom d'une machine</b> : l'ERP bascule sur sa <b>Fiche 360</b>, déjà chargée, pour comprendre l'historique complet.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Ces indicateurs ne valent que ce que valent les OM : une panne réparée sans OM n'existe pas pour la GMAO, et une intervention non clôturée n'entre pas dans le MTTR.</li>\r\n      <li>Le MTBF se calcule sur l'<b>écart entre les dates de signalement</b> des pannes successives : il ne devient significatif qu'après plusieurs incidents sur la même machine.</li>\r\n      <li>Une machine qui n'a jamais eu d'OM est considérée comme disponible à 100&nbsp;% — c'est normal, mais ce n'est pas une preuve de fiabilité tant qu'elle n'a pas d'historique.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> avant une revue de direction, filtrez sur chaque site et notez les trois machines au plus faible MTBF : c'est le format d'argumentaire le plus court pour obtenir un budget de fiabilisation.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 4. FICHE 360 ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-fiche\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Fiche 360</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Tout savoir d'une machine sur un seul écran : ce qu'elle coûte (coût total de possession), ce qu'elle vaut en fiabilité, ce qui est passé dessus en production et tout ce qu'on lui a fait comme maintenance. C'est la fiche que l'on ouvre avant un arbitrage — réparer ou remplacer, sous-traiter ou investir — et celle que l'on montre en audit pour prouver la traçabilité du moyen de production.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Un menu déroulant <b>« Machine : »</b> en haut ; tant qu'aucune machine n'est choisie, l'écran invite à en sélectionner une. Une fois la machine choisie, la fiche se déploie :</p>\r\n    <ul class=\"points\">\r\n      <li>Un <b>bandeau d'identité</b> : nom et code de la machine, atelier, année en cours, et une pastille d'état — <span class=\"b b-ok\">Opérationnel</span> · <span class=\"b b-warn\">En maintenance</span> · <span class=\"b b-crit\">En panne</span>.</li>\r\n      <li>Une première rangée de tuiles <b>coûts</b> : <b>TCO</b> de l'année (OPEX + maintenance), <b>OPEX annuel</b> (avec le taux horaire de la machine), <b>Maintenance</b> de l'année (avec le nombre d'OM, dont les ouverts), <b>Coût absorbé prod.</b> (heures BDT × taux horaire) et <b>Valeur PDR stock</b> (nombre de pièces, et combien sont sous le stock mini).</li>\r\n      <li>Une seconde rangée de tuiles <b>fiabilité</b> : <b>Disponibilité</b>, <b>TRS*</b>, <b>MTTR</b>, <b>MTBF</b>, <b>Pannes</b>, <b>Heures machine</b> et <b>SPC cotes</b> (part de relevés de cotes conformes, issus des contrôles Qualité).</li>\r\n      <li>Deux tableaux côte à côte : <b>Historique de production</b> — ce qui est passé sur la machine (Date, Opération, Pièce, Client, Temps, Résultat) — et <b>Maintenance</b>, avec le cumul dépensé en titre (OM, Intervention, Date, Coût).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/maintenance-fiche.png\" alt=\"Capture de l'onglet Fiche 360\" loading=\"lazy\">\r\n      <figcaption><b>Fiche 360</b> — tout part du menu « Machine : » ; la fiche complète (coûts, fiabilité, historiques) s'affiche dès la sélection.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — instruire un arbitrage « réparer ou remplacer »</h3>\r\n    <ol class=\"steps\">\r\n      <li>Sélectionnez la machine dans le menu <b>« Machine : »</b>.</li>\r\n      <li>Comparez la tuile <b>Maintenance de l'année</b> à la tuile <b>OPEX annuel</b> : quand la maintenance approche le coût d'exploitation, la machine est en fin de vie économique.</li>\r\n      <li>Regardez la <b>Disponibilité</b> et le nombre de <b>Pannes</b> : une machine peu chère mais souvent arrêtée coûte surtout des retards de livraison.</li>\r\n      <li>Vérifiez le <b>Coût absorbé prod.</b> et les <b>Heures machine</b> : une machine peu chargée ne justifie pas un investissement de remplacement — elle justifie plutôt un redéploiement.</li>\r\n      <li>Parcourez le tableau <b>Maintenance</b> pour repérer les interventions répétitives (même titre, même cause) : c'est souvent là que se cache le vrai défaut à traiter.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Les <b>heures machine</b> comptabilisent uniquement le temps machine issu de la gamme (analyse DT), pas le temps homme : elles ne se comparent pas aux heures de présence des opérateurs.</li>\r\n      <li>Le <b>coût absorbé production</b> (heures × taux) est un indicateur de charge, il n'entre <b>pas</b> dans le TCO — sinon la machine serait comptée deux fois.</li>\r\n      <li>Le <b>TRS</b> affiché est <b>partiel</b> : c'est Disponibilité × Qualité. La composante Performance (cadence réelle rapportée à la cadence théorique) n'est pas encore mesurée — d'où l'astérisque.</li>\r\n      <li>L'historique de production affiche les derniers passages, et le bloc maintenance les derniers OM : pour l'exhaustivité comptable, appuyez-vous sur les tuiles, qui portent les cumuls.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> depuis la maquette du bâtiment (service <b>Plan / Bâtiment</b>), cliquer un repère de machine ouvre directement sa Fiche 360 — pratique en réunion devant le plan de l'atelier. Le nom des machines du tableau « MTBF &amp; Historique » y mène aussi en un clic.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 5. COÛTS POSTES ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-postes\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Coûts postes</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Voir le coût de l'atelier non plus machine par machine, mais <b>poste de travail par poste de travail</b> — un poste regroupant plusieurs machines. L'onglet additionne, pour chaque poste, l'<b>OPEX annuel</b> de ses machines et le <b>coût des OM</b> de ces mêmes machines, pour donner le <b>TCO annuel</b> du poste. C'est le chaînon entre la maintenance et le prix de revient : le taux horaire du poste sert directement au calcul du coût de revient unitaire des pièces.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Une seule carte, <b>« Coûts par poste — OPEX + maintenance (TCO annuel) »</b>, avec un tableau dont chaque ligne est un poste actif :</p>\r\n    <ul class=\"points\">\r\n      <li><b>Poste</b> — le nom, précédé de la pastille de couleur du poste (la même qu'au planning de Production).</li>\r\n      <li><b>Machines</b> — combien de machines composent le poste.</li>\r\n      <li><b>OPEX annuel</b> — le coût d'exploitation annuel cumulé des machines du poste (valeur réelle si elle a été saisie, sinon estimation à partir du taux horaire et de la capacité).</li>\r\n      <li><b>Maintenance <i>année en cours</i></b> — le cumul des coûts réels des OM des machines du poste sur l'exercice.</li>\r\n      <li><b>TCO annuel</b> — la somme des deux colonnes précédentes.</li>\r\n      <li><b>Taux/h effectif</b> — le taux horaire qui alimente le coût de revient, en €/h. La mention <span class=\"b b-warn\">manuel</span> signale un taux forcé à la main ; la mention « dont +X achats » signale la part provenant des achats machine reçus dans l'année.</li>\r\n      <li>Une ligne <b>TOTAL POSTES</b> en bas récapitule l'OPEX, la maintenance et le TCO de tout l'atelier.</li>\r\n      <li>Si aucun poste n'est défini, l'écran renvoie vers <b>Production → onglet Machines → « Postes de travail »</b>, où les postes se créent.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/maintenance-postes.png\" alt=\"Capture de l'onglet Coûts postes\" loading=\"lazy\">\r\n      <figcaption><b>Coûts postes</b> — l'onglet se situe entre « Fiche 360 » et « Pièces &amp; PDR » ; son compteur indique le nombre de postes actifs pris en compte.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — contrôler le coût d'un poste</h3>\r\n    <ol class=\"steps\">\r\n      <li>Repérez la ligne du poste concerné et lisez son nombre de <b>machines</b> : un poste sans machine rattachée n'a ni OPEX ni taux (colonnes à « — »).</li>\r\n      <li>Comparez <b>Maintenance</b> et <b>OPEX annuel</b> : une maintenance qui pèse lourd face à l'OPEX signale un poste à fiabiliser.</li>\r\n      <li>Vérifiez le <b>Taux/h effectif</b> : c'est lui qui est facturé au prix de revient. S'il porte la mention « manuel », le taux a été forcé en Production — assurez-vous qu'il est toujours d'actualité.</li>\r\n      <li>En cas d'écart, corrigez à la source : le rattachement des machines aux postes et le taux se règlent en <b>Production</b>, les coûts d'intervention se corrigent dans l'OM concerné (onglet « Interventions / OM »).</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>L'agrégation est <b>exactement la même qu'en Production</b> : les deux services doivent afficher les mêmes chiffres. Un écart signale une donnée saisie deux fois ou un rattachement de machine incohérent.</li>\r\n      <li>Seuls les postes <b>actifs</b> sont listés ; un poste passé inactif disparaît du tableau et du total.</li>\r\n      <li>Une machine <b>sans poste</b> n'est comptée nulle part ici : elle n'apparaît que dans sa Fiche 360. Rattachez chaque machine à un poste pour que le TCO de l'atelier soit complet.</li>\r\n      <li>La colonne Maintenance ne retient que les OM de l'<b>année civile en cours</b> : elle repart à zéro au 1<sup>er</sup> janvier, contrairement au cumul affiché dans la Fiche 360.</li>\r\n    </ul>\r\n    <div class=\"note\"><b>Rappel :</b> cet onglet est en <b>consultation</b>. Rien ne s'y saisit — tout vient des machines (Production), des OPEX et des OM.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 6. PIÈCES & PDR ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-pieces\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">6</span><h2>Pièces &amp; PDR</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Tenir le magasin des pièces de rechange (PDR), machine par machine : ce qu'on a, où c'est rangé, chez qui on le rachète, à quel prix, et à partir de quel seuil il faut recommander. C'est aussi ici que se règlent les deux paramètres qui font vivre le <b>Plan Préventif</b> : la durée de vie conseillée d'une pièce et la date de son dernier remplacement.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Le titre <b>« Pièces de rechange (PDR) par machine »</b>, puis un menu déroulant <b>« Machine : »</b>. Tant qu'aucune machine n'est choisie, l'écran affiche « Choisissez une machine pour voir et gérer ses pièces de rechange. » Une fois la machine sélectionnée, deux blocs apparaissent :</p>\r\n    <ul class=\"points\">\r\n      <li>Le formulaire <b>« Ajouter une pièce de rechange »</b> (voir le tableau champ par champ plus bas) et son bouton jaune <b>« Ajouter la pièce »</b>.</li>\r\n      <li>Le tableau <b>« Pièces de rechange »</b> avec son compteur : <b>Désignation</b>, <b>Référence</b>, <b>Fournisseur</b>, <b>Prix</b>, <b>Stock</b> (stock actuel / stock mini), <b>Emplac.</b> et un bouton corbeille pour supprimer la ligne.</li>\r\n      <li>Une pièce dont le stock est <b>tombé au niveau du mini</b> s'affiche en rouge, suivie d'un ⚠ : c'est le signal de réapprovisionnement.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/maintenance-pieces.png\" alt=\"Capture de l'onglet Pièces &amp; PDR\" loading=\"lazy\">\r\n      <figcaption><b>Pièces &amp; PDR</b> — le magasin est organisé <i>par machine</i> : le menu « Machine : » conditionne tout l'écran.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — enregistrer une pièce de rechange</h3>\r\n    <ol class=\"steps\">\r\n      <li>Choisissez la machine dans le menu <b>« Machine : »</b>.</li>\r\n      <li>Saisissez au minimum la <b>Désignation</b> (par exemple « Courroie trapézoïdale A38 ») — c'est le seul champ obligatoire.</li>\r\n      <li>Complétez la <b>Référence</b>, le <b>Fournisseur</b> (le champ propose les fournisseurs déjà utilisés sur d'autres pièces), le <b>Prix unitaire</b>, le <b>Stock actuel</b>, le <b>Stock mini</b> et l'<b>Emplacement</b> (magasin / casier).</li>\r\n      <li>Renseignez les deux champs sur fond jaune — <b>Durée de vie conseillée (h)</b> et <b>Dernier remplacement</b> — si la pièce doit être suivie en préventif.</li>\r\n      <li>Cliquez sur <b>« Ajouter la pièce »</b> : elle rejoint la liste de la machine et, si sa durée de vie est renseignée, apparaît immédiatement dans le tableau d'usure du <b>Plan Préventif</b>.</li>\r\n    </ol>\r\n\r\n    <h3>Le formulaire d'ajout, champ par champ</h3>\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td>Machine</td><td>Menu déroulant</td><td>Oui</td><td>Sélectionné en haut de l'écran ; la pièce est toujours rattachée à une machine.</td></tr>\r\n        <tr><td>Désignation</td><td>Texte</td><td>Oui</td><td>Nom courant de la pièce, tel qu'on la demande au magasin.</td></tr>\r\n        <tr><td>Référence</td><td>Texte</td><td>Non</td><td>Référence constructeur ou fournisseur — utile pour recommander sans erreur.</td></tr>\r\n        <tr><td>Fournisseur</td><td>Texte (propositions)</td><td>Non</td><td>Chez qui la pièce se rachète ; les fournisseurs déjà saisis sont proposés automatiquement.</td></tr>\r\n        <tr><td>Prix unitaire (€)</td><td>Nombre</td><td>Non</td><td>Sert à valoriser le stock PDR affiché dans la Fiche 360 de la machine.</td></tr>\r\n        <tr><td>Stock actuel</td><td>Nombre</td><td>Non (0 par défaut)</td><td>Quantité réellement en magasin.</td></tr>\r\n        <tr><td>Stock mini</td><td>Nombre</td><td>Non (0 par défaut)</td><td>Seuil d'alerte : au-dessous ou à égalité, la ligne passe en rouge avec un ⚠.</td></tr>\r\n        <tr><td>Emplacement</td><td>Texte</td><td>Non</td><td>Magasin / casier — évite de chercher la pièce pendant que la machine est arrêtée.</td></tr>\r\n        <tr><td>Durée de vie conseillée (h)</td><td>Nombre</td><td>Non (obligatoire pour le préventif)</td><td>Heures de fonctionnement machine avant remplacement conseillé. Déclenche le suivi d'usure et, une fois atteinte, la création automatique d'un OM préventif.</td></tr>\r\n        <tr><td>Dernier remplacement</td><td>Date</td><td>Non (fortement conseillé)</td><td>Point de départ du compteur d'usure. Sans cette date, l'usure est comptée depuis l'origine des heures machine.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Une pièce ne se déplace pas d'une machine à l'autre : si la même référence sert sur deux machines, créez-la des deux côtés (chaque machine a son propre compteur d'usure).</li>\r\n      <li>Le stock PDR de cet onglet est <b>indépendant du service Stocks</b> : il ne se décrémente pas tout seul quand vous utilisez une pièce. Mettez le <b>stock actuel</b> à jour après chaque intervention.</li>\r\n      <li>Le prix unitaire × le stock donne la <b>valeur PDR</b> affichée dans la Fiche 360 : un prix laissé vide sous-évalue le stock immobilisé.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> la suppression d'une pièce (bouton corbeille) est <b>définitive</b>, après une simple confirmation — son historique d'usure et sa date de dernier remplacement disparaissent avec elle.</div>\r\n    <div class=\"astuce\"><b>Astuce :</b> pour recommander une pièce sous le mini, utilisez le bouton <b>« Demande d'achat »</b> du bandeau : la demande arrive dans le service Achats, qui la transforme en demande de prix puis en bon de commande fournisseur.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 7. DASHBOARD ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-dashboard\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">7</span><h2>Dashboard</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La photo du service en une page : combien d'interventions sont en cours, combien de machines sont à l'arrêt, quelle est la disponibilité du parc, combien la maintenance a coûté depuis le début de l'année, et quels entretiens préventifs tombent dans les sept jours. C'est l'écran d'ouverture de journée et l'écran de point hebdomadaire avec la Production.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li>Six tuiles en haut : <b>OM ouverts / en cours</b> (interventions actives), <b>OM critiques</b> (action immédiate requise), <b>Disponibilité moy.</b> (calculée MTBF/MTTR), <b>TRS moyen*</b> (Dispo × Qualité), <b>Coût maintenance</b> (cumul depuis le début de l'année) et <b>Machines arrêtées</b>.</li>\r\n      <li>Le tableau <b>Disponibilité &amp; TRS par machine (calculé)</b> : <b>Machine</b>, <b>Disponibilité</b> (barre + %), <b>TRS*</b>, <b>MTBF</b>, <b>MTTR</b>, <b>Pannes</b>, <b>Qualité</b>. La disponibilité passe au vert au-dessus de 90&nbsp;%, à l'orange entre 75 et 90&nbsp;%, au rouge en dessous ; le TRS au vert au-dessus de 85&nbsp;%, à l'orange entre 65 et 85&nbsp;%, au rouge en dessous.</li>\r\n      <li>La carte <b>Statut machines</b> — une ligne par machine suivie, avec sa barre de disponibilité, son MTBF et son état : <span class=\"b b-ok\">Opérationnel</span> · <span class=\"b b-warn\">En maintenance</span> · <span class=\"b b-crit\">Arrêt</span>.</li>\r\n      <li>La carte <b>Prochains PM urgents (≤ 7 jours)</b> — les entretiens préventifs à venir, avec une pastille d'échéance (<b>J-<i>n</i></b> à venir, <b>Auj.</b> aujourd'hui, <b>J+<i>n</i></b> en retard), l'intitulé, la machine, le responsable et le type. Le bouton <b>« Voir le plan préventif complet »</b> bascule vers l'onglet Plan Préventif. Quand rien n'est dû : « Aucun PM urgent cette semaine ».</li>\r\n      <li>Le tableau <b>Ordres de maintenance actifs</b> (les 8 premiers) : <b>N°&nbsp;OM</b>, <b>Type</b>, <b>Machine</b>, <b>Titre</b>, <b>Priorité</b>, <b>Statut</b>, <b>Prévu le</b>. La date prévue est colorée selon l'urgence : rouge si l'échéance est dépassée, orange à 3 jours ou moins, ambre à 7 jours ou moins, vert au-delà.</li>\r\n      <li>Types d'OM identifiables par leur pastille : <b>correctif</b>, <b>preventif</b>, <b>amelioratif</b>, <b>vgp</b> (vérification générale périodique) et <b>inspection</b>.</li>\r\n      <li>Statuts affichés ici : <span class=\"b b-info\">Ouvert</span> · <span class=\"b b-warn\">En cours</span> · <span class=\"b b-mut\">En attente PDR</span> · <span class=\"b b-ok\">Terminé</span> · <span class=\"b b-mut\">Annulé</span>.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/maintenance-dashboard.png\" alt=\"Capture de l'onglet Dashboard Maintenance\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard</b> — les six tuiles, puis le tableau Disponibilité &amp; TRS par machine ; en bas de page, le statut des machines, les préventifs de la semaine et les OM actifs.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — le point du lundi matin</h3>\r\n    <ol class=\"steps\">\r\n      <li>Lisez d'abord les tuiles <b>Machines arrêtées</b> et <b>OM critiques</b> : si elles ne sont pas à zéro, commencez la journée par l'onglet « Interventions / OM ».</li>\r\n      <li>Balayez la carte <b>Prochains PM urgents</b> : toute pastille <b>J+</b> est un préventif en retard — planifiez-le avec la Production avant qu'il ne devienne une panne.</li>\r\n      <li>Dans le tableau <b>Disponibilité &amp; TRS</b>, repérez les lignes orange ou rouges : ce sont les machines qui pèsent sur la capacité de l'atelier.</li>\r\n      <li>Terminez par le tableau <b>Ordres de maintenance actifs</b> et traitez d'abord les dates « Prévu le » affichées en rouge.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le <b>coût maintenance</b> affiché est un cumul depuis le début de l'année : il ne vaut que si le champ « coût réel » des OM est renseigné à chaque clôture.</li>\r\n      <li>Le <b>TRS</b> est partiel (Disponibilité × Qualité) : la composante Performance n'est pas encore mesurée. Ne le comparez pas tel quel à un TRS constructeur.</li>\r\n      <li>La colonne <b>Qualité</b> vient des passages de production enregistrés sur la machine : elle reste vide tant qu'aucun bon de travail n'a été soldé dessus.</li>\r\n      <li>Une machine sans aucun OM est portée à 100&nbsp;% de disponibilité : la moyenne du parc est donc optimiste tant que l'historique de la GMAO est jeune.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> le vrai levier de ce tableau de bord n'est pas ici mais dans la saisie : un OM clôturé avec sa durée, son coût et sa cause racine fait progresser d'un coup la disponibilité mesurée, le TCO des machines et le coût des postes.</div>\r\n  </section>\r\n\r\n  <div class=\"docnav\">\r\n    <a href=\"index.html\">← Sommaire des manuels</a>\r\n    <a href=\"rh.html\">Manuel suivant : RH →</a>\r\n  </div>\r\n\r\n  <footer class=\"doc\">\r\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\r\n  </footer>\r\n\r\n</div>\r\n</body>\r\n</html>\r\n",
  "oas": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Manuel — OAS · ERP Seem Semrac</title>\n<link rel=\"stylesheet\" href=\"manuel.css\">\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header class=\"doc\">\n    <div class=\"brandrow\">\n      <div class=\"logo\">SS</div>\n      <div>\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\n        <div class=\"eyebrow\">Manuel utilisateur</div>\n      </div>\n      <div class=\"kind\">docs/manuel/html</div>\n    </div>\n    <h1>Service <span class=\"hi\">OAS</span></h1>\n    <p class=\"lede\">L'OAS (Oxydation Anodique Sulfurique) est le traitement de surface de l'atelier. Ce service suit les lots arrivés à l'étape OAS, les <b>balancelles</b> (sessions de traitement multi-références), les relevés de consommation d'eau et les relevés périodiques des bains. Vous y apprendrez à composer une balancelle, à la clore avec un autocontrôle, et à saisir les relevés réglementaires eau et bains.</p>\n    <div class=\"metachips\">\n      <span class=\"chip\">👤 Pour qui : <b>Opérateur OAS</b> (lecture : BE, Production, Qualité, Sécurité, Stock, Maintenance)</span>\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → OAS</b></span>\n      <span class=\"chip\">🗂 <b>4 onglets</b></span>\n    </div>\n  </header>\n\n  <nav class=\"toc\">\n    <div class=\"toc-t\">Sommaire</div>\n    <ol>\n      <li><a href=\"#tab-lots-balancelles\">Lots &amp; Balancelles</a></li>\n      <li><a href=\"#tab-eau\">Relevé consommation eau</a></li>\n      <li><a href=\"#tab-bains\">Relevés périodiques bains</a></li>\n      <li><a href=\"#tab-dashboard\">Dashboard OAS</a></li>\n    </ol>\n  </nav>\n\n  <!-- ═══════════════ ONGLET 1 : LOTS & BALANCELLES ═══════════════ -->\n  <section class=\"tab\" id=\"tab-lots-balancelles\">\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Lots &amp; Balancelles</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> L'OAS est une « porte de lot » : l'étape n'a pas de bon de travail propre. Dès que le bon de travail (BDT) <b>précédant</b> l'étape OAS est soldé en Production, le lot apparaît <b>automatiquement</b> dans cet onglet — vous n'avez rien à créer. Vous y composez ensuite les <b>balancelles</b> (une balancelle = une session de traitement pouvant mélanger plusieurs références de plusieurs lots), puis vous les clôturez avec un autocontrôle. Quand 100 % des pièces d'un lot sont traitées, le lot bascule automatiquement vers son étape suivante.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>L'écran empile trois tableaux, avec en haut à droite le bouton <b>« Nouvelle balancelle »</b> :</p>\n    <ul class=\"points\">\n      <li><b>Lots arrivés à l'OAS</b> — colonnes : Lot · Client · Pièce · Pièces traitées (traitées / total) · Progression OAS (barre de progression en %) · Statut · Étape suivante (le BDT qui suivra) · Action. Chaque ligne porte un bouton <b>« Balancelle »</b> qui ouvre le formulaire avec le lot déjà présélectionné. Statuts : <span class=\"b b-info\">En OAS</span> tant que le traitement est en cours, <span class=\"b b-ok\">Terminé</span> à 100 %.</li>\n      <li><b>Balancelles (sessions OAS)</b> — colonnes : Session · Lot(s) / Réf · Qté · Charge surface (jauge en % de la limite de 550 000 mm²) · Bain · Entrée · Sortie · Durée · Statut · Résultat · Action. Statuts : <span class=\"b b-info\">En cours</span>, <span class=\"b b-ok\">Terminé</span>, <span class=\"b b-mut\">Annulé</span> ; résultat : <span class=\"b b-ok\">Conforme</span> ou <span class=\"b b-crit\">Non conforme</span>. Une balancelle en cours porte le bouton <b>« Clore + autocontrôle »</b>. Un champ de recherche filtre la liste par <b>n° d'affaire, n° de lot ou n° de session</b>.</li>\n      <li><b>Lots OAS terminés</b> — colonnes : Lot · Client · Pièce · Pièces traitées · Statut OAS (badge <span class=\"b b-ok\">✓ 100% OAS</span>) · Bascule vers (le BDT suivant du lot, activé automatiquement).</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/oas.png\" alt=\"Capture de l'onglet Lots &amp; Balancelles du service OAS\" loading=\"lazy\">\n      <figcaption><b>Lots &amp; Balancelles</b> — en haut les lots arrivés à l'OAS avec leur barre de progression, au milieu les balancelles avec la jauge de charge surface, en bas les lots terminés qui basculent vers l'étape suivante.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — créer une balancelle</h3>\n    <ol class=\"steps\">\n      <li>Dans le tableau <b>Lots arrivés à l'OAS</b>, cliquez sur <b>« Balancelle »</b> sur la ligne du lot à traiter (le lot est présélectionné), ou cliquez sur <b>« Nouvelle balancelle »</b> en haut de page pour partir d'un formulaire vierge.</li>\n      <li>Le <b>N° de session</b> (format OAS-AAAA-NNNN) est généré automatiquement. Choisissez le <b>type de traitement</b> (la liste reprend les process des postes OAS déclarés dans Production → Process Ateliers) et le <b>bain</b> utilisé. L'<b>heure d'entrée</b> est préremplie à l'instant présent.</li>\n      <li>Composez le chargement : pour chaque référence, choisissez le <b>lot</b> (la liste affiche « n° de lot · pièce · reste N pcs »), la <b>référence pièce</b> et la <b>surface unitaire</b> se préremplissent, puis saisissez le <b>nombre de pièces</b> posées sur la balancelle. Cliquez sur <b>« Ajouter une référence »</b> pour mélanger plusieurs lots sur la même balancelle.</li>\n      <li>Surveillez la <b>jauge de charge</b> : elle cumule surface unitaire × quantité de toutes les lignes, sur une limite de <b>550 000 mm²</b>. Verte = charge OK (le message affiche la marge libre restante) ; orange à partir de 85 % = « charge proche du maximum » ; rouge au-delà de 100 % = « charge dépassée : retirez des pièces ou réduisez la quantité ».</li>\n      <li>Cliquez sur <b>« Enregistrer la balancelle »</b>. La session apparaît dans le tableau des balancelles avec le statut <span class=\"b b-info\">En cours</span>, et la progression des lots concernés augmente d'autant.</li>\n    </ol>\n\n    <h3>Le formulaire « Nouvelle balancelle » en détail</h3>\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>N° Session</td><td>Automatique</td><td>—</td><td>Généré au format OAS-AAAA-NNNN, non modifiable.</td></tr>\n          <tr><td>Type de traitement (bain)</td><td>Liste déroulante</td><td>Oui</td><td>Reprend les noms des process des postes d'activité OAS (Production → Postes). À défaut : OAS incolore, OAS noire, Désoxydation.</td></tr>\n          <tr><td>Bain</td><td>Liste déroulante</td><td>Oui</td><td>Principal OAS · Bain de lavage · Rinçage 1 · Rinçage 2 · Neutralisation · Bain 2 (essais).</td></tr>\n          <tr><td>Heure entrée</td><td>Date + heure</td><td>Oui</td><td>Préremplie à l'instant présent ; c'est le début de la session (la durée est calculée entrée → sortie).</td></tr>\n          <tr><td>Références (une ligne par référence)</td><td>Lot + référence + surface unitaire (mm²) + nb pièces</td><td>Oui (au moins une ligne)</td><td>Chaque ligne doit avoir un lot, une surface &gt; 0 et une quantité &gt; 0. La référence et la surface se préremplissent au choix du lot ; la surface vient de la nomenclature de la pièce quand elle y est renseignée.</td></tr>\n          <tr><td>Observations</td><td>Texte libre</td><td>Non</td><td>Remarques sur la session (montage, particularités…).</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-oas-balancelle.png\" alt=\"Formulaire Nouvelle balancelle OAS multi-références\" loading=\"lazy\">\n      <figcaption><b>Nouvelle balancelle</b> — les lignes de références en haut, la jauge de charge (0 → 550 000 mm²) qui se recalcule à chaque saisie.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — clore une balancelle (autocontrôle)</h3>\n    <ol class=\"steps\">\n      <li>Dans le tableau des balancelles, cliquez sur <b>« Clore + autocontrôle »</b> sur la ligne de la session en cours. Le bandeau de la fenêtre rappelle la session, le lot et la pièce concernés.</li>\n      <li>Saisissez les <b>mesures finales</b> : pH final du bain, température finale (°C), épaisseur anodique (µm), Cp et Cpk si vous les avez ; l'<b>heure de sortie</b> est obligatoire (préremplie à l'instant présent).</li>\n      <li>Choisissez l'<b>aspect visuel</b> (Uniforme — couleur homogène · Léger voile · Tache locale · Coulure · Brûlure) puis le <b>résultat de l'autocontrôle</b> : <span class=\"b b-ok\">✓ Conforme — libéré</span> ou <span class=\"b b-crit\">✗ Non conforme — bloqué (NC ouverte)</span>. Notez les anomalies éventuelles dans Observations.</li>\n      <li><b>Identifiez-vous</b> : saisissez votre <b>matricule</b> et votre <b>code PIN</b> (les mêmes que pour la connexion à l'ERP). Sans identification valide, la clôture est refusée.</li>\n      <li>Cliquez sur <b>« Valider la clôture + créer le PV »</b>. La balancelle passe à <span class=\"b b-ok\">Terminé</span> avec son résultat, et un <b>PV de contrôle</b> (type autocontrôle) est créé automatiquement dans le service <b>Qualité</b> — la notification affiche son numéro.</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-oas-cloture-balancelle.png\" alt=\"Fenêtre Clore + autocontrôle d'une balancelle OAS\" loading=\"lazy\">\n      <figcaption><b>Clore + autocontrôle</b> — le bandeau rappelle la session, le lot et la pièce ; en dessous les mesures finales (pH, température, épaisseur anodique, Cp/Cpk), l'heure de sortie obligatoire, l'aspect visuel, le résultat conforme / non conforme, puis le matricule et le code PIN qui signent l'autocontrôle. La validation clôt la session et crée le PV de contrôle en Qualité.</figcaption>\n    </figure>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>La limite de charge d'une balancelle est de <b>550 000 mm²</b> de surface totale : l'enregistrement est refusé au-delà, quelle que soit la jauge affichée.</li>\n      <li>La <b>progression OAS d'un lot</b> est calculée sur les quantités posées en balancelles : elle passe à « Terminé » à 100 %, et le lot bascule alors automatiquement vers son étape suivante (colonne « Bascule vers »).</li>\n      <li>La surface unitaire proposée vient de la <b>nomenclature</b> de la pièce (Bureau Études). Vérifiez-la avant d'enregistrer : une surface fausse fausse la jauge de charge.</li>\n      <li>La clôture exige le <b>matricule + PIN</b> de l'opérateur : c'est la signature de l'autocontrôle sur le PV envoyé à la Qualité.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> un résultat d'autocontrôle « Non conforme » <b>bloque</b> les pièces et ouvre une non-conformité côté Qualité. Ne clôturez en non conforme qu'après avoir vérifié vos mesures — la suite (dérogation, retouche, rebut) se traite dans le service Qualité.</div>\n    <div class=\"astuce\"><b>Astuce :</b> le bouton <b>« Demande d'achat »</b> en haut à droite de la bannière du service permet de demander un réapprovisionnement (chimiques, consommables…) sans quitter l'OAS : la demande est transmise directement au service Achats.</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 2 : RELEVÉ CONSOMMATION EAU ═══════════════ -->\n  <section class=\"tab\" id=\"tab-eau\">\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Relevé consommation eau</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Le traitement de surface consomme de l'eau (bains, rinçages) : cet onglet trace les relevés périodiques de consommation et de qualité de l'eau. C'est un suivi réglementaire — les relevés alimentent aussi les mesures environnementales (HSE) de l'entreprise.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Le sous-titre récapitule le nombre de relevés et le <b>volume total</b> consommé (en m³). Le tableau liste chaque relevé : Date · Opérateur · Volume · pH · Température · Turbidité · Chlore · Conformité (<span class=\"b b-ok\">✓ Conforme</span> ou <span class=\"b b-crit\">✗ NC</span>) · Observations. Le bouton <b>« Nouveau relevé »</b> ouvre le formulaire de saisie.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/oas-eau.png\" alt=\"Capture de l'onglet Relevé consommation eau\" loading=\"lazy\">\n      <figcaption><b>Relevé consommation eau</b> — l'historique des relevés avec le volume total en tête et le badge de conformité par ligne.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — saisir un relevé d'eau</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Nouveau relevé »</b> : la fenêtre « Relevé consommation d'eau » s'ouvre, la date du jour est préremplie.</li>\n      <li>Saisissez le <b>volume</b> relevé (en m³, 3 décimales possibles, ex. 1.250) puis les mesures disponibles : pH, température (°C), turbidité (NTU), chlore (mg/L). Tous ces champs sont facultatifs — ne saisissez que ce que vous avez mesuré.</li>\n      <li>Laissez la case <b>« Conforme aux seuils réglementaires »</b> cochée si tout est dans les seuils ; décochez-la sinon (le relevé apparaîtra <span class=\"b b-crit\">✗ NC</span> dans la liste).</li>\n      <li>Cliquez sur <b>« Enregistrer »</b>. Le relevé s'ajoute à l'historique ; si des mesures environnementales sont générées, la notification l'indique (« N mesure(s) HSE créée(s) »).</li>\n    </ol>\n\n    <h3>Le formulaire « Relevé consommation d'eau » en détail</h3>\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Date</td><td>Date</td><td>Oui</td><td>Préremplie à la date du jour.</td></tr>\n          <tr><td>Volume (m³)</td><td>Nombre (3 décimales)</td><td>Non</td><td>Volume d'eau consommé sur la période relevée ; s'additionne dans le volume total de l'onglet.</td></tr>\n          <tr><td>pH</td><td>Nombre</td><td>Non</td><td>pH de l'eau mesurée.</td></tr>\n          <tr><td>Température (°C)</td><td>Nombre</td><td>Non</td><td>Température de l'eau.</td></tr>\n          <tr><td>Turbidité (NTU)</td><td>Nombre</td><td>Non</td><td>Trouble de l'eau, en unités NTU.</td></tr>\n          <tr><td>Chlore (mg/L)</td><td>Nombre</td><td>Non</td><td>Teneur en chlore.</td></tr>\n          <tr><td>Observations</td><td>Texte libre</td><td>Non</td><td>Remarques (origine d'un écart, intervention…).</td></tr>\n          <tr><td>Conforme aux seuils réglementaires</td><td>Case à cocher</td><td>—</td><td>Cochée par défaut ; décochez si une mesure sort des seuils.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-oas-eau.png\" alt=\"Formulaire de relevé de consommation d'eau\" loading=\"lazy\">\n      <figcaption><b>Relevé d'eau</b> — la date est préremplie ; seuls les champs mesurés doivent être renseignés.</figcaption>\n    </figure>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>La colonne Opérateur affiche l'auteur du relevé quand il est connu ; les champs non mesurés restent affichés « — » dans la liste.</li>\n      <li>Le volume total affiché en tête d'onglet est la somme de tous les relevés listés : il alimente aussi la tuile « Eau consommée » du Dashboard OAS.</li>\n    </ul>\n    <div class=\"note\"><b>Bon à savoir :</b> les relevés d'eau peuvent générer automatiquement des <b>mesures HSE</b> exploitées par les services Sécurité et Environnement — d'où l'importance de saisir des valeurs exactes et datées.</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 3 : RELEVÉS PÉRIODIQUES BAINS ═══════════════ -->\n  <section class=\"tab\" id=\"tab-bains\">\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>Relevés périodiques bains</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La qualité du traitement OAS dépend directement de la chimie des bains. Cet onglet trace les contrôles périodiques des cinq bains de la ligne (Principal OAS, Bain de lavage, Rinçage 1, Rinçage 2, Neutralisation) : pH, température, concentration, titrages… C'est le point de vigilance n° 1 du service : <b>un bain déclaré non conforme ouvre automatiquement une non-conformité dans le service Qualité</b>.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Le sous-titre affiche le nombre de relevés et l'état global : <span class=\"b b-ok\">Tous conformes</span> en vert, ou le nombre de relevés <span class=\"b b-crit\">hors seuil</span> en rouge. Le tableau (avec défilement horizontal) liste chaque relevé : Date · Bain (badge coloré par bain) · pH · Température · Concentration (g/L) · Densité · Titrage H₂SO₄ · Titrage Al · Conductivité · Conformité · Observations. Le bouton <b>« Nouveau relevé »</b> ouvre le formulaire.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/oas-bains.png\" alt=\"Capture de l'onglet Relevés périodiques bains\" loading=\"lazy\">\n      <figcaption><b>Relevés périodiques bains</b> — un badge de couleur par bain, les mesures chimiques colonne par colonne et le badge de conformité en bout de ligne.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — saisir un relevé de bain</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Nouveau relevé »</b> : la fenêtre « Relevé périodique bain » s'ouvre, la date du jour est préremplie.</li>\n      <li>Choisissez le <b>bain</b> contrôlé (Principal OAS, Bain de lavage, Rinçage 1, Rinçage 2 ou Neutralisation).</li>\n      <li>Saisissez les mesures réalisées : pH, température (°C), concentration (g/L), densité, titrage H₂SO₄ (g/L), titrage Al (g/L), conductivité (mS/cm). Tous ces champs sont facultatifs — renseignez ce que votre contrôle a couvert.</li>\n      <li>Statuez sur la conformité : laissez la case <b>« Conforme »</b> cochée si le bain est dans les tolérances ; <b>décochez-la</b> si une mesure sort des seuils, et expliquez l'écart dans Observations.</li>\n      <li>Cliquez sur <b>« Enregistrer »</b>. Si le bain est conforme, le relevé s'ajoute simplement à l'historique. S'il est <b>non conforme</b>, une notification orange vous prévient : « Bain … non conforme : NC ouverte côté Qualité » — la non-conformité est créée automatiquement et sera traitée par le service Qualité.</li>\n    </ol>\n\n    <h3>Le formulaire « Relevé périodique bain » en détail</h3>\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Date</td><td>Date</td><td>Oui</td><td>Préremplie à la date du jour.</td></tr>\n          <tr><td>Bain</td><td>Liste déroulante</td><td>Oui</td><td>Principal OAS · Bain de lavage · Rinçage 1 · Rinçage 2 · Neutralisation.</td></tr>\n          <tr><td>pH</td><td>Nombre</td><td>Non</td><td>Pour le bain principal, la tolérance de référence est pH 0.7 – 1.1 (visible sur le Dashboard OAS).</td></tr>\n          <tr><td>Température (°C)</td><td>Nombre</td><td>Non</td><td>Température du bain.</td></tr>\n          <tr><td>Concentration (g/L)</td><td>Nombre</td><td>Non</td><td>Concentration du bain (référence bain principal : 180 g/L de H₂SO₄).</td></tr>\n          <tr><td>Densité</td><td>Nombre (3 décimales)</td><td>Non</td><td>Densité mesurée du bain.</td></tr>\n          <tr><td>Titrage H₂SO₄ (g/L)</td><td>Nombre</td><td>Non</td><td>Résultat du titrage acide.</td></tr>\n          <tr><td>Titrage Al (g/L)</td><td>Nombre</td><td>Non</td><td>Teneur en aluminium dissous.</td></tr>\n          <tr><td>Conductivité (mS/cm)</td><td>Nombre</td><td>Non</td><td>Conductivité du bain.</td></tr>\n          <tr><td>Conforme</td><td>Case à cocher</td><td>—</td><td>Cochée par défaut. <b>Décochée = NC créée automatiquement en Qualité.</b></td></tr>\n          <tr><td>Observations</td><td>Texte libre</td><td>Non</td><td>Écart constaté, action réalisée (ajout, dilution…).</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-oas-bain.png\" alt=\"Formulaire de relevé périodique de bain\" loading=\"lazy\">\n      <figcaption><b>Relevé de bain</b> — les mesures chimiques et la case « Conforme » : c'est elle qui déclenche (ou non) la NC automatique.</figcaption>\n    </figure>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Un relevé par bain et par échéance : c'est le <b>dernier relevé de chaque bain</b> qui fait l'état de référence affiché sur le Dashboard OAS.</li>\n      <li>La conformité est déclarée par l'opérateur (case à cocher) : comparez vos mesures aux tolérances de la gamme avant de statuer.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> décocher « Conforme » ouvre <b>immédiatement et automatiquement</b> une non-conformité dans le service Qualité. C'est le comportement voulu (traçabilité EN 9100) — ne « corrigez » jamais un relevé en le déclarant conforme à tort pour éviter la NC.</div>\n    <div class=\"astuce\"><b>Astuce :</b> consultez l'évolution du pH du bain principal sur le <a href=\"#tab-dashboard\">Dashboard OAS</a> avant de lancer une session : une dérive lente se voit mieux sur la courbe des derniers relevés que sur une mesure isolée.</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 4 : DASHBOARD OAS ═══════════════ -->\n  <section class=\"tab\" id=\"tab-dashboard\">\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Dashboard OAS</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Vue d'ensemble en temps réel de l'activité du traitement de surface : sessions, conformité, lots en cours, consommation d'eau et état des bains. C'est l'écran à consulter en début de poste pour savoir où en est la ligne avant de charger une balancelle.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Cinq tuiles d'indicateurs en haut de page :</p>\n    <ul class=\"points\">\n      <li><b>Sessions totales</b> — nombre de balancelles enregistrées, avec le nombre en cours.</li>\n      <li><b>Taux conformité</b> — pourcentage de sessions terminées conformes (le sous-texte détaille « X NC sur Y » sessions terminées).</li>\n      <li><b>Lots actifs à l'OAS</b> — lots en cours de traitement, avec le nombre de lots terminés.</li>\n      <li><b>Eau consommée (période)</b> — volume total en m³ et nombre de relevés.</li>\n      <li><b>État des bains</b> — « OK » en vert si tous les relevés sont conformes, sinon le nombre de relevés NC en rouge ; le sous-texte rappelle le dernier pH du bain principal.</li>\n    </ul>\n    <p>En dessous, deux blocs côte à côte : le graphique <b>« Évolution pH — Bain Principal OAS »</b> (les 5 derniers relevés en barres, vertes dans la tolérance pH 0.7 – 1.1, rouges en dehors — référence H₂SO₄ 180 g/L) et le tableau <b>« Dernier état des bains »</b> (Bain · Dernier relevé · pH · Température · État) qui récapitule le dernier relevé de chacun des cinq bains.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/oas-dashboard.png\" alt=\"Capture du Dashboard OAS\" loading=\"lazy\">\n      <figcaption><b>Dashboard OAS</b> — les 5 tuiles d'indicateurs, l'évolution du pH du bain principal et le dernier état de chaque bain.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — le réflexe de début de poste</h3>\n    <ol class=\"steps\">\n      <li>Ouvrez le <b>Dashboard OAS</b> et vérifiez la tuile <b>État des bains</b> : si elle affiche des NC, traitez d'abord la chimie (voir onglet <a href=\"#tab-bains\">Relevés périodiques bains</a>) avant de charger des pièces.</li>\n      <li>Contrôlez la courbe de <b>pH du bain principal</b> : une barre rouge ou une dérive vers les bornes 0.7 / 1.1 appelle un nouveau relevé, voire un ajustement du bain.</li>\n      <li>Regardez <b>Lots actifs à l'OAS</b> puis passez à l'onglet <a href=\"#tab-lots-balancelles\">Lots &amp; Balancelles</a> pour composer vos balancelles de la journée.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Tous les indicateurs sont calculés en direct à partir des trois onglets précédents : un relevé ou une clôture saisis apparaissent immédiatement ici.</li>\n      <li>Le taux de conformité ne compte que les <b>sessions terminées</b> : les balancelles en cours n'y entrent pas encore.</li>\n    </ul>\n    <div class=\"note\"><b>Bon à savoir :</b> un tableau de bord OAS plus complet (avec filtres et export) existe aussi dans le service <b>Tableaux de bord → Dashboard OAS</b>, accessible aux autres services en lecture.</div>\n  </section>\n\n  <div class=\"docnav\">\n    <a href=\"index.html\">← Sommaire des manuels</a>\n    <a href=\"qualite.html\">Manuel suivant : Qualité →</a>\n  </div>\n\n  <footer class=\"doc\">\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\n  </footer>\n\n</div>\n</body>\n</html>\n",
  "plans": "<!doctype html>\r\n<html lang=\"fr\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>Manuel — Plan / Bâtiment · ERP Seem Semrac</title>\r\n<link rel=\"stylesheet\" href=\"manuel.css\">\r\n</head>\r\n<body>\r\n<div class=\"wrap\">\r\n\r\n  <header class=\"doc\">\r\n    <div class=\"brandrow\">\r\n      <div class=\"logo\">SS</div>\r\n      <div>\r\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\r\n        <div class=\"eyebrow\">Manuel utilisateur</div>\r\n      </div>\r\n      <div class=\"kind\">docs/manuel/html</div>\r\n    </div>\r\n    <h1>Service <span class=\"hi\">Plan / Bâtiment</span></h1>\r\n    <p class=\"lede\">Le service Plan / Bâtiment est la <b>maquette interactive de l'usine</b> : on charge une image du plan des locaux, on y dessine les <b>zones</b> (rectangles : atelier, bureaux, magasin, zone ATEX…), puis on y pose des <b>objets</b> (postes de travail, produits chimiques, périssables, extincteurs) que l'on relie aux fiches déjà saisies dans les autres services. Résultat : une vue « où se trouve quoi » qui se colore toute seule quand une vérification est en retard ou qu'un produit périme. Ce manuel décrit l'unique onglet du service, écran par écran.</p>\r\n    <div class=\"metachips\">\r\n      <span class=\"chip\">👤 Pour qui : <b>Bureau d'Études, Production, Maintenance, Qualité, Direction</b> (écriture) · lecture pour tout utilisateur connecté</span>\r\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Plan / Bâtiment</b></span>\r\n      <span class=\"chip\">🗂 <b>1 onglet</b></span>\r\n    </div>\r\n  </header>\r\n\r\n  <nav class=\"toc\">\r\n    <div class=\"toc-t\">Sommaire</div>\r\n    <ol>\r\n      <li><a href=\"#tab-plan\">Maquette</a></li>\r\n    </ol>\r\n  </nav>\r\n\r\n  <!-- ══════════════ 1. MAQUETTE ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-plan\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Maquette</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> L'ERP sait <i>ce que</i> l'on possède (postes, produits chimiques, extincteurs, périssables) mais pas <i>où</i> cela se trouve dans le bâtiment. Cet onglet répond à cette question : il superpose au plan des locaux des repères reliés aux vraies fiches de l'ERP. On s'en sert pour préparer un accueil sécurité ou une visite d'auditeur (« montrez-moi vos zones ATEX, vos extincteurs, vos stockages de produits chimiques »), pour situer un poste avant une intervention de maintenance, et pour repérer d'un coup d'œil ce qui est en retard : un extincteur dont la vérification périodique est dépassée ou un produit périmé devient rouge sur le plan.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>La page est organisée en trois bandes. En <b>haut</b>, la barre de plan : une liste déroulante <b>« — Choisir un plan — »</b>, le bouton <b>« Nouveau plan »</b>, et à droite le bouton bleu <b>« Modifier »</b> (qui devient <b>« Aperçu »</b> une fois activé) accompagné de <b>« Annuler »</b> et du bouton vert <b>« Enregistrer »</b>. Au <b>centre à gauche</b>, la visionneuse du plan avec sa propre petite barre d'outils : <b>−</b> / <b>+</b> pour le zoom, <b>« Ajuster »</b> pour revenir à 100&nbsp;%, le pourcentage courant, et le bouton <b>« Vue risque chimique »</b>. À <b>droite</b>, trois panneaux empilés : <b>Catégories</b>, <b>Élément</b> (n'apparaît que lorsqu'un repère est sélectionné) et <b>Par zone</b>.</p>\r\n    <ul class=\"points\">\r\n      <li>Le panneau <b>Catégories</b> est le <b>catalogue de ce qui est plaçable</b>. Chaque ligne porte une <b>icône œil</b> (afficher / masquer sur le plan), la pastille de couleur — <b>carrée</b> pour une zone, <b>ronde</b> pour un objet —, le libellé, et un compteur <b>« posés / catalogue »</b> : « 4 / 12 » signifie que 4 fiches sont posées sur ce plan alors que l'ERP en contient 12 de ce type. <b>Cliquez le libellé</b> pour dérouler la liste : chaque fiche de l'ERP y apparaît, avec <span class=\"b b-ok\">✓</span> si elle est déjà posée (cliquez-la pour la localiser) ou <b>+</b> si elle reste à poser. Un champ <b>« Rechercher dans les catalogues… »</b> filtre l'ensemble d'un coup.</li>\r\n      <li><b>Trois catalogues de zone</b> (tracées en rectangle) : <b>Poste de travail</b> (la zone porte ses process et ses machines) · <b>Zone atelier (EPI)</b> — le zonage Z1–Z7 / A qui porte la matrice des EPI obligatoires · <b>Zone ATEX</b>.</li>\r\n      <li><b>Six catalogues d'objet</b> (posés en épingle) : <b>Machine</b> · <b>Produit chimique / FDS</b> · <b>Produit périssable</b> · <b>Équipement de mesure (ECME)</b> · <b>Équipement de sécurité (VGP)</b> · <b>Point de collecte déchets</b>.</li>\r\n      <li><b>Hors catalogue</b> — un bloc ambré en bas du panneau regroupe les anciens tracés faits à la main, sans fiche correspondante dans l'ERP. Ils restent affichés mais ne sont plus créables ; le fond de plan porte déjà les noms de salles.</li>\r\n      <li>Le panneau <b>Par zone</b> affiche le nombre total d'éléments entre parenthèses, puis la liste <b>groupée par rectangle</b> : chaque zone est suivie des objets qu'elle contient et de leur compte (« 3 obj. »). Les objets posés en dehors de tout rectangle sont regroupés en bas sous <b>Hors zone</b>. Si des repères sont en défaut, deux bandeaux de synthèse s'affichent en tête de liste : <span class=\"b b-crit\">● N alerte(s)</span> et <span class=\"b b-warn\">● N à surveiller</span>.</li>\r\n      <li>Les repères se colorent <b>tout seuls</b> d'après les dates et statuts des fiches liées : <span class=\"b b-ok\">à jour</span> (vert) · <span class=\"b b-warn\">à surveiller</span> (orange) · <span class=\"b b-crit\">alerte</span> (rouge). Une zone en alerte prend un <b>contour en pointillés</b>, un objet en alerte prend un <b>halo</b> et une petite pastille de couleur en haut à droite de son épingle.</li>\r\n      <li>Détail des états calculés : pour un repère <b>Sécurité</b>, « VGP à jour », « VGP à prévoir (Xj) » à 30 jours ou moins de l'échéance, « VGP en retard (Xj) » au-delà. Pour un <b>Produit périssable</b>, « Valide », « Périme dans Xj » à 30 jours ou moins, « Périmé depuis le … ». Pour une <b>Zone ATEX</b>, « À jour », « Revue ATEX proche (Xj) » à 60 jours ou moins, « Revue ATEX en retard ».</li>\r\n      <li>Tant qu'aucun plan n'est choisi, la visionneuse affiche <b>« Choisissez un plan pour l'afficher. »</b> ; si le plan existe mais n'a pas encore d'image de fond, le message devient <b>« Aucune image. « Modifier » puis chargez le plan. »</b>.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/plans-maquette.png\" alt=\"Capture de l'onglet Maquette du service Plan / Bâtiment\" loading=\"lazy\">\r\n      <figcaption><b>Maquette</b> — à gauche le plan avec ses rectangles de zones et ses épingles d'objets ; à droite le panneau Catégories (légende + filtres + compteurs « posés / catalogue ») et le panneau Par zone qui range chaque objet dans le local qui le contient.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — créer un plan et charger le fond</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouveau plan »</b>. Une petite fenêtre demande <b>« Nom du plan : »</b> — saisissez par exemple le nom du bâtiment ou du niveau, puis validez. Le plan est créé et automatiquement sélectionné dans la liste déroulante.</li>\r\n      <li>Cliquez sur <b>« Modifier »</b> : une barre grise <b>« Fond »</b> apparaît sous la barre de plan.</li>\r\n      <li>Dans cette barre, cliquez sur <b>« Parcourir »</b> et choisissez le fichier image de votre plan, puis cliquez sur <b>« Remplacer l'image »</b>. Le message « Envoi… » puis <b>« Image mise à jour. »</b> confirment l'opération, et le plan s'affiche immédiatement dans la visionneuse.</li>\r\n      <li>Réglez le confort de lecture avec <b>+</b> / <b>−</b> (par pas de 25&nbsp;%, jusqu'à 400&nbsp;%) et faites glisser le fond avec la souris pour vous déplacer dans le plan agrandi. Le bouton <b>« Ajuster »</b> ramène à 100&nbsp;%.</li>\r\n      <li>Pour revenir sur un plan existant plus tard, il suffit de le rappeler par la liste déroulante en haut à gauche : ses repères sont rechargés automatiquement.</li>\r\n    </ol>\r\n    <div class=\"warn\"><b>Attention :</b> le fond de plan doit être une <b>image</b> — les formats acceptés sont PNG, JPG, JPEG, WEBP, GIF et SVG. Un <b>PDF n'est pas accepté</b> : si votre plan vient de l'architecte au format PDF, exportez-le d'abord en PNG ou JPG (une seule page, la plus lisible possible) avant de le charger ici.</div>\r\n    <div class=\"note\"><b>Bon à savoir :</b> l'image du plan est rangée dans la GED de l'ERP, exactement comme un plan de pièce ou un document technique. Elle reste donc disponible et versionnable indépendamment de la maquette.</div>\r\n\r\n    <h3>Pas à pas — dessiner une zone (un local)</h3>\r\n    <p>Les zones sont la <b>charpente</b> de la maquette : ce sont elles qui donnent un sens aux objets, puisqu'un objet est automatiquement rattaché au rectangle dans lequel il tombe. Commencez donc toujours par les zones.</p>\r\n    <ol class=\"steps\">\r\n      <li>Assurez-vous d'être en mode <b>Modifier</b> (le bouton bleu affiche « Aperçu » et la barre « Fond » est visible).</li>\r\n      <li>Dans le panneau <b>Catégories</b>, dépliez le catalogue voulu — <b>Poste de travail</b>, <b>Zone atelier (EPI)</b> ou <b>Zone ATEX</b> — puis <b>cliquez la fiche</b> à placer (par exemple le poste « Poinçonnage »). Un message apparaît : <b>« → glissez sur le plan pour dessiner la zone : Poinçonnage »</b>.</li>\r\n      <li><b>Glissez</b> la souris sur le plan pour tracer le rectangle du local, d'un coin à l'autre. Un cadre en pointillés suit votre geste ; relâchez pour valider.</li>\r\n      <li>Le rectangle apparaît <b>déjà nommé et déjà relié</b> à la fiche choisie — il n'y a rien à saisir. Le panneau <b>Élément</b> s'ouvre à droite pour la note de placement et le lien vers la fiche d'origine.</li>\r\n      <li>Pour <b>redimensionner</b> une zone, tirez la petite poignée blanche située à son <b>coin bas-droite</b>. Pour la <b>déplacer</b>, faites glisser le rectangle lui-même.</li>\r\n      <li>Quand vos zones sont posées, cliquez <b>« Enregistrer »</b>. Le message confirme le nombre d'éléments sauvegardés et la page repasse en consultation.</li>\r\n    </ol>\r\n    <div class=\"note\"><b>À noter :</b> un rectangle trop petit (moins de 2&nbsp;% du plan en largeur ou en hauteur) est ignoré — c'est une sécurité contre les clics involontaires. Si votre zone ne se crée pas, refaites le geste en tirant plus largement.</div>\r\n\r\n    <h3>Pas à pas — poser un objet</h3>\r\n    <ol class=\"steps\">\r\n      <li>Toujours en mode <b>Modifier</b>, dépliez un catalogue d'objet — par exemple <b>Machine</b>, <b>Produit chimique / FDS</b> ou <b>Équipement de mesure (ECME)</b> — et <b>cliquez la fiche</b> à poser. Le message devient <b>« → cliquez le plan pour poser : &lt;nom de la fiche&gt; »</b>.</li>\r\n      <li><b>Cliquez</b> (un simple clic, sans glisser) à l'endroit exact du plan où se trouve l'objet, de préférence <b>à l'intérieur d'un rectangle de zone</b>. L'épingle se pose et le panneau <b>Élément</b> s'ouvre.</li>\r\n      <li>En haut de ce panneau, une ligne rappelle le rattachement : <b>« Zone : &lt;nom du local&gt; (auto) »</b> sur fond vert si l'épingle est bien dans un rectangle, ou <b>« Zone : hors zone — déplacez le repère dans un rectangle »</b> sur fond orange sinon.</li>\r\n      <li>Le repère est <b>déjà relié</b> à sa fiche : vous n'avez rien à saisir. C'est cette liaison qui le fait vivre — elle apporte son <b>état en direct</b> (péremption, échéance VGP, revue ATEX, niveau de risque chimique) et le bouton d'ouverture de la fiche dans son service.</li>\r\n      <li>Ajoutez si besoin une <b>note de placement</b> (« contre le mur nord »…), puis cliquez <b>« Appliquer »</b>. Le message <b>« Appliqué — pensez à Enregistrer. »</b> vous rappelle que rien n'est encore sauvegardé.</li>\r\n      <li>Pour <b>déplacer</b> une épingle, faites-la simplement glisser : son rattachement à la zone est recalculé en direct. Pour la <b>supprimer</b>, utilisez la croix rouge en bout de ligne dans le panneau <b>Par zone</b>, ou le bouton <b>« Supprimer »</b> du panneau Élément.</li>\r\n      <li>Terminez par <b>« Enregistrer »</b>. Le bouton <b>« Annuler »</b>, lui, abandonne toutes les modifications en cours et recharge la maquette telle qu'elle était en base.</li>\r\n    </ol>\r\n\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td>Zone (rappel)</td><td>Affichage seul</td><td>—</td><td>Uniquement pour un objet. Indique le rectangle qui le contient, calculé automatiquement d'après sa position. Vert = rangé dans une zone, orange = hors zone.</td></tr>\r\n        <tr><td>Fiche liée</td><td>Affichage seul</td><td>—</td><td>Le repère <b>est</b> une fiche de l'ERP posée sur le plan. Son nom, sa catégorie et ses données viennent de cette fiche : pour les changer, ouvrez-la dans son service via le lien fourni.</td></tr>\r\n        <tr><td>Lien vers le service</td><td>Bouton</td><td>—</td><td>Ouvre la fiche d'origine (poste, machine, produit chimique, périssable, ECME, zone ATEX, vérification VGP, déchet). C'est <b>là</b> que se modifient le nom et les données ; le plan ne fait que les <b>situer</b>.</td></tr>\r\n        \r\n        \r\n        \r\n        <tr><td>Note de placement</td><td>Texte</td><td>Non</td><td>Commentaire libre (consigne d'accès, précision d'emplacement…). Il s'affiche dans le panneau Élément lorsqu'on clique le repère en consultation.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-plans-editeur.png\" alt=\"Panneau Élément : édition d'un repère de la maquette\" loading=\"lazy\">\r\n      <figcaption><b>Panneau « Élément »</b> — la fiche liée en haut, le rappel de zone, le lien vers son service et la note de placement ; les boutons « Appliquer » et « Retirer du plan » en bas. Aucun libellé libre : le nom vient de la fiche.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Créer une zone ATEX ou un extincteur sans quitter le plan</h3>\r\n    <p><b>On ne crée rien depuis le plan.</b> Si une fiche manque au catalogue — une zone ATEX, un extincteur, un produit chimique —, elle se crée dans <b>son service</b> (Sécurité, Qualité, Production, Environnement), puis elle apparaît aussitôt dans le catalogue, prête à être posée. Le plan répond à la question « <em>où est-ce ?</em> », jamais à « <em>qu'est-ce que c'est ?</em> ».</p>\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Repère</th><th>Champ</th><th>Saisie</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td rowspan=\"3\">Zone ATEX</td><td>Nom de la zone ATEX *</td><td>Texte</td><td>Nom qui identifiera la zone dans le service Sécurité.</td></tr>\r\n        <tr><td>Type de zone</td><td>Liste : 0 · 1 · 2 · 20 · 21 · 22</td><td>Zonage réglementaire (gaz 0/1/2, poussières 20/21/22). Il détermine aussi la sévérité affichée en vue Risque chimique.</td></tr>\r\n        <tr><td>Localisation</td><td>Texte</td><td>Emplacement en clair.</td></tr>\r\n        <tr><td rowspan=\"3\">Sécurité (extincteur…)</td><td>Équipement *</td><td>Texte</td><td>Désignation de l'équipement à vérifier, par exemple « Extincteur hall A ».</td></tr>\r\n        <tr><td>Type de vérification</td><td>Liste</td><td>Incendie / extincteur · Levage · Électrique · ESP (sous pression) · Portes / portails · Racks · Ventilation · ATEX.</td></tr>\r\n        <tr><td>Organisme de contrôle</td><td>Texte</td><td>Organisme agréé qui réalise la vérification périodique.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n    <ol class=\"steps\">\r\n      <li>Renseignez le formulaire puis cliquez <b>« Créer &amp; relier »</b> (ou <b>« Annuler »</b> pour renoncer).</li>\r\n      <li>Le message <b>« Créé dans Sécurité et relié au repère. Pensez à Enregistrer le plan. »</b> confirme : la fiche existe désormais dans le service <b>Sécurité</b> et le repère lui est rattaché, libellé compris.</li>\r\n      <li>Cliquez <b>« Enregistrer »</b> pour figer la maquette.</li>\r\n    </ol>\r\n    <div class=\"note\"><b>Enchaînement :</b> la fiche ainsi créée est une vraie fiche du service Sécurité. Il faut ensuite y compléter les dates (échéance de vérification, date de revue ATEX) depuis le service Sécurité — c'est ce qui permettra au repère de passer en orange puis en rouge le moment venu.</div>\r\n\r\n    <h3>Pas à pas — pré-remplir la maquette avec « Auto-placer »</h3>\r\n    <p>Poser un à un plusieurs dizaines de repères serait fastidieux. Le bouton <b>« Auto-placer »</b> (barre d'édition, en mode Modifier) fait le gros du travail : il compare le <b>nom de vos zones</b> à la <b>localisation déjà renseignée en base</b> pour les postes de travail, les produits périssables et les produits chimiques, et pose automatiquement les repères correspondants dans le bon rectangle.</p>\r\n    <ol class=\"steps\">\r\n      <li>Dessinez et nommez d'abord vos zones — sans rectangle, l'outil refuse et affiche <b>« Dessinez d'abord des zones (rectangles). »</b>. Donnez-leur des noms proches de ceux utilisés en base (par exemple « Oxydation », « Magasin », « Tôlerie »).</li>\r\n      <li>Cliquez <b>« Auto-placer »</b>. Une demande de confirmation récapitule ce qui va être posé, catégorie par catégorie, et combien d'éléments seront ignorés faute de zone correspondante.</li>\r\n      <li>Confirmez : les repères sont disposés en grille à l'intérieur de chaque zone, et le message final indique <b>« Placés : N · ignorés : M. Vérifiez puis Enregistrez. »</b>.</li>\r\n      <li><b>Vérifiez</b> visuellement, déplacez les épingles à leur emplacement réel, puis cliquez <b>« Enregistrer »</b>.</li>\r\n    </ol>\r\n    <ul class=\"points\">\r\n      <li>L'outil ne crée <b>jamais de doublon</b> : un élément déjà posé sur ce plan est ignoré.</li>\r\n      <li>Les produits périssables <b>archivés</b> et les produits chimiques <b>retirés</b> ne sont pas placés — la maquette ne montre que ce qui est réellement en service.</li>\r\n      <li>Les éléments dont la localisation en base ne correspond à aucune de vos zones sont simplement comptés comme « ignorés » : à vous de les poser à la main, ou de renommer la zone pour qu'elle corresponde.</li>\r\n      <li>Si vous cliquez « Auto-placer » hors du mode Modifier, l'ERP répond <b>« Passez d'abord en Modifier. »</b>.</li>\r\n    </ul>\r\n\r\n    <h3>La vue « Risque chimique » (SEIRICH)</h3>\r\n    <p>Le bouton <b>« Vue risque chimique »</b>, dans la barre d'outils de la visionneuse, bascule le plan en <b>carte du risque chimique de l'usine</b>. Seuls les repères <b>Chimie / FDS</b> et <b>Zone ATEX</b> restent colorés — par leur niveau de risque — sur fond des rectangles de zones ; le panneau Catégories est remplacé par une légende qui compte les repères de chaque niveau.</p>\r\n    <ul class=\"points\">\r\n      <li>Quatre niveaux, du plus grave au plus léger : <span class=\"b b-crit\">Élevé</span> · <span class=\"b b-warn\">Moyen</span> · <span class=\"b b-ok\">Faible</span> · <span class=\"b b-mut\">—</span> (non évalué).</li>\r\n      <li>Un repère chimique dont l'étiquetage est incomplet s'affiche avec un <b>point d'interrogation</b>. <b>Ne le lisez pas comme « sans risque »</b> : c'est une fiche à compléter dans le service Sécurité.</li>\r\n      <li>La cotation est <b>indicative</b>, calculée à partir des mentions de danger et des situations d'exposition. Elle ne remplace pas un mesurage ni l'avis d'un préventeur.</li>\r\n      <li>Un clic sur un repère chimique ouvre directement sa <b>fiche produit 360</b> ; un clic sur une zone ATEX ouvre la zone dans le service Environnement.</li>\r\n      <li>La vue est réservée à la <b>consultation</b> : le bouton disparaît en mode Modifier, et passer en Modifier la désactive automatiquement.</li>\r\n    </ul>\r\n\r\n    <h3>Consulter la maquette au quotidien</h3>\r\n    <p>Hors mode Modifier, la maquette est un outil de navigation : elle vous emmène vers la bonne fiche dans le bon service.</p>\r\n    <ol class=\"steps\">\r\n      <li>Choisissez le plan dans la liste déroulante ; les repères se chargent et se colorent selon leur état.</li>\r\n      <li>Utilisez les <b>icônes œil</b> du panneau Catégories pour ne garder à l'écran que ce qui vous intéresse (par exemple uniquement « Sécurité (extincteur…) » avant une ronde incendie).</li>\r\n      <li><b>Survolez</b> un repère <b>Poste de travail</b> : une infobulle noire détaille le poste — la liste de ses <b>process</b>, la liste de ses <b>machines</b>, son <b>taux effectif en €/h</b> et son <b>OPEX théorique en €/an</b>.</li>\r\n      <li><b>Cliquez</b> un repère : le panneau <b>Élément</b> affiche son libellé, sa catégorie, la zone qui le contient, l'élément lié, la pastille d'état (« VGP en retard », « Périme dans 12j »…) et vos notes.</li>\r\n      <li>Cliquez le bouton violet en bas du panneau pour ouvrir la fiche correspondante dans son service : <b>« Ouvrir « Postes &amp; Process » »</b> (Production), <b>« Ouvrir la vérification (VGP) »</b> et <b>« Ouvrir la matrice EPI de la zone »</b> (Sécurité), <b>« Ouvrir la zone ATEX »</b> (Environnement), <b>« Ouvrir la fiche produit chimique 360 »</b> (Sécurité).</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li><b>Rien n'est enregistré tant que vous n'avez pas cliqué « Enregistrer ».</b> « Appliquer » ne fait que valider la saisie du panneau Élément à l'écran — le message le rappelle d'ailleurs à chaque fois.</li>\r\n      <li>Le <b>rattachement objet → zone est toujours automatique</b> et jamais saisi à la main : il découle de la position de l'épingle. Si un objet apparaît « Hors zone » dans la liste de droite, c'est qu'il est tombé à côté du rectangle — déplacez-le.</li>\r\n      <li>Quand deux rectangles se chevauchent, l'objet est rattaché au <b>plus petit</b> des deux : dessinez donc les grands ensembles d'abord, puis les locaux à l'intérieur.</li>\r\n      <li>Un repère non relié à une fiche reste <b>gris et muet</b> : pas d'état, pas d'infobulle, pas de lien. La valeur de la maquette vient de la liaison, pas du dessin.</li>\r\n      <li>Les <b>couleurs d'état ne se saisissent pas</b> : elles sont recalculées à chaque affichage à partir des dates réelles des fiches (échéance de vérification, date d'expiration, date de revue ATEX). Un repère qui reste vert alors que vous l'attendiez rouge signale une <b>date manquante ou fausse dans la fiche source</b>, pas un bug du plan.</li>\r\n      <li>Le compteur « posés / catalogue » du panneau Catégories est votre indicateur de complétude : tant que l'écart est grand, la maquette ne couvre qu'une partie du parc réel.</li>\r\n      <li>Les zones de la catégorie <b>Atelier / Process</b> peuvent être reliées au référentiel des zones d'atelier (Z1 à Z7 et l'allée piétonne A) : c'est ce qui permet d'ouvrir directement la <b>matrice EPI</b> de la zone depuis le plan.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> « Annuler » abandonne <b>toutes</b> les modifications faites depuis le passage en mode Modifier — zones dessinées, objets posés, liaisons et suppressions comprises — et recharge la maquette telle qu'elle est en base. Il n'y a pas de retour en arrière après ce clic.</div>\r\n    <div class=\"astuce\"><b>Astuce :</b> la bonne séquence de mise en place est toujours la même — <b>charger le fond → dessiner et nommer les zones → Enregistrer → Auto-placer → corriger les positions → Enregistrer</b>. En enregistrant après les zones, vous sécurisez la charpente du plan avant de lancer le remplissage automatique.</div>\r\n    <div class=\"note\"><b>Bon à savoir :</b> plusieurs plans peuvent coexister (un par bâtiment ou par niveau), chacun avec sa propre image de fond et ses propres repères. Un même poste ou un même extincteur peut être posé sur plusieurs plans si nécessaire.</div>\r\n  </section>\r\n\r\n  <div class=\"docnav\">\r\n    <a href=\"index.html\">← Sommaire des manuels</a>\r\n    <a href=\"direction.html\">Manuel suivant : Direction →</a>\r\n  </div>\r\n\r\n  <footer class=\"doc\">\r\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\r\n  </footer>\r\n\r\n</div>\r\n</body>\r\n</html>\r\n",
  "production": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Manuel — Production · ERP Seem Semrac</title>\n<link rel=\"stylesheet\" href=\"manuel.css\">\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header class=\"doc\">\n    <div class=\"brandrow\">\n      <div class=\"logo\">SS</div>\n      <div>\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\n        <div class=\"eyebrow\">Manuel utilisateur</div>\n      </div>\n      <div class=\"kind\">docs/manuel/html</div>\n    </div>\n    <h1>Service <span class=\"hi\">Production</span></h1>\n    <p class=\"lede\">La Production planifie la fabrication et en trace l'exécution : les commandes clients sont découpées en lots, chaque lot en BDT (bons de travail, réalisés à l'atelier) et en BST/BDS (bons de sous-traitance, envoyés chez un prestataire). Un <b>planning unique</b> (page « Production », par poste de travail) porte les deux Gantt — <b>BDT</b> à l'atelier et <b>BST</b> chez les sous-traitants — ainsi que l'affectation des opérateurs aux postes par créneau. Ce manuel le couvre, plus la présence, les commandes &amp; lots, les postes/machines et les deux dashboards.</p>\n    <div class=\"metachips\">\n      <span class=\"chip\">👤 Pour qui : <b>Programmation (Sylvie) · chefs d'atelier · opérateurs</b></span>\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Production</b></span>\n      <span class=\"chip\">🗂 <b>7 onglets</b></span>\n    </div>\n  </header>\n\n  <nav class=\"toc\">\n    <div class=\"toc-t\">Sommaire</div>\n    <ol>\n      <li><a href=\"#tab-gantt-bdt\">Planning Gantt BDT</a></li>\n      <li><a href=\"#tab-gantt-bst\">Planning Gantt BST (sous-traitance)</a></li>\n      <li><a href=\"#tab-presence\">Présence opérateurs</a></li>\n      <li><a href=\"#tab-commandes\">Commandes &amp; Lots</a></li>\n      <li><a href=\"#tab-machines\">Process Ateliers (machines + postes &amp; process)</a></li>\n      <li><a href=\"#tab-dash-prog\">Dashboard Programmation</a></li>\n      <li><a href=\"#tab-dash-prod\">Dashboard Production</a></li>\n    </ol>\n  </nav>\n\n  <!-- ════════ 1. GANTT BDT (PROGRAMMATION) ════════ -->\n  <section class=\"tab\" id=\"tab-gantt-bdt\">\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Planning Gantt BDT</h2></div>\n    <h3>Ce qui décide qu'un bon de travail apparaît au planning</h3>\n    <p>Un bon de travail n'apparaît ici que si <b>deux conditions</b> sont réunies : sa <b>matière est réceptionnée</b>, et la <b>préparation technique de son lot est terminée</b> (plan et programme CN disponibles).</p>\n    <p><b>Depuis le 9 septembre 2026, ce blocage se joue lot par lot.</b> Auparavant, une seule préparation en attente gelait <i>toute l'affaire</i> : des pièces parfaitement prêtes restaient invisibles à cause d'une autre pièce en retard. Désormais, sur une affaire de trois pièces dont une seule attend son plan, <b>les deux autres partent en fabrication</b>.</p>\n    <p>Pour savoir où en est chaque lot, ouvrez la <b>fiche affaire</b> (Commercial › Affaires) : le tableau « Production — lots » porte une colonne <b>Fabricable</b> qui indique, lot par lot, <span class=\"b b-ok\">Prêt à fabriquer</span> ou ce qui manque encore (préparation technique, matière non réceptionnée), avec le compte des lots prêts en tête de tableau.</p>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le planning de la journée d'atelier, organisé par <b>poste de travail</b> (et non par personne) : chaque ligne du Gantt est un poste, chaque barre est un BDT — une opération de fabrication d'un lot. La Programmation y classe les BDT en attente, les glisse sur les postes au bon horaire, puis suit leur avancement (programmé → reçu → soldé). C'est aussi ici que l'on affecte les opérateurs aux postes par plage horaire.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>C'est désormais le <b>seul</b> planning de l'atelier : il n'y a plus de page « Affectation » séparée, tout se fait ici. De haut en bas :</p>\n    <ul class=\"points\">\n      <li><b>Barre d'outils</b> : sélecteur de date avec flèches ‹ › (jour précédent / suivant), filtres d'activité et de type de process (voir sous-onglets ci-dessous), légende des couleurs, champ de recherche « N° d'affaire… » et bouton orange <b>« Nouveau BDT »</b>. Un bouton <b>« Demande d'achat »</b> (borne opérateur au matricule + PIN) est disponible dans le bandeau du service.</li>\n      <li><b>7 tuiles de statistiques</b> : Programmés, Reçus, Soldés, Soldés NC, En attente, Sous-trait., Process.</li>\n      <li><b>Goulotte « BDT à classer / en attente de programmation »</b> au-dessus du planning : les cartes y sont triées par échéance client puis par chemin critique (séquence des opérations du lot). Chaque carte porte la couleur de son lot, la pièce, la durée, l'activité et l'échéance. On peut aussi y <em>redéposer</em> une barre du planning pour la déprogrammer.</li>\n      <li><b>Le Gantt</b> : lignes = postes de travail (avec le nombre de process et de machines du poste), colonnes = heures de 5&nbsp;h à 23&nbsp;h. Chaque barre BDT est colorée selon son statut et porte un liseré gauche à la <b>couleur de son lot</b> — la même couleur que sur le planning BST, pour suivre un lot d'un planning à l'autre. Dans la colonne de gauche, chaque poste offre trois sous-cases <b>Matin / Ap-m / Soir</b> qui reçoivent les opérateurs affectés.</li>\n      <li><b>« Affectation des ressources aux postes »</b> : les opérateurs du jour classés en quatre colonnes (Matin, Après-midi, Soir, Absent). On glisse une carte — ou on la sélectionne au clic — vers une sous-case de process du planning.</li>\n    </ul>\n    <p>Couleurs des barres et statuts d'un BDT :\n      <span class=\"b b-mut\">à programmer</span> (dans la goulotte),\n      <span class=\"b b-info\">programmé</span> (bleu, bordure pointillée),\n      <span class=\"b b-warn\">reçu</span> (jaune : l'opérateur a pris le travail),\n      <span class=\"b b-ok\">soldé</span> (vert : opération terminée),\n      <span class=\"b b-crit\">soldé NC</span> (rouge : terminé avec non-conformité).\n      Un petit carré blanc ou noir devant le numéro du BDT signale une oxydation <em>incolore</em> ou <em>noire</em> à produire pour le lot.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/production-service.png\" alt=\"Capture du planning Gantt BDT par poste\" loading=\"lazy\">\n      <figcaption><b>Planning Gantt BDT</b> — la goulotte des BDT à classer au-dessus, le Gantt par poste au-dessous ; notez le liseré de couleur « lot » sur chaque barre et les sous-cases Matin / Ap-m / Soir des postes.</figcaption>\n    </figure>\n\n    <h3>Pas à pas</h3>\n    <p><b>Programmer un BDT sur un poste :</b></p>\n    <ol class=\"steps\">\n      <li>Choisissez la date en haut à gauche (le planning affiche les BDT prévus ce jour-là).</li>\n      <li>Prenez une carte dans la goulotte <b>« BDT à classer »</b> et glissez-la sur la ligne du poste : un guide vertical orange indique l'heure de dépôt (arrondie au quart d'heure). Vous pouvez aussi <em>cliquer</em> la carte puis cliquer le poste.</li>\n      <li>L'ERP vérifie qu'un process du poste est compatible (même activité Seem/Semrac que le BDT) ; sinon le dépôt est refusé avec un message. Si c'est bon, le BDT passe <span class=\"b b-info\">programmé</span> à la date et l'heure choisies.</li>\n      <li>Pour déplacer un BDT déjà programmé, glissez sa barre sur un autre poste ou un autre horaire. Pour le remettre en attente : clic droit → <b>« Déprogrammer (retour en attente) »</b>, ou glissez la barre dans la goulotte.</li>\n    </ol>\n    <p><b>Réceptionner puis solder un BDT (traçabilité opérateur au PIN) :</b></p>\n    <ol class=\"steps\">\n      <li>Quand l'opérateur démarre l'opération : clic droit sur la barre → <b>« Réceptionner (Reçu) »</b>. La modale demande le <b>matricule</b> et le <b>code PIN</b> de l'opérateur ; l'heure de début réelle est enregistrée et la barre passe en jaune.</li>\n      <li>À la fin : clic droit → <b>« Solder le BDT »</b>. Saisissez l'heure de fin réelle, le résultat (✅ Conforme, ⚠️ Reprise partielle, ❌ Non-conformité), d'éventuelles observations, puis le matricule + PIN de l'opérateur.</li>\n      <li>Si le résultat est « Non-conformité », un champ <b>Gravité</b> apparaît (Mineure / Majeure / Critique / Bloquante). La fiche NC part automatiquement à la Qualité ; une gravité <b>Critique</b> ou <b>Bloquante</b> bloque l'expédition de l'affaire jusqu'à traitement ou dérogation.</li>\n      <li>Le temps réel est calculé et comparé au temps alloué — il alimente le journal des temps et les indicateurs (TRS, écarts).</li>\n    </ol>\n    <p><b>Déclarer une sortie matière :</b> double-cliquez une barre BDT → la modale « Déclaration de sortie matière » s'ouvre. Choisissez le type (<b>Matière</b>, <b>Fourniture</b> ou <b>Consommable machine</b>), l'article du stock, la quantité, et pour un consommable la <b>machine</b> ou le <b>poste</b> concerné (traçage OPEX). La sortie décrémente le stock et se rattache au coût du lot.</p>\n    <p><b>Affecter les opérateurs aux postes :</b> dans le bloc « Affectation des ressources », glissez une carte opérateur (ou cliquez-la pour la sélectionner) puis déposez-la dans une sous-case <b>Matin / Ap-m / Soir</b> d'un poste du planning. L'affectation est enregistrée et tracée pour le jour ; la croix sur l'étiquette la retire. Un opérateur peut tenir plusieurs process et créneaux.</p>\n    <ul class=\"points\">\n      <li>Les opérateurs sont classés automatiquement dans la colonne correspondant à leur <b>présence du jour</b> (Matin, Après-midi, Soir) — celle que vous saisissez dans l'onglet <b>Présence opérateurs</b>.</li>\n      <li>Un opérateur <b>absent</b> ou <b>non planifié</b> (présence non saisie) apparaît grisé dans la colonne « Absent » et n'est <b>pas déplaçable</b> : passez d'abord par l'onglet Présence pour le rendre affectable.</li>\n      <li>Le contrôle de <b>compétence</b> reste porté par le process : un BDT ne peut être programmé que sur un poste dont un process couvre son opération et son activité (Seem/Semrac).</li>\n    </ul>\n\n    <h3>Filtres activité Seem/Semrac</h3>\n    <p>Les boutons <b>Tous / Seem / Semrac</b> filtrent à la fois les postes du Gantt, les cartes de la goulotte et les tuiles de statistiques. Les postes « both » (Seem &amp; Semrac) restent visibles dans les deux cas.</p>\n\n    <h3>Filtres process machine/manuel</h3>\n    <p>Les boutons <b>Tous process / Machine / Manuel</b> restreignent les statistiques aux process nécessitant une machine ou réalisés à la main. La recherche « N° d'affaire… » surligne en orange les BDT de l'affaire cherchée (planning + goulotte) et estompe les autres.</p>\n\n    <h3>Se concentrer sur une étape</h3>\n    <p>Un <b>clic simple</b> sur une barre BDT (ou la sélection d'une carte en attente) resserre le planning autour de l'<b>étape cliquée</b> : au lieu d'afficher tous les postes traversés par le lot, l'ERP ne garde que <b>trois lignes au maximum</b> — le poste de l'étape précédente, celui de l'étape cliquée et celui de l'étape suivante de la gamme. Vous voyez ainsi « d'où arrive » et « où repart » la pièce, sans le bruit du reste de l'atelier.</p>\n    <ol class=\"steps\">\n      <li>Cliquez une barre BDT du Gantt (ou une carte de la goulotte) : les lignes de postes sans rapport avec l'étape disparaissent.</li>\n      <li>Un <b>bandeau violet « Focus étape »</b> s'affiche au-dessus du planning et résume la position dans la gamme, par exemple : <span class=\"b b-mut\">LOT-2026-0042 · etape 2/4 — Pliage (avant : Poinçonnage · apres : ST Aalberts)</span>. Si le lot ne comporte qu'une opération, le bandeau indique « seule etape ».</li>\n      <li>Pour revenir à la vue complète : bouton <b>« Tout afficher »</b> du bandeau, ou re-cliquez la <b>même</b> barre. Cliquer une <em>autre</em> barre déplace simplement le focus sur cette nouvelle étape.</li>\n      <li>Le focus se libère aussi automatiquement dès que vous programmez le BDT sélectionné.</li>\n    </ol>\n    <div class=\"note\"><b>Bon à savoir — les étapes sous-traitées :</b> la gamme d'un lot mélange des opérations faites à l'atelier (BDT) et des opérations confiées à un prestataire (BST/BDS). Si l'étape d'avant ou d'après est <b>sous-traitée</b>, elle est nommée dans le bandeau sous la forme <b>« ST &lt;nom du sous-traitant&gt; »</b> — mais elle n'ajoute évidemment <b>aucune ligne</b> au planning des postes, puisqu'elle ne se fait pas dans l'atelier. Le comptage des étapes (« etape 2/4 ») tient bien compte des deux, internes et sous-traitées.</div>\n\n    <h3>Fractionner un BDT (Séparer)</h3>\n    <p>Un BDT long peut être découpé en plusieurs morceaux à répartir sur plusieurs jours ou postes : clic droit sur la barre → <b>« Séparer en morceaux »</b> (disponible tant que le BDT n'est ni reçu ni soldé).</p>\n    <ol class=\"steps\">\n      <li>La modale affiche la durée totale du BDT. Choisissez le <b>nombre de morceaux</b> (2 à 12) — « Répartir également » égalise les durées.</li>\n      <li>Ajustez librement la durée de chaque morceau ; la somme est contrôlée en direct. Si elle diffère de la durée d'origine, la répartition est ajustée au prorata à l'enregistrement.</li>\n      <li>Cliquez <b>« Séparer »</b> : le BDT d'origine est réduit au premier morceau, les suivants sont créés avec les suffixes <b>-M2</b>, <b>-M3</b>… et arrivent dans la goulotte, à programmer.</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-production-separer.png\" alt=\"Modale de fractionnement d'un BDT en morceaux\" loading=\"lazy\">\n      <figcaption><b>Séparer le BDT en morceaux</b> — la durée totale d'origine en haut, le <b>nombre de morceaux</b> (2 à 12) et la ligne de durée de chaque morceau ; surveillez le contrôle de la <b>somme</b> qui se met à jour en direct — si elle diffère du total, l'enregistrement répartit au prorata, puis les morceaux <b>-M2</b>, <b>-M3</b>… repartent dans la goulotte à programmer.</figcaption>\n    </figure>\n\n    <h3>Formulaire « Créer / Affecter un BDT »</h3>\n    <p>Le bouton <b>« Nouveau BDT »</b> ouvre la modale de création (pour un travail ponctuel hors cascade commande → lots) :</p>\n    <div class=\"tbl\"><table>\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n      <tbody>\n        <tr><td>N° Commande</td><td>Texte (CMD-2026-XXXX)</td><td>Oui</td><td>Commande / affaire de rattachement.</td></tr>\n        <tr><td>Client</td><td>Texte</td><td>Oui</td><td>Raison sociale du client final.</td></tr>\n        <tr><td>Activité</td><td>Liste : Seem / Semrac</td><td>Oui</td><td>Site concerné — conditionne la liste des opérations.</td></tr>\n        <tr><td>Opération</td><td>Liste (selon l'activité)</td><td>Oui</td><td>Opération de fabrication (Usinage CN, Pliage, Soudure…).</td></tr>\n        <tr><td>Pièce</td><td>Texte</td><td>Oui</td><td>Référence de la pièce fabriquée.</td></tr>\n        <tr><td>Durée (h)</td><td>Nombre (pas 0,5)</td><td>Oui</td><td>Temps alloué à l'opération.</td></tr>\n        <tr><td>Heure début</td><td>Heure (défaut 06:00)</td><td>Non</td><td>Position initiale de la barre sur le Gantt.</td></tr>\n        <tr><td>Priorité</td><td>Normal / Urgent / Critique</td><td>Non</td><td>Colore la carte en attente (vert / orange / rouge).</td></tr>\n        <tr><td>Process atelier</td><td>Liste des process compatibles</td><td>Non</td><td>Laisser vide = le BDT reste en attente dans la goulotte.</td></tr>\n      </tbody>\n    </table></div>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li><b>Porte matière + prépa technique</b> : un BDT créé par la cascade d'acceptation d'offre n'apparaît dans ce planning que lorsque <b>toute la matière de l'affaire est réceptionnée</b> (tous les BC matière reçus) <b>et</b> que la <b>préparation technique</b> de l'affaire est terminée. Tant que ce n'est pas le cas, le BDT existe en base mais <b>n'est visible ni dans la goulotte ni dans le Gantt</b> : suivez son avancement depuis l'onglet <b>Commandes &amp; Lots</b> (section 4) ou depuis la préparation technique du Bureau d'Études.</li>\n      <li>Les process de traitement de surface (OAS, oxydation, Surtec…) n'apparaissent <b>jamais</b> dans ce planning : ils se pilotent dans le service OAS.</li>\n      <li>La goulotte trie automatiquement par échéance client puis par séquence d'opérations (chemin critique du lot) : traitez-la de haut en bas.</li>\n      <li>Pendant un glisser, tous les BDT du même lot sont surlignés en jaune — pratique pour repérer l'opération précédente.</li>\n      <li>Clic droit sur une barre : le menu propose aussi <b>« Aller à la commande rattachée »</b> et <b>« Aller au lot rattaché »</b>. Double-clic sur une carte en attente : ouvre la commande mère.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> réceptionner et solder exigent le matricule + code PIN de l'opérateur — c'est la signature de traçabilité (EN 9100). Un BDT soldé ne peut plus être déplacé ni séparé ; une NC Critique/Bloquante bloque l'expédition de toute l'affaire.</div>\n    <div class=\"astuce\"><b>Astuce :</b> le survol d'une barre affiche une infobulle complète (client, pièce, durée, process, statut). Rappel des gestes : <b>clic</b> = focus étape (3 lignes max) · <b>double-clic</b> = sortie matière · <b>clic droit</b> = statuts et navigation.</div>\n  </section>\n\n  <!-- ════════ 2. GANTT BST ════════ -->\n  <section class=\"tab\" id=\"tab-gantt-bst\">\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Planning Gantt BST (sous-traitance)</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Les opérations confiées à un prestataire extérieur (oxydation, zingage, peinture poudre, traitement thermique…) sont portées par des BST (bons de sous-traitance). Cet onglet les planifie sur une grille jour par jour : quel sous-traitant, quel jour d'envoi, quelle durée — et suit leur retour. L'affectation d'un BST crée automatiquement le bon de commande sous-traitant côté Expéditions.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <ul class=\"points\">\n      <li><b>Barre d'outils</b> : date de début de la fenêtre avec navigation ±7 jours (‹ ›) et ±1 jour (−1j / +1j), rappel « Vue 21 jours · BST de 1 à 20+ jours · couleur = lot », légende des statuts et bouton violet <b>« Nouveau BST »</b>.</li>\n      <li><b>5 tuiles KPI</b> : BST total, À planifier, En attente d'envoi, Envoyés (chez ST), Revenus.</li>\n      <li><b>La grille</b> : lignes = sous-traitants (nom, localisation, qualification, pastilles des prestations maîtrisées, <b>OTD</b> en % coloré vert ≥ 90, orange ≥ 75, rouge en dessous) ; colonnes = 21 jours (week-ends grisés, aujourd'hui surligné orange). Chaque barre BST porte la couleur de son <b>lot</b> (la même que sur le Gantt BDT) et son statut en contour : <span class=\"b b-warn\">en attente d'envoi</span> (pointillé orange), <span class=\"b b-info\">envoyé</span> (contour bleu), <span class=\"b b-ok\">revenu</span> (contour vert).</li>\n      <li><b>« BST à planifier »</b> <b>au-dessus</b> de la grille (comme la goulotte des BDT sur le Gantt d'atelier) : les cartes sans date ni sous-traitant. Glissez-en une sur la case d'un jour, sur la ligne du sous-traitant, pour la planifier.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/production-gantt-bst.png\" alt=\"Capture du planning BST jour par jour\" loading=\"lazy\">\n      <figcaption><b>Planning Gantt BST</b> — le bac « BST à planifier » au-dessus, puis la grille 21 jours par sous-traitant (avec OTD et prestations) et les barres colorées par lot.</figcaption>\n    </figure>\n\n    <h3>Pas à pas</h3>\n    <p><b>Planifier un BST :</b></p>\n    <ol class=\"steps\">\n      <li>Prenez une carte dans <b>« BST à planifier »</b> (ou cliquez-la pour la sélectionner) et déposez-la sur la case du jour d'envoi, sur la ligne du sous-traitant choisi.</li>\n      <li>Le BST passe <span class=\"b b-warn\">en attente d'envoi</span> et l'ERP <b>crée automatiquement le BC sous-traitant</b> lié — il apparaît dans Expéditions → Bons de Commande, prêt à être envoyé.</li>\n      <li>Ensuite, le statut du BST est <b>piloté par ce BC</b> : BC envoyé/accusé → le BST passe « envoyé » ; BC reçu → « revenu ». On ne change donc pas le statut depuis le planning, mais depuis le BC en Expéditions.</li>\n      <li>Pour déplacer un BST, glissez sa barre sur une autre case. Clic droit → <b>« Déplanifier (retour à l'attente) »</b> pour le remettre dans le bac.</li>\n    </ol>\n    <p><b>Créer un BST (modale « Nouveau BST ») :</b></p>\n    <div class=\"tbl\"><table>\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n      <tbody>\n        <tr><td>Lot lié</td><td>Liste des lots</td><td>Oui</td><td>Le lot dont l'opération part en sous-traitance.</td></tr>\n        <tr><td>Sous-traitant</td><td>Liste des sous-traitants</td><td>Oui</td><td>Prestataire pressenti.</td></tr>\n        <tr><td>Opération ST</td><td>Liste (oxydation, zingage, sérigraphie…)</td><td>Non</td><td>Prestation demandée.</td></tr>\n        <tr><td>Qté</td><td>Nombre</td><td>Non</td><td>Par défaut, la quantité du lot.</td></tr>\n        <tr><td>Date envoi</td><td>Date</td><td>Non</td><td>Jour de départ prévu chez le prestataire.</td></tr>\n        <tr><td>Durée (jours)</td><td>Nombre 1–60 (défaut 5)</td><td>Non</td><td>Longueur de la barre sur la grille.</td></tr>\n      </tbody>\n    </table></div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-production-st.png\" alt=\"Formulaire de sous-traitance\" loading=\"lazy\">\n      <figcaption><b>Nouvelle sous-traitance</b> — le formulaire d'envoi d'une opération chez un prestataire (commande, client final, opération, sous-traitant, date de retour, priorité).</figcaption>\n    </figure>\n\n    <h3>Se concentrer sur une étape</h3>\n    <p>Comme sur le Gantt BDT, un <b>clic simple</b> sur une barre BST (ou sur une carte à planifier) resserre la grille autour de l'<b>étape cliquée</b> : ne restent que les lignes des sous-traitants de l'étape précédente, de l'étape cliquée et de l'étape suivante de la gamme. Le bandeau violet <b>« Focus étape »</b> rappelle la position dans la gamme (« … · etape 3/5 — Zingage (avant : atelier Pliage · apres : Peinture poudre) »).</p>\n    <ul class=\"points\">\n      <li>Si l'étape voisine est réalisée <b>à l'atelier</b> (et non chez un prestataire), le bandeau la nomme <b>« atelier &lt;opération&gt; »</b> : elle n'ajoute aucune ligne à cette grille, qui ne liste que des sous-traitants.</li>\n      <li>Pour sortir du focus : bouton <b>« Tout afficher »</b> du bandeau, ou nouveau clic sur la même barre.</li>\n    </ul>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>La couleur d'une barre = son <b>lot</b>, partagée entre les plannings BDT et BST : un même lot garde sa couleur partout.</li>\n      <li>Le clic droit propose aussi la navigation : <b>Ouvrir la commande</b>, <b>Ouvrir le lot</b>, <b>Ouvrir le BC sous-traitant</b> (s'il existe). Double-clic sur une barre : ouvre la commande mère.</li>\n      <li>L'OTD affiché sur chaque ligne aide à choisir le prestataire le plus fiable en délai.</li>\n    </ul>\n    <div class=\"note\"><b>Bon à savoir :</b> le passage « envoyé » / « revenu » se fait dans <b>Expéditions</b> (envoi du BC, réception du BL) — le planning reflète l'état du BC lié en temps réel.</div>\n  </section>\n\n  <!-- ════════ 3. PRÉSENCE OPÉRATEURS ════════ -->\n  <section class=\"tab\" id=\"tab-presence\">\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>Présence opérateurs</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> On y programme les horaires des opérateurs Seem et Semrac, semaine par semaine : matin, journée, soir ou absent. Cette présence pilote directement la disponibilité dans le bloc « Affectation des ressources aux postes » du planning — un opérateur non programmé n'est pas affectable. L'onglet traite aussi les demandes de congés des opérateurs.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Deux vues, commutées par les deux boutons du haut :</p>\n    <ul class=\"points\">\n      <li><b>Planning de présence</b> : une grille opérateurs × 7 jours de la semaine, avec navigation ‹ › entre semaines et filtres Tous / Seem / Semrac. Chaque cellule est colorée : <span class=\"b b-info\">Matin</span> (bleu, 06h-14h), <span class=\"b b-ok\">Journée</span> (vert, 08h-17h), <span class=\"b\" style=\"background:#ede9fe;color:#5b21b6\">Soir</span> (violet, 14h-22h), <span class=\"b b-crit\">Absent</span> (rouge), <span class=\"b b-mut\">Non programmé</span> (gris).</li>\n      <li><b>Demandes de congés à traiter</b> : la liste des demandes des opérateurs (type, dates, heures/jours, motif) avec les boutons <b>Approuver</b> et refuser (✕).</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/production-presence.png\" alt=\"Capture du planning de présence hebdomadaire\" loading=\"lazy\">\n      <figcaption><b>Présence opérateurs</b> — la grille hebdomadaire : cliquez une cellule pour faire défiler les shifts ; les cases verrouillées (cadenas) sont des absences RH.</figcaption>\n    </figure>\n\n    <h3>Pas à pas</h3>\n    <ol class=\"steps\">\n      <li><b>Programmer un jour</b> : cliquez la cellule de l'opérateur — chaque clic fait défiler matin → journée → soir → absent → vide. La sauvegarde est immédiate.</li>\n      <li><b>Programmer une semaine entière</b> : bouton orange <b>« Programmer la semaine »</b> → choisissez le shift à appliquer, les jours (Lun → Ven ou Lun → Dim), cochez les opérateurs (boutons rapides : Tout cocher / Seem / Semrac) puis <b>« Appliquer à la semaine »</b>. Les jours en absence RH ne sont pas touchés.</li>\n      <li><b>Traiter un congé</b> : vue « Demandes de congés » → <b>Approuver</b> pose l'absence sur le planning de présence <em>et</em> décompte les heures du solde de congés du salarié ; ✕ refuse la demande.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Les absences RH (congés validés, maladie) arrivent automatiquement et sont <b>verrouillées</b> ici (icône cadenas) — elles se gèrent côté RH.</li>\n      <li>La présence saisie ici détermine la colonne (Matin / Après-midi / Soir) des opérateurs dans le bloc « Affectation des ressources aux postes » du planning (section 1), et le calcul de capacité du Dashboard Programmation.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> programmez la semaine type en une fois avec « Programmer la semaine », puis corrigez les exceptions cellule par cellule.</div>\n  </section>\n\n  <!-- ════════ 4. COMMANDES & LOTS ════════ -->\n  <section class=\"tab\" id=\"tab-commandes\">\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Commandes &amp; Lots</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La vue d'ensemble du carnet de fabrication : toutes les commandes en cours et leur avancement, et tous les lots avec leur progression opération par opération. C'est le point d'entrée vers les fiches détaillées (commande → lots → BDT/BDS) et l'ordre de fabrication.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Deux sous-vues commutées par les boutons <b>Commandes</b> et <b>Lots</b> (avec leur compteur) :</p>\n    <ul class=\"points\">\n      <li><b>Commandes en cours</b> — colonnes : N° CMD / Affaire, Client, Pièces, Montant, Date cmd, Livraison, Statut (badge <span class=\"b b-crit\">Retard</span> si la date est dépassée), <b>Avancement BDT</b> (barre de progression % = BDT soldés / total) et ST (badge si la commande passe en sous-traitance).</li>\n      <li><b>Lots en cours</b> — colonnes : Réf. Lot, Client, Pièce, Qté, Début, Fin, Statut, <b>Avancement</b> (opérations soldées — BDT usine + BDS revenus — sur le total, ex. « 3/5 »), Commande (lien direct).</li>\n      <li>Au-dessus de chaque tableau : une <b>recherche</b> avec choix du champ (N° affaire, client, statut… ). Un clic sur une ligne ouvre la fiche détaillée.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/production-commandes.png\" alt=\"Capture de l'onglet Commandes et Lots\" loading=\"lazy\">\n      <figcaption><b>Commandes &amp; Lots</b> — le tableau des commandes avec la barre d'avancement BDT ; le bouton « Lots » bascule sur la vue par lot.</figcaption>\n    </figure>\n\n    <h3>Pas à pas</h3>\n    <ol class=\"steps\">\n      <li>Recherchez la commande (choisissez le champ, tapez le texte) puis <b>cliquez la ligne</b> : la fiche commande liste tous ses lots, chacun découpé en opérations ordonnées (badge <span class=\"b b-info\">BDT</span> pour l'usine, <span class=\"b\" style=\"background:#ede9fe;color:#6d28d9\">BDS</span> pour la sous-traitance) avec leur statut, plus des cartes KPI d'avancement.</li>\n      <li>Depuis la vue Lots, cliquez un lot pour ouvrir sa fiche : les étapes de production dans l'ordre, et l'impression de l'<b>ordre de fabrication</b> (OF) à joindre au dossier atelier.</li>\n      <li>Depuis un BDT du planning, le clic droit « Aller à la commande / au lot rattaché » mène aux mêmes fiches.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>L'avancement d'un lot compte les BDT <b>soldés</b> et les BDS <b>revenus</b> — un BST encore chez le prestataire ne compte pas.</li>\n      <li>Une commande passe automatiquement à 100 % quand toutes ses opérations sont soldées ; son coût réel est consolidé au soldage.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> depuis la fiche d'un lot, vous pouvez rejoindre le planning avec le BDT déjà surligné (lien « planning » avec focus).</div>\n  </section>\n\n  <!-- ════════ 5. PROCESS ATELIERS ════════ -->\n  <section class=\"tab\" id=\"tab-machines\">\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Process Ateliers (machines + postes &amp; process)</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le référentiel de l'atelier : les <b>postes de travail</b> regroupent machines et process ; le planning est organisé sur ces postes, et leurs coûts (OPEX, taux horaire effectif) alimentent le calcul du coût de revient des pièces (CRU). On y crée et gère postes, process et machines, on y suit l'OPEX réel, et on y déclare une panne machine.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <ul class=\"points\">\n      <li><b>4 tuiles KPI</b> : Machines actives, En maintenance, Arrêtées, OPEX annuel estimé.</li>\n      <li>Deux volets commutés par les boutons <b>« Postes &amp; Process »</b> (par défaut) et <b>« Machines »</b>.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/production-process.png\" alt=\"Capture de l'onglet Process Ateliers\" loading=\"lazy\">\n      <figcaption><b>Process Ateliers</b> — les tuiles KPI du parc et la bascule entre les volets « Postes &amp; Process » et « Machines ».</figcaption>\n    </figure>\n\n    <h3>Volet « Postes &amp; Process »</h3>\n    <p>Le tableau des postes de travail — colonnes : Poste (avec sa pastille couleur et une flèche pour déplier ses process et machines), Code, Activité (Seem / Semrac / both / OAS), Machines, Process, <b>OPEX réel (YTD)</b>, OPEX théorique/an, <b>Taux/h effectif</b> et Actions. Les lignes se réordonnent par glisser-déposer (l'ordre est celui du planning). Boutons d'action par poste : <b>+ Process</b> (créer un process directement dans le poste), main-euro (fixer / réinitialiser un <b>taux horaire manuel</b>, avec confirmation), crayon (modifier), corbeille (supprimer). Le bouton <b>« Nouveau poste »</b> ouvre la modale : Nom*, Code, Activité, Couleur (planning), Ordre d'affichage.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/production-postes.png\" alt=\"Capture du volet Postes et Process\" loading=\"lazy\">\n      <figcaption><b>Postes de travail</b> — OPEX réel/théorique et colonne « Taux/h effectif » (base machines + achats de l'année) qui alimente le CRU des pièces.</figcaption>\n    </figure>\n\n    <h3>Volet « Machines »</h3>\n    <p>Le parc machines — colonnes : Machine, Code, Activité (filtres Tous / SEEM / SEMRAC / OAS), Catégorie, Taux/h, Capa./j, OPEX théorique/an, <b>OPEX réel conso. (YTD)</b>, Postes (bouton ouvrant le détail des postes de dépenses consommables), Statut (✔ Opérationnel / ⚙ Maintenance / ✖ Arrêt) et Actions : <b>« Panne »</b> (déclare la machine en panne → service Maintenance) ou <b>« Réparée »</b> (remise en service), modifier, supprimer. En dessous, le graphique d'évolution mensuelle de l'OPEX.</p>\n    <p>Modale « Nouvelle machine » (bouton orange), champ par champ :</p>\n    <div class=\"tbl\"><table>\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n      <tbody>\n        <tr><td>Nom de la machine</td><td>Texte</td><td>Oui</td><td>Ex. « Tour CNC Mazak QT-200 ».</td></tr>\n        <tr><td>Code</td><td>Texte</td><td>Non</td><td>Code court (CNC-03…).</td></tr>\n        <tr><td>Activité</td><td>Seem / Semrac / both / OAS</td><td>Oui</td><td>Une machine OAS est hors planning (traitement de surface).</td></tr>\n        <tr><td>Catégorie</td><td>Texte</td><td>Non</td><td>Usinage, Découpe…</td></tr>\n        <tr><td>Capacité (h/jour)</td><td>Nombre (défaut 8)</td><td>Non</td><td>Base du calcul d'OPEX théorique et d'utilisation.</td></tr>\n        <tr><td>Coût machine (€/h)</td><td>Nombre (défaut 35)</td><td>Non</td><td>Taux horaire — alimente le taux du poste et le CRU.</td></tr>\n        <tr><td>Tolérance ± (mm)</td><td>Nombre</td><td>Non</td><td>Sert aux études de capabilité (Qualité).</td></tr>\n        <tr><td>Statut</td><td>Opérationnel / Maintenance / Arrêt</td><td>Non</td><td>État courant de la machine.</td></tr>\n        <tr><td>Poste de travail</td><td>Liste des postes</td><td>Non</td><td>Poste de rattachement (planning + OPEX du poste).</td></tr>\n        <tr><td>Machine CNC</td><td>Case à cocher</td><td>Non</td><td>Une CNC porte des codes programme (saisis en préparation technique).</td></tr>\n        <tr><td>Opérations possibles</td><td>Texte (séparées par virgule)</td><td>Non</td><td>Opérations que la machine sait réaliser.</td></tr>\n        <tr><td>Process rattachés</td><td>Cases (process du poste)</td><td>Non</td><td>Process alimentés par cette machine ; option « créer aussi un nouveau process » au nom de la machine.</td></tr>\n      </tbody>\n    </table></div>\n\n    <h3>Pas à pas</h3>\n    <ol class=\"steps\">\n      <li><b>Créer un poste</b> : « Nouveau poste » → nom, activité, couleur → le poste apparaît (vide). Rattachez-y ensuite machines et process.</li>\n      <li><b>Créer un process dans un poste</b> : bouton <b>+ Process</b> de la ligne du poste → nom, type (<b>Machine</b> / <b>Manuel</b> / <b>OAS</b>), machine rattachée le cas échéant. Le crayon d'un process permet ensuite de changer son nom, sa machine, son taux horaire et son poste.</li>\n      <li><b>Déclarer une panne</b> : volet Machines → bouton <b>« Panne »</b> sur la ligne → la machine passe en arrêt et le service Maintenance est saisi ; « Réparée » la remet en service.</li>\n      <li><b>Fixer un taux horaire manuel</b> : bouton main-euro du poste → saisir le taux (ou vider pour revenir à l'automatique) → double confirmation, car ce taux prime en absolu sur le calcul et impacte le CRU.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li><b>OPEX réel</b> d'une machine = somme des sorties stock « consommable » déclarées sur ses BDT (quantité × prix d'achat HT), en temps réel. L'OPEX d'un <b>poste</b> = somme de ses machines + consommables tirés directement au poste. Ce calcul est repris à l'identique en Maintenance.</li>\n      <li><b>Taux/h effectif</b> d'un poste = moyenne pondérée du coût/h de ses machines + achats machine reçus dans l'année / heures budgétées. C'est ce taux qui alimente le CRU des pièces usinées au poste.</li>\n      <li>Un poste ou process <b>OAS</b> n'apparaît pas au planning ; ses process alimentent les types de bain de l'onglet OAS.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> supprimer un process ou une machine est définitif (confirmation demandée). Un process « Machine » sans machine rattachée est signalé « à rattacher » — faites-le, sinon son coût machine est nul dans le CRU.</div>\n  </section>\n\n  <!-- ════════ 6. DASHBOARD PROGRAMMATION ════════ -->\n  <section class=\"tab\" id=\"tab-dash-prog\">\n    <div class=\"tab-head\"><span class=\"tab-num\">6</span><h2>Dashboard Programmation</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Le tableau de bord de la charge : combien de commandes et de lots sont en cours, combien de BDT restent actifs, et surtout si la capacité des opérateurs présents absorbe la charge de la semaine. C'est l'outil d'arbitrage de Sylvie avant de programmer.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <ul class=\"points\">\n      <li><b>4 cartes KPI</b> : Commandes en cours (avec le nombre en retard), Lots en cours (avec les bloqués), BDT actifs, Charge journée en % (heures de BDT / capacité = opérateurs × 8 h).</li>\n      <li><b>« Charge opérateurs par jour »</b> : un histogramme Lun → Dim, calculé sur les présences réelles (présents × 8 h par jour) ; les barres passent de vert à orange (≥ 70 %) puis rouge (≥ 85 %), le jour courant est encadré. Navigation par semaine avec ‹ › et le sélecteur de date.</li>\n      <li>Deux tableaux : <b>Lots en cours · étape de production</b> (Planifié / Production / Sous-traitance / Bloqué, fin prévue) et <b>Commandes · avancement</b> (barre %, OK / Retard).</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/production-dash-prog.png\" alt=\"Capture du dashboard Programmation\" loading=\"lazy\">\n      <figcaption><b>Dashboard Programmation</b> — surveillez l'histogramme de charge : un jour rouge (≥ 85 %) signifie qu'il faut lisser, décaler ou sous-traiter.</figcaption>\n    </figure>\n\n    <h3>Pas à pas</h3>\n    <ol class=\"steps\">\n      <li>Consultez la charge de la semaine : si un jour dépasse 85 %, retournez au planning (onglet 1) pour déplacer des BDT vers un jour creux, ou vérifiez la présence (onglet 3) pour renforcer l'équipe.</li>\n      <li>Contrôlez les tableaux du bas : un lot « Bloqué » ou une commande « Retard » se traite en priorité — ouvrez la fiche depuis Commandes &amp; Lots.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>La capacité quotidienne dépend des <b>présences saisies</b> : un jour sans présence programmée affiche 0 % — pensez à remplir l'onglet Présence.</li>\n    </ul>\n  </section>\n\n  <!-- ════════ 7. DASHBOARD PRODUCTION ════════ -->\n  <section class=\"tab\" id=\"tab-dash-prod\">\n    <div class=\"tab-head\"><span class=\"tab-num\">7</span><h2>Dashboard Production</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Le tableau de bord de la performance : rendement des machines (TRS/TRG/TRE), coûts d'exploitation du parc (OPEX) et liste des BDT actifs du jour. Il est calculé sur les données réelles tracées par les soldages au PIN.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <ul class=\"points\">\n      <li><b>Trois jauges</b> : TRS (Taux de Rendement Synthétique), TRG (Global), TRE (Économique), accompagnées des trois composantes en barres : <b>Disponibilité</b> (machines opérationnelles), <b>Performance</b> (temps alloué / temps réel des BDT soldés) et <b>Qualité</b> (BDT soldés sans NC).</li>\n      <li><b>OPEX Machines · YTD</b> : par machine, le taux/h, l'utilisation (charge BDT / capacité hebdo) et l'OPEX cumulé de l'année, avec le total du parc.</li>\n      <li><b>BDTs du jour</b> : les BDT actifs (client, pièce, opération, priorité, statut, durée) avec un bouton <b>« Dupliquer »</b> pour recréer un BDT identique et le réaffecter.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/production-dash-prod.png\" alt=\"Capture du dashboard Production\" loading=\"lazy\">\n      <figcaption><b>Dashboard Production</b> — jauges TRS/TRG/TRE avec leurs composantes, table OPEX machines et BDT actifs du jour.</figcaption>\n    </figure>\n\n    <h3>Pas à pas</h3>\n    <ol class=\"steps\">\n      <li>Lisez le TRS puis identifiez la composante faible : Disponibilité basse → voir Maintenance (pannes) ; Performance basse → temps réels supérieurs aux temps alloués (revoir les gammes) ; Qualité basse → NC au soldage (voir la Qualité).</li>\n      <li>Pour dupliquer un BDT récurrent : bouton « Dupliquer » sur la ligne → choisissez l'opérateur et l'heure de début → « Dupliquer &amp; Affecter ».</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Ces indicateurs ne valent que si les BDT sont réellement réceptionnés et soldés au fil de l'eau — les temps réels viennent exclusivement des soldages au PIN.</li>\n    </ul>\n  </section>\n\n  <div class=\"docnav\">\n    <a href=\"index.html\">← Sommaire des manuels</a>\n    <a href=\"oas.html\">Manuel suivant : OAS →</a>\n  </div>\n\n  <footer class=\"doc\">\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\n  </footer>\n\n</div>\n</body>\n</html>\n",
  "qualite": "<!doctype html>\r\n<html lang=\"fr\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>Manuel — Qualité · ERP Seem Semrac</title>\r\n<link rel=\"stylesheet\" href=\"manuel.css\">\r\n</head>\r\n<body>\r\n<div class=\"wrap\">\r\n\r\n  <header class=\"doc\">\r\n    <div class=\"brandrow\">\r\n      <div class=\"logo\">SS</div>\r\n      <div>\r\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\r\n        <div class=\"eyebrow\">Manuel utilisateur</div>\r\n      </div>\r\n      <div class=\"kind\">docs/manuel/html</div>\r\n    </div>\r\n    <h1>Service <span class=\"hi\">Qualité</span></h1>\r\n    <p class=\"lede\">Le service Qualité est la tour de contrôle de la conformité : il centralise les PV de contrôle, les non-conformités et leur résolution (8D), les dérogations, la libération des lots avant expédition, la quarantaine, le parc d'équipements de mesure (ECME), la capabilité des machines, les périssables, le plan de contrôle EN&nbsp;9100 et le programme d'audits internes. Ce manuel décrit chacun des 13 onglets, écran par écran.</p>\r\n    <div class=\"metachips\">\r\n      <span class=\"chip\">👤 Pour qui : <b>Qualiticien(ne)</b> (écriture : Qualité, Sécurité · lecture : BE, Production, OAS, Expéditions, Stock, Maintenance)</span>\r\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Qualité</b></span>\r\n      <span class=\"chip\">🗂 <b>13 onglets</b></span>\r\n    </div>\r\n  </header>\r\n\r\n  <nav class=\"toc\">\r\n    <div class=\"toc-t\">Sommaire</div>\r\n    <ol>\r\n      <li><a href=\"#tab-pv\">PV de Contrôle</a></li>\r\n      <li><a href=\"#tab-nc\">Non-Conformités</a></li>\r\n      <li><a href=\"#tab-8d\">Rapports 8D</a></li>\r\n      <li><a href=\"#tab-derogations\">Dérogations</a></li>\r\n      <li><a href=\"#tab-liberation\">Libération Lots</a></li>\r\n      <li><a href=\"#tab-quarantaine\">Quarantaine</a></li>\r\n      <li><a href=\"#tab-ecme\">Contrôle des ECME</a></li>\r\n      <li><a href=\"#tab-capabilite\">Étude de capabilité</a></li>\r\n      <li><a href=\"#tab-perissables\">Produits Périssables</a></li>\r\n      <li><a href=\"#tab-plan-controle\">Plan de contrôle</a></li>\r\n      <li><a href=\"#tab-audit\">Audit Conformité</a></li>\r\n      <li><a href=\"#tab-referentiels\">Référentiels</a></li>\r\n      <li><a href=\"#tab-dashboard\">Dashboard Qualité</a></li>\r\n    </ol>\r\n  </nav>\r\n\r\n  <!-- ══════════════ 1. PV DE CONTRÔLE ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-pv\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>PV de Contrôle</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Cet onglet rassemble tous les procès-verbaux de contrôle qualité de l'usine, quelle que soit leur origine : un PV peut provenir de l'<b>OAS</b> (balancelle clôturée), d'un <b>BDT</b> soldé, d'un <b>BL fournisseur</b> (contrôle de réception), d'un <b>BL sous-traitant</b> (retour de sous-traitance) ou d'un <b>retour client</b>. C'est le registre de preuve du contrôle : chaque PV porte un statut, une décision de libération et, le cas échéant, les indices Cp/Cpk.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>En haut, une rangée de <b>filtres par origine</b> (Tous · OAS · BDT · BL Fournisseur · BL Sous-traitant · Retour client), chacun avec son compteur. À droite, un champ <b>Rechercher…</b> et le bouton rouge <b>« Nouveau PV »</b>. Le tableau liste les PV avec les colonnes : N°&nbsp;PV, Date, Origine, Type contrôle, Lien (badge <span class=\"b b-info\">Lot</span> ou <span class=\"b b-warn\">BL</span> suivi du numéro), Pièce, Client / Fourn., Cp/Cpk, Statut, Décision, Actions.</p>\r\n    <ul class=\"points\">\r\n      <li>Statuts possibles : <span class=\"b b-info\">En cours</span> · <span class=\"b b-ok\">Validé ✓</span> · <span class=\"b b-crit\">Refusé</span> · <span class=\"b b-warn\">NC ouverte</span>.</li>\r\n      <li>Décisions : <span class=\"b b-ok\">Libéré ✓</span> · <span class=\"b b-warn\">Libéré (dérogation)</span> · <span class=\"b b-crit\">Bloqué ✗</span> (ou « — » si aucune décision).</li>\r\n      <li>La colonne Cp/Cpk est colorée : vert si Cpk ≥ 1,33, orange entre 1 et 1,33, rouge en dessous de 1 ; « N/A » si le PV n'a pas de mesure.</li>\r\n      <li>Deux boutons d'action par ligne : <b>Ouvrir NC</b> (triangle rouge — bascule vers l'onglet Non-Conformités avec le formulaire de création) et <b>Libérer lot</b> (cadenas vert — bascule vers l'onglet Libération Lots).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-pv.png\" alt=\"Capture de l'onglet PV de Contrôle\" loading=\"lazy\">\r\n      <figcaption><b>PV de Contrôle</b> — les pastilles d'origine en haut filtrent le tableau ; repérez les colonnes Statut et Décision qui résument le sort de chaque contrôle.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — créer un PV manuellement</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouveau PV »</b> : la fenêtre de saisie s'ouvre.</li>\r\n      <li>Renseignez la <b>date</b> et le <b>type de contrôle</b> (autocontrôle, intermédiaire, final, réception fournisseur).</li>\r\n      <li>Choisissez le rattachement : <b>« Lié à un Lot »</b> ou <b>« Lié à un BL »</b>, puis saisissez le numéro correspondant (LOT-2026-XXX ou BL-2026-XXX).</li>\r\n      <li>Complétez la pièce, le client, éventuellement les indices <b>Cp</b> et <b>Cpk</b>, et vos observations.</li>\r\n      <li>Cliquez sur <b>« Créer le PV »</b> : le PV rejoint la liste.</li>\r\n    </ol>\r\n\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td>Date PV</td><td>Date</td><td>Recommandé</td><td>Date du contrôle.</td></tr>\r\n        <tr><td>Type contrôle</td><td>Liste</td><td>Recommandé</td><td>Autocontrôle · intermédiaire · final · réception fournisseur.</td></tr>\r\n        <tr><td>Lié à un Lot / à un BL</td><td>Bouton bascule</td><td>Oui</td><td>Détermine si le PV se rattache à un lot de production ou à un bon de livraison.</td></tr>\r\n        <tr><td>N° Lot ou N° BL</td><td>Texte</td><td>Oui</td><td>Numéro du lot (LOT-2026-XXX) ou du BL (BL-2026-XXX) contrôlé.</td></tr>\r\n        <tr><td>Pièce / Client</td><td>Texte</td><td>Non</td><td>Référence de la pièce et raison sociale concernées.</td></tr>\r\n        <tr><td>Cp / Cpk</td><td>Nombres</td><td>Non</td><td>Indices de capabilité si un relevé de cotes a été fait.</td></tr>\r\n        <tr><td>Observations</td><td>Texte libre</td><td>Non</td><td>Constat du contrôle.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-qualite-pv.png\" alt=\"Formulaire Nouveau PV de contrôle\" loading=\"lazy\">\r\n      <figcaption><b>Nouveau PV</b> — le rattachement Lot/BL se choisit avec les deux boutons bleus au centre du formulaire.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>La plupart des PV arrivent <b>automatiquement</b> depuis les autres services (OAS, Production, Expéditions) : la création manuelle sert surtout aux cas hors flux.</li>\r\n      <li>Utilisez le filtre d'origine avant de chercher : un PV de réception se trouve sous « BL Fournisseur », pas sous « BDT ».</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> le bouton « Libérer lot » d'une ligne de PV est le raccourci le plus court vers l'onglet Libération Lots quand le contrôle final vient d'être passé.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 2. NON-CONFORMITÉS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-nc\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Non-Conformités</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le registre central des non-conformités (NC). Les NC peuvent être créées <b>automatiquement</b> par l'ERP (fin de balancelle OAS non conforme, soldage de BDT, réception fournisseur) ou <b>manuellement</b> ici. De chaque NC partent les suites : rapport 8D, dérogation, mise en quarantaine, et — pour une NC client — le traitement du retour (avoir ou commande prioritaire).</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Sous le bandeau d'information, deux rangées de filtres : <b>Catégorie</b> (Toutes · Administratif · Production) et <b>Entité</b> (Toutes · Seem · Semrac), plus un champ de recherche et le bouton <b>« Nouvelle NC »</b>. Le tableau est très complet : N°&nbsp;NC, Entrée, Fin traitement, Type NC, Catégorie, Entité, Lot, Article, Fournisseur, Client, Détection, Imputation, FRC, Gravité, Statut, Actions.</p>\r\n    <ul class=\"points\">\r\n      <li>Gravité : <span class=\"b b-warn\">Mineure</span> · <span class=\"b b-warn\">Majeure</span> · <span class=\"b b-crit\">Critique</span> · <span class=\"b b-crit\">Bloquante</span> (badge sombre à l'écran).</li>\r\n      <li>Statut : <span class=\"b b-info\">En cours</span> · <span class=\"b b-warn\">8D ouvert</span> · <span class=\"b b-ok\">Clôturé ✓</span> / <span class=\"b b-ok\">Traité ✓</span>. Un badge supplémentaire apparaît si la NC est passée en validation Direction.</li>\r\n      <li>Le <b>numéro de NC est cliquable</b> (souligné) : il rouvre la NC dans son formulaire pour la modifier.</li>\r\n      <li>Actions par ligne : <b>« Ouvrir 8D »</b> (ou « 8D en cours » si déjà lancé), <b>créer une dérogation liée</b> (icône signature), <b>mettre en quarantaine</b> (icône caisse) et, sur les NC de type client, le bouton violet <b>« Retour »</b> — remplacé par un badge vert une fois le retour traité (Avoir AV-…, Cmd P …, ou Refusé).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-nc.png\" alt=\"Capture de l'onglet Non-Conformités\" loading=\"lazy\">\r\n      <figcaption><b>Non-Conformités</b> — les boutons d'action à droite déclenchent tout le circuit aval : 8D, dérogation, quarantaine, retour client.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — déclarer une NC</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouvelle NC »</b>.</li>\r\n      <li>Choisissez la <b>catégorie</b> : « Administratif » ou « Production ». Pour une NC de production, choisissez aussi l'<b>entité</b> (Seem ou Semrac) — une NC administrative n'est pas rattachée à une entité (le champ disparaît).</li>\r\n      <li>Renseignez le type de NC, la gravité, le détecteur, la nature du défaut et de la cause, l'action immédiate, le lot, l'article, le lieu de détection et l'imputation (voir tableau ci-dessous).</li>\r\n      <li>Cochez si besoin <b>« Soumettre à la validation de la Direction »</b> : la NC apparaîtra dans Direction › À valider (automatique en priorité « urgent » pour une gravité Critique ou Bloquante).</li>\r\n      <li>Cliquez sur <b>« Créer NC »</b> : la NC est numérotée et rejoint la liste.</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — traiter un retour client</h3>\r\n    <ol class=\"steps\">\r\n      <li>Sur une NC de <b>type client</b>, cliquez sur <b>« Retour »</b> : la fenêtre « Traiter le retour client » s'ouvre, préremplie (client, référence, lot, nombre de pièces).</li>\r\n      <li>Renseignez le <b>n° de facture</b> et le <b>n° d'affaire</b> — ce dernier sert de base à la numérotation : l'aperçu affiche en direct les futurs numéros <b>AV-AAAA-XXX</b> (avoir) et <b>CMDP-AAAA-XXX</b> (commande prioritaire).</li>\r\n      <li>Saisissez le nombre de <b>pièces NC</b>, le <b>prix de vente unitaire</b> (→ montant de l'avoir, calculé en direct) et/ou le <b>coût de revient unitaire</b> (→ coût de la relance).</li>\r\n      <li>Choisissez la décision : <b>« Refuser le retour »</b>, <b>« Faire un avoir »</b> ou <b>« Commande prioritaire »</b>. L'avoir ou la commande P créés sont visibles dans <b>Commercial › Avoirs &amp; Commandes P</b> ; la décision s'affiche ensuite en badge sur la ligne de NC (le traitement n'est pas rejouable).</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — mettre un objet en quarantaine depuis une NC</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur l'icône caisse (« Mettre un objet en quarantaine ») de la ligne concernée.</li>\r\n      <li>Décrivez l'<b>objet</b> isolé — n'importe quel objet de l'usine : lot, palette, outillage, réception… (champ obligatoire, prérempli depuis la NC), la référence de lot éventuelle et le motif.</li>\r\n      <li>Validez : l'objet apparaît dans l'onglet <b>Quarantaine</b>, où la décision de sortie sera prise.</li>\r\n    </ol>\r\n\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td>Date détection</td><td>Date</td><td>Non</td><td>Jour du constat.</td></tr>\r\n        <tr><td>Type NC</td><td>Liste</td><td>Oui</td><td>Interne, fournisseur, client, procédé… (vocabulaire du référentiel qualité).</td></tr>\r\n        <tr><td>Catégorie</td><td>Administratif / Production</td><td>Oui</td><td>Détermine le filtre de la liste et si une entité est requise.</td></tr>\r\n        <tr><td>Entité</td><td>Seem / Semrac</td><td>Oui si Production</td><td>Site concerné — masqué pour une NC administrative.</td></tr>\r\n        <tr><td>Gravité</td><td>Mineure / Majeure / Critique / Bloquante</td><td>Non (Majeure par défaut)</td><td>Pilote l'urgence ; Critique/Bloquante = priorité « urgent » en validation Direction.</td></tr>\r\n        <tr><td>Détecteur</td><td>Opérateur / Contrôleur / Client / Auditeur / Réception</td><td>Non</td><td>Qui a détecté — détermine le badge d'origine (Auto-BDT, Auto-OAS, Client, Fournisseur, Audit, Manuel).</td></tr>\r\n        <tr><td>Nature de la NC / de la cause</td><td>Listes</td><td>Non</td><td>Vocabulaires contrôlés — alimentent le Pareto du Dashboard.</td></tr>\r\n        <tr><td>Action immédiate / Statut / Responsable</td><td>Listes</td><td>Non</td><td>Suivi du traitement.</td></tr>\r\n        <tr><td>Fournisseur / ST · Client</td><td>Texte</td><td>Non</td><td>Raison sociale selon l'origine — le champ Client active le bouton « Retour ».</td></tr>\r\n        <tr><td>FRC client</td><td>Texte</td><td>Non</td><td>Numéro de la NC dans le système du client.</td></tr>\r\n        <tr><td>LOT concerné · Code article · Désignation</td><td>Texte</td><td>Non</td><td>Rattachement à la production (LOT-2026-XXXX, code nomenclature).</td></tr>\r\n        <tr><td>Poste (lieu de détection) · Imputation</td><td>Listes</td><td>Non</td><td>Où le défaut a été vu, et quel service en porte la responsabilité.</td></tr>\r\n        <tr><td>Description</td><td>Texte libre</td><td>Non</td><td>Constat détaillé.</td></tr>\r\n        <tr><td>Soumettre à la validation de la Direction</td><td>Case à cocher</td><td>Non</td><td>Envoie la NC dans le circuit Direction › À valider.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-qualite-nc.png\" alt=\"Formulaire Nouvelle Non-Conformité\" loading=\"lazy\">\r\n      <figcaption><b>Nouvelle NC</b> — la catégorie conditionne l'affichage du champ Entité ; la case Direction est tout en bas.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Une NC <b>critique ou bloquante</b> sur un lot bloque ses bons de livraison (porte qualité) : l'expédition refusera le BL tant que la NC n'est pas traitée.</li>\r\n      <li>La colonne « Fin traitement » se remplit seule quand le statut devient clôturé/traité ; avant cela elle affiche « en cours ».</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> le traitement d'un retour client est <b>définitif</b> : une fois l'avoir ou la commande P créés, le bouton « Retour » est remplacé par le badge de la décision — impossible de le rejouer.</div>\r\n    <div class=\"astuce\"><b>Astuce :</b> remplissez soigneusement Nature, Cause, Poste et Imputation : ce sont les axes du Pareto du Dashboard Qualité, qui oriente les actions de fond.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 3. RAPPORTS 8D ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-8d\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>Rapports 8D</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Le 8D est la méthode de résolution structurée des problèmes (8 disciplines, exigence EN&nbsp;9100 §10.2). L'onglet liste les rapports en cours et complétés ; la rédaction elle-même se fait sur une <b>page dédiée</b> (<code>/qualite/8d</code>) qui guide pas à pas de D1 à D8. Un rapport peut être ouvert <b>librement</b> ou <b>depuis une NC</b> (bouton « Ouvrir 8D » de l'onglet Non-Conformités).</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>En haut, le bouton <b>« Créer un rapport 8D »</b> ouvre un formulaire de création rapide directement dans la page. En dessous, deux listes : <b>« Rapports 8D à compléter / en cours »</b> (colonnes : N°&nbsp;8D, Problème, Gravité, Client, Responsable, Statut, Avancement, Actions) et <b>« Rapports 8D complétés »</b> (avec la date de clôture et un bouton « Voir »).</p>\r\n    <ul class=\"points\">\r\n      <li>Statuts : <span class=\"b b-info\">Ouvert</span> · <span class=\"b b-warn\">En cours</span> · <span class=\"b b-info\">À valider</span> · <span class=\"b b-ok\">Clôturé</span>.</li>\r\n      <li>La colonne <b>Avancement</b> montre une barre de progression « D<i>x</i>/8 » : le nombre d'étapes D1→D8 réellement renseignées.</li>\r\n      <li>Actions : <b>« Compléter »</b> (ouvre la page 8D du rapport) et <b>✓</b> (marquer le rapport comme complété — il passe dans la liste du bas).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-8d.png\" alt=\"Capture de l'onglet Rapports 8D\" loading=\"lazy\">\r\n      <figcaption><b>Rapports 8D</b> — la barre d'avancement D<i>x</i>/8 indique d'un coup d'œil où en est chaque résolution.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — créer un rapport 8D</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Créer un rapport 8D »</b> : le formulaire se déplie.</li>\r\n      <li>Renseignez le <b>titre du problème</b> (obligatoire), le client concerné, la gravité (Majeure par défaut), le lot / la référence produit, le responsable 8D, la date de détection et la description du problème (trame QQOQCCP).</li>\r\n      <li>Cliquez sur <b>« Créer le rapport 8D »</b> : le rapport est numéroté puis la page dédiée s'ouvre automatiquement pour poursuivre la rédaction.</li>\r\n      <li>Alternative depuis une NC : onglet Non-Conformités → bouton <b>« Ouvrir 8D »</b> — la page 8D s'ouvre préremplie avec les données de la NC.</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — dérouler les 8 disciplines (page /qualite/8d)</h3>\r\n    <p>La page dédiée affiche un <b>fil d'étapes</b> en haut : D1&nbsp;Équipe · D2&nbsp;Problème · D3&nbsp;Inhibition · D4&nbsp;Causes · D5&nbsp;Actions · D6&nbsp;Validation · D7&nbsp;Préventif · D8&nbsp;Clôture. Chaque étape est un écran guidé :</p>\r\n    <ol class=\"steps\">\r\n      <li><b>D1 — Constitution de l'équipe</b> : responsable et membres du groupe de travail.</li>\r\n      <li><b>D2 — Description du problème</b> : trame <b>QQOQCCP</b> (Qui, Quoi, Où, Quand, Comment, Combien, Pourquoi) pour délimiter précisément le périmètre.</li>\r\n      <li><b>D3 — Actions d'inhibition</b> (containment) : mesures immédiates de protection du client, ajoutables ligne à ligne.</li>\r\n      <li><b>D4 — Recherche des causes</b> : diagramme d'<b>Ishikawa 6M</b> puis <b>5 Pourquoi</b> pour remonter à la cause racine.</li>\r\n      <li><b>D5 — Actions correctives permanentes</b> : les actions qui suppriment la cause racine, avec pilote et échéance.</li>\r\n      <li><b>D6 — Validation de l'efficacité</b> : preuve que les actions fonctionnent.</li>\r\n      <li><b>D7 — Actions préventives</b> : généralisation aux produits/process similaires.</li>\r\n      <li><b>D8 — Clôture</b> : liste de vérification récapitulant D1→D7, puis clôture du rapport (il passe dans « Rapports 8D complétés »).</li>\r\n    </ol>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-8d-d1.png\" alt=\"Page 8D, étape D1 équipe\" loading=\"lazy\">\r\n      <figcaption><b>Page 8D — D1</b> — le fil d'étapes D1→D8 en haut permet de naviguer entre les disciplines.</figcaption>\r\n    </figure>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-8d-d5.png\" alt=\"Page 8D, étape D5 actions correctives\" loading=\"lazy\">\r\n      <figcaption><b>Page 8D — D5</b> — les actions correctives permanentes se saisissent avec pilote et échéance.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>L'avancement D<i>x</i>/8 est calculé sur les champs réellement remplis : un rapport « en cours » à D2/8 n'a documenté que l'équipe et le problème.</li>\r\n      <li>Sur une NC dont le 8D est déjà ouvert, le bouton affiche « 8D en cours » : cliquer rouvre le rapport existant, il n'en crée pas un deuxième.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> le bouton <b>✓</b> de la liste permet de clôturer un rapport sans rouvrir la page 8D — pratique quand la validation D8 a été faite en réunion.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 4. DÉROGATIONS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-derogations\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Dérogations</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Quand un produit s'écarte de la définition mais reste potentiellement acceptable, on demande au client une <b>dérogation</b> (formulaire bilingue PMQ3-D3, registre PMQ3-D4). L'onglet suit tout le circuit : rédaction → envoi au client → décision du client (accord total, accord limité, refus) → et, en cas de refus, la suite commerciale (avoir ou commande prioritaire).</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Quatre tuiles KPI : <b>Dérogations</b> (total, registre PMQ3-D4), <b>En cours</b>, <b>Accordées</b> (AT + AL), <b>Refusées</b>. Puis une recherche, le bouton <b>« Nouvelle dérogation »</b> et le tableau : N°&nbsp;/&nbsp;Date, Client / Contact, Désignation, Réf., Type, Décision, Statut, Actions.</p>\r\n    <ul class=\"points\">\r\n      <li>Décision client : <span class=\"b b-ok\">Accord total</span> (AT) · <span class=\"b b-warn\">Accord limité</span> (AL) · <span class=\"b b-crit\">Refus</span> (R) · <span class=\"b b-mut\">en attente</span>.</li>\r\n      <li>Statut du dossier : <span class=\"b b-warn\">En cours</span> · <span class=\"b b-info\">Envoyée (attente)</span> · <span class=\"b b-ok\">Soldée</span> · <span class=\"b b-mut\">Annulée</span>.</li>\r\n      <li>Actions : <b>Traiter le refus</b> (marteau, visible seulement si la décision est « R » et le dossier non soldé), <b>Exporter PDF</b>, <b>Modifier</b>.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-derogations.png\" alt=\"Capture de l'onglet Dérogations\" loading=\"lazy\">\r\n      <figcaption><b>Dérogations</b> — les KPI en tête donnent le solde du registre ; la colonne Décision reflète la réponse du client.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — le circuit complet d'une dérogation</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouvelle dérogation »</b> (ou, depuis une NC, sur l'icône signature : le formulaire s'ouvre prérempli et un bandeau rappelle la NC liée).</li>\r\n      <li>Remplissez les blocs <b>Émetteur</b>, <b>Destinataire</b>, <b>Références</b> et le <b>descriptif</b> de la demande (voir tableau).</li>\r\n      <li>Enregistrez en statut <b>« En cours (brouillon) »</b>, puis exportez le <b>PDF</b> (document bilingue français/anglais avec logo) et envoyez-le au client. Passez alors le statut à <b>« Envoyée au client (attente réponse) »</b>.</li>\r\n      <li>À réception de la réponse, rouvrez la dérogation et saisissez la <b>décision</b> : AT (accord total), AL (accord limité) ou R (refus), puis le statut « Soldée » si le dossier est terminé.</li>\r\n      <li>Si la décision est <b>R — Refus</b> : cliquez sur le bouton marteau <b>« Traiter le refus »</b>. Renseignez le n° d'affaire (base de numérotation — l'aperçu affiche AV-AAAA-XXX et CMDP-AAAA-XXX), le nombre de pièces, le prix de vente unitaire (→ avoir) et/ou le coût de revient unitaire (→ commande P), puis choisissez : <b>Refus sec</b>, <b>Faire un avoir</b> ou <b>Commande P</b>. Le résultat part dans <b>Commercial › Avoirs &amp; Commandes P</b> et la ligne affiche ensuite « ✓ » avec la décision retenue.</li>\r\n    </ol>\r\n\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td>Émetteur : Date, Émise par, Service, Tél., Email</td><td>Texte / date</td><td>Non</td><td>Qui émet la demande (Service prérempli « Qualité », email prérempli qualite@seem-semrac.com).</td></tr>\r\n        <tr><td>Destinataire : Société, Nom, Tél., Email</td><td>Texte</td><td>Client ou désignation requis</td><td>Le client à qui la dérogation est adressée.</td></tr>\r\n        <tr><td>Désignation · Votre Cde · Votre Réf. · AR · Notre Réf. · Quantité</td><td>Texte / nombre</td><td>Non</td><td>Références croisées de la pièce et de la commande concernées.</td></tr>\r\n        <tr><td>Type de demande</td><td>AC / AE / AR</td><td>Non</td><td>Nature de la demande de dérogation.</td></tr>\r\n        <tr><td>Descriptif de la demande</td><td>Texte libre</td><td>Non</td><td>L'écart constaté et la justification — repris tel quel sur le PDF.</td></tr>\r\n        <tr><td>Décision</td><td>— / AT / AL / R</td><td>Non</td><td>Réponse du client (saisie au retour).</td></tr>\r\n        <tr><td>Statut</td><td>En cours / Envoyée / Soldée / Annulée</td><td>Non</td><td>Avancement du dossier.</td></tr>\r\n        <tr><td>Commentaire</td><td>Texte libre</td><td>Non</td><td>Précisions internes ou conditions de l'accord limité.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-qualite-derogation.png\" alt=\"Formulaire de demande de dérogation PMQ3-D3\" loading=\"lazy\">\r\n      <figcaption><b>Formulaire PMQ3-D3</b> — blocs Émetteur / Destinataire / Références / Décision client ; le bandeau rouge signale une dérogation créée depuis une NC.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Une dérogation peut aussi naître de l'onglet <b>Quarantaine</b> (branche « Dérogation » du bouton Statuer) : elle arrive ici préremplie, à compléter puis à envoyer.</li>\r\n      <li>Le traitement d'un refus est <b>idempotent</b> : une fois l'avoir ou la commande P créés, la ligne affiche la décision et le bouton marteau disparaît.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> le bouton « Exporter PDF » du formulaire fonctionne aussi sur un brouillon non enregistré — pratique pour faire relire le document avant envoi.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 5. LIBÉRATION LOTS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-liberation\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Libération Lots</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le <b>contrôle qualité final avant expédition</b>. Un lot apparaît ici dès que <b>tous ses BDT sont soldés</b> : il doit alors passer un <b>PV de libération</b> — libéré, ou bloqué (départ en quarantaine) — avant de pouvoir partir. Une commande n'est expédiable que si <b>tous ses lots</b> sont libérés.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Deux tableaux : <b>« Lots terminés à libérer »</b> et <b>« Lots libérés »</b>, avec les colonnes N°&nbsp;Lot, Pièce, Commande, Qté, Production (nombre de BDT soldés, coche verte) et Action / Statut. Sur un lot à libérer, le bouton violet <b>« PV de libération »</b> ouvre la décision ; sur un lot libéré, le badge <span class=\"b b-ok\">Libéré ✓</span> indique aussi qui a libéré.</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-liberation.png\" alt=\"Capture de l'onglet Libération Lots\" loading=\"lazy\">\r\n      <figcaption><b>Libération Lots</b> — en haut les lots en attente de décision, en bas l'historique des lots libérés.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — libérer (ou bloquer) un lot</h3>\r\n    <ol class=\"steps\">\r\n      <li>Dans « Lots terminés à libérer », cliquez sur <b>« PV de libération »</b> du lot concerné.</li>\r\n      <li>Renseignez éventuellement <b>Cp</b> et <b>Cpk</b> (facultatifs) et vos <b>observations</b> (conformité dimensionnelle, aspect, documents…).</li>\r\n      <li>Choisissez : <b>« Libérer le lot »</b> — un PV est créé, le lot passe dans la liste des libérés et devient expédiable — ou <b>« Bloquer (quarantaine) »</b> — le lot est mis en quarantaine et se traite dans l'onglet Quarantaine.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Tant qu'un seul lot d'une commande n'est pas libéré, l'expédition de la commande reste bloquée côté Expéditions.</li>\r\n      <li>La colonne « Production » confirme le prérequis : le nombre de BDT soldés du lot.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> « Bloquer (quarantaine) » sort le lot du flux d'expédition ; sa remise en circulation exige ensuite une décision explicite dans l'onglet Quarantaine.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 6. QUARANTAINE ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-quarantaine\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">6</span><h2>Quarantaine</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La quarantaine isole tout objet douteux — lot bloqué au contrôle final, palette, outillage, réception fournisseur — en attendant une décision. C'est un flux <b>séparé</b> de la libération : ce qui entre ici (depuis une NC, ou un blocage de libération) doit en sortir par une décision tracée.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Trois tuiles KPI : <b>Lots en quarantaine</b> (en attente de décision), <b>Durée max (jours)</b> (lot le plus ancien), <b>Libérés (total)</b>. Puis le tableau : N°&nbsp;Quarantaine, Lot / Réf., Pièce, Client, Motif, Mise en Q., Durée (j), Statut, Actions. La durée passe en orange au-delà de 2 jours et en rouge au-delà de 5.</p>\r\n    <ul class=\"points\">\r\n      <li>Statuts : <span class=\"b b-warn\">En quarantaine</span> · <span class=\"b b-info\">Validation Direction</span> · <span class=\"b b-ok\">Libéré ✓</span> · <span class=\"b b-info\">Libéré (dérogation)</span> · <span class=\"b b-crit\">Rejeté</span>.</li>\r\n      <li>Sur une ligne « En quarantaine », le bouton violet <b>« Statuer »</b> ouvre la décision de sortie ; une ligne déjà statuée affiche qui a décidé et quand.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-quarantaine.png\" alt=\"Capture de l'onglet Quarantaine\" loading=\"lazy\">\r\n      <figcaption><b>Quarantaine</b> — surveillez la colonne Durée : rouge = plus de 5 jours sans décision.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — statuer la sortie de quarantaine (3 branches)</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Statuer »</b> : la fenêtre affiche l'objet concerné et le champ « Décision par » (prérempli « Qualité »).</li>\r\n      <li><b>Branche 1 — Validation managériale</b> : choisissez la priorité (normale ou critique) et cliquez sur <b>« Soumettre à la Direction »</b>. Le dossier passe en statut « Validation Direction » ; la décision prise par la Direction (dans Direction › À valider) <b>libère ou rejette automatiquement</b> l'objet.</li>\r\n      <li><b>Branche 2 — Dérogation</b> : cliquez sur <b>« Créer une dérogation »</b>. Le lot est libéré <b>sous dérogation</b> et une demande préremplie est créée, à compléter et envoyer depuis l'onglet Dérogations.</li>\r\n      <li><b>Branche 3 — Décision immédiate</b> : saisissez le texte de la décision (ex. « Libéré après retouche », « Rebut », « Accepté en l'état ») puis cliquez sur <b>« Libérer »</b> ou <b>« Rejeter »</b>. Le texte de décision est obligatoire.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Un objet en quarantaine bloque les BL qui le concernent (porte qualité côté Expéditions).</li>\r\n      <li>L'entrée en quarantaine se fait depuis une NC (onglet Non-Conformités) ou par le blocage d'un lot à la libération — pas directement ici.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> réservez la branche « Validation managériale » aux cas à enjeu (client sensible, coût élevé) : la Direction est notifiée et sa décision s'applique sans autre manipulation.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 7. CONTRÔLE DES ECME ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-ecme\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">7</span><h2>Contrôle des ECME</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Cet onglet gère le parc d'<b>Équipements de Contrôle, Mesure &amp; Essai</b> (pieds à coulisse, micromètres, tampons, balances…) : identité de chaque instrument, <b>statut périodique calculé en direct</b> à partir de la prochaine échéance, saisie des <b>PV de vérification</b> (avec calcul automatique des erreurs de justesse Ej et de fidélité Ef) et <b>fiche de vie</b> complète imprimable.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Cinq tuiles KPI : <b>ECME au parc</b> (avec le nombre de vérifications tracées), <b>Valides</b>, <b>À vérifier &lt; 30 j</b>, <b>En retard</b>, <b>Réformés</b>. Dessous, le bandeau <b>« Contrôles à faire »</b> liste sous forme de pastilles cliquables les ECME en retard ou à échéance ≤ 30 jours (actualisé chaque jour) — ou un bandeau vert si tout le parc est dans sa validité. Des filtres (Tous · En retard · À vérifier bientôt · Valides · Réformés) précèdent le tableau : Code, Désignation, Type, Localisation, Périod., Dernière vérif., Prochaine (avec « X j de retard » ou « dans X j »), Statut, Actions.</p>\r\n    <ul class=\"points\">\r\n      <li>Statut <b>live</b> (recalculé à l'affichage, jamais stocké) : <span class=\"b b-ok\">Valide</span> · <span class=\"b b-warn\">À vérifier bientôt</span> (échéance ≤ 30 j) · <span class=\"b b-crit\">En retard</span> · <span class=\"b b-mut\">Réformé</span> · « À planifier » si aucune échéance n'est connue.</li>\r\n      <li>Quatre actions par ligne : <b>Nouvelle vérification (PV)</b> (règle violette), <b>Fiche de vie</b> (document bleu, avec le compteur de vérifications), <b>Modifier l'identité</b> (crayon), <b>Supprimer</b>.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-ecme.png\" alt=\"Capture de l'onglet Contrôle des ECME\" loading=\"lazy\">\r\n      <figcaption><b>Contrôle des ECME</b> — le bandeau « Contrôles à faire » est votre liste de travail du jour : chaque pastille ouvre directement le PV de vérification.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — créer un ECME</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouvel ECME »</b> et renseignez l'identité : code d'identification (ex. « JP 1 »), <b>désignation</b> (obligatoire), type (liste des familles : PC pied à coulisse, JP jauge de profondeur, MI micromètre, tampons filetés, balance…), marque, modèle, n° série, n° de commande d'achat, emplacement, activité (Seem / Semrac), responsable, capacité/étendue, précision, incertitude.</li>\r\n      <li>Indiquez la <b>périodicité</b> (12 mois par défaut), la date de dernière vérification et la mise en service ; pour un étalonnage externe, l'organisme et la référence du certificat.</li>\r\n      <li>Enregistrez : l'ECME rejoint le parc et son statut périodique se calcule aussitôt.</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — saisir un PV de vérification</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur la règle violette (ou sur une pastille du bandeau « Contrôles à faire ») : la fenêtre <b>« PV de vérification »</b> s'ouvre.</li>\r\n      <li>Renseignez la date, l'intervenant, le <b>lieu</b> (interne ou externe), l'étalon utilisé (cale n°), la réf. du PV, l'indice et les interventions réalisées.</li>\r\n      <li>En interne, remplissez la <b>grille de mesures adaptée à la famille</b> de l'instrument : pour un <b>pied à coulisse (PC)</b>, 5 sections de becs avec valeur de cale (Vc) et 3 relevés → la moyenne Vcr et l'écart Ej se calculent seuls ; pour les familles JP, MI, CO, FO, 4 points de mesure avec cote nominale (Cn) et 5 relevés → moyenne MJ et <b>Ej = Cn − MJ</b> calculés automatiquement, <b>Ef</b> = étendue des relevés au point de plus fort écart. Les familles sans grille détaillée se contentent du résultat et de la décision.</li>\r\n      <li><b>Ej et Ef s'affichent automatiquement</b> ; lisez la <b>classe</b> sur votre tableau des écarts et saisissez-la (classe justesse, fidélité, classe retenue) — l'ERP n'invente aucun seuil.</li>\r\n      <li>Choisissez le <b>résultat</b> (B — Bon, M — Moyen, HS — Hors service), la <b>décision</b> (Conforme / Non conforme, avec motif si NC), le visa du responsable et la date « À refaire avant » (proposée automatiquement = date + périodicité).</li>\r\n      <li>Cliquez sur <b>« Enregistrer le PV »</b> : la vérification alimente la fiche de vie et <b>recalcule la prochaine échéance</b> de l'instrument.</li>\r\n    </ol>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-qualite-ecme.png\" alt=\"Formulaire ECME\" loading=\"lazy\">\r\n      <figcaption><b>PV de vérification ECME</b> — la grille de mesures dépend de la famille ; Ej et Ef (encadré violet) se calculent en direct pendant la saisie.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — consulter la fiche de vie</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur l'icône document bleu : la <b>fiche de vie</b> s'ouvre — identité complète de l'instrument + <b>journal des opérations</b> (date, intervenant, lieu, interventions, Ej, Ef, résultat, décision/classe, visa, prochaine échéance).</li>\r\n      <li>Le bouton <b>« PDF »</b> imprime la fiche de vie ; le bouton <b>« Nouvelle vérification »</b> enchaîne directement sur la saisie d'un PV.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le statut n'est <b>jamais figé en base</b> : il se déduit chaque jour de la prochaine échéance — un instrument « Valide » aujourd'hui peut être « À vérifier bientôt » demain.</li>\r\n      <li>Cochez <b>« Réformé »</b> dans l'identité pour sortir définitivement un instrument du service : il quitte les alertes mais reste consultable.</li>\r\n      <li>Pour un étalonnage <b>externe</b>, la grille de mesures est remplacée par les champs organisme + référence du certificat.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> « Supprimer » efface l'ECME <b>et tout son historique</b> de vérifications. Pour un instrument hors service, préférez toujours « Réformé ».</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 8. ÉTUDE DE CAPABILITÉ ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-capabilite\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">8</span><h2>Étude de capabilité</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Cet onglet mesure la <b>capabilité des machines et process</b> de l'atelier (SPC) : chaque contrôle de cote — saisi ici par la Qualité ou par les opérateurs depuis leur BDT — alimente une <b>carte de contrôle aux écarts réduits</b>, qui produit les indices <b>Cp / Cpk</b>, le pourcentage conforme et le PPM. On sait ainsi quelles machines tiennent leurs tolérances.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>À gauche, la liste <b>« Process &amp; machines »</b> avec recherche : chaque ressource porte un badge <span class=\"b b-info\">Machine</span> ou <span class=\"b b-mut\">Manuel</span> et son dernier Cpk (ou « non étudié »). En cliquant sur une ressource, l'espace de travail à droite affiche : l'en-tête (machine liée et sa tolérance par défaut, nombre de contrôles, bouton <b>« Nouveau contrôle »</b>) et trois vues :</p>\r\n    <ul class=\"points\">\r\n      <li><b>Liste des contrôles</b> — colonnes Date, Cote, Pièce, Mesure, Écart réd. (rouge si |écart| &gt; 1), Par (Qualité en violet, opérateur en vert), Conf. — triable par opérateur d'une case à cocher.</li>\r\n      <li><b>Carte complète</b> — la carte aux écarts réduits de <b>tous</b> les contrôles (opérateurs + qualité) : verdict <span class=\"b b-ok\">Capable</span> (Cpk ≥ 1,33) · <span class=\"b b-warn\">Limite</span> (≥ 1) · <span class=\"b b-crit\">Non capable</span> (&lt; 1) · <span class=\"b b-mut\">À étoffer</span>, avec Cp, Cpk, σ réduit, % conforme et PPM. Sur le graphique : point rouge = hors tolérance, violet = contrôle qualité.</li>\r\n      <li><b>Par opérateur</b> — une carte individuelle par contrôleur (et une pour la Qualité), chacune avec son propre Cp/Cpk.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-capabilite.png\" alt=\"Capture de l'onglet Étude de capabilité\" loading=\"lazy\">\r\n      <figcaption><b>Étude de capabilité</b> — sélectionnez une ressource à gauche ; la carte complète donne le verdict Capable / Limite / Non capable de la machine.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — enregistrer un contrôle de cote</h3>\r\n    <ol class=\"steps\">\r\n      <li>Sélectionnez la ressource dans la liste de gauche, puis cliquez sur <b>« Nouveau contrôle »</b>.</li>\r\n      <li>Vérifiez la <b>machine</b>, saisissez la pièce, la <b>cote</b> (ex. Ø12 H7), la valeur <b>nominale</b> et la <b>mesure</b> relevée.</li>\r\n      <li>Les tolérances <b>mini (LSL)</b> et <b>maxi (USL)</b> se préremplissent depuis la tolérance par défaut de la machine — ajustez-les si le plan impose autre chose. Indiquez le contrôleur.</li>\r\n      <li>Cliquez sur <b>« Enregistrer »</b> : le point s'ajoute aux cartes et les indices se recalculent.</li>\r\n    </ol>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-qualite-capabilite.png\" alt=\"Fenêtre Contrôle de cote — Qualité de l'étude de capabilité\" loading=\"lazy\">\r\n      <figcaption><b>Contrôle de cote — Qualité</b> — la <b>Machine</b> est présélectionnée depuis la ressource choisie à gauche ; saisissez Pièce, Cote (ex.&nbsp;Ø12&nbsp;H7), Nominale et Mesure, puis vérifiez le couple <b>Tol.&nbsp;mini (LSL)</b> / <b>Tol.&nbsp;maxi (USL)</b> prérempli. « Enregistrer » ajoute le point à la carte aux écarts réduits et recalcule Cp/Cpk ; le <b>Contrôleur</b> saisi ici détermine la carte individuelle de la vue « Par opérateur ».</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Les contrôles saisis par les <b>opérateurs sur leurs BDT</b> remontent automatiquement sur la machine correspondante : la carte complète agrège tout, toutes pièces confondues.</li>\r\n      <li>La carte travaille en <b>écarts réduits</b> (position de la mesure dans sa tolérance) : c'est ce qui permet de mélanger des pièces et des cotes différentes sur une même machine.</li>\r\n      <li>Cote, nominale, mesure et les deux tolérances sont obligatoires pour enregistrer.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> la vue « Par opérateur » sert aussi à détecter un écart de méthode de mesure : si un seul contrôleur dérive, le problème est plus probablement humain que machine.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 9. PRODUITS PÉRISSABLES ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-perissables\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">9</span><h2>Produits Périssables</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Suivi des produits à durée de vie limitée (colles, résines, produits chimiques…) <b>par lot</b>, conformément au formulaire PRA2-D1 : réception, péremption, date d'alerte, lieu d'utilisation, et consommation en FIFO. Le statut de chaque lot est <b>recalculé automatiquement</b> à partir des dates.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Des bandeaux d'alerte apparaissent si nécessaire : rouge « X lot(s) expiré(s) — retrait immédiat requis » et orange « X lot(s) à renouveler / proches péremption ». Puis des filtres (Tous · Valides · À renouveler · Expirés · Archivés / épuisés), la recherche, le bouton <b>« Nouveau lot »</b> et le tableau : Produit (avec fournisseur et n° de lot fournisseur), Code, Réception, Péremption, Alerte, Lieu, Inventaire (quantité courante / initiale + unité), Sorties, Statut, Actions (Sortie · Modifier · Supprimer).</p>\r\n    <ul class=\"points\">\r\n      <li>Statuts calculés : <span class=\"b b-ok\">Valide ✓</span> · <span class=\"b b-warn\">À renouveler ⚠</span> (date d'alerte atteinte, ou péremption dans ≤ 30 jours) · <span class=\"b b-crit\">Expiré ✗</span> (péremption dépassée — la ligne est surlignée) · <span class=\"b b-mut\">Archivé</span>.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-perissables.png\" alt=\"Capture de l'onglet Produits Périssables\" loading=\"lazy\">\r\n      <figcaption><b>Produits Périssables</b> — les bandeaux d'alerte en tête signalent les lots expirés ou proches de la péremption ; la colonne Inventaire suit la consommation.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — enregistrer un lot puis suivre sa consommation</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouveau lot »</b> et renseignez au minimum le <b>nom du produit</b> (obligatoire), puis les dates (réception, <b>péremption</b>, <b>alerte</b>), les quantités et le lieu (voir tableau).</li>\r\n      <li>Enregistrez : le statut du lot se calcule aussitôt selon les dates saisies.</li>\r\n      <li>À chaque consommation, cliquez sur l'icône <b>Sortie</b> de la ligne : indiquez la quantité sortie (bornée par le reste), la date, le n° de commande client et le motif, puis <b>« Valider la sortie »</b> — l'inventaire courant se décrémente et la sortie s'ajoute au compteur.</li>\r\n    </ol>\r\n\r\n    <div class=\"tbl\"><table>\r\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\r\n      <tbody>\r\n        <tr><td>Produit</td><td>Texte</td><td>Oui</td><td>Nom du produit périssable.</td></tr>\r\n        <tr><td>Code produit</td><td>Texte</td><td>Non</td><td>Référence fabricant.</td></tr>\r\n        <tr><td>Fournisseur</td><td>Texte (aide à la saisie)</td><td>Non</td><td>Choisi dans la liste des fournisseurs connus de l'ERP.</td></tr>\r\n        <tr><td>N° lot fournisseur · N° commande fourn.</td><td>Texte</td><td>Non</td><td>Traçabilité amont du lot.</td></tr>\r\n        <tr><td>Date réception · Date péremption · Date d'alerte</td><td>Dates</td><td>Recommandé</td><td>Les deux dernières pilotent le statut (À renouveler / Expiré).</td></tr>\r\n        <tr><td>Délai appro</td><td>Texte</td><td>Non</td><td>Ex. « 8 semaines » — pour anticiper le renouvellement.</td></tr>\r\n        <tr><td>Lieu d'utilisation</td><td>Texte</td><td>Non</td><td>Zone ou machine où le produit est utilisé.</td></tr>\r\n        <tr><td>Qté initiale · Inventaire courant · Unité</td><td>Nombres / texte</td><td>Non</td><td>Stock du lot (boîtier, L, kg…) — l'inventaire baisse à chaque sortie.</td></tr>\r\n        <tr><td>Observations</td><td>Texte</td><td>Non</td><td>Remarques libres.</td></tr>\r\n      </tbody>\r\n    </table></div>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-qualite-perissable.png\" alt=\"Formulaire Nouveau lot périssable\" loading=\"lazy\">\r\n      <figcaption><b>Nouveau lot périssable</b> — les trois dates (réception, péremption, alerte) déterminent le statut affiché dans la liste.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Un lot <b>expiré</b> doit être retiré immédiatement de l'atelier : c'est une exigence d'audit (préservation du produit).</li>\r\n      <li>La consommation suit la logique <b>FIFO</b> : sortez d'abord le lot le plus ancien.</li>\r\n      <li>Même sans date d'alerte saisie, un lot passe « À renouveler » quand sa péremption est à 30 jours ou moins.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> renseignez la date d'alerte en tenant compte du <b>délai d'approvisionnement</b> : alerte = péremption − délai appro, pour recommander à temps.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 10. PLAN DE CONTRÔLE ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-plan-controle\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">10</span><h2>Plan de contrôle</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Le plan de contrôle (référence PRP1-D9) est le <b>plan d'inspection EN&nbsp;9100 / ISO&nbsp;9001</b> de l'entreprise : pour chaque opération, de la réception au contrôle final, il fixe les paramètres à contrôler, l'ECME ou l'outil à utiliser, la fréquence et l'échantillonnage, le critère d'acceptation (règle <b>C=0</b>, zéro défaut), le responsable, le type de contrôle et le plan de réaction en cas d'écart.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Quatre tuiles KPI : <b>Lignes de contrôle</b>, <b>Opérations couvertes</b>, <b>Avec ECME/outil</b>, <b>Contrôles destructifs</b>. Puis la recherche, les boutons <b>« Exporter PDF »</b> et <b>« Nouvelle ligne »</b>, et le tableau : N°, Opération / Classification, Paramètres, ECME / Outils, Fréquence &amp; échantillon, Critère, Responsable, Type (<span class=\"b b-ok\">Non destructif</span> / <span class=\"b b-warn\">Destructif</span>), Plan de réaction, Actions (Modifier · Supprimer).</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-plan-controle.png\" alt=\"Capture de l'onglet Plan de contrôle\" loading=\"lazy\">\r\n      <figcaption><b>Plan de contrôle</b> — une ligne par opération contrôlée ; l'export PDF produit le document A4 paysage à jour pour les audits.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — ajouter ou modifier une ligne</h3>\r\n    <ol class=\"steps\">\r\n      <li>Cliquez sur <b>« Nouvelle ligne »</b> (ou le crayon d'une ligne existante).</li>\r\n      <li>Renseignez le n° de ligne, l'<b>opération</b> (obligatoire — la liste propose les process de l'atelier), la classification client, les <b>paramètres à contrôler</b>, l'<b>ECME / outil</b> (la liste propose le parc ECME de l'onglet 7), la fréquence &amp; l'échantillonnage, le <b>critère d'acceptation</b> (par défaut « C=0 (Zéro défaut) »), le responsable, le type de contrôle, l'activité (Seem / Semrac) et le <b>plan de réaction</b> en cas d'écart.</li>\r\n      <li>Enregistrez. Pour diffuser le document, cliquez sur <b>« Exporter PDF »</b> : le plan complet s'imprime, trié par n° de ligne, avec le logo et la mention de la règle C=0.</li>\r\n    </ol>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/form-qualite-plan-controle.png\" alt=\"Fenêtre Nouvelle ligne de contrôle du plan de contrôle\" loading=\"lazy\">\r\n      <figcaption><b>Nouvelle ligne de contrôle</b> — la fenêtre reprend exactement les colonnes du tableau : N°&nbsp;ligne, <b>Opération</b> (obligatoire) et Classification client en tête, puis Paramètres à contrôler, <b>ECME&nbsp;/&nbsp;outils</b>, Fréquence &amp; échantillonnage, Critère d'acceptation (« C=0 (Zéro défaut) » par défaut), Responsable, Type de contrôle (Non destructif&nbsp;/&nbsp;Destructif), Activité et <b>Plan de réaction (en cas d'écart)</b>. « Enregistrer » insère la ligne dans le plan et elle part aussitôt dans l'export PDF d'audit.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le champ « Opération » est obligatoire ; nommer l'ECME depuis la liste garantit la cohérence avec le parc réel.</li>\r\n      <li>Le plan de réaction est ce que l'auditeur vérifie en premier : décrivez la conduite à tenir concrète (tri, blocage, NC…).</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> après toute évolution du parc ECME ou d'un process, relisez les lignes concernées — le plan de contrôle doit toujours refléter les moyens réellement disponibles.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 11. AUDIT CONFORMITÉ ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-audit\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">11</span><h2>Audit Conformité</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le module d'<b>audits internes du SMI</b> (système de management intégré) couvrant Qualité (ISO&nbsp;9001 / EN&nbsp;9100), Sécurité (ISO&nbsp;45001), Environnement (ISO&nbsp;14001) et Sécurité de l'information (ISO&nbsp;27001). Il ordonnance le programme annuel, fait réaliser les audits sur des grilles de questions (dont des questions <b>AUTO</b> pré-remplies par l'ERP), transforme les écarts en NC et trace les plans d'action jusqu'à clôture. Quatre sous-onglets : <b>Programme</b>, <b>Constats &amp; plans d'action</b>, <b>Grilles</b>, <b>Référentiels</b>.</p>\r\n\r\n    <h3>Sous-onglet Programme</h3>\r\n    <p>L'ordonnancement annuel (EN&nbsp;9100 §9.2). En haut : le <b>sélecteur d'exercice</b> (une pastille par année), le bouton <b>« Reconduire pour AAAA+1 »</b> et <b>« Nouvelle ligne »</b>. Pour l'exercice affiché : quatre KPI (Lignes au programme, Taux de réalisation, En retard, Plans d'action soldés), puis le <b>calendrier annuel</b> — 12 mois, une case par jour, colorée selon l'état : bleu pâle = aucun audit, bleu foncé = programmé, jaune = pas fait (échéance dépassée), rouge = non conforme (NC ouverte), vert = soldé conforme. Les lignes du programme sont ensuite regroupées en sections : <b>Audits de processus</b> (thèmes A–K), <b>Audits de poste &amp; flash</b> (thèmes T1–T9), <b>Procédés spéciaux</b> (soudure, traitement de surface OAS / Surtec 650, CND…), <b>Exigences client</b>. Colonnes : Entité auditée, Type, Thèmes, Référentiels, Date cible (avec alerte retard), Auditeur, Statut, Actions.</p>\r\n    <ul class=\"points\">\r\n      <li>Statuts d'une ligne : <span class=\"b b-mut\">À planifier</span> · <span class=\"b b-info\">Planifié</span> · <span class=\"b b-warn\">Réalisé</span> · <span class=\"b b-info\">Rapport envoyé</span> · <span class=\"b b-info\">Retour reçu</span> · <span class=\"b b-ok\">Clôturé</span>.</li>\r\n      <li>Actions par ligne : <b>✎ Modifier</b> (date, auditeur, statut, thèmes, référentiels, grille…), <b>fiche d'évaluation</b> (réaliser l'audit), <b>📄 Rapport PDF</b> (téléchargeable <i>seulement une fois l'audit soldé</i>), <b>🗑 Supprimer</b>.</li>\r\n      <li>Le calendrier est interactif : cliquer une case avec audit permet de le consulter ou le <b>déprogrammer</b> ; cliquer une case vide propose d'<b>affecter</b> un audit non programmé (ou d'en déplacer un) à cette date.</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-audit-programme.png\" alt=\"Capture du sous-onglet Programme d'audit\" loading=\"lazy\">\r\n      <figcaption><b>Audit › Programme</b> — le calendrier annuel code l'état de chaque journée d'audit ; les sections regroupent processus, postes et procédés spéciaux.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — réaliser un audit</h3>\r\n    <ol class=\"steps\">\r\n      <li>Sur la ligne du programme, cliquez sur la <b>fiche d'évaluation</b> (icône presse-papiers) : la fiche s'agrandit avec les questions de la grille associée.</li>\r\n      <li>Pour chaque question, cochez <b>Conforme</b> / <b>Non conforme</b> / <b>Axe d'amélioration</b> et saisissez la preuve ou le constat. Les questions en mode <b>AUTO</b> arrivent pré-remplies depuis les sondes de l'ERP (parc ECME, habilitations, DUER, FDS, périssables, VGP, bains, NC ouvertes…) avec leur preuve.</li>\r\n      <li>Ajoutez un constat global si besoin, puis choisissez : <b>« Enregistrer (réalisé) »</b> — l'audit reste modifiable — ou <b>« Solder l'audit »</b> — clôture définitive, le <b>rapport PDF devient téléchargeable</b> sur la ligne.</li>\r\n    </ol>\r\n\r\n    <h3>Pas à pas — reconduire le programme pour l'année suivante</h3>\r\n    <ol class=\"steps\">\r\n      <li>En fin d'exercice, cliquez sur <b>« Reconduire pour AAAA+1 »</b> et confirmez.</li>\r\n      <li>Tout le programme est recopié vers l'année suivante : les dates sont décalées d'un an et les statuts remis à « planifié ».</li>\r\n    </ol>\r\n\r\n    <h3>Sous-onglet Constats &amp; plans d'action</h3>\r\n    <p>Chaque réponse « Non conforme » ou « Axe » des fiches d'évaluation devient un constat listé ici (Audit / entité, Type <span class=\"b b-crit\">NC</span> ou <span class=\"b b-warn\">Axe</span>, Constat, Preuve, Action). Le bouton <b>« Convertir en NC »</b> crée une non-conformité avec le détecteur « Audit » : elle suit alors le cycle normal (8D → clôture) dans l'onglet Non-Conformités ; une fois convertie, le badge <span class=\"b b-ok\">NC …</span> remplace le bouton.</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-audit-constats.png\" alt=\"Capture du sous-onglet Constats et plans d'action\" loading=\"lazy\">\r\n      <figcaption><b>Audit › Constats</b> — chaque écart d'audit se convertit en NC d'un clic ; le suivi se poursuit dans l'onglet Non-Conformités.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Sous-onglet Grilles</h3>\r\n    <p>La bibliothèque de questionnaires réutilisables (issus du classeur qualité : contrôle final, soudure, emballage, informatique…). Chaque grille affiche son titre, sa cible (poste / processus / procédé), son référentiel et ses questions : n°, libellé (avec la preuve attendue), clause (ex. EN&nbsp;9100 §8.5.2), thème, <b>mode</b> (<span class=\"b b-ok\">AUTO</span> · <span class=\"b b-info\">ASSISTÉ</span> · <span class=\"b b-mut\">MANUEL</span>) et <b>sonde ERP</b> pour le mode auto. Boutons : « vierge » (grille imprimable PDF), « + question », ✎ modifier / × supprimer une question, supprimer la grille, et <b>« Nouvelle grille »</b> en tête. Les grilles ne sont pas figées : vous pouvez les enrichir à tout moment.</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-audit-grilles.png\" alt=\"Capture du sous-onglet Grilles d'audit\" loading=\"lazy\">\r\n      <figcaption><b>Audit › Grilles</b> — le mode AUTO relie une question à une sonde ERP : la réponse se pré-remplit toute seule lors de l'audit.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Sous-onglet Référentiels</h3>\r\n    <p>La documentation de référence du module : les <b>thèmes d'audit processus A–K</b> (code, thème, chapitres/clauses, périmètre), les <b>thèmes de poste / terrain T1–T9</b>, et les <b>grilles de conformité clause-par-clause</b> pour l'auto-évaluation, une par norme : ISO&nbsp;9001, EN&nbsp;9100, ISO&nbsp;45001, ISO&nbsp;14001, ISO&nbsp;27001 (boutons de bascule entre normes).</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-audit-ref.png\" alt=\"Capture du sous-onglet Référentiels d'audit\" loading=\"lazy\">\r\n      <figcaption><b>Audit › Référentiels</b> — thèmes A–K et T1–T9, puis les grilles clause-par-clause des cinq normes du SMI.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Le rapport PDF d'un audit n'est disponible qu'une fois l'audit <b>soldé</b> — l'icône reste grisée avant.</li>\r\n      <li>Chaque processus, poste et procédé doit être audité <b>au moins une fois par an</b> (EN&nbsp;9100 §9.2) : la matrice de couverture du Dashboard Qualité montre les trous.</li>\r\n      <li>La « Conformité vive » (surveillance auto-observée des sondes) et le tableau de bord des audits sont dans l'onglet <b>Dashboard Qualité</b>.</li>\r\n    </ul>\r\n    <div class=\"warn\"><b>Attention :</b> « Solder l'audit » est une clôture : la fiche n'est plus modifiable ensuite. Utilisez « Enregistrer (réalisé) » tant que des réponses peuvent encore évoluer.</div>\r\n  </section>\r\n\r\n  <!-- ══════════════ 12. RÉFÉRENTIELS ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-referentiels\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">12</span><h2>Référentiels</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le dictionnaire QHSE de l'entreprise : les <b>vocabulaires contrôlés</b> utilisés partout ailleurs (formulaires de NC, dérogations, sécurité). Source unique partagée entre les services Qualité et Sécurité — on le consulte quand on hésite sur un code ou un terme.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <p>Des cartes de consultation (lecture seule) : <b>Acronymes</b>, <b>Imputation / secteurs</b> (code → service), <b>Types de NC</b>, <b>Types de défaut</b>, <b>Types de cause</b>, <b>Décisions qualité</b>, <b>Dérogations</b> (types de demande et résultats : R = Refus, AT = Accord Total, AL = Accord Limité) et <b>Sécurité</b> (types et secteurs). Les acronymes notés « à confirmer » sont déduits du contexte.</p>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-referentiels.png\" alt=\"Capture de l'onglet Référentiels\" loading=\"lazy\">\r\n      <figcaption><b>Référentiels</b> — le vocabulaire officiel : c'est ici que l'on vérifie la signification d'un code avant de le saisir dans une NC ou une dérogation.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas</h3>\r\n    <ol class=\"steps\">\r\n      <li>Ouvrez l'onglet quand un code ou un acronyme vous échappe (ex. la signification d'une imputation ou d'un type de cause).</li>\r\n      <li>Utilisez les mêmes libellés dans vos saisies : c'est ce qui rend les Pareto et les filtres fiables.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>Onglet en <b>consultation</b> : les listes se retrouvent automatiquement dans les menus déroulants des formulaires (NC, dérogations…).</li>\r\n    </ul>\r\n  </section>\r\n\r\n  <!-- ══════════════ 13. DASHBOARD QUALITÉ ══════════════ -->\r\n  <section class=\"tab\" id=\"tab-dashboard\">\r\n    <div class=\"tab-head\"><span class=\"tab-num\">13</span><h2>Dashboard Qualité</h2></div>\r\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La synthèse chiffrée du service : état des NC, des 8D, de la quarantaine et des PV, analyse Pareto des non-conformités, et le pilotage du programme d'audits avec la <b>« Conformité vive »</b> — une surveillance automatique qui détecte les écarts directement dans les données de l'ERP.</p>\r\n\r\n    <h3>Ce que vous voyez</h3>\r\n    <ul class=\"points\">\r\n      <li>Quatre tuiles KPI : <b>NC ouvertes</b> (dont critiques/bloquantes), <b>Rapports 8D actifs</b>, <b>Lots en quarantaine</b> (avec la durée max), <b>PV validés</b> (sur le total).</li>\r\n      <li><b>Répartition NC par gravité</b> — barres Mineure / Majeure / Critique / Bloquante.</li>\r\n      <li><b>Conformité audits</b> — les derniers audits réalisés avec leur score, et la prochaine échéance.</li>\r\n      <li><b>Pareto des non-conformités</b> — barres triées décroissantes + courbe de % cumulé + seuil 80/20, sur six axes au choix : Nature, Cause (5M), Poste, Imputation, Type NC, Responsable. Sur l'axe <b>Nature</b>, cliquez une grande famille pour <b>zoomer sur ses sous-catégories</b> (bouton « ← toutes familles » pour revenir).</li>\r\n      <li>Section <b>Audits de conformité</b> : KPI (Réalisation du programme, Audits en retard, Items auto conformes, Plans d'action soldés) ; le bandeau <b>Conformité vive</b> — chaque sonde (ECME, habilitations, DUER, FDS, VGP, bains, NC…) affiche une carte <span class=\"b b-ok\">Conforme</span> / <span class=\"b b-crit\">Écart détecté</span> / <span class=\"b b-mut\">Non renseigné</span> avec sa preuve ; un item au rouge signifie que l'ERP n'est pas rempli au bon endroit — le constat s'écrit tout seul.</li>\r\n      <li><b>Matrice de couverture Processus × Thèmes (A–K)</b> — coche verte = audité, point bleu = planifié, « · » = jamais couvert (exhaustivité EN&nbsp;9100 §9.2).</li>\r\n    </ul>\r\n    <figure class=\"shot\">\r\n      <img src=\"../../assets/qualite-dashboard.png\" alt=\"Capture de l'onglet Dashboard Qualité\" loading=\"lazy\">\r\n      <figcaption><b>Dashboard Qualité</b> — le Pareto se pilote par axes ; plus bas, la Conformité vive et la matrice de couverture des audits.</figcaption>\r\n    </figure>\r\n\r\n    <h3>Pas à pas — exploiter le Pareto</h3>\r\n    <ol class=\"steps\">\r\n      <li>Choisissez l'axe d'analyse (Nature, Cause 5M, Poste, Imputation, Type NC, Responsable) avec les pastilles en haut à droite du graphique.</li>\r\n      <li>Repérez les barres à gauche du seuil 80/20 : ce sont les familles qui concentrent l'essentiel des NC.</li>\r\n      <li>Sur l'axe Nature, cliquez une barre pour descendre dans ses sous-catégories et cibler l'action corrective.</li>\r\n    </ol>\r\n\r\n    <h3>Règles &amp; points d'attention</h3>\r\n    <ul class=\"points\">\r\n      <li>La qualité du Pareto dépend directement de la saisie des champs Nature / Cause / Poste / Imputation dans les NC (onglet 2).</li>\r\n      <li>Un « écart » de la Conformité vive n'est pas forcément un problème terrain : c'est d'abord une donnée manquante ou périmée dans l'ERP — corrigez la saisie à la source.</li>\r\n    </ul>\r\n    <div class=\"astuce\"><b>Astuce :</b> avant un audit de certification, passez la Conformité vive au vert et vérifiez la matrice de couverture : ce sont les deux premiers écrans qu'un auditeur comprendra immédiatement.</div>\r\n  </section>\r\n\r\n  <div class=\"docnav\">\r\n    <a href=\"index.html\">← Sommaire des manuels</a>\r\n    <a href=\"expeditions.html\">Manuel suivant : Expéditions →</a>\r\n  </div>\r\n\r\n  <footer class=\"doc\">\r\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\r\n  </footer>\r\n\r\n</div>\r\n</body>\r\n</html>\r\n",
  "rh": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Manuel — RH · ERP Seem Semrac</title>\n<link rel=\"stylesheet\" href=\"manuel.css\">\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header class=\"doc\">\n    <div class=\"brandrow\">\n      <div class=\"logo\">SS</div>\n      <div>\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\n        <div class=\"eyebrow\">Manuel utilisateur</div>\n      </div>\n      <div class=\"kind\">docs/manuel/html</div>\n    </div>\n    <h1>Service <span class=\"hi\">RH</span></h1>\n    <p class=\"lede\">Le service RH tient le registre du personnel et tout ce qui en découle dans l'ERP : la fiche de chaque salarié (qui donne son matricule, son code PIN et donc ses droits d'accès), ses habilitations et certifications, son niveau de compétence par process d'atelier, son rattachement hiérarchique, ses heures et ses congés. Rien n'y est décoratif : un salarié sans fiche ne peut ni pointer, ni solder un bon de travail ; un congé validé ici crée les absences du planning de production ; les heures cumulées ici partent en paie. Le service se parcourt <b>page par page</b> (barre de navigation violette en haut), et non par onglets.</p>\n    <div class=\"metachips\">\n      <span class=\"chip\">👤 Pour qui : <b>RH</b> (écriture) · lecture : Production, Sécurité, Comptabilité</span>\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → RH</b></span>\n      <span class=\"chip\">🗂 <b>7 pages</b></span>\n    </div>\n  </header>\n\n  <nav class=\"toc\">\n    <div class=\"toc-t\">Sommaire</div>\n    <ol>\n      <li><a href=\"#tab-employes\">Employés</a></li>\n      <li><a href=\"#tab-habilitations\">Habilitations &amp; Certifications</a></li>\n      <li><a href=\"#tab-competences\">Matrice Compétences</a></li>\n      <li><a href=\"#tab-organigramme\">Organigramme</a></li>\n      <li><a href=\"#tab-temps\">Gestion des Temps</a></li>\n      <li><a href=\"#tab-dashboard\">Dashboard RH</a></li>\n      <li><a href=\"#tab-pointage\">Système de pointage</a></li>\n    </ol>\n  </nav>\n\n  <!-- ══════════════ 1. EMPLOYÉS ══════════════ -->\n  <section class=\"tab\" id=\"tab-employes\">\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Employés</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le fichier du personnel, et c'est aussi la porte d'entrée dans l'ERP : créer une fiche salarié, c'est lui attribuer un matricule, un code PIN et un ou plusieurs rôles — donc lui ouvrir exactement les écrans dont il a besoin. Toutes les autres pages RH (habilitations, compétences, organigramme, temps, congés) et une bonne partie de l'atelier (pointage, soldage des bons, autocontrôle) s'appuient sur cette liste.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>En haut de page, le compteur <b>« Effectif (N) »</b>, un champ <b>Rechercher…</b> qui filtre la liste au fil de la frappe (nom ou prénom) et le bouton violet <b>« Nouvel employé »</b>. En dessous, l'effectif est découpé en trois blocs, chacun avec son compteur : <b>Opérateurs Seem</b>, <b>Opérateurs Semrac</b> et <b>Fonctions support</b>. Les colonnes sont : ID&nbsp;/&nbsp;Matricule, Nom Prénom (avec l'e-mail en dessous), Rôle, Poste, Contrat, Shift, ERP, Statut et Action.</p>\n    <ul class=\"points\">\n      <li>La colonne <b>ERP</b> affiche une clé : <b>verte</b> = identifiant ERP actif (le salarié a un code PIN, il peut se connecter et pointer) · <b>grise</b> = pas de code PIN, donc pas d'accès.</li>\n      <li>Statut : <span class=\"b b-ok\">actif</span> ou <span class=\"b b-crit\">inactif</span>. Un second badge apparaît sous le statut si la fiche a été soumise à la Direction (décision de validation).</li>\n      <li>Le <b>rôle</b> est affiché en pastille : Opérateur (bleu pour Seem, rose pour Semrac), OAS (opérateur), Qualité, Commercial, Bureau d'Études, Achats, Logistique, Production, Comptable, Maintenance, RH, Direction.</li>\n      <li>Shifts proposés : <b>Matin 6h-14h</b>, <b>Après-midi 14h-22h</b>, <b>Journée 7h-17h</b>, <b>Nuit</b>.</li>\n      <li>Deux boutons par ligne : <b>« Fiche »</b> (ouvre la fiche complète — un clic n'importe où sur la ligne fait la même chose) et la <b>corbeille</b> (supprimer le salarié).</li>\n      <li>Un bandeau jaune <b>« Salariés à rattacher »</b> peut s'afficher au-dessus de la liste : ce sont des noms cités ailleurs dans l'ERP (accidents du travail, dotations EPI, habilitations) mais qui n'ont pas de fiche. Chaque ligne indique la provenance (<span class=\"b b-crit\">accident(s)</span>, <span class=\"b b-info\">EPI</span>, <span class=\"b b-mut\">habilit.</span>) et propose <b>« Créer &amp; rattacher »</b>, qui ouvre une fiche vierge préremplie avec le nom.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/rh-employes.png\" alt=\"Capture de la page Employés\" loading=\"lazy\">\n      <figcaption><b>Employés</b> — l'effectif séparé en Opérateurs Seem / Opérateurs Semrac / Fonctions support ; regardez la colonne ERP (clé) pour savoir qui peut réellement se connecter.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — créer un salarié et lui ouvrir l'accès à l'ERP</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Nouvel employé »</b> : la fiche s'ouvre en fenêtre, vide, avec le bouton « Créer le salarié » en bas.</li>\n      <li>Saisissez le <b>Nom</b> (seul champ réellement obligatoire) et le prénom.</li>\n      <li>Choisissez le <b>Rôle principal</b>. Si vous choisissez <b>Opérateur</b> ou <b>OAS</b>, un champ <b>Activité</b> apparaît pour désigner le site (Seem ou Semrac) ; pour tous les autres rôles ce champ disparaît (le salarié est rattaché aux fonctions support). Sous le bloc « Identifiants ERP », une ligne rappelle en clair les <b>autorisations</b> que le rôle choisi accorde.</li>\n      <li>Complétez le poste, le contrat, le shift et la date d'entrée. Le <b>taux horaire chargé</b> est masqué : <b>maintenez le clic</b> sur le champ pour le révéler ou le saisir (il n'est modifiable qu'avec les droits d'écriture RH).</li>\n      <li>Pour donner des droits qui ne correspondent pas exactement au rôle, utilisez le tableau <b>Accès par service</b> : une case <b>Lire</b> et une case <b>Écrire</b> pour chacun des 15 services. Cocher <b>Écrire</b> coche et verrouille <b>Lire</b> (on n'écrit pas sans lire). <b>Tant que tout est vide</b>, la personne garde exactement les droits de son rôle ; <b>dès qu'une seule case est cochée</b>, ce tableau décide seul de ce qu'elle voit et modifie — y compris pour lui <b>retirer</b> un service que son rôle lui donnait. Deux points à connaître : cela n'a <b>aucun effet</b> sur un compte de rôle Direction (accès total, la fiche vous le rappelle), et les nouveaux droits ne s'appliquent qu'à la <b>prochaine connexion</b> de la personne.</li>\n      <li>Dans le cadre bleu <b>« Identifiants ERP »</b>, renseignez l'<b>Identifiant / Matricule</b> (celui qui sera tapé sur la borne de pointage) et le <b>Code PIN</b>, puis les soldes de congés et de RTT en heures.</li>\n      <li>Renseignez le cadre vert <b>« Données sociales »</b> (sexe, travailleur handicapé, date de sortie) : ces informations alimentent les indicateurs RSE.</li>\n      <li>Dans le cadre jaune <b>« Habilitation requise »</b>, saisissez le <b>matricule</b> et le <b>code PIN d'un responsable RH ou Direction</b> : sans cette double signature, la création est refusée.</li>\n      <li>Cochez si besoin <b>« Soumettre cette fiche à la validation de la Direction »</b> (embauche ou changement de rôle) : la fiche apparaîtra dans <b>Direction › À valider</b>.</li>\n      <li>Cliquez sur <b>« Créer le salarié »</b>. Le message de confirmation indique « Identifiants ERP actifs » et, le cas échéant, le nombre d'enregistrements Sécurité (accidents, EPI, habilitations) automatiquement rattachés à la nouvelle fiche.</li>\n    </ol>\n\n    <h3>Pas à pas — modifier une fiche existante</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur la ligne du salarié (ou sur son bouton <b>« Fiche »</b>).</li>\n      <li>Modifiez les champs voulus. Laisser le <b>Code PIN</b> vide conserve le code actuel ; y saisir une valeur le remplace.</li>\n      <li>Pour désactiver un départ, passez le <b>Statut</b> à « Inactif » et renseignez la <b>date de sortie</b> — la fiche reste consultable mais le salarié sort des listes actives (matrice de compétences, organigramme).</li>\n      <li>Cliquez sur <b>« Enregistrer »</b>. La modification est immédiate ; si vous avez changé le rôle, les droits d'accès du salarié sont recalculés dans la foulée.</li>\n    </ol>\n\n    <div class=\"tbl\"><table>\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n      <tbody>\n        <tr><td>Nom</td><td>Texte</td><td>Oui</td><td>Refus d'enregistrement si vide.</td></tr>\n        <tr><td>Prénom</td><td>Texte</td><td>Non</td><td>Sert à composer le nom affiché partout dans l'ERP.</td></tr>\n        <tr><td>Rôle principal</td><td>Liste (12 rôles)</td><td>Oui</td><td>Fixe le métier, l'entité et le socle d'autorisations dans l'ERP.</td></tr>\n        <tr><td>Activité (opérateur)</td><td>Seem / Semrac</td><td>Oui si Opérateur ou OAS</td><td>Site de rattachement ; le champ est masqué pour les fonctions support.</td></tr>\n        <tr><td>Poste</td><td>Texte</td><td>Non</td><td>Intitulé métier libre (ex. « Usinage CN ») — visible dans l'organigramme.</td></tr>\n        <tr><td>Contrat</td><td>CDI / CDD / Apprenti / Intérim / Stage</td><td>Non (CDI par défaut)</td><td>Nature du contrat.</td></tr>\n        <tr><td>Shift</td><td>Matin / Après-midi / Journée / Nuit</td><td>Non</td><td>Horaire théorique — sert à reconstituer les temps quand il n'y a pas de pointage.</td></tr>\n        <tr><td>Date d'entrée</td><td>Date</td><td>Non</td><td>Date d'embauche (aujourd'hui par défaut).</td></tr>\n        <tr><td>Taux horaire chargé (€/h)</td><td>Nombre, masqué</td><td>Non</td><td>Confidentiel : révélé seulement en maintenant le clic, et seulement avec les droits d'écriture RH. Alimente la masse salariale du Dashboard.</td></tr>\n        <tr><td>E-mail · Téléphone · Adresse</td><td>Texte</td><td>Non</td><td>Coordonnées.</td></tr>\n        <tr><td>Statut</td><td>Actif / Inactif</td><td>Non (Actif par défaut)</td><td>Un salarié inactif disparaît des listes opérationnelles.</td></tr>\n        <tr><td>Accès par service</td><td>Deux cases (Lire / Écrire) × 15 services</td><td>Non</td><td>Affine ou remplace les droits du rôle. Écrire coche et verrouille Lire. Tout vide = droits du rôle ; une seule case cochée = ce tableau décide seul (il peut aussi <b>fermer</b> un service). Sans effet sur un rôle Direction. Prise d'effet à la prochaine connexion de la personne.</td></tr>\n        <tr><td>Identifiant / Matricule</td><td>Texte</td><td>Non mais fortement recommandé</td><td>Identifiant tapé sur la borne de pointage et à la connexion. Si vous ne le renseignez pas, l'ERP en génère un.</td></tr>\n        <tr><td>Code PIN (MDP)</td><td>Chiffres</td><td>Non</td><td>Mot de passe du salarié. Sans PIN, pas de connexion ni de pointage (clé grise dans la liste).</td></tr>\n        <tr><td>Solde congés payés (h)</td><td>Nombre</td><td>Non (175 h par défaut)</td><td>Exprimé en heures — 175 h correspond à 25 jours × 7 h. Décrémenté à chaque congé payé validé.</td></tr>\n        <tr><td>Solde RTT / repos (h)</td><td>Nombre</td><td>Non (0 par défaut)</td><td>Décrémenté à chaque RTT validé.</td></tr>\n        <tr><td>Sexe · Travailleur handicapé (OETH) · Date de sortie</td><td>Listes / Date</td><td>Non</td><td>Données sociales RSE : égalité femmes-hommes, OETH, turnover.</td></tr>\n        <tr><td>Matricule + PIN validateur</td><td>Texte + code</td><td>Oui à la création</td><td>Signature d'un responsable RH ou Direction. Sans elle, la création est refusée.</td></tr>\n        <tr><td>Soumettre à la validation de la Direction</td><td>Case à cocher</td><td>Non</td><td>Envoie la fiche dans le circuit Direction › À valider.</td></tr>\n      </tbody>\n    </table></div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-rh-employe.png\" alt=\"Fenêtre Nouvel employé\" loading=\"lazy\">\n      <figcaption><b>Nouvel employé</b> — le rôle principal en haut à gauche commande l'affichage du champ « Activité » ; les rôles supplémentaires (cases à cocher) cumulent les droits ; le bloc « Identifiants ERP » plus bas contient matricule, PIN et soldes.</figcaption>\n    </figure>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Créer une fiche = ouvrir des droits. Choisissez le rôle avec soin : c'est lui, et lui seul, qui décide des services accessibles (les rôles supplémentaires ne font qu'élargir).</li>\n      <li>Le <b>matricule</b> saisi ici est celui que le salarié tapera sur la borne de pointage et à la connexion : évitez de le changer une fois diffusé.</li>\n      <li>Les soldes de congés sont en <b>heures</b>, pas en jours (base 7 h par jour ouvré).</li>\n      <li>Le bandeau « Salariés à rattacher » signale des données Sécurité orphelines : traitez-le, sinon les accidents et les dotations EPI de ces personnes resteront hors statistiques.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> la <b>suppression</b> d'un salarié est irréversible et libère son matricule. L'ERP demande d'abord une confirmation, puis le <b>matricule</b> et le <b>code PIN</b> d'un valideur RH / Direction. Pour un départ ordinaire, préférez le passage en statut « Inactif » avec une date de sortie : l'historique reste lisible.</div>\n    <div class=\"astuce\"><b>Astuce :</b> la colonne ERP est le meilleur contrôle du lundi matin — une clé grise sur un opérateur signifie qu'il ne pourra ni pointer, ni solder son bon de travail.</div>\n  </section>\n\n  <!-- ══════════════ 2. HABILITATIONS & CERTIFICATIONS ══════════════ -->\n  <section class=\"tab\" id=\"tab-habilitations\">\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Habilitations &amp; Certifications</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le registre des titres détenus par le personnel : habilitations (soudure, pontier, électrique…), diplômes, certifications et formations. En aéronautique, la preuve qu'un opérateur est habilité au moment où il a travaillé est exigible en audit ; cette page tient cette preuve et surveille les dates de fin de validité. Elle est partagée avec la Qualité et la Sécurité, qui y ont aussi accès en écriture.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Trois boutons en haut de page organisent l'écran : <b>« Vue d'ensemble »</b>, <b>« Alertes (N) »</b> — le compteur est le nombre de titres qui ne sont pas valides — et <b>« Ajouter »</b>. En « Vue d'ensemble », une rangée de pastilles filtre par type : <b>Toutes (N)</b>, <b>Habilitations</b>, <b>Certifications</b>, <b>Diplômes</b>, <b>Formations</b>. Le tableau liste : Employé, Type, Intitulé, Organisme, Obtention, Expiration, Statut, Critique, Actions.</p>\n    <ul class=\"points\">\n      <li>Statuts : <span class=\"b b-ok\">Valide</span> · <span class=\"b b-warn\">À renouveler</span> · <span class=\"b b-crit\">Expiré</span>.</li>\n      <li>La colonne <b>Expiration</b> affiche « Illimitée » quand aucune date n'a été saisie, et passe en rouge dès que le titre n'est plus valide.</li>\n      <li>La colonne <b>Critique</b> affiche <b>⚠️ OUI</b> pour les habilitations déclarées critiques au sens EN&nbsp;9100 (celles dont la péremption interdit de produire), « Non » sinon.</li>\n      <li>Deux icônes par ligne : le <b>crayon</b> (modifier) et la <b>corbeille</b> (supprimer).</li>\n      <li>Sous <b>« Alertes »</b>, deux blocs se succèdent : <b>« Habilitations EXPIRÉES — Action immédiate requise »</b> (encadré rouge) puis <b>« À renouveler prochainement »</b> (encadré orange). Chaque carte rappelle le salarié, l'intitulé, l'organisme, la date, le badge <b>CRITIQUE</b> le cas échéant, et porte un bouton <b>« Renouveler »</b>. Si tout est en ordre, un bandeau vert annonce « Aucune alerte ».</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/rh-habilitations.png\" alt=\"Capture de la page Habilitations et Certifications\" loading=\"lazy\">\n      <figcaption><b>Habilitations &amp; Certifications</b> — les trois boutons du haut (Vue d'ensemble / Alertes / Ajouter) commandent la page ; le compteur d'alertes est le premier chiffre à regarder.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — déclarer une habilitation</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Ajouter »</b> : le formulaire s'affiche, vierge.</li>\n      <li>Choisissez le <b>Salarié</b> dans la liste déroulante (obligatoire — une habilitation est toujours rattachée à une fiche salarié).</li>\n      <li>Choisissez le <b>Type</b> : habilitation, diplôme, certification ou formation.</li>\n      <li>Saisissez l'<b>Intitulé</b> (obligatoire), l'<b>Organisme</b> émetteur, la <b>date d'obtention</b> et la <b>date d'expiration</b>.</li>\n      <li>Cochez <b>« Habilitation critique (EN 9100) »</b> si l'absence de ce titre empêche de tenir le poste.</li>\n      <li>Ajoutez éventuellement des <b>Notes</b>, puis cliquez sur <b>« Enregistrer »</b> : le titre rejoint la liste et, s'il est proche de l'échéance, il apparaît immédiatement dans les Alertes et sur le Dashboard RH.</li>\n    </ol>\n\n    <h3>Pas à pas — renouveler un titre expiré</h3>\n    <ol class=\"steps\">\n      <li>Ouvrez <b>« Alertes »</b> et repérez la carte du salarié concerné.</li>\n      <li>Cliquez sur <b>« Renouveler »</b> : le titre repasse en <span class=\"b b-ok\">Valide</span> avec la date du jour comme nouvelle date d'obtention.</li>\n      <li>Rouvrez ensuite la ligne avec le <b>crayon</b> pour saisir la nouvelle <b>date d'expiration</b> et, si elle a changé, l'organisme — sans quoi le titre resterait sans échéance de surveillance.</li>\n    </ol>\n\n    <div class=\"tbl\"><table>\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n      <tbody>\n        <tr><td>Salarié</td><td>Liste des salariés</td><td>Oui</td><td>Rattachement à une fiche existante — créez d'abord la fiche si elle manque.</td></tr>\n        <tr><td>Type</td><td>habilitation / diplome / certification / formation</td><td>Oui</td><td>Détermine la pastille de couleur et le filtre de la liste.</td></tr>\n        <tr><td>Intitulé</td><td>Texte</td><td>Oui</td><td>Libellé exact du titre tel qu'il figure sur l'attestation.</td></tr>\n        <tr><td>Organisme</td><td>Texte</td><td>Non</td><td>Émetteur (organisme de formation, client, interne…).</td></tr>\n        <tr><td>Date obtention</td><td>Date</td><td>Non (aujourd'hui par défaut)</td><td>Point de départ de la validité.</td></tr>\n        <tr><td>Date expiration</td><td>Date</td><td>Non</td><td>Sans date, le titre est considéré comme « Illimitée » et ne déclenche aucune alerte.</td></tr>\n        <tr><td>Habilitation critique (EN 9100)</td><td>Case à cocher</td><td>Non</td><td>Marque le titre comme bloquant : il ressort en rouge dans les alertes et sur le Dashboard.</td></tr>\n        <tr><td>Notes</td><td>Texte libre</td><td>Non</td><td>Numéro d'attestation, restrictions, commentaire d'audit.</td></tr>\n      </tbody>\n    </table></div>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Un titre <b>sans date d'expiration</b> ne sera jamais signalé : ne laissez le champ vide que pour les diplômes réellement définitifs.</li>\n      <li>Les titres non valides remontent automatiquement dans <b>Dashboard RH</b> (tuiles « Habilit. expirées » et « À renouveler ≤30j ») et dans la revue de conformité de la Qualité.</li>\n      <li>Ce registre est le même pour la RH, la Qualité et la Sécurité : ne créez pas de doublon parce que la ligne n'apparaît pas sous le type attendu — vérifiez d'abord avec le filtre « Toutes ».</li>\n    </ul>\n    <div class=\"note\"><b>À savoir :</b> une personne citée dans une habilitation mais absente du fichier du personnel réapparaît dans le bandeau <b>« Salariés à rattacher »</b> de la page Employés. C'est le signe qu'il faut lui créer une fiche.</div>\n  </section>\n\n  <!-- ══════════════ 3. MATRICE COMPÉTENCES ══════════════ -->\n  <section class=\"tab\" id=\"tab-competences\">\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>Matrice Compétences</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est la polyvalence de l'atelier vue d'un seul écran : pour chaque process (tronçonnage, usinage CN, pliage, soudure, montage…), qui sait faire, et à quel niveau. Elle sert à répartir le travail, à repérer les process tenus par une seule personne, et à préparer les plans de formation. C'est aussi une pièce que les auditeurs demandent.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Deux boutons en haut : <b>« Matrice Production »</b> et <b>« Diagramme »</b>. La matrice croise les <b>process d'atelier</b> (en lignes, issus du référentiel Production) et les <b>opérateurs actifs</b> (en colonnes, représentés par une pastille d'initiales — bleue pour Seem, rose pour Semrac, violette pour les deux — avec le prénom en dessous). Chaque case contient le niveau. Un filtre segmenté en haut à droite propose <b>Tous</b>, <b>Seem</b> et <b>Semrac</b> avec leurs compteurs. Sous le tableau, un rappel indique le nombre d'opérateurs actifs et de process affichés.</p>\n    <ul class=\"points\">\n      <li>Légende des niveaux : <span class=\"b b-mut\">— Non formé</span> · <span class=\"b b-warn\">★ En formation</span> · <span class=\"b b-ok\">★★ Autonome</span> · <span class=\"b b-info\">★★★ Expert</span>.</li>\n      <li>Le filtre Seem / Semrac masque à la fois les colonnes et les lignes du site non concerné ; les process communs aux deux sites restent affichés quel que soit le filtre.</li>\n      <li>Seuls les <b>opérateurs actifs</b> apparaissent : une fiche passée en « Inactif » disparaît de la matrice.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/rh-competences.png\" alt=\"Capture de la page Matrice Compétences\" loading=\"lazy\">\n      <figcaption><b>Matrice Compétences</b> — process en lignes, opérateurs en colonnes ; la légende des quatre niveaux est rappelée au-dessus du tableau.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — mettre à jour le niveau d'un opérateur</h3>\n    <ol class=\"steps\">\n      <li>Choisissez le site avec le filtre <b>Tous / Seem / Semrac</b> pour réduire le tableau à ce qui vous intéresse.</li>\n      <li>Repérez la case au croisement du <b>process</b> (ligne) et de l'<b>opérateur</b> (colonne).</li>\n      <li><b>Cliquez sur la case</b> : le niveau avance d'un cran à chaque clic — <b>—</b> → <b>★</b> → <b>★★</b> → <b>★★★</b> → puis retour à <b>—</b>.</li>\n      <li>La sauvegarde est <b>automatique</b> : un message « Niveau enregistré » confirme. En cas de problème réseau, la case revient d'elle-même à sa valeur précédente : recommencez.</li>\n    </ol>\n\n    <h3>Sous-onglet « Diagramme »</h3>\n    <p>Cette seconde vue lit la même donnée à l'envers, <b>par process</b> : une ligne par process, avec à droite les pastilles de tous les opérateurs habilités (niveau ★ ou plus), triés du plus expert au moins expérimenté, et le décompte « N opérateurs habilités ». Quand personne n'est habilité, la ligne affiche en rouge <b>« Aucun opérateur habilité — risque de blocage »</b> : c'est l'alerte la plus utile de la page. En dessous figure l'<b>organigramme des services</b> Seem &amp; Semrac, sous forme arborescente à partir de la Direction Générale.</p>\n    <p>L'ERP se souvient du sous-onglet que vous consultiez : si vous quittez la page en vue « Diagramme », vous la retrouverez en « Diagramme ».</p>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Un clic de trop fait repasser la case de <b>★★★</b> à <b>—</b> : le cycle boucle. Vérifiez toujours l'état final de la case après vos clics.</li>\n      <li>La liste des process vient du <b>référentiel Production</b> : pour ajouter une ligne à la matrice, il faut créer le process côté Production, pas ici.</li>\n      <li>Les process affichant « Aucun opérateur habilité » sont des points de fragilité industrielle : traitez-les en plan de formation avant qu'une absence ne bloque un lot.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> avant de valider un congé long (page Gestion des Temps), passez par le Diagramme : il montre en une ligne s'il reste quelqu'un d'habilité sur les process concernés.</div>\n  </section>\n\n  <!-- ══════════════ 4. ORGANIGRAMME ══════════════ -->\n  <section class=\"tab\" id=\"tab-organigramme\">\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Organigramme</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Cette page dessine la hiérarchie réelle de l'entreprise à partir d'une seule information par salarié : son responsable. Elle sert à situer chacun, à documenter les lignes de reporting pour les audits, et à savoir à qui remonte une demande.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Le titre <b>Organigramme</b>, deux boutons de bascule — <b>« Vue organigramme »</b> et <b>« Liens hiérarchiques »</b> — et, à droite, le compteur <b>« N salariés actifs »</b>. En vue organigramme, l'arbre est composé de cartes reliées par des traits ; chaque carte porte les initiales dans une pastille de couleur, le nom complet, le poste, le badge d'entité (<span class=\"b b-info\">Seem</span>, <span class=\"b b-crit\">Semrac</span> ou <span class=\"b b-mut\">Support</span>) et, s'il y a lieu, le nombre de personnes rattachées. Les salariés sans responsable désigné forment le sommet de l'arbre.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/rh-organigramme.png\" alt=\"Capture de la page Organigramme\" loading=\"lazy\">\n      <figcaption><b>Organigramme</b> — l'arbre se construit tout seul à partir des rattachements ; tant qu'aucun responsable n'est défini, tout le monde apparaît au même niveau.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — construire ou corriger la hiérarchie</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Liens hiérarchiques »</b> : la page bascule sur une liste, une ligne par salarié actif.</li>\n      <li>Sur la ligne du salarié, ouvrez le menu <b>« Responsable : »</b> et choisissez la personne à laquelle il est rattaché. L'option <b>« — Aucun (sommet) — »</b> place le salarié au sommet de l'arbre (typiquement la Direction).</li>\n      <li>Le choix est enregistré <b>immédiatement</b> — le message « Rattachement mis à jour » s'affiche et la page se rafraîchit.</li>\n      <li>Revenez sur <b>« Vue organigramme »</b> pour vérifier le résultat.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Seuls les salariés <b>actifs</b> figurent sur cette page : un départ passé en « Inactif » disparaît de l'arbre.</li>\n      <li>Un salarié ne peut pas être son propre responsable ; l'ERP ignore ce choix.</li>\n      <li>Il n'y a pas de bouton « Enregistrer » : chaque sélection dans un menu déroulant est écrite aussitôt. Ne quittez pas la page en pensant devoir valider.</li>\n      <li>Le poste affiché sur les cartes est celui saisi dans la fiche salarié (page Employés) : pour corriger un libellé, c'est là qu'il faut le faire.</li>\n    </ul>\n    <div class=\"note\"><b>À savoir :</b> l'organigramme <b>par services</b> (Direction Générale → Commercial, Bureau d'Études, Qualité, Production, Maintenance, OAS) est une vue distincte, présentée en bas du sous-onglet « Diagramme » de la Matrice Compétences.</div>\n  </section>\n\n  <!-- ══════════════ 5. GESTION DES TEMPS ══════════════ -->\n  <section class=\"tab\" id=\"tab-temps\">\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Gestion des Temps</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le poste de pilotage des heures et des absences. On y relit les pointages de la journée venus de la borne, on les corrige si nécessaire (avec autorisation), on suit le cumul mensuel de chacun, on traite les demandes de congé — et on exporte le tout vers la paie. Un congé validé ici ne reste pas dans le module RH : il crée les absences du planning de production et rend au pool les bons de travail déjà affectés.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Tout en haut, la barre <b>« Export paie (Silae) »</b> : un sélecteur de mois et le bouton <b>« Exporter CSV »</b>. En dessous, trois boutons organisent l'écran : <b>« Journée (date du jour) »</b>, <b>« Historique »</b> et <b>« Corrections »</b>. La vue « Journée » affiche le tableau des pointages : Employé, Arrivée, Départ, Pause, Heures, Type, Statut, Validé par, Actions, suivi d'une ligne <b>TOTAL JOURNÉE</b>. Un encart bleu rappelle que les pointages proviennent de la page <b>Pointage</b> et que les corrections nécessitent une autorisation. Enfin, deux cartes se partagent le bas de page : <b>« Cumul du mois »</b> et <b>« Absences &amp; congés »</b>.</p>\n    <ul class=\"points\">\n      <li>Statut d'un pointage : <span class=\"b b-info\">En cours</span> (arrivée pointée, pas encore de sortie) · <span class=\"b b-ok\">Validé</span> · <span class=\"b b-warn\">Corrigé</span>.</li>\n      <li>Tant que la personne n'a pas pointé sa sortie, la colonne Départ affiche <b>« En cours »</b> en bleu et les heures ne sont pas encore calculées.</li>\n      <li><b>« Cumul du mois »</b> additionne les heures par salarié et les compare à la base mensuelle de <b>151,67 h</b> : le pourcentage est vert au-delà, orange en dessous.</li>\n      <li>Statuts d'un congé : <span class=\"b b-warn\">En attente</span> · <span class=\"b b-ok\">Validé</span> · <span class=\"b b-crit\">Refusé</span> · <span class=\"b b-mut\">Annulé</span>.</li>\n      <li>Si aucune badgeuse n'a alimenté la journée, l'ERP reconstitue les temps à partir de la <b>présence saisie en Production</b> : l'horaire du shift du salarié est appliqué (6h-14h, 14h-22h, 7h-17h ou nuit), le type affiché est « présence » et la colonne « Validé par » indique « Planning présence ».</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/rh-temps.png\" alt=\"Capture de la page Gestion des Temps\" loading=\"lazy\">\n      <figcaption><b>Gestion des Temps</b> — la barre d'export Silae en haut, les pointages du jour au centre, le cumul mensuel et les congés en bas de page.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — enregistrer et valider une demande de congé</h3>\n    <ol class=\"steps\">\n      <li>Dans la carte <b>« Absences &amp; congés »</b>, bloc <b>« Nouvelle demande »</b>, choisissez le <b>salarié</b> — la liste rappelle son solde d'heures entre parenthèses.</li>\n      <li>Choisissez le <b>type</b> : Congé payé, RTT, Maladie, Sans solde, Événement familial, Formation ou Récupération, et saisissez un motif si utile.</li>\n      <li>Renseignez la <b>date de début</b> et la <b>date de fin</b>. Laissez le champ <b>Heures</b> vide pour laisser l'ERP calculer : jours ouvrés (week-ends exclus) × 7 h.</li>\n      <li>Cliquez sur <b>« Soumettre la demande »</b> : elle apparaît sous <b>« À valider (N) »</b> avec le badge <span class=\"b b-warn\">En attente</span>.</li>\n      <li>Pour trancher, utilisez les deux boutons de la ligne : <b>« Valider »</b> (coche verte) ou <b>refuser</b> (croix rouge).</li>\n      <li>À la validation, l'ERP enchaîne tout seul : il pose <b>une absence par jour ouvré</b> dans le planning de présence, <b>libère les bons de travail</b> déjà affectés à l'opérateur sur la période (ils repartent au pool à réaffecter) et <b>décrémente le solde</b> — congés payés ou RTT selon le type. Le message de confirmation indique le nombre de jours réellement posés.</li>\n    </ol>\n\n    <h3>Pas à pas — corriger un pointage</h3>\n    <ol class=\"steps\">\n      <li>Dans la vue <b>« Journée »</b>, cliquez sur <b>« Modifier »</b> sur la ligne concernée.</li>\n      <li>Saisissez l'<b>heure d'arrivée</b> et/ou l'<b>heure de départ</b> corrigées, puis le <b>Motif</b> (obligatoire — il est tracé).</li>\n      <li>Dans le cadre jaune, saisissez le <b>matricule RH habilité</b> et le <b>code secret</b> : sans cette autorisation, la correction est refusée.</li>\n      <li>Cliquez sur <b>« Valider »</b>.</li>\n      <li>Variante : le bouton <b>« Corrections »</b> en haut de page ouvre un formulaire de <b>demande</b> de correction (employé, date concernée, heures corrigées, autorisation accordée par, motif obligatoire) destiné aux cas traités en différé.</li>\n    </ol>\n\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-rh-correction.png\" alt=\"Fenêtre de correction d'un pointage\" loading=\"lazy\">\n      <figcaption><b>Corriger un pointage</b> — le nom du salarié et la date sont rappelés en tête ; on ne resaisit que l'heure d'arrivée et/ou de départ à rectifier. Le <b>motif</b> est obligatoire et reste tracé, et le cadre jaune du bas (matricule RH habilité + code secret) conditionne l'enregistrement : sans lui, « Valider » refuse la correction. Après validation, la ligne repasse en statut <b>Corrigé</b> dans le tableau de la journée.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — exporter les temps vers la paie</h3>\n    <ol class=\"steps\">\n      <li>En haut de page, choisissez le <b>mois</b> dans le sélecteur « Export paie (Silae) ».</li>\n      <li>Cliquez sur <b>« Exporter CSV »</b> : le fichier <b>silae_temps_AAAA-MM.csv</b> se télécharge.</li>\n      <li>Il contient une ligne par salarié : matricule, nom, prénom, entité, période, <b>heures normales</b>, <b>heures supplémentaires</b>, <b>heures de nuit</b>, <b>jours d'absence</b> et <b>jours de congés</b> — à mapper une fois pour toutes aux rubriques de Silae.</li>\n      <li>Sous « Historique », le bouton <b>« Exporter Excel »</b> propose un export de confort du détail des pointages.</li>\n    </ol>\n\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-rh-conge.png\" alt=\"Bloc Nouvelle demande de congé sur la page Gestion des Temps\" loading=\"lazy\">\n      <figcaption><b>Nouvelle demande de congé</b> — dans la carte « Absences &amp; congés » : salarié, type, motif, dates, puis heures laissées vides pour le calcul automatique ; les demandes en attente s'empilent juste en dessous sous « À valider ».</figcaption>\n    </figure>\n\n    <div class=\"tbl\"><table>\n      <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n      <tbody>\n        <tr><td>Salarié</td><td>Liste</td><td>Oui</td><td>Le solde de congés en heures est rappelé à côté du nom.</td></tr>\n        <tr><td>Type</td><td>Congé payé / RTT / Maladie / Sans solde / Événement familial / Formation / Récupération</td><td>Oui</td><td>Détermine le solde décrémenté (congés payés ou RTT) et la nature de l'absence posée au planning (maladie ou congé).</td></tr>\n        <tr><td>Motif</td><td>Texte</td><td>Non</td><td>Précision libre.</td></tr>\n        <tr><td>Date début · Date fin</td><td>Dates</td><td>Oui</td><td>Bornes incluses ; seuls les jours ouvrés sont comptés.</td></tr>\n        <tr><td>Heures</td><td>Nombre</td><td>Non</td><td>Laissé vide : calcul automatique (jours ouvrés × 7 h). Rempli : votre valeur fait foi.</td></tr>\n      </tbody>\n    </table></div>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Le décompte ignore les <b>samedis et dimanches</b> mais pas les jours fériés : ajustez le champ Heures pour une période qui en contient.</li>\n      <li>La validation d'un congé est le seul geste qui <b>écrit dans le planning de production</b> : ne la faites qu'une fois la décision prise.</li>\n      <li>Si le message de confirmation annonce moins de jours posés que prévu, un avertissement le signale : vérifiez le planning de présence avant de considérer l'absence comme acquise.</li>\n      <li>Les corrections de pointage sont <b>tracées</b> (motif + matricule autorisant) : c'est ce qui rend l'export de paie défendable.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> valider un congé <b>libère les bons de travail</b> affectés à l'opérateur sur la période — ils retournent au pool des bons à affecter. Prévenez la Production, sinon des bons attendront sans titulaire au planning.</div>\n    <div class=\"astuce\"><b>Astuce :</b> lancez l'export Silae en tout début de mois suivant, après avoir purgé les pointages « En cours » (sorties oubliées) via le bouton « Modifier » : une sortie manquante, ce sont des heures absentes du CSV.</div>\n  </section>\n\n  <!-- ══════════════ 6. DASHBOARD RH ══════════════ -->\n  <section class=\"tab\" id=\"tab-dashboard\">\n    <div class=\"tab-head\"><span class=\"tab-num\">6</span><h2>Dashboard RH</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est la page d'accueil du service RH : elle répond en un coup d'œil aux quatre questions du matin — combien de personnes présentes, qui est absent, quelles habilitations sont en péril, et où en est la masse salariale. Elle ne se saisit pas : elle agrège ce qui a été renseigné sur les autres pages.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Cinq tuiles en haut de page, puis deux tableaux côte à côte.</p>\n    <ul class=\"points\">\n      <li><b>Effectif actif</b> — nombre de salariés au statut actif, détaillé en dessous : N Seem · N Semrac · N Admin.</li>\n      <li><b>Absences aujourd'hui</b> — congés et arrêts maladie du jour.</li>\n      <li><b>Habilit. expirées</b> — titres dont la validité est dépassée : <i>action requise urgente</i>.</li>\n      <li><b>À renouveler ≤30j</b> — titres dont l'échéance approche.</li>\n      <li><b>Masse salariale / mois</b> — estimation du brut chargé : somme des taux horaires chargés × 151,67 h.</li>\n      <li><b>« Habilitations à surveiller »</b> — les cinq premiers titres non valides, avec le salarié, l'intitulé (marqué <b>⚠️ CRITIQUE</b> le cas échéant), la date d'expiration et le statut. Quand tout est en règle, un message vert l'annonce.</li>\n      <li><b>« Pointages du jour »</b> — pour la date du jour : employé, arrivée, départ (ou « En cours »), heures, statut, et le total de la journée.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/rh-dashboard.png\" alt=\"Capture du Dashboard RH\" loading=\"lazy\">\n      <figcaption><b>Dashboard RH</b> — les deux tuiles rouge et orange (habilitations expirées / à renouveler) sont celles qui appellent une action ; le détail est juste en dessous.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — la revue quotidienne</h3>\n    <ol class=\"steps\">\n      <li>Regardez la tuile <b>Habilit. expirées</b>. Si elle n'est pas à zéro, ouvrez la page <b>Habilitations &amp; Certifications</b> → bouton <b>« Alertes »</b> et traitez les cartes rouges en priorité.</li>\n      <li>Regardez <b>À renouveler ≤30j</b> : ce sont les formations à programmer maintenant pour éviter la case rouge le mois prochain.</li>\n      <li>Parcourez <b>« Pointages du jour »</b> : une ligne restée « En cours » en fin de journée signale une sortie non pointée, à corriger sur la page <b>Gestion des Temps</b>.</li>\n      <li>Comparez l'<b>Effectif actif</b> aux <b>Absences aujourd'hui</b> pour anticiper la charge d'atelier avec la Production.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>La <b>masse salariale</b> n'est qu'une estimation : elle vaut ce que valent les taux horaires chargés saisis dans les fiches salarié. Une fiche sans taux compte pour zéro.</li>\n      <li>Les chiffres sont calculés à l'ouverture de la page : rechargez-la après une saisie faite sur une autre page RH.</li>\n      <li>Le Dashboard ne corrige rien : chaque tuile est une invitation à ouvrir la page correspondante.</li>\n    </ul>\n  </section>\n\n  <!-- ══════════════ 7. SYSTÈME DE POINTAGE ══════════════ -->\n  <section class=\"tab\" id=\"tab-pointage\">\n    <div class=\"tab-head\"><span class=\"tab-num\">7</span><h2>Système de pointage</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est la <b>borne d'atelier</b> : un écran plein, prévu pour rester allumé sur un poste partagé à l'entrée de la production. Chacun y déclare son arrivée, ses pauses et sa sortie avec son matricule et son code PIN — sans avoir à se connecter à l'ERP. Tout ce qui est badgé ici alimente la page Gestion des Temps, puis l'export de paie. C'est aussi depuis cette borne qu'un salarié peut déposer une demande de congé.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Un écran sombre, sans barre latérale ni menus : une <b>horloge géante</b> qui défile à la seconde, le titre <b>« Terminal de Pointage · Seem Semrac »</b>, la date du jour en toutes lettres et un lien discret <b>« Service RH »</b> en haut à gauche pour revenir à l'ERP. Au centre, quatre grands boutons, puis un bouton pleine largeur pour les congés, et enfin le journal <b>« Derniers pointages du jour »</b>.</p>\n    <ul class=\"points\">\n      <li><b>Arrivée</b> (vert) — <i>Début de service</i>.</li>\n      <li><b>Début Pause</b> (orange) — <i>Pause déjeuner</i>.</li>\n      <li><b>Fin Pause</b> (bleu) — <i>Retour en service</i>.</li>\n      <li><b>Sortie</b> (rouge) — <i>Fin de service</i>.</li>\n      <li><b>« Faire une demande de congé »</b> (bandeau turquoise) — accessible à tous les salariés.</li>\n      <li>Le journal du bas récapitule les passages de la journée, heure par heure, avec le nom et le type d'événement (arrivée en vert, sortie en rouge).</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/rh-pointage.png\" alt=\"Capture de l'écran de pointage\" loading=\"lazy\">\n      <figcaption><b>Système de pointage</b> — écran autonome plein écran : horloge, quatre boutons d'action, demande de congé et journal du jour.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — pointer son arrivée ou sa sortie</h3>\n    <ol class=\"steps\">\n      <li>Appuyez sur le bouton correspondant : <b>Arrivée</b>, <b>Début Pause</b>, <b>Fin Pause</b> ou <b>Sortie</b>.</li>\n      <li>Une fenêtre <b>« Pointage — <i>action</i> »</b> s'ouvre : saisissez votre <b>matricule</b> (il se met automatiquement en majuscules) puis votre <b>code secret</b>.</li>\n      <li>Appuyez sur <b>« Valider le pointage »</b> — ou simplement sur la touche <b>Entrée</b> depuis le champ du code.</li>\n      <li>Le passage s'inscrit aussitôt en haut du journal et un message confirme le nom et l'heure. À la <b>sortie</b>, le message indique en plus le nombre d'heures travaillées : temps entre l'arrivée et la sortie, <b>moins la pause</b> si elle a été badgée.</li>\n    </ol>\n\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-rh-pointage.png\" alt=\"Fenêtre de pointage à la borne : matricule et code secret\" loading=\"lazy\">\n      <figcaption><b>Pointage à la borne</b> — le titre de la fenêtre rappelle l'action badgée (Arrivée, Début Pause, Fin Pause ou Sortie) : vérifiez-le avant de saisir. Deux champs seulement, <b>Matricule</b> (passé automatiquement en majuscules) et <b>Code secret</b> ; la touche <b>Entrée</b> depuis le code équivaut au bouton « Valider le pointage ». Un matricule inconnu ou sans code PIN est refusé ici même.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — demander un congé depuis la borne</h3>\n    <ol class=\"steps\">\n      <li>Appuyez sur <b>« Faire une demande de congé »</b>.</li>\n      <li>Saisissez votre <b>matricule</b> et votre <b>code secret</b> (obligatoires : ils authentifient la demande), puis vos <b>nom</b> et <b>prénom</b>.</li>\n      <li>Choisissez le <b>type</b> — Congé payé, RTT, Maladie, Sans solde ou Autre — et saisissez les <b>dates de début et de fin</b> (obligatoires) ainsi qu'un motif si vous le souhaitez.</li>\n      <li>Appuyez sur <b>« Envoyer la demande »</b>. Le décompte se fait tout seul en jours ouvrés × 7 h, et le message de confirmation indique <b>vers qui</b> part la demande : <b>Production (Présence opérateurs)</b> pour un opérateur, <b>Direction</b> pour une fonction support.</li>\n      <li>La demande apparaît alors dans <b>Gestion des Temps → « À valider »</b> avec le statut <span class=\"b b-warn\">En attente</span>.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li><b>Pas de matricule ou pas de code PIN = pas de pointage.</b> Un salarié refusé à la borne a presque toujours une clé grise dans la colonne ERP de la page Employés : c'est là qu'on lui attribue son PIN.</li>\n      <li>On ne peut pointer son <b>arrivée qu'une fois par jour</b> : une seconde tentative renvoie « a déjà pointé son arrivée aujourd'hui ».</li>\n      <li>Impossible de pointer une pause ou une sortie sans avoir pointé l'arrivée : le message « doit d'abord pointer son arrivée » s'affiche. Dans ce cas, la RH régularise via <b>Gestion des Temps → Modifier</b>.</li>\n      <li>Une <b>sortie oubliée</b> laisse la journée en statut « En cours » et sans heures : elle sera absente de l'export de paie tant qu'elle n'est pas corrigée.</li>\n      <li>La borne n'affiche aucune donnée personnelle au-delà du journal des passages du jour : elle peut rester en libre accès à l'atelier.</li>\n    </ul>\n    <div class=\"note\"><b>À savoir :</b> l'écran de pointage s'ouvre depuis le lien <b>« Système de pointage »</b> tout en bas de la barre latérale de l'ERP, ou directement à l'adresse <code>/rh/pointage</code> — c'est cette adresse qu'il faut mettre en page d'accueil du poste d'atelier.</div>\n    <div class=\"astuce\"><b>Astuce :</b> demandez aux opérateurs de badger aussi <b>Début Pause</b> et <b>Fin Pause</b> : sans elles, la pause n'est pas déduite du calcul et le temps de présence est surestimé.</div>\n  </section>\n\n  <div class=\"docnav\">\n    <a href=\"index.html\">← Sommaire des manuels</a>\n    <a href=\"plans.html\">Manuel suivant : Plan / Bâtiment →</a>\n  </div>\n\n  <footer class=\"doc\">\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\n  </footer>\n\n</div>\n</body>\n</html>\n",
  "securite": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Manuel — Sécurité · ERP Seem Semrac</title>\n<link rel=\"stylesheet\" href=\"manuel.css\">\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header class=\"doc\">\n    <div class=\"brandrow\">\n      <div class=\"logo\">SS</div>\n      <div>\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\n        <div class=\"eyebrow\">Manuel utilisateur</div>\n      </div>\n      <div class=\"kind\">docs/manuel/html</div>\n    </div>\n    <h1>Service <span class=\"hi\">Sécurité</span></h1>\n    <p class=\"lede\">Le service Sécurité regroupe la Santé-Sécurité au Travail (HSE) des deux sites Seem et Semrac : le Document Unique (DUER), les accidents et presqu'accidents, les dotations d'EPI, le risque chimique (FDS + cotation SEIRICH), les vérifications réglementaires (VGP), les formations sécurité et la conformité ISO 45001. Vous y apprendrez à tenir le DUER à jour, à déclarer un événement, à doter un salarié en EPI et à piloter l'inventaire chimique. Le volet environnement (déchets, rejets, ATEX, ISO 14001, RSE) a son propre service : <b>Environnement</b>.</p>\n    <div class=\"metachips\">\n      <span class=\"chip\">👤 Pour qui : <b>Responsable HSE / QSE</b> (écriture via le rôle Qualité ; lecture : BE, Production, OAS, Maintenance, RH)</span>\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Sécurité</b></span>\n      <span class=\"chip\">🗂 <b>9 onglets</b></span>\n    </div>\n  </header>\n\n  <nav class=\"toc\">\n    <div class=\"toc-t\">Sommaire</div>\n    <ol>\n      <li><a href=\"#tab-duer\">DUER / Risques</a></li>\n      <li><a href=\"#tab-evenements\">Événements (accidents, actions, flash)</a></li>\n      <li><a href=\"#tab-epi\">EPI (dotations + matrice EPI × zone)</a></li>\n      <li><a href=\"#tab-chimie\">Chimie / FDS (+ SEIRICH + expositions)</a></li>\n      <li><a href=\"#tab-controles\">Contrôles &amp; prévention (VGP, formations, plans)</a></li>\n      <li><a href=\"#tab-veille\">Veille réglementaire (obligations SST)</a></li>\n      <li><a href=\"#tab-audit\">Audit Conformité (ISO 45001)</a></li>\n      <li><a href=\"#tab-referentiels\">Référentiels</a></li>\n      <li><a href=\"#tab-dashboard\">Tableau de bord</a></li>\n    </ol>\n  </nav>\n\n  <div class=\"note\"><b>Bon à savoir (valable dans tout le service) :</b> chaque liste possède son champ <b>« Rechercher… »</b> (filtre instantané) et chaque ligne porte les boutons <b>Modifier</b> (crayon) et <b>Supprimer</b> (poubelle, avec confirmation). Chaque formulaire de saisie propose en bas la case <b>« Soumettre à la validation de la Direction »</b> : si vous la cochez, l'élément part dans la file « À valider » du service Direction, et une fois la décision rendue un badge apparaît sur la ligne concernée. Les onglets qui gèrent des listes affichent un <b>compteur</b> du nombre d'éléments accessibles.</div>\n\n  <!-- ═══════════════ ONGLET 1 : DUER / RISQUES ═══════════════ -->\n  <section class=\"tab\" id=\"tab-duer\">\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>DUER / Risques</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le <b>Document Unique d'Évaluation des Risques Professionnels</b> (DUERP) de l'entreprise, obligation du Code du travail (art. R.4121-1) : le recensement des dangers <b>par unité de travail</b>, coté et classé par exercice annuel (mise à jour au moins une fois par an, R.4121-2). Les mesures prévues constituent le plan d'action annuel (<b>PAPRIPACT</b>). C'est le point d'entrée de toute la prévention : on y revient après chaque accident, chaque nouvelle machine, chaque nouveau produit chimique.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Un seul grand tableau des risques, précédé d'une barre d'outils : le sélecteur d'exercice <b>« DUERP AAAA »</b> (filtre le tableau sur l'année choisie), le bouton <b>« Imprimer / PDF »</b> (exporte la DUERP de l'exercice au format A4 paysage avec le logo de l'entreprise), le bouton <b>« Générer DUERP N+1 »</b> (reconduction annuelle) et le bouton orange <b>« Nouveau risque »</b>. Colonnes du tableau :</p>\n    <ul class=\"points\">\n      <li><b>Prio</b> — priorité de traitement : <span class=\"b b-crit\">P1</span> (urgent), <span class=\"b b-warn\">P2</span>, <span class=\"b b-ok\">P3</span>.</li>\n      <li><b>Famille</b> — l'une des <b>20 familles de risque INRS ED 840 (2023)</b>, conformité stricte : aucune famille hors nomenclature (chutes de plain-pied, chute de hauteur, circulation interne, produits chimiques, bruit, incendie/explosion, RPS… la liste complète est dans l'onglet Référentiels).</li>\n      <li><b>Unité de travail · Danger</b> — où et quoi (14 unités de travail canoniques : Usinage, Montage, Magasins, Bureaux…).</li>\n      <li><b>G · F · Criticité · Score</b> — gravité (1-4), fréquence (1-4), criticité = gravité × fréquence avec badge couleur (<span class=\"b b-ok\">≤ 4</span>, <span class=\"b b-warn\">5–8</span>, 9–11 orange, <span class=\"b b-crit\">≥ 12</span>) et score brut (méthode Kinney P×F×G×coefficient).</li>\n      <li><b>Responsable · Échéance</b> — le pilote de l'action et sa date limite ; l'échéance passe <span class=\"b b-crit\">en rouge</span> si elle est dépassée, <span class=\"b b-warn\">en jaune</span> si elle tombe dans les 30 jours.</li>\n      <li><b>Statut</b> — <span class=\"b b-crit\">à traiter</span>, <span class=\"b b-warn\">en cours</span>, <span class=\"b b-ok\">maîtrisé</span>.</li>\n      <li><b>Site</b> — Seem ou Semrac.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/securite-duer.png\" alt=\"Capture de l'onglet DUER / Risques\" loading=\"lazy\">\n      <figcaption><b>DUER / Risques</b> — le sélecteur d'exercice et les boutons PDF / Générer N+1 en haut, puis le tableau coté avec les badges de priorité et de criticité.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — ajouter un risque au DUER</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Nouveau risque »</b> : la fenêtre « Risque (DUER) » s'ouvre.</li>\n      <li>Renseignez l'<b>année</b> (exercice), choisissez la <b>famille de risque</b> dans la liste ED 840, l'<b>unité de travail</b> (obligatoire, liste suggérée) et décrivez le <b>danger</b> (obligatoire) puis la situation dangereuse.</li>\n      <li>Cotez : <b>gravité</b>, <b>fréquence</b> et <b>maîtrise</b>, chacune de 1 à 4. La criticité et la priorité se déduisent de la cotation.</li>\n      <li>Décrivez les <b>mesures existantes</b> puis les <b>mesures prévues</b> (c'est le plan d'action / PAPRIPACT), nommez un <b>responsable</b> et fixez une <b>échéance</b>.</li>\n      <li>Laissez le statut « À traiter » et enregistrez. Le risque apparaît dans le tableau de l'exercice ; faites-le vivre en le passant « En cours » puis « Maîtrisé » au fil des actions.</li>\n    </ol>\n\n    <h3>Pas à pas — reconduire le DUER pour l'année suivante</h3>\n    <ol class=\"steps\">\n      <li>Sélectionnez l'exercice source dans la liste <b>« DUERP AAAA »</b>.</li>\n      <li>Cliquez sur <b>« Générer DUERP N+1 »</b> et confirmez. Les dangers et leur cotation sont <b>reconduits</b> ; le plan d'action (PAPRIPACT), les statuts et les échéances repartent <b>à zéro</b> pour le nouvel exercice.</li>\n      <li>Un message confirme « DUERP N+1 créé : X risques reconduits ». Sélectionnez le nouvel exercice et mettez à jour cotations et plans d'action lors de la revue annuelle.</li>\n    </ol>\n\n    <h3>Le formulaire « Risque (DUER) » en détail</h3>\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Année (exercice)</td><td>Nombre</td><td>Non</td><td>Exercice DUERP de rattachement (ex. 2026) ; pilote le filtre du sélecteur d'année.</td></tr>\n          <tr><td>Famille de risque</td><td>Liste déroulante</td><td>Non</td><td>Les 20 familles INRS ED 840 (2023), numérotées 1 à 20.</td></tr>\n          <tr><td>Unité de travail</td><td>Texte + suggestions</td><td><b>Oui</b></td><td>14 unités canoniques proposées (Bureaux, Usinage, Montage, Magasins, Maintenance…).</td></tr>\n          <tr><td>Zone / secteur</td><td>Texte + suggestions</td><td>Non</td><td>Secteur physique de l'atelier (Oxydation, Tôlerie, Usinage, Magasin…).</td></tr>\n          <tr><td>Danger</td><td>Texte</td><td><b>Oui</b></td><td>Le danger identifié (ex. projection de copeaux).</td></tr>\n          <tr><td>Risque résiduel</td><td>Texte</td><td>Non</td><td>Ce qui reste après les mesures existantes.</td></tr>\n          <tr><td>Situation dangereuse</td><td>Texte long</td><td>Non</td><td>Description concrète de l'exposition.</td></tr>\n          <tr><td>Gravité / Fréquence / Maîtrise</td><td>Nombres 1-4</td><td>Non</td><td>La cotation ; criticité = gravité × fréquence.</td></tr>\n          <tr><td>Mesures existantes / Mesures prévues</td><td>Texte long</td><td>Non</td><td>Les mesures prévues alimentent le plan d'action (PAPRIPACT).</td></tr>\n          <tr><td>Responsable · Échéance</td><td>Texte · Date</td><td>Non</td><td>Pilote et date limite de l'action.</td></tr>\n          <tr><td>Statut</td><td>À traiter / En cours / Maîtrisé</td><td>Non</td><td>Avancement du traitement du risque.</td></tr>\n          <tr><td>Site</td><td>Seem / Semrac</td><td>Non</td><td>Site concerné.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-securite-risque.png\" alt=\"Formulaire de saisie d'un risque DUER\" loading=\"lazy\">\n      <figcaption><b>Nouveau risque (DUER)</b> — famille ED 840, unité de travail, cotation 1-4 et plan d'action ; en bas la case « Soumettre à la validation de la Direction ».</figcaption>\n    </figure>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Le DUER est recalé <b>strictement</b> sur les 20 familles ED 840 : ne créez pas de famille « libre », rattachez chaque risque à sa famille de danger (brûlure chimique → famille 7, écran → famille 5, travail isolé → famille 17…).</li>\n      <li>La mise à jour est réglementaire : <b>au moins une fois par an</b> et après tout accident ou changement notable.</li>\n      <li>L'export <b>« Imprimer / PDF »</b> reprend l'exercice sélectionné, colonnes réglementaires incluses (mesures existantes, mesures prévues / PAPRIPACT, responsable, échéance) — c'est le document à présenter en cas de contrôle.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> « Générer DUERP N+1 » remet à zéro plan d'action, statuts et échéances du nouvel exercice — l'exercice source, lui, reste intact. Ne lancez la reconduction qu'une fois par an, en fin d'exercice.</div>\n    <div class=\"astuce\"><b>Astuce :</b> l'évaluation du risque chimique (onglet Chimie / FDS, cotation SEIRICH) alimente le volet « Produits chimiques » du DUER : cotez d'abord vos produits, puis reportez les situations « Élevé » comme risques prioritaires du Document Unique.</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 2 : ÉVÉNEMENTS ═══════════════ -->\n  <section class=\"tab\" id=\"tab-evenements\">\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Événements</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le registre unique des événements sécurité, en <b>trois blocs empilés</b> : les <b>accidents &amp; presqu'accidents</b> (déclaration et enquête), les <b>actions correctives &amp; 5 Pourquoi</b> (traitement des causes) et les <b>flash sécurité</b> (alertes diffusées au personnel). Le compteur de l'onglet cumule les trois listes. Tout ce qui se passe sur le terrain se déclare ici — et alimente les indicateurs TF/TG et le schéma corporel du Tableau de bord.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p><b>Bloc 1 — Accidents &amp; presqu'accidents</b> (bouton <b>« Déclarer »</b>). Colonnes : Date · Type (accident du travail, accident de trajet, maladie professionnelle, presqu'accident, situation dangereuse, soin / premiers secours) · Salarié · Partie du corps · Gravité · Arrêt (badge <span class=\"b b-crit\">N j</span> si arrêt, sinon « non ») · Statut · Site. Statuts du circuit d'enquête : <span class=\"b b-info\">nouveau</span> → <span class=\"b b-warn\">enquête</span> → <span class=\"b b-warn\">actions</span> → <span class=\"b b-mut\">clos</span>. Chaque ligne porte en plus un bouton violet (clé-outil) <b>« Créer une action corrective liée »</b>.</p>\n    <p><b>Bloc 2 — Actions correctives &amp; 5 Pourquoi</b> (bouton <b>« Nouvelle action »</b>). Colonnes : N° · Type (<span class=\"b b-info\">AC</span> action corrective, <span class=\"b b-warn\">PAC</span> presque accident, <span class=\"b b-crit\">SD</span> situation dangereuse) · Date · Secteur · Constat · 5 Pourquoi (la chaîne de causes « pourquoi → pourquoi → … », les 3 premiers affichés) · Action(s) d'éradication · Pilote / délai · Statut (<span class=\"b b-warn\">en cours</span>, <span class=\"b b-ok\">soldé</span>, <span class=\"b b-mut\">annulé</span>).</p>\n    <p><b>Bloc 3 — Flash Sécurité</b> (bouton <b>« Nouveau flash »</b>). Colonnes : N° · Date · Secteur · Description du flash · Mesures · Rédacteur · Statut (Diffusé, En cours, Soldé, À supprimer). Un flash est une alerte courte diffusée à l'ensemble du personnel : consigne, situation à risque, retour d'expérience — daté et tracé jusqu'à clôture.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/securite-evenements.png\" alt=\"Capture de l'onglet Événements\" loading=\"lazy\">\n      <figcaption><b>Événements</b> — les trois blocs empilés : accidents &amp; presqu'accidents, actions correctives avec la colonne 5 Pourquoi, flash sécurité.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — déclarer un accident ou un presqu'accident</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Déclarer »</b> dans le bloc Accidents &amp; presqu'accidents (la date du jour est préremplie).</li>\n      <li>Choisissez le <b>type</b> d'événement, l'heure, le <b>salarié</b> concerné (liste du personnel), la zone et le poste.</li>\n      <li>Précisez la <b>partie du corps</b> touchée et la <b>nature de la lésion</b> — c'est ce champ « Partie du corps » qui nourrit le schéma corporel du Tableau de bord.</li>\n      <li>Cotez la <b>gravité</b> (Bénin, Léger, Grave, Mortel) ; cochez <b>« Avec arrêt »</b> et saisissez les <b>jours d'arrêt</b> le cas échéant (ils alimentent le taux de gravité TG).</li>\n      <li>Complétez la description, les premiers secours prodigués, les témoins et la <b>date de déclaration CPAM</b> — la déclaration doit partir en <b>moins de 48 h</b> pour un accident du travail.</li>\n      <li>Enregistrez avec le statut <span class=\"b b-info\">Nouveau</span>. Menez ensuite l'enquête (statut <span class=\"b b-warn\">Enquête</span>, champ Analyse des causes), lancez les actions (statut <span class=\"b b-warn\">Actions</span>) puis clôturez (<span class=\"b b-mut\">Clos</span>).</li>\n    </ol>\n\n    <h3>Pas à pas — traiter la cause (action corrective liée)</h3>\n    <ol class=\"steps\">\n      <li>Sur la ligne de l'accident, cliquez sur le bouton violet <b>« Créer une action corrective liée »</b> : le formulaire « Action corrective (AC / PAC / SD) » s'ouvre <b>prérempli</b> (type AC, secteur = zone de l'accident, constat = description + salarié + date). Le lien avec l'accident source est conservé.</li>\n      <li>Menez l'analyse <b>5 Pourquoi</b> : dans le champ « Cause racine (5 Pourquoi) », enchaînez les pourquoi jusqu'à la cause racine.</li>\n      <li>Décrivez l'<b>action d'éradication</b>, nommez le <b>pilote</b>, fixez l'<b>échéance</b>, enregistrez.</li>\n      <li>Quand l'action est faite et son <b>efficacité vérifiée</b> (champ dédié), passez le statut à <span class=\"b b-ok\">Soldé</span>.</li>\n    </ol>\n\n    <h3>Le formulaire « Accident / presqu'accident » en détail</h3>\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Type</td><td>Liste déroulante</td><td>Non</td><td>Accident du travail · Accident de trajet · Maladie professionnelle · Presqu'accident · Situation dangereuse · Soin / premiers secours.</td></tr>\n          <tr><td>Date · Heure</td><td>Date · Texte</td><td>Non</td><td>Date préremplie au jour même.</td></tr>\n          <tr><td>Salarié</td><td>Liste du personnel</td><td>Non</td><td>Liste alimentée par le module RH.</td></tr>\n          <tr><td>Zone / secteur · Poste</td><td>Texte + suggestions</td><td>Non</td><td>Lieu de l'événement (secteurs atelier suggérés).</td></tr>\n          <tr><td>Partie du corps · Nature de la lésion</td><td>Texte</td><td>Non</td><td>La partie du corps alimente le schéma corporel du Tableau de bord.</td></tr>\n          <tr><td>Gravité</td><td>Bénin / Léger / Grave / Mortel</td><td>Non</td><td>Cotation de l'événement.</td></tr>\n          <tr><td>Avec arrêt · Jours d'arrêt</td><td>Case + nombre</td><td>Non</td><td>Alimentent les taux TF (fréquence) et TG (gravité).</td></tr>\n          <tr><td>Témoins · Décl. CPAM le</td><td>Texte · Date</td><td>Non</td><td>Traçabilité de la déclaration (délai légal 48 h).</td></tr>\n          <tr><td>Description · Premiers secours · Analyse des causes · Actions correctives</td><td>Texte long</td><td>Non</td><td>Le récit, les soins, l'enquête et les suites.</td></tr>\n          <tr><td>Responsable · Statut · Site</td><td>Texte · Liste · Seem/Semrac</td><td>Non</td><td>Statuts : Nouveau · Enquête · Actions · Clos.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-securite-incident.png\" alt=\"Formulaire de déclaration d'accident\" loading=\"lazy\">\n      <figcaption><b>Déclarer un accident</b> — type, salarié, partie du corps, gravité, arrêt et déclaration CPAM.</figcaption>\n    </figure>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Déclarez <b>aussi</b> les presqu'accidents et situations dangereuses : ce sont les remontées terrain qui évitent le prochain accident (indicateur dédié au Tableau de bord).</li>\n      <li>Un accident du travail se déclare à la CPAM sous <b>48 h</b> : renseignez la date « Décl. CPAM le » comme preuve.</li>\n      <li>Les <b>jours d'arrêt</b> ne comptent dans le TG que si la case « Avec arrêt » est cochée.</li>\n      <li>Un flash sécurité doit rester <b>court et concret</b> : le fait, la consigne, le rédacteur — puis soldez-le une fois la consigne intégrée.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> passez toujours par le bouton « Créer une action corrective liée » plutôt que par « Nouvelle action » quand l'action découle d'un accident : le préremplissage garde la référence de l'accident source, ce qui trace le lien accident → cause → action.</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 3 : EPI ═══════════════ -->\n  <section class=\"tab\" id=\"tab-epi\">\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>EPI</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Deux blocs empilés. Le premier gère les <b>dotations nominatives</b> d'équipements de protection individuelle : qui a reçu quoi, en quelle taille, quand, à quel prix et jusqu'à quelle péremption — c'est la <b>preuve de remise</b> exigée en cas de contrôle ou d'accident. Le second est la <b>matrice EPI × zone</b> : quels équipements sont obligatoires dans quelle zone de l'atelier, complétée des bonnes pratiques sécurité affichées en atelier.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p><b>Bloc 1 — Dotations EPI</b> (boutons <b>« Nouvelle dotation »</b> et <b>« Réappro »</b>, qui ouvre une demande d'achat transmise au service Achats). Colonnes : Salarié · Fourniture / EPI · Taille · Qté · Fournisseur · Marque · Remis le · Péremption (<span class=\"b b-crit\">rouge</span> si dépassée, <span class=\"b b-warn\">jaune</span> si sous 30 jours) · Statut (<span class=\"b b-ok\">en service</span>, <span class=\"b b-warn\">à renouveler</span>, restitué). En dessous, le <b>Catalogue EPI</b> (bouton <b>« Nouvel EPI »</b>) définit les équipements de référence : EPI · Catégorie · Norme EN · Durée de vie (mois) · Réf. stock · Fournisseur.</p>\n    <p><b>Bloc 2 — EPI obligatoires par zone</b> : la matrice croise les 6 EPI de l'atelier (Casque, Lunettes de sécurité, Bouchons d'oreilles, Vêtements de travail, Gants anti-coupure, Chaussures de sécurité) avec les 8 zones physiques (Z1 Dissipation/Tronçonnage, Z2 Oxydation, Z3 Tôlerie, Z4 Bureaux, Z5 Magasin/Expédition, Z6 Collage/Labo, Z7 Montage Puissance, A Allée piétonne). Une coche rouge = EPI obligatoire dans la zone. Suivent les <b>7 bonnes pratiques sécurité</b> (tenue adaptée, chaussures hors zones piéton, protection auditive, lunettes, gants anti-coupure, posture de manutention, demander conseil).</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/securite-epi.png\" alt=\"Capture de l'onglet EPI\" loading=\"lazy\">\n      <figcaption><b>EPI</b> — les dotations nominatives avec leurs péremptions, le catalogue, puis la matrice EPI × zone et les bonnes pratiques.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — doter un salarié</h3>\n    <ol class=\"steps\">\n      <li>Si l'équipement n'existe pas encore au catalogue, créez-le d'abord (<b>« Nouvel EPI »</b> : désignation, catégorie tête/yeux/audition/voies respiratoires/mains/pieds/corps/antichute, norme EN, durée de vie en mois).</li>\n      <li>Cliquez sur <b>« Nouvelle dotation »</b>, choisissez le <b>salarié</b>, puis l'<b>EPI du catalogue</b> (optionnel) ou saisissez une fourniture libre ; précisez le type (EPI ou Matériel).</li>\n      <li>Renseignez taille, quantité, fournisseur, marque, référence et <b>prix</b> (les prix alimentent l'indicateur « Dépenses EPI/matériel » du Tableau de bord).</li>\n      <li>Saisissez la date de <b>remise</b> (préremplie au jour même) et la <b>péremption</b> ; cochez <b>« Signature obtenue »</b> une fois la fiche de remise signée par le salarié.</li>\n      <li>Enregistrez avec le statut <span class=\"b b-ok\">En service</span>. À l'approche de la péremption, la date passe en jaune puis en rouge et l'EPI compte dans la tuile « EPI à renouveler » du Tableau de bord.</li>\n    </ol>\n\n    <h3>Pas à pas — modifier la matrice EPI × zone</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Modifier la matrice »</b> : les cases deviennent cliquables.</li>\n      <li>Cliquez sur chaque case à changer : la coche « obligatoire » se pose ou se retire.</li>\n      <li>Cliquez sur <b>« Sauvegarder »</b> pour enregistrer d'un coup, ou <b>« Annuler »</b> pour tout abandonner. <b>Rien n'est enregistré tant que vous n'avez pas sauvegardé.</b></li>\n    </ol>\n\n    <h3>Le formulaire « Remise EPI / matériel » en détail</h3>\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Salarié</td><td>Liste du personnel</td><td>Non</td><td>Le bénéficiaire de la dotation.</td></tr>\n          <tr><td>EPI du catalogue (optionnel)</td><td>Liste</td><td>Non</td><td>Relie la dotation à un EPI défini au catalogue (norme, durée de vie).</td></tr>\n          <tr><td>Fourniture / EPI (libre)</td><td>Texte</td><td>Non</td><td>Désignation libre si l'article n'est pas au catalogue.</td></tr>\n          <tr><td>Type</td><td>EPI / Matériel</td><td>Non</td><td>Distingue protection individuelle et matériel remis.</td></tr>\n          <tr><td>Taille · Quantité</td><td>Texte · Nombre</td><td>Non</td><td>Ce qui est réellement remis.</td></tr>\n          <tr><td>Fournisseur · Marque · Référence</td><td>Liste · Texte · Texte</td><td>Non</td><td>Traçabilité de l'achat (le fournisseur vient du référentiel Achats).</td></tr>\n          <tr><td>Prix (€)</td><td>Nombre</td><td>Non</td><td>Valorise la dépense EPI de l'année (Tableau de bord).</td></tr>\n          <tr><td>Remis le · Péremption</td><td>Dates</td><td>Non</td><td>La péremption déclenche l'alerte de renouvellement (≤ 30 j).</td></tr>\n          <tr><td>Signature obtenue</td><td>Case à cocher</td><td>Non</td><td>Preuve de remise signée par le salarié.</td></tr>\n          <tr><td>Statut · Site</td><td>En service / À renouveler / Restitué · Seem/Semrac</td><td>Non</td><td>Cycle de vie de la dotation.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-securite-epi.png\" alt=\"Formulaire de dotation EPI\" loading=\"lazy\">\n      <figcaption><b>Nouvelle dotation</b> — salarié, EPI du catalogue, taille, prix, dates de remise et de péremption, case signature.</figcaption>\n    </figure>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>La dotation est <b>nominative</b> : une ligne par salarié et par équipement remis, avec signature — c'est elle qui prouve la remise en cas d'accident.</li>\n      <li>Renseignez systématiquement le <b>prix</b> et le <b>fournisseur</b> : les dotations sans prix et les articles non reliés à un fournisseur sont comptés à part sur le Tableau de bord (« dotation(s) sans prix », « Items sans fournisseur »).</li>\n      <li>Le bouton <b>« Réappro »</b> crée une demande d'achat pré-cadrée côté Achats : utilisez-le dès qu'un stock d'EPI baisse, sans quitter le service.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> en mode édition de la matrice EPI × zone, vos clics ne sont pas enregistrés au fur et à mesure — si vous quittez la page sans cliquer « Sauvegarder », toutes vos modifications sont perdues.</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 4 : CHIMIE / FDS ═══════════════ -->\n  <section class=\"tab\" id=\"tab-chimie\">\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Chimie / FDS</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Trois blocs empilés couvrent tout le risque chimique. D'abord l'<b>inventaire des produits chimiques</b> avec leurs Fiches de Données de Sécurité (FDS, règlement REACH/CLP), pictogrammes et agents CMR. Ensuite la <b>cotation SEIRICH</b> du danger de chaque produit (méthode INRS ND 2233). Enfin l'<b>exposition par situation de travail</b> : le même produit coté là où et comme il est réellement utilisé, sur 3 axes (Santé, Incendie-Explosion avec alerte ATEX, Environnement). C'est la matière première du volet chimique du DUER.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p><b>Bloc 1 — Produits chimiques &amp; FDS</b>, avec trois boutons : <b>« Nouveau produit »</b>, <b>« Pictogrammes »</b> (rappel des pictogrammes CLP/SGH et matrice de compatibilité de stockage : ✗ ne pas stocker ensemble, ● sous conditions, ＋ compatibles) et <b>« Réappro »</b> (demande d'achat). Colonnes : Produit · N° identif. · Réf. produit · Pictos CLP (vignettes) · CMR (badge <span class=\"b b-crit\">rouge</span>) · Quantité · Stockage · FDS (<span class=\"b b-ok\">FDS</span> présente ou <span class=\"b b-crit\">manquante</span>) · Date FDS · Site. Chaque ligne porte quatre actions spécifiques : l'icône <b>fiche produit 360</b> (ouvre la page du produit réunissant danger, cotation SEIRICH, FDS, péremption des lots et stock, avec un PDF fiche produit), l'icône radiation <b>« + exposition SEIRICH »</b> (crée une situation d'exposition préremplie avec ce produit), l'icône PDF <b>« Exporter la fiche FDS »</b> (résumé FDS interne imprimable, avec logo), puis Modifier et Supprimer.</p>\n    <p><b>Bloc 2 — Risque chimique, cotation SEIRICH</b> (bandeau <b>« INDICATIVE — À VALIDER »</b>) : 4 tuiles (Niveau élevé, Niveau moyen, CMR / très toxique, Données incomplètes) puis le tableau : Produit · Dangers (codes H, pictogrammes, badge CMR) · Quantité · Santé · Incendie · Environ. · Priorité. Chaque axe reçoit un niveau <span class=\"b b-ok\">Faible</span>, <span class=\"b b-warn\">Moyen</span> ou <span class=\"b b-crit\">Élevé</span> ; la priorité est le niveau le plus défavorable. Un ⚠ signale les produits sans codes H ni pictogrammes (à compléter dans l'inventaire).</p>\n    <p><b>Bloc 3 — Exposition par situation de travail (SEIRICH intermédiaire)</b> : 4 tuiles (Situations niveau élevé, Niveau moyen, Expositions significatives AES/CMR, Situations ATEX), les boutons <b>« Export SEIRICH »</b> (tableur .xlsx de l'inventaire coté, à recopier dans le logiciel SEIRICH de l'INRS), <b>« Rapport SEIRICH »</b> (rapport PDF d'évaluation en 3 parties : inventaire coté, expositions, plan d'actions) et <b>« Nouvelle exposition »</b>. Colonnes du tableau : Produit (+ badge CMR) · Unité de travail (+ tâche) · Procédé · Protection (+EPI) · Santé · Incendie (+ ⚡ATEX si atmosphère explosive probable) · Environ. · Retenu (le plus défavorable des 3 axes, en gras si exposition significative). Chaque ligne porte un bouton clé-outil <b>« Créer une action corrective (réduire l'exposition) »</b>. En dessous, la <b>matrice produits × unités de travail</b> donne, pour chaque croisement, le niveau retenu le plus élevé.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/securite-chimie.png\" alt=\"Capture de l'onglet Chimie / FDS\" loading=\"lazy\">\n      <figcaption><b>Chimie / FDS</b> — l'inventaire avec pictogrammes CLP et statut FDS, puis la cotation SEIRICH des produits et les expositions par situation de travail.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — référencer un produit chimique</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Nouveau produit »</b> et saisissez le nom (obligatoire), le fournisseur, le n° d'identification et la référence produit.</li>\n      <li>Cliquez sur les <b>tuiles de pictogrammes CLP</b> pour sélectionner ceux de l'étiquette (SGH01 à SGH09) et listez les <b>mentions de danger H/P</b> (séparées par des virgules, ex. H226, H315) : ce sont ces données qui alimentent la cotation SEIRICH.</li>\n      <li>Renseignez la catégorie <b>CMR</b> le cas échéant, la VLEP, la référence et la <b>date de la FDS</b> (et son lien URL si elle est numérisée).</li>\n      <li>Précisez la zone de stockage, la rétention, les compatibilités, la quantité détenue et le statut (En stock / En commande / Périmé), puis enregistrez.</li>\n      <li>Le produit apparaît dans l'inventaire <b>et</b> dans le tableau de cotation SEIRICH juste en dessous, avec son niveau calculé automatiquement.</li>\n    </ol>\n\n    <h3>Pas à pas — coter une situation d'exposition (SEIRICH)</h3>\n    <ol class=\"steps\">\n      <li>Depuis l'inventaire, cliquez sur l'icône radiation du produit concerné (formulaire prérempli) ou sur <b>« Nouvelle exposition »</b>.</li>\n      <li>Indiquez l'<b>unité de travail</b> (obligatoire), la zone et la <b>tâche exposante</b> (ex. dégraissage au pinceau).</li>\n      <li>Décrivez la mise en œuvre : <b>procédé</b> (clos en permanence, clos ouvert régulièrement, à l'air libre, dispersif), <b>quantité mise en œuvre</b> et unité, <b>fréquence</b> (occasionnelle à permanente), <b>état physique / volatilité</b>.</li>\n      <li>Renseignez la <b>protection collective</b> (vase clos, captage à la source, ventilation générale, aucune) et les cases : EPI adapté porté, protection non entretenue, fumée/poussière issue de transformation, non utilisé depuis ≥ 1 an, rejet possible vers l'environnement.</li>\n      <li>Enregistrez : la ligne apparaît cotée sur les 3 axes, avec le niveau <b>Retenu</b> et, le cas échéant, l'alerte ⚡ATEX. Les situations « Élevé » remontent en tête de liste.</li>\n      <li>Pour chaque situation Élevé ou CMR, cliquez sur le bouton clé-outil : l'action corrective préremplie rappelle la priorité <b>STOP</b> (Substituer · Technique : capter à la source · Organiser · Protéger par EPI).</li>\n    </ol>\n\n    <h3>Le formulaire « Produit chimique / FDS » en détail</h3>\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Produit</td><td>Texte</td><td><b>Oui</b></td><td>Nom commercial du produit.</td></tr>\n          <tr><td>Fournisseur</td><td>Liste</td><td>Non</td><td>Référentiel fournisseurs (Achats).</td></tr>\n          <tr><td>N° d'identification · Réf. produit</td><td>Texte</td><td>Non</td><td>Identifiants internes (étiquetage, codes).</td></tr>\n          <tr><td>État</td><td>Liquide / Solide / Gaz-aérosol</td><td>Non</td><td>État physique du produit.</td></tr>\n          <tr><td>Pictogrammes CLP</td><td>Tuiles cliquables SGH01-09</td><td>Non</td><td>Cliquer pour sélectionner ; ils s'affichent dans la liste et sur la fiche PDF.</td></tr>\n          <tr><td>Mentions de danger (H/P)</td><td>Liste (virgules)</td><td>Non</td><td>Codes H et P de l'étiquette — la cotation SEIRICH en dépend.</td></tr>\n          <tr><td>CMR (cat.) · VLEP</td><td>Texte</td><td>Non</td><td>Catégorie CMR et valeur limite d'exposition professionnelle.</td></tr>\n          <tr><td>Réf. FDS · Date FDS · Lien FDS (URL)</td><td>Texte · Date · URL</td><td>Non</td><td>Sans réf. ni lien, le produit est marqué « FDS manquante ».</td></tr>\n          <tr><td>Zone de stockage · Rétention · Compatibilités</td><td>Texte · Case · Texte long</td><td>Non</td><td>Conditions de stockage (voir la matrice « Pictogrammes »).</td></tr>\n          <tr><td>Quantité · Unité</td><td>Nombre · Texte</td><td>Non</td><td>Quantité détenue — entre dans la cotation Phase 1.</td></tr>\n          <tr><td>Statut · Site</td><td>En stock / En commande / Périmé · Seem/Semrac</td><td>Non</td><td>Cycle de vie du produit.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-securite-chimie.png\" alt=\"Formulaire produit chimique avec pictogrammes CLP\" loading=\"lazy\">\n      <figcaption><b>Nouveau produit chimique</b> — les tuiles de pictogrammes CLP cliquables, les mentions H/P et les informations FDS.</figcaption>\n    </figure>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>La cotation SEIRICH est <b>indicative</b> : cote par défaut (méthode simplifiée INRS ND 2233 / R 409) à faire <b>valider par le référent QHSE</b> et à recouper avec le logiciel SEIRICH de l'INRS — utilisez « Export SEIRICH » pour recopier l'inventaire dans l'outil officiel.</li>\n      <li>Un produit sans codes H ni pictogrammes est marqué <b>⚠ données incomplètes</b> et sa cotation n'est pas fiable : complétez d'abord l'inventaire.</li>\n      <li>Les produits <b>CMR</b> sont prioritaires pour la <b>substitution</b> — le plancher de cotation santé leur est appliqué d'office.</li>\n      <li>Le résumé FDS exporté en PDF est un document <b>interne</b> : la FDS officielle du fournisseur fait foi pour les mesures de prévention et d'urgence.</li>\n      <li>Le niveau retenu d'une exposition dépend de la <b>plus grande quantité utilisée dans l'unité de travail</b> : une même quantité peut donc être cotée différemment selon la zone.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> l'icône « fiche produit 360 » ouvre une page dédiée au produit (<i>/securite/chimique/…</i>) qui réunit danger, cotation SEIRICH, FDS, péremption des lots et stock : c'est la page à consulter avant un achat ou lors d'un audit.</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 5 : CONTRÔLES & PRÉVENTION ═══════════════ -->\n  <section class=\"tab\" id=\"tab-controles\">\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Contrôles &amp; prévention</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> Trois blocs empilés pour tout ce qui se planifie et se vérifie : les <b>vérifications générales périodiques</b> (VGP) obligatoires des équipements, les <b>formations sécurité</b> requises par poste (croisées avec les habilitations réellement détenues, module RH) avec les <b>exercices d'évacuation</b>, et les <b>plans de prévention &amp; permis</b> pour les interventions d'entreprises extérieures.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p><b>Bloc 1 — Vérifications périodiques (VGP)</b> (bouton <b>« Nouvelle vérification »</b>) : l'échéancier des contrôles réglementaires — levage, électrique, incendie, ESP (équipements sous pression), portes/portails, racks, ventilation, ATEX. Colonnes : Type · Équipement · Organisme · Contrôle (date) · Prochaine (<span class=\"b b-crit\">rouge</span> si dépassée, <span class=\"b b-warn\">jaune</span> sous 30 jours) · Résultat (<span class=\"b b-ok\">conforme</span>, avec observations, <span class=\"b b-crit\">non conforme</span>) · Statut (<span class=\"b b-ok\">à jour</span>, <span class=\"b b-warn\">à prévoir</span>, <span class=\"b b-crit\">en retard</span>) · Site.</p>\n    <p><b>Bloc 2 — Formations sécurité requises</b> (bouton <b>« Nouveau besoin »</b>) : la matrice des formations obligatoires par poste (accueil, SST, habilitation électrique, CACES, ATEX, gestes &amp; postures…). Colonnes : Poste / famille · Formation · Obligatoire · Périodicité (« N mois » ou « unique ») · Site. Un encart bleu récapitule les certifications et habilitations du module RH et le nombre à renouveler / expirées. Suit la <b>matrice de suivi des formations &amp; habilitations</b> : chaque salarié actif × chaque formation requise pour son poste, avec un symbole par case (✓ valide · ⚠ à renouveler · ⏱ expirée · ✗ manquante · — non requise) et un <b>% de couverture</b> par salarié et global. Puis les <b>Exercices d'évacuation / incendie</b> (bouton <b>« Nouvel exercice »</b>) : Date · Type (évacuation, incendie, POI) · Site · Participants · Durée · Conforme.</p>\n    <p><b>Bloc 3 — Plans de prévention &amp; permis</b> (bouton <b>« Nouveau document »</b>) : plans de prévention (entreprises extérieures, décret 92-158), protocoles de sécurité chargement/déchargement et permis de feu. Colonnes : Type · Entreprise ext. · Opération · Début · Fin · Statut (<span class=\"b b-warn\">en cours</span>, <span class=\"b b-mut\">clos</span>) · Site.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/securite-controles.png\" alt=\"Capture de l'onglet Contrôles et prévention\" loading=\"lazy\">\n      <figcaption><b>Contrôles &amp; prévention</b> — l'échéancier VGP avec les échéances colorées, la matrice formations × salariés, les exercices et les plans de prévention.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — enregistrer une vérification périodique (VGP)</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Nouvelle vérification »</b>, choisissez le <b>type</b> (levage, électrique, incendie, ESP, portes/portails, racks, ventilation, ATEX) et nommez l'<b>équipement</b> (obligatoire) ; reliez-le à une <b>machine</b> du parc si elle existe dans l'ERP.</li>\n      <li>Indiquez l'<b>organisme</b> vérificateur, la <b>date du contrôle</b> et la <b>prochaine échéance</b> (ou la périodicité en mois).</li>\n      <li>Saisissez le <b>résultat</b> (Conforme / Avec observations / Non conforme), les <b>levées de réserves</b> éventuelles et le lien vers le rapport.</li>\n      <li>Enregistrez avec le statut adéquat (À jour / À prévoir / En retard). Les VGP dont l'échéance est dépassée comptent dans la tuile <b>« VGP en retard »</b> du Tableau de bord.</li>\n    </ol>\n\n    <h3>Pas à pas — suivre les formations sécurité</h3>\n    <ol class=\"steps\">\n      <li>Déclarez chaque besoin avec <b>« Nouveau besoin »</b> : poste / famille (obligatoire), formation (obligatoire), obligatoire ou non, périodicité de recyclage en mois (vide = formation unique).</li>\n      <li>Consultez la <b>matrice de suivi</b> : elle croise automatiquement ces besoins avec les certifications / habilitations saisies dans <b>RH › Habilitations &amp; Certifications</b> — survolez l'en-tête d'une colonne pour le détail (poste, recyclage).</li>\n      <li>Traitez les ✗ (manquantes) et ⏱ (expirées) en planifiant les formations côté RH : la matrice se met à jour d'elle-même, la couverture remonte.</li>\n      <li>Après chaque exercice d'évacuation ou d'incendie, tracez-le avec <b>« Nouvel exercice »</b> (date, participants, durée, scénario, conformité).</li>\n    </ol>\n\n    <h3>Le formulaire « Vérification périodique (VGP) » en détail</h3>\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Type</td><td>Liste déroulante</td><td>Non</td><td>Levage · Électrique · Incendie · ESP (sous pression) · Portes/portails · Racks · Ventilation · ATEX.</td></tr>\n          <tr><td>Équipement</td><td>Texte</td><td><b>Oui</b></td><td>L'équipement vérifié (pont roulant, armoire électrique…).</td></tr>\n          <tr><td>Machine liée</td><td>Liste du parc machines</td><td>Non</td><td>Relie la VGP à une machine de l'ERP (Production/Maintenance).</td></tr>\n          <tr><td>Organisme</td><td>Texte</td><td>Non</td><td>Organisme de contrôle agréé.</td></tr>\n          <tr><td>Date contrôle · Prochaine échéance · Périodicité (mois)</td><td>Dates · Nombre</td><td>Non</td><td>L'échéancier ; l'échéance dépassée passe en rouge.</td></tr>\n          <tr><td>Résultat</td><td>Conforme / Avec observations / Non conforme</td><td>Non</td><td>Conclusion du rapport de vérification.</td></tr>\n          <tr><td>Levée des réserves</td><td>Texte long</td><td>Non</td><td>Suivi des observations jusqu'à leur levée.</td></tr>\n          <tr><td>Lien rapport (URL)</td><td>URL</td><td>Non</td><td>Rapport numérisé de l'organisme.</td></tr>\n          <tr><td>Statut · Site</td><td>À jour / À prévoir / En retard · Seem/Semrac</td><td>Non</td><td>État de l'échéancier.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-securite-vgp.png\" alt=\"Formulaire de vérification périodique VGP\" loading=\"lazy\">\n      <figcaption><b>Nouvelle vérification (VGP)</b> — type, équipement, organisme, dates de contrôle et prochaine échéance, résultat.</figcaption>\n    </figure>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Les enregistrements réels de formation (dates, organismes, attestations) vivent dans <b>RH › Habilitations &amp; Certifications</b> ; cet onglet définit les <b>besoins</b> par poste et en mesure la couverture.</li>\n      <li>Une VGP « Non conforme » appelle une <b>levée de réserves</b> tracée — ne la passez « À jour » qu'une fois les réserves levées.</li>\n      <li>Un plan de prévention se rédige <b>avant</b> l'intervention de l'entreprise extérieure ; un permis de feu avant tout travail par point chaud.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> la matrice formations reconnaît les intitulés (SST, CACES, habilitation électrique, ATEX, hauteur, gestes &amp; postures, chimique, incendie/évacuation, pontier-élingueur, accueil) : nommez vos besoins avec ces mots-clés pour que le croisement avec les certifications RH se fasse tout seul.</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 6 : VEILLE RÉGLEMENTAIRE ═══════════════ -->\n  <section class=\"tab\" id=\"tab-veille\">\n    <div class=\"tab-head\"><span class=\"tab-num\">6</span><h2>Veille réglementaire</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le <b>registre des obligations</b> qui s'imposent à l'entreprise en santé-sécurité : Code du travail, REACH-CLP, risque chimique, ISO 45001, ISO 9001, EN 9100. Pour chacune, on dit si elle nous est applicable, où on en est, qui en répond et quand il faut la revérifier. C'est la checklist que l'on présente à l'<b>inspection du travail</b> et à la <b>CARSAT</b>.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Un tableau unique et son bouton <b>« Nouvelle obligation »</b>. Colonnes : <b>Domaine</b> · <b>Obligation</b> · <b>Référence</b> réglementaire · <b>Échéance</b> (surlignée en rouge si dépassée) · <b>Responsable</b> · <b>Statut</b> — <span class=\"b b-info\">à vérifier</span>, <span class=\"b b-ok\">conforme</span>, <span class=\"b b-warn\">partiel</span>, <span class=\"b b-crit\">non conforme</span>.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/securite-veille.png\" alt=\"Capture de l'onglet Veille réglementaire\" loading=\"lazy\">\n      <figcaption><b>Veille réglementaire</b> — la matrice de conformité SST : une ligne par obligation, son statut, son responsable et son échéance de revérification.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — tenir la matrice de conformité</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Nouvelle obligation »</b>.</li>\n      <li>Choisissez le <b>domaine</b> (Code du travail, Risque chimique, ISO 45001, ISO 9001, EN 9100), décrivez l'<b>obligation</b> (obligatoire) et sa <b>référence réglementaire</b>.</li>\n      <li>Cochez <b>« Applicable »</b>, positionnez le <b>statut</b> (À vérifier / Conforme / Partiel / Non conforme / Non applicable), datez le <b>dernier contrôle</b> et fixez l'<b>échéance</b> de la prochaine vérification.</li>\n      <li>Nommez un <b>responsable</b> et joignez la <b>preuve</b> (URL du document).</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Les obligations <b>non conformes ou échues</b> alimentent la tuile <b>« Alertes conformité »</b> du Tableau de bord.</li>\n      <li>Chaque obligation gagne à porter une <b>preuve</b> (rapport, registre, attestation) : c'est exactement ce que demandent l'inspection du travail et la CARSAT.</li>\n      <li>La conformité <b>environnementale</b> (ICPE, ISO 14001, ATEX, RSE) ne se gère pas ici : elle est dans le service <b>Environnement</b>, onglet <b>Veille réglementaire</b>, avec la même mécanique.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> passez la matrice en revue à échéances fixes (revue de direction, préparation d'audit) en triant par la colonne Échéance grâce au champ Rechercher — les échues sont surlignées en rouge.</div>\n  </section>\n\n  <!-- ═══════════════ ONGLET 7 : AUDIT CONFORMITÉ ═══════════════ -->\n  <section class=\"tab\" id=\"tab-audit\">\n    <div class=\"tab-head\"><span class=\"tab-num\">7</span><h2>Audit Conformité</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le cycle d'<b>audit interne</b> appliqué à la santé-sécurité : on ordonnance les audits ISO 45001 de l'année, on les réalise, on consigne les écarts et on solde les plans d'action. Cet onglet est <b>identique à celui de la Qualité et de l'Environnement</b> — mêmes quatre sous-onglets, même planning, seul le filtre normatif change (ici l'ISO 45001).</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Une barre de <b>quatre</b> sous-onglets, chacun avec son compteur (sauf <b>Référentiels</b>, qui n'est pas une liste) : <b>Programme</b> · <b>Constats &amp; plans d'action</b> · <b>Grilles</b> · <b>Référentiels</b>. Le bouton actif est bleu, les autres gris ; le contenu change sous la barre sans recharger la page, et <b>Programme</b> s'affiche à l'ouverture.</p>\n    <ul class=\"points\">\n      <li><b>Programme</b> — le planning d'audit interne, <b>commun avec le service Qualité</b> mais <b>filtré sur l'ISO 45001</b> : seules remontent ici les lignes portant ce référentiel ou le <b>thème I</b>, et les compteurs ne comptent que ce périmètre. Écran détaillé au paragraphe suivant.</li>\n      <li><b>Constats &amp; plans d'action</b> — les écarts relevés pendant les audits (<span class=\"b b-crit\">NC</span> ou <span class=\"b b-warn\">Axe</span>) avec leur preuve et l'action décidée. Le bouton <b>« Convertir en NC »</b> bascule un constat dans le cycle 8D de la Qualité.</li>\n      <li><b>Grilles</b> — les questionnaires d'audit <b>qui posent au moins une question de santé-sécurité</b> ; les grilles purement qualité ou informatique ne remontent pas ici. Chaque grille est affichée <b>entière</b> (elle reste le document de terrain, identique au PDF vierge imprimable) et porte un repère <span class=\"b b-info\">N question(s) ISO 45001</span> indiquant ce qui vous concerne. Pour chaque question : libellé, preuve attendue, clause, thème et <b>mode</b> (<span class=\"b b-ok\">AUTO</span> pré-rempli par les sondes de l'ERP, <span class=\"b b-info\">ASSISTÉ</span>, <span class=\"b b-mut\">MANUEL</span>).</li>\n      <li><b>Référentiels</b> — la documentation normative <b>de ce service uniquement</b> : le thème d'audit processus <b>I</b> (santé-sécurité au travail), les thèmes terrain <b>T5, T7, T8, T9</b>, et la grille de conformité clause par clause de l'<b>ISO 45001</b>. Les autres normes du SMI (ISO 9001, EN 9100, ISO 14001, ISO 27001) sont dans <b>Qualité › Audit Conformité › Référentiels</b>, qui reste le hub du système.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/securite-audit.png\" alt=\"Capture de l'onglet Audit Conformité (ISO 45001)\" loading=\"lazy\">\n      <figcaption><b>Audit Conformité</b> — les quatre sous-onglets standard, ouverts sur le programme d'audit filtré ISO 45001, planning annuel compris. Exactement la même barre qu'en Qualité et en Environnement.</figcaption>\n    </figure>\n\n    <h3>Le programme d'audit, écran par écran</h3>\n    <p>Le sous-onglet <b>Programme</b> est <b>identique à celui du service Qualité</b> : c'est le même <b>ordonnancement annuel des audits internes (EN 9100 §9.2)</b>, simplement <b>filtré sur le référentiel du service</b> — ici l'ISO 45001. Une ligne créée par la Qualité avec ce référentiel apparaît donc ici, et réciproquement.</p>\n    <ol class=\"steps\">\n      <li><b>Choisissez l'exercice.</b> Les pastilles d'années, en haut à gauche, basculent le programme d'une année sur l'autre ; l'exercice le plus récent est sélectionné à l'ouverture.</li>\n      <li><b>Lisez les quatre indicateurs</b> de l'exercice affiché : <b>Lignes au programme</b>, <b>Taux de réalisation</b>, <b>En retard</b> (date cible passée sans audit réalisé) et <b>Plans d'action soldés</b>. Ils ne comptent que le périmètre du service.</li>\n      <li><b>Servez-vous du planning annuel</b> — les douze mois de l'exercice, une case par jour, colorée selon l'état : <b>bleu</b> = audit programmé, <b>jaune</b> = pas fait (échéance dépassée), <b>rouge</b> = non conforme (NC ouverte), <b>vert</b> = soldé conforme ; une case pâle signifie qu'aucun audit n'est prévu ce jour-là. Cliquez une case occupée pour consulter l'audit ou le <b>déprogrammer</b> ; cliquez une case vide pour y <b>affecter</b> un audit non encore programmé (ou en déplacer un).</li>\n      <li><b>Ajoutez une ligne</b> avec <b>« + Nouvelle ligne »</b> : le formulaire demande le <b>type</b> (processus, poste, flash, procédé spécial, exigence client), la <b>famille</b> de processus, l'<b>entité auditée</b> (obligatoire), les <b>thèmes</b>, les <b>référentiels couverts</b> (cases à cocher), la <b>date cible</b>, le <b>temps estimé</b>, l'<b>auditeur</b>, l'<b>audité principal</b> et la <b>grille associée</b>. Sous le planning, les lignes se rangent dans les tableaux <b>« Audits de processus »</b> et <b>« Audits de poste &amp; flash »</b>.</li>\n      <li><b>Reconduisez le programme</b> en fin d'exercice avec <b>« Reconduire pour <em>année+1</em> »</b> : tout le programme est recopié sur l'année suivante, les dates décalées d'un an et les statuts remis à « planifié ».</li>\n    </ol>\n    <div class=\"note\"><b>Bon à savoir :</b> le planning est <b>partagé avec la Qualité</b> — un seul calendrier pour tout le SMI. Le filtre porte sur le <b>référentiel</b> : une ligne créée depuis cet écran sans cocher l'ISO 45001 (et sans thème I) n'y réapparaîtra pas. Cochez donc toujours le référentiel.</div>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Le programme d'audit est <b>partagé</b> avec le service Qualité : une ligne créée ici (référentiel 45001) apparaît aussi dans Qualité › Audit, et réciproquement — un seul planning pour tout le SMI.</li>\n      <li>Les <b>obligations réglementaires</b> ne sont plus dans cet onglet : elles ont leur propre onglet <b>Veille réglementaire</b> (le précédent). L'audit vérifie, la veille recense — deux gestes différents.</li>\n      <li>Cet onglet a <b>exactement la même structure</b> en Qualité, en Sécurité et en Environnement : ce que vous apprenez ici vaut dans les trois services.</li>\n    </ul>\n  </section>\n  <!-- ═══════════════ ONGLET 8 : RÉFÉRENTIELS ═══════════════ -->\n  <section class=\"tab\" id=\"tab-referentiels\">\n    <div class=\"tab-head\"><span class=\"tab-num\">8</span><h2>Référentiels</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est la page de <b>consultation</b> des vocabulaires contrôlés QHSE, partagée entre Qualité et Sécurité : elle garantit que tout le monde emploie les mêmes mots et les mêmes codes dans les formulaires. Aucune saisie ici — on s'y réfère quand on hésite sur un acronyme, une famille de risque ou un code de zone.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Des cartes de référence empilées :</p>\n    <ul class=\"points\">\n      <li><b>Acronymes</b> et <b>Imputation / secteurs</b> (code → service) — le lexique commun QHSE.</li>\n      <li><b>Types de NC, types de défaut, types de cause, décisions qualité, dérogations</b> (AT = Accord Total, AL = Accord Limité, R = Refus) — vocabulaires partagés avec le service Qualité.</li>\n      <li><b>Sécurité</b> — les types d'événements et les secteurs.</li>\n      <li><b>Familles de risque DUER — INRS ED 840 (2023)</b> — les 20 familles, en conformité stricte : aucune famille hors nomenclature.</li>\n      <li><b>Unités de travail (DUER)</b> — les 14 unités canoniques utilisées dans les formulaires.</li>\n      <li><b>Zones atelier</b> (code → secteur : Z1 Dissipation/Tronçonnage … Z7 Montage Puissance, A Allée piétonne) et <b>EPI de l'atelier</b> (les 6 EPI de la matrice).</li>\n      <li><b>Bonnes pratiques sécurité</b> — les 7 consignes affichées en atelier.</li>\n    </ul>\n    <figure class=\"shot\">\n      <img src=\"../../assets/securite-referentiels.png\" alt=\"Capture de l'onglet Référentiels\" loading=\"lazy\">\n      <figcaption><b>Référentiels</b> — les cartes de vocabulaires contrôlés QHSE, dont les 20 familles ED 840 et les zones atelier.</figcaption>\n    </figure>\n\n    <h3>Pas à pas</h3>\n    <ol class=\"steps\">\n      <li>Ouvrez l'onglet quand un formulaire vous demande une valeur codée (famille de risque, zone, secteur, type de dérogation…).</li>\n      <li>Repérez la carte correspondante et utilisez la valeur exacte du référentiel dans votre saisie — les listes déroulantes des formulaires reprennent ces mêmes valeurs.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Les acronymes notés « à confirmer » sont <b>déduits</b> : signalez toute correction au référent QHSE.</li>\n      <li>Ces référentiels sont la <b>source unique</b> Qualité / Sécurité : ne pas inventer de variantes dans les champs libres.</li>\n    </ul>\n  </section>\n\n  <!-- ═══════════════ ONGLET 9 : TABLEAU DE BORD ═══════════════ -->\n  <section class=\"tab\" id=\"tab-dashboard\">\n    <div class=\"tab-head\"><span class=\"tab-num\">9</span><h2>Tableau de bord</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> La photographie chiffrée de la sécurité de l'entreprise : accidentologie de l'année, taux réglementaires TF/TG, alertes (EPI, VGP, conformité, FDS) et dépenses. C'est l'onglet à projeter en réunion sécurité ou en revue de direction — tout s'y calcule automatiquement à partir de ce que vous avez saisi dans les autres onglets.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Quatorze tuiles d'indicateurs :</p>\n    <ul class=\"points\">\n      <li><b>Jours sans accident</b> (avec la date du dernier accident du travail) · <b>Accidents de l'année</b> (dont avec arrêt) · <b>Presqu'accidents de l'année</b> (remontées terrain).</li>\n      <li><b>Taux de fréquence (TF)</b> = accidents avec arrêt × 1 000 000 / heures travaillées, et <b>Taux de gravité (TG)</b> = jours d'arrêt × 1 000 / heures travaillées — les heures viennent des pointages du module RH ; sans heures saisies, les taux affichent « — ».</li>\n      <li><b>EPI à renouveler</b> (péremption sous 30 jours ou dépassée) · <b>VGP en retard</b> · <b>Alertes conformité</b> (obligations non conformes ou échues) · <b>FDS manquantes</b> (produits chimiques sans FDS) · <b>Conformité</b> (obligations conformes / total).</li>\n      <li><b>Eau (mois)</b> et <b>Déchets (mois)</b> — mesures environnementales du mois en cours.</li>\n      <li><b>Dépenses EPI/matériel de l'année</b> (somme des prix des dotations, avec rappel des dotations sans prix) · <b>Items sans fournisseur</b> (EPI et produits chimiques à relier au référentiel Achats).</li>\n    </ul>\n    <p>Sous les tuiles, le <b>schéma corporel des accidents</b> : deux silhouettes (face et dos) colorées en dégradé (jaune → rouge) selon le nombre de cas par partie du corps — main/doigts, yeux, oreille, dos/colonne, tête, bras/épaule/coude, jambe/genou, pied/cheville, cou/nuque, tronc — accompagnées du <b>top des localisations</b> et de l'échelle « Moins → Plus ». Il se construit à partir du champ « Partie du corps » des accidents et soins déclarés dans l'onglet Événements.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/securite-dashboard.png\" alt=\"Capture du tableau de bord Sécurité\" loading=\"lazy\">\n      <figcaption><b>Tableau de bord</b> — les tuiles TF/TG et alertes en haut, le schéma corporel face/dos avec le top des localisations en dessous.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — préparer la réunion sécurité</h3>\n    <ol class=\"steps\">\n      <li>Vérifiez d'abord les tuiles d'<b>alerte</b> : VGP en retard, EPI à renouveler, alertes conformité, FDS manquantes — chacune renvoie à l'onglet où agir (Contrôles, EPI, Conformité, Chimie).</li>\n      <li>Commentez l'accidentologie : jours sans accident, TF/TG, presqu'accidents — et appuyez-vous sur le <b>schéma corporel</b> pour cibler la prévention (ex. beaucoup de mains → campagne gants).</li>\n      <li>Si TF et TG affichent « — », faites saisir les <b>heures travaillées</b> dans RH › Système de pointage : les taux se calculent dès que des heures existent sur l'année.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Le tableau de bord ne se saisit pas : il <b>reflète</b> les autres onglets. Un chiffre faux se corrige à la source (l'événement, la dotation, la VGP…).</li>\n      <li>Les tuiles Eau et Déchets proviennent des mesures environnementales — désormais saisies dans le service <b>Environnement</b>.</li>\n      <li>Le schéma corporel ne compte que les événements dont la <b>partie du corps</b> est renseignée : soignez ce champ à la déclaration.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> la tuile « Items sans fournisseur » est votre checklist de fiabilisation des données : reliez chaque EPI et chaque produit chimique à son fournisseur pour fiabiliser les dépenses et les réapprovisionnements.</div>\n  </section>\n\n  <div class=\"docnav\">\n    <a href=\"index.html\">← Sommaire des manuels</a>\n    <a href=\"environnement.html\">Manuel suivant : Environnement →</a>\n  </div>\n\n  <footer class=\"doc\">\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\n  </footer>\n\n</div>\n</body>\n</html>\n",
  "stock": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Manuel — Stocks · ERP Seem Semrac</title>\n<link rel=\"stylesheet\" href=\"manuel.css\">\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header class=\"doc\">\n    <div class=\"brandrow\">\n      <div class=\"logo\">SS</div>\n      <div>\n        <div class=\"co\">SEEM · SEMRAC — ERP</div>\n        <div class=\"eyebrow\">Manuel utilisateur</div>\n      </div>\n      <div class=\"kind\">docs/manuel/html</div>\n    </div>\n    <h1>Service <span class=\"hi\">Stocks</span></h1>\n    <p class=\"lede\">Le service Stocks est le magasin de l'entreprise, en vue unifiée Seem + Semrac : niveaux en temps réel de la matière, des consommables et des produits chimiques, saisie des entrées et sorties, journal complet des mouvements, alertes de réapprovisionnement reliées aux Achats. Vous apprendrez ici à lire les jauges de stock, enregistrer un mouvement, régler les seuils et déclencher une demande d'achat quand une référence descend trop bas.</p>\n    <div class=\"metachips\">\n      <span class=\"chip\">👤 Pour qui : <b>Magasinier(ère)</b> (écriture : Stocks, Achats, Logistique)</span>\n      <span class=\"chip\">🧭 Dans l'ERP : <b>Sidebar → Stocks</b></span>\n      <span class=\"chip\">🗂 <b>5 onglets</b></span>\n    </div>\n  </header>\n\n  <nav class=\"toc\">\n    <div class=\"toc-t\">Sommaire</div>\n    <ol>\n      <li><a href=\"#tab-rt\">Stock en temps réel</a></li>\n      <li><a href=\"#tab-gestion\">Gestion du stock</a></li>\n      <li><a href=\"#tab-mvts\">Mouvements</a></li>\n      <li><a href=\"#tab-alertes\">Alertes et Réappro.</a></li>\n      <li><a href=\"#tab-dashboard\">Dashboard</a></li>\n    </ol>\n  </nav>\n\n  <div class=\"note\"><b>Règle d'or du service :</b> le statut d'une référence n'est <b>jamais saisi à la main</b> — l'ERP le calcule en comparant la quantité en stock aux trois seuils de l'article (seuil mini, point de commande, seuil maxi). Quatre statuts existent : <span class=\"b b-crit\">CRITIQUE</span> (quantité au niveau du seuil mini ou en dessous), <span class=\"b b-warn\">BAS</span> (au niveau du point de commande ou en dessous), <span class=\"b b-info\">MOYEN</span> (sous 75 % du seuil maxi) et <span class=\"b b-ok\">HAUT</span> (75 % du maxi ou plus). Bien régler ses seuils, c'est donc bien régler toutes les alertes. À l'ouverture, la page s'affiche sur l'onglet <b>Stock en temps réel</b> ; les boutons d'onglets en haut de page portent des compteurs (nombre de références, nombre de mouvements, nombre d'articles critiques).</div>\n\n  <!-- ════════════════════════ 1. STOCK EN TEMPS RÉEL ════════════════════════ -->\n  <section class=\"tab\" id=\"tab-rt\">\n    <div class=\"tab-head\"><span class=\"tab-num\">1</span><h2>Stock en temps réel</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est la photographie instantanée du magasin : chaque référence avec sa jauge de niveau, son statut, sa couverture en jours et son fournisseur. C'est l'écran de départ du magasinier : un coup d'œil aux compteurs de statut suffit pour savoir si la journée commence par des réapprovisionnements urgents. C'est aussi ici que l'on ajoute une nouvelle référence au catalogue.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>En haut, le titre avec le nombre de références et le bouton vert <b>« Ajouter article »</b>. Dessous, cinq compteurs cliquables qui filtrent le tableau par statut : <span class=\"b b-crit\">CRITIQUE</span>, <span class=\"b b-warn\">BAS</span>, <span class=\"b b-info\">MOYEN</span>, <span class=\"b b-ok\">HAUT</span> et <b>TOUT</b> (retour à la liste complète). Une barre de filtres complète le tri : par <b>activité</b> (Tout / Seem / Semrac / Les deux), par <b>catégorie</b> (Matière première, Consommable, Chimique OAS, Emballage, Sécurité/EPI, Outillage, Pièce rechange — seules les catégories réellement présentes en stock s'affichent) et un champ <b>« Rechercher article, ref… »</b> qui filtre en direct. Une légende rappelle le code couleur des jauges.</p>\n    <p>Le tableau liste chaque article avec les colonnes <b>Article / Réf</b>, <b>Activité</b> (badge <span class=\"b b-info\">SEEM</span>, <span class=\"b b-info\">SEMRAC</span> ou <span class=\"b b-mut\">LES DEUX</span>), <b>Catégorie</b>, <b>Niveau de stock</b> (jauge colorée avec la quantité et l'unité, plus deux traits repères : le seuil mini et le point de commande), <b>Couverture</b> (nombre de jours de stock restant — rouge sous 7 jours, orange sous 14 ; « N/A » si la consommation mensuelle n'est pas renseignée), <b>Rotation</b> (coefficient de rotation annuel : sorties annualisées divisées par le stock moyen, calculé depuis les mouvements, avec l'équivalent en jours de stock), <b>Fournisseur</b>, <b>Statut</b> et <b>Actions</b>. Les lignes en statut critique sont teintées de rouge pâle pour sauter aux yeux.</p>\n    <p>Dans la colonne <b>Actions</b>, chaque ligne propose deux boutons flèches : <b>Entrée stock</b> (flèche verte vers le bas) et <b>Sortie stock</b> (flèche rouge vers le haut) pour enregistrer un mouvement rapide — l'ERP confirme aussitôt « stock mis à jour ». Sur les seules références <span class=\"b b-crit\">CRITIQUE</span> ou <span class=\"b b-warn\">BAS</span>, un troisième bouton panier <b>« Créer DA »</b> apparaît : il déclenche une demande d'achat vers les Achats (voir l'onglet Alertes et Réappro.).</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/stock-rt.png\" alt=\"Capture de l'onglet Stock en temps réel\" loading=\"lazy\">\n      <figcaption><b>Stock en temps réel</b> — les compteurs de statut cliquables, la barre de filtres et les jauges de niveau avec leurs repères seuil mini / point de commande.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — ajouter un article au catalogue</h3>\n    <ol class=\"steps\">\n      <li>Cliquez sur <b>« Ajouter article »</b> en haut de l'onglet (le même formulaire s'ouvre aussi depuis <b>Gestion du stock → Catalogue &amp; seuils</b> avec le bouton « Nouvel article »).</li>\n      <li>Saisissez la <b>désignation</b>, la <b>référence</b>, l'<b>activité</b> concernée (Seem, Semrac ou les deux), la <b>catégorie</b> et l'<b>unité</b> de comptage.</li>\n      <li>Renseignez les <b>trois seuils</b> (mini, point de commande, maxi) et la <b>quantité à commander</b> : ce sont eux qui piloteront le statut, les jauges et les alertes de réapprovisionnement.</li>\n      <li>Complétez le <b>fournisseur préféré</b>, le <b>prix unitaire HT</b>, le <b>délai fournisseur</b> et l'<b>emplacement magasin</b>, puis cliquez <b>« Ajouter article »</b>. L'ERP confirme : « Article ajouté au catalogue. Seuils enregistrés. »</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-stock-article.png\" alt=\"Formulaire d'ajout d'un article au catalogue\" loading=\"lazy\">\n      <figcaption><b>Ajouter un article</b> — identité de la référence en haut, seuils et paramètres d'approvisionnement en bas.</figcaption>\n    </figure>\n\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Désignation (nom complet)</td><td>Texte (ex : Barres alu 2024-T3 Ø30)</td><td>Non</td><td>Nom de l'article tel qu'il apparaîtra partout dans le service.</td></tr>\n          <tr><td>Référence</td><td>Texte (REF-XXX)</td><td>Non</td><td>Référence interne ; elle fait aussi le lien avec le catalogue fournisseurs (voir onglet Gestion).</td></tr>\n          <tr><td>Activité</td><td>Liste : Seem / Semrac / both (les deux)</td><td>Non</td><td>Site(s) qui consomment l'article ; alimente le badge et le filtre d'activité.</td></tr>\n          <tr><td>Catégorie</td><td>Liste : matière première, consommable, chimique, emballage, sécurité, outillage, pièce rechange</td><td>Non</td><td>Famille de l'article ; alimente les filtres et la répartition de valeur du Dashboard.</td></tr>\n          <tr><td>Unité</td><td>Liste : kg, L, pcs, m, bobine, bouteille, rouleau, paire, palette</td><td>Non</td><td>Unité de comptage utilisée par toutes les jauges et saisies.</td></tr>\n          <tr><td>Fournisseur préféré</td><td>Texte</td><td>Non</td><td>Fournisseur proposé par défaut lors des demandes d'achat.</td></tr>\n          <tr><td>Seuil mini (stock sécurité)</td><td>Nombre</td><td>Non (fortement recommandé)</td><td>En dessous, l'article passe <b>CRITIQUE</b> : commander immédiatement.</td></tr>\n          <tr><td>Point de commande</td><td>Nombre</td><td>Non (fortement recommandé)</td><td>En dessous, l'article passe <b>BAS</b> : planifier l'approvisionnement.</td></tr>\n          <tr><td>Seuil maxi</td><td>Nombre</td><td>Non (fortement recommandé)</td><td>Capacité cible de stockage ; sert de référence à la jauge (100 %).</td></tr>\n          <tr><td>Quantité à commander (EOQ)</td><td>Nombre</td><td>Non</td><td>Quantité économique proposée par défaut quand on crée une DA depuis une alerte.</td></tr>\n          <tr><td>Prix unitaire HT (EUR)</td><td>Nombre</td><td>Non</td><td>Sert à valoriser le stock (Dashboard) et à estimer le montant des commandes.</td></tr>\n          <tr><td>Délai fournisseur (jours)</td><td>Nombre (7 par défaut)</td><td>Non</td><td>Délai de livraison habituel ; alimente l'alerte « Livraison urgente ».</td></tr>\n          <tr><td>Emplacement magasin</td><td>Texte (ex : Rack A1 / Armoire C2)</td><td>Non</td><td>Où trouver physiquement l'article dans le magasin.</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <h3>Pas à pas — retrouver et filtrer une référence</h3>\n    <ol class=\"steps\">\n      <li>Tapez un mot du nom ou de la référence dans <b>« Rechercher article, ref… »</b> : le tableau se filtre au fil de la frappe.</li>\n      <li>Combinez avec les filtres <b>activité</b> et <b>catégorie</b>, ou cliquez sur un <b>compteur de statut</b> pour ne voir que les articles critiques, bas, moyens ou hauts. Les filtres se cumulent ; le compteur <b>TOUT</b> réaffiche tout.</li>\n      <li>Sur la ligne trouvée, lisez la jauge : la barre colorée indique le niveau, les deux traits verticaux marquent le seuil mini et le point de commande, et les valeurs mini/max sont rappelées sous la barre.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Un article configuré « Les deux » reste visible que l'on filtre sur Seem ou sur Semrac : il appartient aux deux activités.</li>\n      <li>La <b>couverture</b> se calcule à partir de la consommation mensuelle de l'article : stock ÷ consommation × 30 jours. Sans consommation renseignée, elle affiche « N/A ».</li>\n      <li>La <b>rotation</b> est calculée automatiquement depuis l'historique des mouvements ; un tiret signifie qu'il n'y a pas encore assez de sorties pour la mesurer.</li>\n      <li>Le bouton <b>« Créer DA »</b> n'apparaît que sur les lignes critiques ou basses : pour commander un article encore « haut », passez par le bouton <b>« Nouvelle DA »</b> de l'onglet Alertes et Réappro.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> le formulaire d'ajout d'article ne bloque aucun champ, mais un article créé <b>sans seuils</b> ne déclenchera jamais d'alerte de réapprovisionnement et sa jauge n'aura pas de sens. Renseignez toujours seuil mini, point de commande et seuil maxi, dans cet ordre croissant.</div>\n    <div class=\"astuce\"><b>Astuce :</b> commencez chaque prise de poste par un clic sur le compteur <b>CRITIQUE</b> : s'il n'est pas à zéro, traitez ces références en premier (bouton panier ou onglet Alertes et Réappro.).</div>\n  </section>\n\n  <!-- ════════════════════════ 2. GESTION DU STOCK ════════════════════════ -->\n  <section class=\"tab\" id=\"tab-gestion\">\n    <div class=\"tab-head\"><span class=\"tab-num\">2</span><h2>Gestion du stock</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est l'atelier de saisie du magasin : on y enregistre les flux physiques — entrées à la réception, sorties vers la production, régularisations d'inventaire — et on y règle le paramétrage du catalogue (seuils, réappro automatique). Chaque mouvement saisi ici est traçable : opérateur, référence de commande ou de lot, date. Les seuils réglés ici pilotent les alertes et les suggestions de réapprovisionnement de tout le service.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Un bandeau vert rappelle la règle de traçabilité, puis quatre boutons à icône colorée servent de sous-onglets : <b>Entrée stock</b>, <b>Sortie stock</b>, <b>Ajustement / Inventaire</b> et <b>Catalogue &amp; seuils</b>. Les trois premiers présentent le même agencement : le formulaire de saisie à gauche, un rappel des derniers mouvements du même type à droite.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/stock-gestion.png\" alt=\"Capture de l'onglet Gestion du stock\" loading=\"lazy\">\n      <figcaption><b>Gestion du stock</b> — les quatre sous-onglets en haut ; formulaire de saisie à gauche, derniers mouvements à droite.</figcaption>\n    </figure>\n\n    <h3>Sous-onglet « Entrée stock »</h3>\n    <p>Pour enregistrer une réception de marchandise. Le formulaire <b>« Saisir une entrée »</b> demande : l'<b>article</b> (liste déroulante affichant le stock actuel de chacun), la <b>quantité reçue</b>, la <b>date de réception</b> (aujourd'hui par défaut), le <b>BL fournisseur</b> (ex : BLF-2026-XXX), la <b>DA liée</b> (ex : DA-2026-XXX) et l'<b>opérateur</b>. Le bouton <b>« Valider entrée »</b> enregistre le mouvement — confirmation « Entrée validée. Stock et historique mis à jour. » Le panneau <b>« Dernières entrées »</b> à droite affiche les cinq réceptions les plus récentes (article, date, quantité, opérateur).</p>\n\n    <h3>Sous-onglet « Sortie stock »</h3>\n    <p>Pour sortir de la matière ou des consommables du magasin. Le formulaire <b>« Saisir une sortie »</b> demande : l'<b>article</b>, la <b>quantité sortie</b>, la <b>date</b>, la <b>référence BDT / LOT / CMD</b> (le bon de travail, le lot ou la commande qui consomme — c'est ce lien qui rend la sortie traçable), l'<b>opérateur</b> et le <b>motif</b> parmi quatre : <i>Consommation production</i>, <i>Rebut / casse</i>, <i>Retour fournisseur</i>, <i>Transfert inter-atelier</i>. Le bouton <b>« Valider sortie »</b> enregistre ; le panneau <b>« Dernières sorties »</b> rappelle les six plus récentes avec leur motif.</p>\n\n    <h3>Sous-onglet « Ajustement / Inventaire »</h3>\n    <p>Pour recaler le stock théorique sur la réalité. Un bandeau jaune précise l'usage : <i>écart entre stock théorique et inventaire physique, perte, ou correction d'erreur de saisie</i>. Le formulaire demande : l'<b>article</b>, le <b>stock réel constaté</b> (la quantité comptée physiquement, pas l'écart), la <b>date d'inventaire</b>, le <b>motif</b> (<i>Inventaire physique périodique</i>, <i>Écart constaté</i>, <i>Perte / détérioration</i>, <i>Correction erreur de saisie</i>) et le <b>responsable inventaire</b>. Le bouton <b>« Valider ajustement »</b> confirme : « Ajustement validé. Écart tracé dans le journal. » À droite, le tableau <b>« Historique complet mouvements »</b> affiche les dix derniers mouvements tous types confondus (Date, Article, Type — badge <span class=\"b b-ok\">ENTREE</span>, <span class=\"b b-crit\">SORTIE</span>, <span class=\"b b-warn\">AJUSTEMENT</span> ou <span class=\"b b-info\">INVENTAIRE</span> —, Quantité, Opérateur).</p>\n\n    <h3>Sous-onglet « Catalogue &amp; seuils »</h3>\n    <p>Le paramétrage de l'approvisionnement, référence par référence. Un tableau éditable liste chaque article avec : <b>Article</b>, <b>Activité</b>, <b>Stock</b> actuel, puis trois champs modifiables directement dans la ligne — <b>Seuil mini</b>, <b>Pt commande</b>, <b>Qté cmd</b> — la case à cocher <b>Réappro auto</b>, le <b>Fournisseur</b> et un bouton disquette <b>Action</b> qui enregistre la ligne (confirmation « Seuils enregistrés », complétée de « réappro auto activé » si la case est cochée). Le bouton <b>« Nouvel article »</b> ouvre le même formulaire d'ajout que l'onglet Stock en temps réel.</p>\n    <p>En dessous, la section <b>« Catalogue fournisseurs par catégorie »</b> agrège toutes les références déclarées dans les fiches fournisseurs (service Achats), groupées par catégorie (Matière, Accessoires…), avec les colonnes <b>Réf</b>, <b>Désignation</b>, <b>Fournisseur</b>, <b>Prix</b> et <b>Stock réel</b> : si la référence existe aussi dans votre stock, la quantité en magasin s'affiche en vert ; sinon la mention « non stocké » apparaît. C'est le pont entre ce que les fournisseurs proposent et ce que le magasin détient réellement.</p>\n\n    <h3>Pas à pas — enregistrer une réception</h3>\n    <ol class=\"steps\">\n      <li>Ouvrez <b>Gestion du stock → Entrée stock</b>.</li>\n      <li>Choisissez l'<b>article</b> dans la liste (le stock actuel s'affiche entre parenthèses), saisissez la <b>quantité reçue</b> et vérifiez la <b>date</b>.</li>\n      <li>Reportez le numéro du <b>BL fournisseur</b> et, si la réception solde une demande d'achat, le numéro de la <b>DA liée</b> : c'est ce qui permet de remonter du stock à la commande d'origine.</li>\n      <li>Indiquez votre nom en <b>opérateur</b> puis cliquez <b>« Valider entrée »</b>. Le mouvement apparaît dans « Dernières entrées » et dans l'onglet <b>Mouvements</b>.</li>\n    </ol>\n\n    <h3>Pas à pas — régler les seuils et activer le réappro automatique</h3>\n    <ol class=\"steps\">\n      <li>Ouvrez <b>Gestion du stock → Catalogue &amp; seuils</b>.</li>\n      <li>Sur la ligne de l'article, ajustez <b>Seuil mini</b>, <b>Pt commande</b> et <b>Qté cmd</b> directement dans les champs.</li>\n      <li>Cochez <b>Réappro auto</b> si vous voulez que l'ERP crée <b>automatiquement une demande d'achat</b> dès que le stock de cette référence passe sous le point de commande — la génération automatique ne concerne que les références cochées.</li>\n      <li>Cliquez le bouton <b>disquette</b> de la ligne : l'ERP confirme « Seuils enregistrés ». Les jauges, statuts et alertes se recalculent avec les nouvelles valeurs.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Gardez toujours l'ordre <b>seuil mini &lt; point de commande &lt; seuil maxi</b> : c'est cette échelle qui donne leur sens aux statuts et aux jauges.</li>\n      <li>Une <b>sortie matière liée à un bon de travail</b> ne fait pas que décompter le magasin : elle alimente aussi le suivi des coûts de production (consommation imputée à la machine et au lot). D'où l'importance de renseigner la référence BDT / LOT / CMD.</li>\n      <li>Le tableau des seuils s'enregistre <b>ligne par ligne</b> : cliquez la disquette de chaque article modifié, sinon la saisie est perdue au changement de page.</li>\n      <li>Si le catalogue fournisseurs est vide, renseignez les catalogues dans les fiches fournisseurs (<b>Achats → Fournisseurs / ST</b>) : cette section se remplira automatiquement.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> l'historique des mouvements se conserve — on ne « supprime » pas une saisie erronée. En cas d'erreur (mauvaise quantité, mauvais article), passez par <b>Ajustement / Inventaire</b> avec le motif <i>Correction erreur de saisie</i> : l'écart reste tracé dans le journal, ce qui est exigé pour la traçabilité aéronautique.</div>\n    <div class=\"astuce\"><b>Astuce :</b> pour l'ajustement, saisissez bien le <b>stock réel constaté</b> (le comptage physique), pas la différence : l'ERP calcule l'écart tout seul et le trace.</div>\n  </section>\n\n  <!-- ════════════════════════ 3. MOUVEMENTS ════════════════════════ -->\n  <section class=\"tab\" id=\"tab-mvts\">\n    <div class=\"tab-head\"><span class=\"tab-num\">3</span><h2>Mouvements</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est le journal de bord complet du magasin : chaque entrée, sortie, réception ou ajustement y est consigné avec son origine, son opérateur et sa date. C'est l'onglet de la traçabilité : en cas de doute sur un niveau de stock, d'audit ou de recherche d'une consommation, c'est ici que l'on remonte le fil.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>En haut, le titre avec le nombre total de mouvements et un champ <b>« Rechercher (article, source, opérateur…) »</b> qui filtre la liste en direct. Un bandeau bleu rappelle que chaque mouvement indique son <b>origine</b> : BDT (production), réception DA / BL, commande, consommation machine, ou sortie / saisie libre. Le tableau, trié du plus récent au plus ancien, comprend les colonnes <b>Date</b>, <b>Article</b>, <b>Type</b> (<span class=\"b b-ok\">↓ Entrée</span>, <span class=\"b b-crit\">↑ Sortie</span>, <span class=\"b b-info\">± Ajustement</span>, <span class=\"b b-ok\">↓ Réception</span>), <b>Qté</b>, <b>Avant→Après</b> (le niveau de stock avant puis après le mouvement), <b>Origine</b> (étiquette colorée : BDT, Réception DA, BL, Lot, Commande, Conso. machine, ou « Sortie / saisie libre » pour une saisie manuelle sans référence), <b>Opérateur</b> et <b>Motif</b>.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/stock-mvts.png\" alt=\"Capture de l'onglet Mouvements\" loading=\"lazy\">\n      <figcaption><b>Mouvements</b> — le journal complet avec, pour chaque ligne, le type, la colonne Avant→Après et l'étiquette d'origine du mouvement.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — retracer l'historique d'un article</h3>\n    <ol class=\"steps\">\n      <li>Tapez le nom de l'article (ou une référence de BDT, un nom d'opérateur, un motif) dans le champ de recherche : seules les lignes correspondantes restent affichées.</li>\n      <li>Lisez la colonne <b>Avant→Après</b> de haut en bas : vous suivez l'évolution exacte du niveau de stock, mouvement par mouvement.</li>\n      <li>L'étiquette <b>Origine</b> vous dit qui a consommé ou approvisionné : un bon de travail (production), une réception de demande d'achat, un bon de livraison, un lot, une commande, une machine — ou une saisie libre du magasin.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Ce journal est <b>en lecture seule</b> : les mouvements se créent depuis l'onglet Gestion du stock (ou automatiquement par la production et les réceptions), jamais ici.</li>\n      <li>Une origine « Sortie / saisie libre » signale un mouvement saisi sans référence de rattachement : à éviter autant que possible, car il casse la chaîne de traçabilité commande → lot → consommation.</li>\n      <li>Le compteur du bandeau d'onglet (en haut de page) reprend le nombre total de mouvements enregistrés.</li>\n    </ul>\n    <div class=\"astuce\"><b>Astuce :</b> avant un inventaire tournant, filtrez l'article concerné et comparez le dernier « Après » du journal avec votre comptage physique : l'écart à régulariser se lit immédiatement.</div>\n  </section>\n\n  <!-- ════════════════════════ 4. ALERTES ET RÉAPPRO. ════════════════════════ -->\n  <section class=\"tab\" id=\"tab-alertes\">\n    <div class=\"tab-head\"><span class=\"tab-num\">4</span><h2>Alertes et Réappro.</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est la liste de courses du magasin : tous les articles passés sous leurs seuils y sont rassemblés, classés par gravité, avec la quantité à commander déjà proposée. De là, un clic crée la <b>demande d'achat</b> qui part chez les Achats. Un stock critique non traité, c'est une production arrêtée : cet onglet se consulte tous les jours.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>En haut, le titre avec une pastille rouge <b>« N articles à commander »</b> (si au moins un article est sous ses seuils) et le bouton vert <b>« Nouvelle DA »</b> pour une demande d'achat libre. Quatre tuiles KPI résument la situation : <b>Articles critiques</b> (sous le seuil mini), <b>Articles bas</b> (sous le point de commande), <b>Valeur à commander</b> (estimation en euros des commandes urgentes : quantités à commander × prix unitaires) et <b>Livraison urgente (≤3j)</b> (articles critiques dont le fournisseur livre en 3 jours ou moins — il est encore temps d'être livré vite).</p>\n    <p>Suivent jusqu'à deux tableaux : <b>Stock CRITIQUE</b>, précédé d'un bandeau rouge « En dessous du seuil de sécurité. Commander immédiatement. », et <b>Stock BAS</b>, précédé d'un bandeau orange « Point de commande atteint. Planifier l'approvisionnement. ». Les deux partagent les mêmes colonnes : <b>Article</b>, <b>Activité</b>, <b>Stock actuel</b>, <b>Seuil mini</b>, <b>Écart</b> (le manque sous le point de commande), <b>Couverture</b> (jours restants), <b>Fournisseur</b> (avec son délai de livraison), <b>Qté à commander</b> (avec le montant estimé) et le bouton <b>« Créer DA »</b>. Si aucun article n'est en alerte, l'onglet affiche simplement « Tous les stocks sont corrects — Aucune alerte de réapprovisionnement. »</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/stock-alertes.png\" alt=\"Capture de l'onglet Alertes et Réappro.\" loading=\"lazy\">\n      <figcaption><b>Alertes et Réappro.</b> — les quatre tuiles de synthèse puis les tableaux Stock CRITIQUE et Stock BAS, chacun avec son bouton « Créer DA » par ligne.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — créer une DA depuis une alerte (le cas courant)</h3>\n    <ol class=\"steps\">\n      <li>Sur la ligne de l'article en alerte, cliquez <b>« Créer DA »</b>.</li>\n      <li>L'ERP crée immédiatement la demande d'achat, pré-remplie avec l'article (nom + référence), la <b>quantité à commander</b> proposée, le <b>fournisseur</b> préféré, la priorité <b>urgent</b> et le demandeur « Stock ». Aucun formulaire à remplir.</li>\n      <li>Une notification confirme le numéro : « DA <b>DA-2026-XXX</b> créée et transmise aux Achats (à traiter). » La demande apparaît aussitôt dans <b>Achats → Demandes d'achat</b>, où l'acheteur la transformera en bon de commande.</li>\n      <li>À la réception de la marchandise, enregistrez l'entrée (onglet Gestion du stock) : l'article repasse au-dessus de ses seuils et sort de la liste des alertes.</li>\n    </ol>\n\n    <h3>Pas à pas — créer une DA manuelle (hors alerte)</h3>\n    <ol class=\"steps\">\n      <li>Cliquez <b>« Nouvelle DA »</b> en haut de l'onglet : la fenêtre « Nouvelle demande d'achat » s'ouvre.</li>\n      <li>Saisissez la <b>désignation</b> (seul champ obligatoire), choisissez le <b>type</b> et la <b>priorité</b>, complétez quantité, fournisseur, date de livraison souhaitée et éventuel numéro d'affaire.</li>\n      <li>Cliquez <b>« Créer la DA »</b> : la demande part chez les Achats (« à traiter »), avec le demandeur « Stock ».</li>\n    </ol>\n    <figure class=\"shot\">\n      <img src=\"../../assets/form-stock-da.png\" alt=\"Formulaire de nouvelle demande d'achat\" loading=\"lazy\">\n      <figcaption><b>Nouvelle DA</b> — seul le champ « Article / Désignation » est obligatoire ; type, priorité et livraison souhaitée guident le travail de l'acheteur.</figcaption>\n    </figure>\n\n    <div class=\"tbl\">\n      <table>\n        <thead><tr><th>Champ</th><th>Saisie</th><th>Obligatoire</th><th>Explication</th></tr></thead>\n        <tbody>\n          <tr><td>Article / Désignation</td><td>Texte (ex : Barres alu 2024-T3 Ø30)</td><td><b>Oui</b></td><td>Ce qu'il faut acheter ; sans désignation, l'ERP refuse la création.</td></tr>\n          <tr><td>Type</td><td>Liste : Matière / Outillage / Consommable / Chimique / Sous-traitance</td><td>Non</td><td>Famille d'achat ; aide les Achats à router la demande.</td></tr>\n          <tr><td>Quantité</td><td>Texte libre (ex : 12 barres)</td><td>Non</td><td>Quantité souhaitée, avec son unité en clair.</td></tr>\n          <tr><td>Fournisseur</td><td>Texte</td><td>Non</td><td>Fournisseur pressenti ; l'acheteur reste libre de le changer.</td></tr>\n          <tr><td>Priorité</td><td>Liste : Normal / Urgent / Critique</td><td>Non</td><td>Niveau d'urgence affiché côté Achats pour prioriser le traitement.</td></tr>\n          <tr><td>Livraison souhaitée</td><td>Date</td><td>Non</td><td>Date à laquelle vous avez besoin de la marchandise.</td></tr>\n          <tr><td>N° affaire (option)</td><td>Texte (AFF-2026-XXX)</td><td>Non</td><td>Rattache l'achat à une affaire cliente pour le suivi des coûts.</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>La <b>quantité à commander</b> proposée est la quantité de commande (EOQ) paramétrée sur l'article ; à défaut, l'ERP propose environ 80 % de l'écart entre le stock actuel et le seuil maxi.</li>\n      <li>La tuile <b>Valeur à commander</b> n'est qu'une estimation : elle multiplie les quantités à commander par les prix unitaires renseignés au catalogue.</li>\n      <li>Si vous avez coché <b>Réappro auto</b> sur une référence (Gestion du stock → Catalogue &amp; seuils), la DA se crée toute seule au passage sous le point de commande : inutile de la doubler ici, vérifiez d'abord dans <b>Achats → Demandes d'achat</b>.</li>\n      <li>Créer la DA ne commande rien chez le fournisseur : c'est l'acheteur qui la transforme en <b>bon de commande</b>, dont la réception se suit ensuite côté <b>Expéditions</b>.</li>\n    </ul>\n    <div class=\"warn\"><b>Attention :</b> le bouton « Créer DA » crée une demande <b>à chaque clic</b> — cliquer deux fois crée deux demandes. Attendez la notification de confirmation avec le numéro de DA avant de recliquer.</div>\n    <div class=\"astuce\"><b>Astuce :</b> surveillez la tuile <b>Livraison urgente (≤3j)</b> : ces articles critiques ont un fournisseur rapide — en créant la DA le matin même, vous pouvez éviter la rupture.</div>\n  </section>\n\n  <!-- ════════════════════════ 5. DASHBOARD ════════════════════════ -->\n  <section class=\"tab\" id=\"tab-dashboard\">\n    <div class=\"tab-head\"><span class=\"tab-num\">5</span><h2>Dashboard</h2></div>\n    <p class=\"tab-but\"><b>À quoi ça sert.</b> C'est la vue de pilotage du magasin : combien d'argent dort en stock, dans quelles catégories, quelle est la santé globale des niveaux et quels articles concentrent la valeur (analyse ABC). Utile pour la revue hebdomadaire, la préparation des inventaires et les arbitrages d'achats.</p>\n\n    <h3>Ce que vous voyez</h3>\n    <p>Quatre tuiles KPI en tête : <b>Valeur totale du stock</b> (en euros, avec le nombre de références), <b>Articles critiques</b> (action immédiate requise), <b>Couverture moyenne</b> (en jours de production) et <b>Mouvements ce mois</b> (entrées + sorties). Dessous, deux blocs côte à côte : <b>Valeur par catégorie</b> (barres horizontales : où se concentre l'argent immobilisé — matière première, consommables, chimiques…) et <b>État du stock global</b> (répartition des références par statut critique / bas / moyen / haut, en nombre et en pourcentage, avec l'objectif affiché : <b>0 critique, moins de 10 % bas</b>).</p>\n    <p>Enfin, le tableau <b>« Analyse ABC — Top articles par valeur de stock »</b> classe les références qui pèsent le plus : la classe <b>A</b> regroupe les articles totalisant 70 % de la valeur du stock, <b>B</b> les 20 % suivants, <b>C</b> les 10 % restants. Colonnes : <b>ABC</b> (badge de classe), <b>Article</b>, <b>Activité</b>, <b>Quantité</b>, <b>PU</b> (prix unitaire), <b>Valeur stock</b>, <b>Couverture</b> et <b>Statut</b>.</p>\n    <figure class=\"shot\">\n      <img src=\"../../assets/stock-dashboard.png\" alt=\"Capture de l'onglet Dashboard\" loading=\"lazy\">\n      <figcaption><b>Dashboard</b> — les quatre KPI, la valeur par catégorie, l'état global du stock et l'analyse ABC en bas.</figcaption>\n    </figure>\n\n    <h3>Pas à pas — la revue hebdomadaire du magasin</h3>\n    <ol class=\"steps\">\n      <li>Vérifiez la tuile <b>Articles critiques</b> : si elle n'est pas à zéro, passez par l'onglet <b>Alertes et Réappro.</b> avant toute autre chose.</li>\n      <li>Comparez l'<b>état du stock global</b> à l'objectif (0 critique, &lt;10 % bas) : une dérive du pourcentage « bas » annonce les ruptures de la semaine suivante.</li>\n      <li>Parcourez l'<b>analyse ABC</b> : concentrez la surveillance (seuils justes, inventaires plus fréquents, négociation fournisseur) sur les articles de classe <b>A</b> — c'est là que se joue la valeur.</li>\n      <li>Un œil à la <b>couverture moyenne</b> et aux <b>mouvements du mois</b> confirme le rythme général : peu de mouvements et une couverture qui gonfle, c'est du stock qui dort.</li>\n    </ol>\n\n    <h3>Règles &amp; points d'attention</h3>\n    <ul class=\"points\">\n      <li>Tous les chiffres sont recalculés à l'affichage à partir du stock et des mouvements réels — rien n'est saisi à la main dans cet onglet.</li>\n      <li>La <b>valeur du stock</b> dépend des prix unitaires renseignés au catalogue : un article sans prix compte pour zéro dans la valeur totale et dans l'analyse ABC.</li>\n      <li>La <b>couverture moyenne</b> ne prend en compte que les articles dont la consommation mensuelle est renseignée.</li>\n    </ul>\n    <div class=\"note\"><b>Bon à savoir :</b> un dashboard Stock plus complet (filtres par période, comparaisons, export) existe aussi dans <b>Tableaux de bord → Dashboard Stock</b>, commun à toute l'entreprise.</div>\n  </section>\n\n  <div class=\"docnav\">\n    <a href=\"index.html\">← Sommaire des manuels</a>\n    <a href=\"compta.html\">Manuel suivant : Comptabilité →</a>\n  </div>\n\n  <footer class=\"doc\">\n    ERP Seem Semrac — manuel utilisateur généré depuis le dépôt (docs/manuel/html). Les captures proviennent de docs/assets (rafraîchies par scripts_doc/capture_screens.mjs). En cas d'écart entre ce manuel et l'application, l'application fait foi ; signaler l'écart pour mise à jour.\n  </footer>\n\n</div>\n</body>\n</html>\n",
}

export const MANUEL_CSS: string = "/* ══════════════════════════════════════════════════════════════\n   Manuels utilisateur HTML — ERP Seem Semrac\n   Feuille de style PARTAGÉE par tous les manuels (docs/manuel/html/*.html)\n   Palette marque : violet #5C5391 · bleu #22409B (cf. src/brand.ts)\n   ══════════════════════════════════════════════════════════════ */\n:root{\n  --violet:#5C5391; --bleu:#22409B;\n  --bg:#F4F6FB; --surface:#FFFFFF; --surface-2:#EEF1F8;\n  --ink:#161A28; --muted:#586074; --faint:#8891a4; --line:#E1E6F0;\n  --ok:#1E8A54; --warn:#B4791F; --crit:#B23B3B;\n  --shadow:0 1px 2px rgba(20,30,60,.06),0 8px 24px rgba(20,30,60,.07);\n  --mono:\"SFMono-Regular\",ui-monospace,Consolas,\"Roboto Mono\",monospace;\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 \"Segoe UI\",system-ui,-apple-system,Roboto,Arial,sans-serif;-webkit-font-smoothing:antialiased}\n.wrap{max-width:1020px;margin:0 auto;padding:clamp(18px,4vw,48px) clamp(14px,3.5vw,36px)}\nh1,h2,h3,h4{line-height:1.2;margin:0;text-wrap:balance}\np{margin:0 0 12px}\na{color:var(--bleu)}\ncode{font-family:var(--mono);font-size:.85em;background:var(--surface-2);border-radius:5px;padding:1px 6px;color:var(--ink)}\n\n/* ── En-tête de manuel ── */\nheader.doc{border-bottom:1px solid var(--line);padding-bottom:26px;margin-bottom:34px}\n.brandrow{display:flex;align-items:center;gap:12px;margin-bottom:20px;flex-wrap:wrap}\n.logo{width:38px;height:38px;border-radius:10px;background:linear-gradient(135deg,var(--bleu),var(--violet));display:grid;place-items:center;color:#fff;font-family:var(--mono);font-weight:700;font-size:.85rem;flex:none}\n.brandrow .co{font-weight:700}\n.brandrow .kind{margin-left:auto;color:var(--faint);font-size:.76rem;font-family:var(--mono)}\n.eyebrow{font-family:var(--mono);font-size:.68rem;letter-spacing:.16em;text-transform:uppercase;color:var(--faint);font-weight:600}\nh1{font-size:clamp(1.6rem,4vw,2.4rem);font-weight:800;letter-spacing:-.02em}\nh1 .hi{color:var(--bleu)}\n.lede{margin-top:12px;color:var(--muted);max-width:70ch;font-size:1.02rem}\n.metachips{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}\n.chip{display:inline-flex;align-items:center;gap:6px;background:var(--surface);border:1px solid var(--line);border-radius:999px;padding:5px 13px;font-size:.76rem;font-weight:600;color:var(--muted);max-width:100%;flex-wrap:wrap}\n.chip b{color:var(--ink)}\n\n/* ── Sommaire ── */\nnav.toc{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:18px 22px;box-shadow:var(--shadow);margin-bottom:34px}\nnav.toc .toc-t{font-size:.72rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);margin-bottom:10px}\nnav.toc ol{margin:0;padding-left:22px;columns:2;column-gap:34px}\nnav.toc li{margin:4px 0;font-size:.92rem;break-inside:avoid}\n@media (max-width:640px){nav.toc ol{columns:1}}\n\n/* ── Sections onglet ── */\nsection.tab{margin:44px 0}\n.tab-head{display:flex;align-items:center;gap:12px;margin-bottom:6px}\n.tab-num{font-family:var(--mono);font-weight:700;color:#fff;background:linear-gradient(135deg,var(--bleu),var(--violet));border-radius:9px;min-width:34px;height:34px;display:grid;place-items:center;font-size:.85rem;flex:none}\nh2{font-size:clamp(1.2rem,2.8vw,1.55rem);font-weight:800}\n.tab-but{color:var(--muted);margin:10px 0 18px;max-width:72ch}\n.tab-but b,.tab-but strong{color:var(--ink)}\nh3{font-size:1.02rem;font-weight:750;margin:22px 0 10px;display:flex;align-items:center;gap:8px}\nh3::before{content:\"\";width:8px;height:8px;border-radius:2px;background:var(--violet);flex:none}\n\n/* Pas-à-pas */\nol.steps{margin:0 0 14px;padding-left:0;list-style:none;counter-reset:step}\nol.steps>li{position:relative;padding:10px 14px 10px 46px;margin:6px 0;background:var(--surface);border:1px solid var(--line);border-radius:10px;font-size:.93rem;counter-increment:step}\nol.steps>li::before{content:counter(step);position:absolute;left:12px;top:10px;width:24px;height:24px;border-radius:50%;background:var(--surface-2);color:var(--bleu);font-weight:800;font-size:.78rem;display:grid;place-items:center;font-family:var(--mono)}\nul.points{margin:0 0 14px;padding-left:20px}\nul.points li{margin:5px 0;font-size:.92rem;color:#2a3040}\n\n/* Captures */\nfigure.shot{margin:18px 0;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:10px;box-shadow:var(--shadow)}\nfigure.shot img{display:block;width:100%;height:auto;border-radius:9px;border:1px solid var(--line)}\nfigure.shot figcaption{padding:9px 6px 2px;font-size:.78rem;color:var(--muted)}\nfigure.shot figcaption b{color:var(--ink)}\n\n/* Encarts */\n.note,.warn,.astuce{border-radius:0 12px 12px 0;padding:12px 18px;margin:14px 0;font-size:.9rem}\n.note{border-left:3px solid var(--bleu);background:#eef2fb;color:#1e2c56}\n.warn{border-left:3px solid var(--crit);background:#fdf0f0;color:#5c2323}\n.astuce{border-left:3px solid var(--ok);background:#eefaf2;color:#174d33}\n.note b,.warn b,.astuce b{font-weight:750}\n\n/* Tableaux (champs de formulaires, statuts) */\n.tbl{overflow-x:auto;border:1px solid var(--line);border-radius:12px;background:var(--surface);box-shadow:var(--shadow);margin:14px 0}\ntable{width:100%;border-collapse:collapse;font-size:.87rem}\nth,td{text-align:left;padding:9px 13px;border-bottom:1px solid var(--line);vertical-align:top}\nth{font-family:var(--mono);font-size:.66rem;letter-spacing:.06em;text-transform:uppercase;color:var(--faint);font-weight:700}\ntbody tr:last-child td{border-bottom:none}\n\n/* Badges de statut (réutilisables dans les tableaux) */\n.b{display:inline-block;padding:2px 9px;border-radius:999px;font-size:.7rem;font-weight:700}\n.b-ok{background:#dcfce7;color:#15803d}.b-warn{background:#fef3c7;color:#92400e}\n.b-info{background:#dbeafe;color:#1d4ed8}.b-crit{background:#fee2e2;color:#b91c1c}\n.b-mut{background:#f1f5f9;color:#64748b}\n\n/* Pied + navigation inter-docs */\n.docnav{display:flex;justify-content:space-between;gap:10px;margin-top:46px;flex-wrap:wrap}\n.docnav a{display:inline-flex;align-items:center;gap:8px;background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:10px 16px;font-size:.85rem;font-weight:700;text-decoration:none;color:var(--bleu);box-shadow:var(--shadow)}\nfooter.doc{margin-top:40px;padding-top:20px;border-top:1px solid var(--line);color:var(--faint);font-size:.75rem;line-height:1.6}\n\n/* Index (hub) */\n.grid-idx{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px;margin-top:8px}\na.card-idx{display:block;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 18px;text-decoration:none;color:inherit;box-shadow:var(--shadow);transition:transform .12s}\na.card-idx:hover{transform:translateY(-2px)}\na.card-idx .t{font-weight:800;color:var(--ink);display:flex;align-items:center;gap:8px}\na.card-idx .dot{width:10px;height:10px;border-radius:3px;flex:none}\na.card-idx .d{font-size:.78rem;color:var(--muted);margin-top:5px}\na.card-idx .n{font-size:.68rem;color:var(--faint);margin-top:7px;font-family:var(--mono)}\n\n@media print{\n  body{background:#fff}\n  .wrap{max-width:none;padding:0}\n  nav.toc ol{columns:2}\n  section.tab{break-inside:avoid-page;margin:26px 0}\n  figure.shot,.note,.warn,.astuce,ol.steps>li{box-shadow:none;break-inside:avoid}\n  .docnav{display:none}\n}\n"
